-- ============================================================
-- 圣经全文（新译本，神名已按公开发布本还原为「耶和华」）· 数据文件 3/6
-- 第二版：可覆盖第一版（冲突时更新经文）。已运行过第一版的直接运行本版即可。
-- 本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '历代志上', 13, 4, 17, '以斯拉的儿子是益帖、米列、以弗和雅伦。米列娶法老的女儿比提雅为妻；比提雅怀孕，生了米利暗、沙买和以实提摩的父亲益巴。米列的犹大妻子生了基多的父亲雅列、梭哥的父亲希伯和撒挪亚的父亲耶古铁。'),
('CNV', '历代志上', 13, 4, 19, '荷第雅的妻子、拿含的妹妹的儿子是迦米人基伊拉的父亲和玛迦人以实提摩的父亲。'),
('CNV', '历代志上', 13, 4, 20, '示门的儿子是暗嫩、林拿、便．哈南和提伦。以示的儿子是梭黑和便．梭黑。'),
('CNV', '历代志上', 13, 4, 21, '犹大的儿子是示拉；示拉的儿子是利迦的父亲珥、玛利沙的父亲拉大，以及在伯亚实比织造细麻布的众家族。'),
('CNV', '历代志上', 13, 4, 22, '还有约敬、哥西巴人、约阿施和萨拉，他们曾统治摩押地，又有雅叔比利恒。这都是古代的记载。'),
('CNV', '历代志上', 13, 4, 23, '他们都是陶匠，是尼他应和基低拉的居民；他们与王一起住在那里，为王作工。'),
('CNV', '历代志上', 13, 4, 24, '西缅的儿子是尼母利、雅悯、雅立、谢拉和扫罗。'),
('CNV', '历代志上', 13, 4, 25, '扫罗的儿子是沙龙；沙龙的儿子是米比衫；米比衫的儿子是米施玛。'),
('CNV', '历代志上', 13, 4, 26, '米施玛的子孙如下：米施玛的儿子是哈母利；哈母利的儿子是撒刻；撒刻的儿子是示每。'),
('CNV', '历代志上', 13, 4, 27, '示每有十六个儿子，六个女儿；他兄弟们的儿女却不多；他们各家的儿女，都不如犹大族的子孙那样多。'),
('CNV', '历代志上', 13, 4, 28, '他们住在别是巴、摩拉大、哈萨．书亚、'),
('CNV', '历代志上', 13, 4, 29, '辟拉、以森、陀腊、'),
('CNV', '历代志上', 13, 4, 30, '彼土利、何珥玛、洗革拉、'),
('CNV', '历代志上', 13, 4, 31, '伯．玛嘉博、哈萨．苏撒、伯．比利和沙拉音。直到大卫王的时代，这些都是他们的城市，'),
('CNV', '历代志上', 13, 4, 32, '还有附近的村庄和以坦、亚因、临门、陀健和亚珊等五座城，'),
('CNV', '历代志上', 13, 4, 33, '以及这些城周围所有的村庄，直到巴力。这是他们居住的地方，他们也有自己的族谱。'),
('CNV', '历代志上', 13, 4, 34, '还有米所巴、雅米勒、亚玛谢的儿子约沙、'),
('CNV', '历代志上', 13, 4, 35, '约珥、约示比的儿子耶户；约示比是西莱雅的儿子，西莱雅是亚薛的儿子。'),
('CNV', '历代志上', 13, 4, 36, '还有以利约乃、雅哥巴、约朔海、亚帅雅、亚底业、耶西篾和比拿雅。'),
('CNV', '历代志上', 13, 4, 37, '示非的儿子是细撒；示非是亚龙的儿子，亚龙是耶大雅的儿子，耶大雅是申利的儿子；申利是示玛雅的儿子。'),
('CNV', '历代志上', 13, 4, 38, '以上所记的名字，都是各家族的领袖；他们的家族都很兴旺。'),
('CNV', '历代志上', 13, 4, 39, '他们往基多的关口去，直到山谷的东面，为自己的羊群寻找草场。'),
('CNV', '历代志上', 13, 4, 40, '他们找到了一块肥美的草场；那地十分宽阔，又清静、又安宁；从前住在那里的是含族的人。'),
('CNV', '历代志上', 13, 4, 41, '以上这些有名字记录的人，在犹大王希西家的日子，前来攻击含族人的帐棚和那里所有的米乌尼人，把他们完全毁灭，直到今日，并且住在他们的地方，因为那里有草场，可以牧放他们的羊群。'),
('CNV', '历代志上', 13, 4, 42, '在西缅人中有五百人往西珥山去，他们的首领是以示的儿子毗拉提、尼利雅、利法雅和乌薛。'),
('CNV', '历代志上', 13, 4, 43, '他们击杀了逃脱余生的亚玛力人，就住在那里，直到今日。'),
('CNV', '历代志上', 13, 5, 1, '以色列的长子流本的儿子如下（流本虽然是长子，但是因为他玷污了他父亲的床，他长子的名分就归给以色列的儿子约瑟的儿子，所以按着家谱他不算是长子。'),
('CNV', '历代志上', 13, 5, 2, '犹大在自己的兄弟中是最强盛的，领袖也是从他而出，但是长子的名分却归约瑟）：'),
('CNV', '历代志上', 13, 5, 3, '以色列的长子流本的儿子是哈诺、法路、希斯伦和迦米。'),
('CNV', '历代志上', 13, 5, 4, '约珥的子孙如下：约珥的儿子是示玛雅，示玛雅的儿子是歌革，歌革的儿子是示每，'),
('CNV', '历代志上', 13, 5, 5, '示每的儿子是米迦，米迦的儿子是利．亚雅，利．亚雅的儿子是巴力，'),
('CNV', '历代志上', 13, 5, 6, '巴力的儿子是备．拉；备．拉被亚述王提革拉．毗尼色掳去，他是流本支派的首领。'),
('CNV', '历代志上', 13, 5, 7, '他的兄弟按着家族历代的谱系记载作首领的，是耶利、撒迦利雅和比拉。'),
('CNV', '历代志上', 13, 5, 8, '比拉是亚撒的儿子，亚撒是示玛的儿子，示玛是约珥的儿子。约珥住在亚罗珥，远至尼波和巴力．免。'),
('CNV', '历代志上', 13, 5, 9, '他也向东面迁居，直到幼发拉底河这边旷野的边缘，因为他们在基列地的牲畜增多起来。'),
('CNV', '历代志上', 13, 5, 10, '扫罗在位的日子，他们与夏甲人作战；夏甲人败在他们手下，他们就在基列东面的全境，住在夏甲人的帐棚里。'),
('CNV', '历代志上', 13, 5, 11, '迦得的子孙在流本支派的对面，住在巴珊地，直到撒迦。'),
('CNV', '历代志上', 13, 5, 12, '住在巴珊的有族长约珥，副族长沙番，还有雅乃和沙法。'),
('CNV', '历代志上', 13, 5, 13, '他们同家族的兄弟是米迦勒、米书兰、示巴、约赖、雅干、细亚和希伯，共七人。'),
('CNV', '历代志上', 13, 5, 14, '以上这些人都是亚比孩的儿子。亚比孩是户利的儿子，户利是耶罗亚的儿子，耶罗亚是基列的儿子，基列是米迦勒的儿子，米迦勒是耶示筛的儿子，耶示筛是耶哈多的儿子，耶哈多是布斯的儿子；'),
('CNV', '历代志上', 13, 5, 15, '还有古尼的孙子、押比叠的儿子亚希，是他们家族的首领。'),
('CNV', '历代志上', 13, 5, 16, '他们住在基列、巴珊和属于巴珊的村庄，以及沙仑的整个草场，直到四周的边缘。'),
('CNV', '历代志上', 13, 5, 17, '以上所有这些人，在犹大王约坦和以色列王耶罗波安在位的日子，都记载在家谱上。'),
('CNV', '历代志上', 13, 5, 18, '流本支派、迦得支派和玛拿西半个支派的人，都是勇士；他们拿盾牌和刀剑，能拉弓射箭，又能出征善战的，共有四万四千七百六十人。'),
('CNV', '历代志上', 13, 5, 19, '他们与夏甲人、伊突人、拿非施人和挪答人作战。'),
('CNV', '历代志上', 13, 5, 20, '他们得神的帮助对抗敌人，夏甲人和所有与夏甲人联盟的人，都交在他们手中，因为他们在作战的时候向神呼求；神应允了他们，因为他们倚靠他。'),
('CNV', '历代志上', 13, 5, 21, '他们又掳掠了敌人的牲畜：骆驼五万、羊二十五万、驴二千，以及人口十万。'),
('CNV', '历代志上', 13, 5, 22, '因为这场战争是出于神，所以敌人被杀的很多；他们就占领了敌人的地方，直到被掳的时候。'),
('CNV', '历代志上', 13, 5, 23, '玛拿西半个支派的人住在那地，从巴珊直到巴力．黑门、示尼珥和黑门山，他们人数众多。'),
('CNV', '历代志上', 13, 5, 24, '以下这些人是他们各家族的族长：以弗、以示、以列、亚斯列、耶利米、何达威雅和雅叠；他们都是英勇的战士，著名的人物，也是各家族的族长。'),
('CNV', '历代志上', 13, 5, 25, '他们背弃了他们列祖的神，随从当地民族的神行邪淫；神曾从他们面前消灭了这些民族。'),
('CNV', '历代志上', 13, 5, 26, '因此，以色列的神激动了亚述王普勒的心，就是亚述王提革拉．毗尼色的心，他就把流本支派、迦得支派和玛拿西半个支派的人掳到哈腊、哈博和哈拉，以及歌散河边，他们的后裔直到今日还在那里。'),
('CNV', '历代志上', 13, 6, 1, '利未的儿子是革顺、哥辖和米拉利。'),
('CNV', '历代志上', 13, 6, 2, '哥辖的儿子是暗兰、以斯哈、希伯伦和乌薛。'),
('CNV', '历代志上', 13, 6, 3, '暗兰的儿女是亚伦、摩西和米利暗。亚伦的儿子是拿答、亚比户、以利亚撒和以他玛。'),
('CNV', '历代志上', 13, 6, 4, '以利亚撒生非尼哈，非尼哈生亚比书，'),
('CNV', '历代志上', 13, 6, 5, '亚比书生布基，布基生乌西，'),
('CNV', '历代志上', 13, 6, 6, '乌西生西拉希雅，西拉希雅生米拉约，'),
('CNV', '历代志上', 13, 6, 7, '米拉约生亚玛利雅，亚玛利雅生亚希突，'),
('CNV', '历代志上', 13, 6, 8, '亚希突生撒督，撒督生亚希玛斯，'),
('CNV', '历代志上', 13, 6, 9, '亚希玛斯生亚撒利雅，亚撒利雅生约哈难，'),
('CNV', '历代志上', 13, 6, 10, '约哈难生亚撒利雅，'),
('CNV', '历代志上', 13, 6, 11, '亚撒利雅生亚玛利雅，亚玛利雅生亚希突，'),
('CNV', '历代志上', 13, 6, 12, '亚希突生撒督，撒督生沙龙，'),
('CNV', '历代志上', 13, 6, 13, '沙龙生希勒家，希勒家生亚撒利雅，'),
('CNV', '历代志上', 13, 6, 14, '亚撒利雅生西莱雅，西莱雅生约萨答；'),
('CNV', '历代志上', 13, 6, 15, '在耶和华藉尼布甲尼撒掳掠犹大人和耶路撒冷人的时候，这约萨答也被掳去了。'),
('CNV', '历代志上', 13, 6, 16, '利未的儿子是革顺、哥辖和米拉利。'),
('CNV', '历代志上', 13, 6, 17, '革顺的儿子名叫立尼和示每。'),
('CNV', '历代志上', 13, 6, 18, '哥辖的儿子是暗兰、以斯哈、希伯伦和乌薛。'),
('CNV', '历代志上', 13, 6, 19, '米拉利的儿子是抹利和母示。以上这些是利未人各宗族的各家。'),
('CNV', '历代志上', 13, 6, 20, '革顺的子孙如下：革顺的儿子是立尼，立尼的儿子是雅哈，雅哈的儿子是薪玛，'),
('CNV', '历代志上', 13, 6, 21, '薪玛的儿子是约亚，约亚的儿子是易多，易多的儿子是谢拉，谢拉的儿子是耶特赖。'),
('CNV', '历代志上', 13, 6, 22, '哥辖的子孙如下：哥辖的儿子是亚米拿达，亚米拿达的儿子是可拉，可拉的儿子是亚惜，'),
('CNV', '历代志上', 13, 6, 23, '亚惜的儿子是以利加拿，以利加拿的儿子是以比雅撒，以比雅撒的儿子是亚惜，'),
('CNV', '历代志上', 13, 6, 24, '亚惜的儿子是他哈，他哈的儿子是乌列，乌列的儿子是乌西雅，乌西雅的儿子是少罗。'),
('CNV', '历代志上', 13, 6, 25, '以利加拿的儿子是亚玛赛和亚希摩，'),
('CNV', '历代志上', 13, 6, 26, '亚希摩的儿子是以利加拿，以利加拿的儿子是琐菲，琐菲的儿子是拿哈，'),
('CNV', '历代志上', 13, 6, 27, '拿哈的儿子是以利押，以利押的儿子是耶罗罕，耶罗罕的儿子是以利加拿，以利加拿的儿子是撒母耳。'),
('CNV', '历代志上', 13, 6, 28, '撒母耳的子孙如下：长子是约珥，次子是亚比亚。'),
('CNV', '历代志上', 13, 6, 29, '米拉利的子孙如下：米拉利的儿子是抹利，抹利的儿子是立尼，立尼的儿子是示每，示每的儿子是乌撒，'),
('CNV', '历代志上', 13, 6, 30, '乌撒的儿子是示米亚，示米亚的儿子是哈基雅，哈基雅的儿子是亚帅雅。'),
('CNV', '历代志上', 13, 6, 31, '自约柜安放妥当以后，大卫指派在耶和华殿里负责歌唱事奉的就是以下这些人。'),
('CNV', '历代志上', 13, 6, 32, '他们在会幕的帐棚前担任歌唱的工作，直到所罗门在耶路撒冷建造了耶和华的殿，他们按着班次执行自己的职务。'),
('CNV', '历代志上', 13, 6, 33, '以下这些就是执行职务的人，以及他们的子孙。哥辖的子孙中有歌唱的希幔，希幔是约珥的儿子，约珥是撒母耳的儿子。'),
('CNV', '历代志上', 13, 6, 34, '撒母耳是以利加拿的儿子，以利加拿是耶罗罕的儿子，耶罗罕是以列的儿子，以列是陀亚的儿子，'),
('CNV', '历代志上', 13, 6, 35, '陀亚是苏弗的儿子，苏弗是以利加拿的儿子，以利加拿是玛哈的儿子，玛哈是亚玛赛的儿子，'),
('CNV', '历代志上', 13, 6, 36, '亚玛赛是以利加拿的儿子，以利加拿是约珥的儿子，约珥是亚撒利雅的儿子，亚撒利雅是西番雅的儿子，'),
('CNV', '历代志上', 13, 6, 37, '西番雅是他哈的儿子，他哈是亚惜的儿子，亚惜是以比雅撒的儿子，以比雅撒是可拉的儿子，'),
('CNV', '历代志上', 13, 6, 38, '可拉是以斯哈的儿子，以斯哈是哥辖的儿子，哥辖是利未的儿子，利未是以色列的儿子。'),
('CNV', '历代志上', 13, 6, 39, '希幔的兄弟亚萨，就是站在希幔右边供职的亚萨，是比利家的儿子，比利家是示米亚的儿子，'),
('CNV', '历代志上', 13, 6, 40, '示米亚是米迦勒的儿子，米迦勒是巴西雅的儿子，巴西雅是玛基雅的儿子，'),
('CNV', '历代志上', 13, 6, 41, '玛基雅是伊特尼的儿子，伊特尼是谢拉的儿子，谢拉是亚大雅的儿子，'),
('CNV', '历代志上', 13, 6, 42, '亚大雅是以探的儿子，以探是薪玛的儿子，薪玛是示每的儿子，'),
('CNV', '历代志上', 13, 6, 43, '示每是雅哈的儿子，雅哈是革顺的儿子，革顺是利未的儿子。'),
('CNV', '历代志上', 13, 6, 44, '希幔和亚萨的兄弟米拉利的子孙，就是在他们左边供职的有以探，以探是基示的儿子，基示是亚伯底的儿子，亚伯底是玛鹿的儿子，'),
('CNV', '历代志上', 13, 6, 45, '玛鹿是哈沙比雅的儿子，哈沙比雅是亚玛谢的儿子，亚玛谢是希勒家的儿子，'),
('CNV', '历代志上', 13, 6, 46, '希勒家是暗西的儿子，暗西是巴尼的儿子，巴尼是沙麦的儿子，'),
('CNV', '历代志上', 13, 6, 47, '沙麦是末力的儿子，末力是母示的儿子，母示是米拉利的儿子，米拉利是利未的儿子。'),
('CNV', '历代志上', 13, 6, 48, '他们的亲族利未人，都被派办理神殿中帐幕里的一切事务。'),
('CNV', '历代志上', 13, 6, 49, '亚伦和他的子孙，却在燔祭坛上和香坛上，献祭烧香，作至圣所里的各种工作，为以色列人赎罪，是完全照着神的仆人摩西所吩咐的。'),
('CNV', '历代志上', 13, 6, 50, '以下这些人是亚伦的子孙：亚伦的儿子是以利亚撒，以利亚撒的儿子是非尼哈，非尼哈的儿子是亚比书，'),
('CNV', '历代志上', 13, 6, 51, '亚比书的儿子是布基，布基的儿子是乌西，乌西的儿子是西拉希雅，'),
('CNV', '历代志上', 13, 6, 52, '西拉希雅的儿子是米拉约，米拉约的儿子是亚玛利雅，亚玛利雅的儿子是亚希突，'),
('CNV', '历代志上', 13, 6, 53, '亚希突的儿子是撒督，撒督的儿子是亚希玛斯。'),
('CNV', '历代志上', 13, 6, 54, '以下是在他们境内，他们按着营房居住的地方：哥辖族中亚伦的子孙抽中了签，'),
('CNV', '历代志上', 13, 6, 55, '以色列人就把犹大地的希伯仑和希伯仑四周的草场，给了他们；'),
('CNV', '历代志上', 13, 6, 56, '但这城的郊野和属于这城的村庄，他们却给了耶孚尼的儿子迦勒。'),
('CNV', '历代志上', 13, 6, 57, '以色列人把避难城希伯仑给了亚伦的子孙，还有立拿和属于立拿的草场，雅提珥、以实提莫和属于以实提莫的草场，'),
('CNV', '历代志上', 13, 6, 58, '希仑和属于希仑的草场，底璧和属于底璧的草场，'),
('CNV', '历代志上', 13, 6, 59, '亚珊和属于亚珊的草场，伯．示麦和属于伯．示麦的草场。'),
('CNV', '历代志上', 13, 6, 60, '又从便雅悯支派中，把迦巴和属于迦巴的草场，阿勒篾和属于阿勒篾的草场，亚拿突和属于亚拿突的草场，分给亚伦的子孙。他们各族所得的城共十三座。'),
('CNV', '历代志上', 13, 6, 61, '哥辖其余家族的子孙从玛拿西半个支派中，抽签分得十座城。'),
('CNV', '历代志上', 13, 6, 62, '革顺的子孙，按着他们的家族，从以萨迦支派、亚设支派、拿弗他利支派和巴珊地的玛拿西支派中，分得十三座城。'),
('CNV', '历代志上', 13, 6, 63, '米拉利的子孙，按着他们的家族，从流本支派、迦得支派和西布伦支派中，抽签分得十二座城。'),
('CNV', '历代志上', 13, 6, 64, '以色列人把这些城和属于这些城的草场，都分给利未人。'),
('CNV', '历代志上', 13, 6, 65, '他们又从犹大支派、西缅支派和便雅悯支派中，抽签把以上这些有名字记录的城给了他们。'),
('CNV', '历代志上', 13, 6, 66, '哥辖子孙的家族中，有些也从以法莲支派中分得他们境内的城市。'),
('CNV', '历代志上', 13, 6, 67, '以色列人又把避难城，在以法莲山地的示剑和属于示剑的草场，给了他们，还有基色和属于基色的草场，'),
('CNV', '历代志上', 13, 6, 68, '约缅和属于约缅的草场，伯．和仑和属伯．和仑的草场，'),
('CNV', '历代志上', 13, 6, 69, '亚雅仑和属于亚雅仑的草场，迦特．临门和属于迦特．临门的草场。'),
('CNV', '历代志上', 13, 6, 70, '以色列人又从玛拿西半个支派中，把亚乃和属于亚乃的草场，比连和属于比连的草场，给了哥辖其余的家族。'),
('CNV', '历代志上', 13, 6, 71, '又从玛拿西半个支派的家族中，把巴珊的哥兰和属于哥兰的草场，亚斯他录和属于亚斯他录的草场，给了革顺的子孙。'),
('CNV', '历代志上', 13, 6, 72, '又从以萨迦支派中，给了他们基低斯和属于基低斯的草场，大比拉和属于大比拉的草场，'),
('CNV', '历代志上', 13, 6, 73, '拉末和属于拉末的草场，亚年和属于亚年的草场。'),
('CNV', '历代志上', 13, 6, 74, '又从亚设支派中给了他们玛沙和属于玛沙的草场，押顿和属于押顿的草场，'),
('CNV', '历代志上', 13, 6, 75, '户割和属于户割的草场，利合和属于利合的草场。'),
('CNV', '历代志上', 13, 6, 76, '又从拿弗他利支派中，把加利利的基低斯和属于基低斯的草场，哈们和属于哈们的草场，基列亭和属于基列亭的草场，给了他们。'),
('CNV', '历代志上', 13, 6, 77, '又从西布伦支派中，把临摩挪和属于临摩挪的草场，他泊和属于他泊的草场，给了米拉利其余的子孙。'),
('CNV', '历代志上', 13, 6, 78, '又在约旦河那边，耶利哥对面，就是约旦河东岸，从流本支派中，给了他们在旷野的比悉和属于比悉的草场，雅哈撒和属于雅哈撒的草场，'),
('CNV', '历代志上', 13, 6, 79, '基底莫和属于基底莫的草场，米法押和属于米法押的草场。'),
('CNV', '历代志上', 13, 6, 80, '又从迦得支派中，给了他们基列的拉末和属于拉末的草场，玛哈念和属于玛哈念的草场，'),
('CNV', '历代志上', 13, 6, 81, '希实本和属于希实本的草场，雅谢和属于雅谢的草场。'),
('CNV', '历代志上', 13, 7, 1, '以萨迦的儿子是陀拉、普瓦、雅述和伸仑，共四人。'),
('CNV', '历代志上', 13, 7, 2, '陀拉的儿子是乌西、利法雅、耶勒、雅买、易伯散和示母利，都是陀拉家族的族长，是他们那世代英勇的战士；到了大卫的日子，他们的人数共有二万二千六百名。'),
('CNV', '历代志上', 13, 7, 3, '乌西的儿子是伊斯拉希，伊斯拉希的儿子是米迦勒、俄巴底亚，约珥和伊示雅，共五人，都是各家族的首领。'),
('CNV', '历代志上', 13, 7, 4, '此外，与他们在一起的，按着谱系和家族，还有能作战的军队三万六千人，因为他们的妻子和儿子很多。'),
('CNV', '历代志上', 13, 7, 5, '他们的兄弟在以萨迦各族中，都是英勇的战士，按着家谱登记的，共有八万七千人。'),
('CNV', '历代志上', 13, 7, 6, '便雅悯的儿子是比拉、比结和耶叠，共三人。'),
('CNV', '历代志上', 13, 7, 7, '比拉的儿子是以斯本、乌西、乌薛、耶利摩和以利，共五人，都是各家族的首领，是英勇的战士，按着家谱登记的，共有二万二千零三十四人。'),
('CNV', '历代志上', 13, 7, 8, '比结的儿子是细米拉、约阿施、以利以谢、以利约乃、暗利、耶利摩、亚比雅、亚拿突和亚拉篾，这都是比结的儿子；'),
('CNV', '历代志上', 13, 7, 9, '他们都是各家族的首领，是英勇的战士，按着家谱登记的，共有二万零二百人。'),
('CNV', '历代志上', 13, 7, 10, '耶叠的儿子是比勒罕；比勒罕的儿子是耶乌斯、便雅悯、以忽、基拿拿、细坦、他施和亚希沙哈；'),
('CNV', '历代志上', 13, 7, 11, '这都是耶叠的儿子，是各家族的首领，是英勇的战士，能上阵作战的，共有一万七千二百人。'),
('CNV', '历代志上', 13, 7, 12, '还有以珥的儿子书品和户品，以及亚黑的儿子户伸。'),
('CNV', '历代志上', 13, 7, 13, '拿弗他利的儿子是雅薛、沽尼、耶色、沙龙；都是辟拉的子孙。'),
('CNV', '历代志上', 13, 7, 14, '玛拿西的儿子是亚斯列，是他亚兰籍的妾所生的；她又生了基列的父亲玛吉。'),
('CNV', '历代志上', 13, 7, 15, '玛吉娶了妻子，是户品和书品的妹妹，名叫玛迦。玛拿西的次子名叫西罗非哈；西罗非哈只有几个女儿。'),
('CNV', '历代志上', 13, 7, 16, '玛吉的妻子玛迦生了一个儿子，她就给他起名叫毗利施；毗利施的兄弟名叫示利施；示利施的儿子是乌兰和利金。'),
('CNV', '历代志上', 13, 7, 17, '乌兰的儿子是比但。这都是基列的子孙；基列是玛吉的儿子，玛吉是玛拿西的儿子。'),
('CNV', '历代志上', 13, 7, 18, '基列的妹妹哈摩利吉生了伊施荷、亚比以谢和玛拉。'),
('CNV', '历代志上', 13, 7, 19, '示米大的儿子是亚现、示剑、利克希和阿尼安。'),
('CNV', '历代志上', 13, 7, 20, '以法莲的儿子是书提拉，书提拉的儿子是比列，比列的儿子是他哈，他哈的儿子是以拉大，以拉大的儿子是他哈，'),
('CNV', '历代志上', 13, 7, 21, '他哈的儿子是撒拔，撒拔的儿子是书提拉。以谢和以列因为下去夺取迦特人的牲畜，被当地出生的迦特人杀了。'),
('CNV', '历代志上', 13, 7, 22, '他们的父亲以法莲为他们悲哀多日，他的兄弟都来安慰他。'),
('CNV', '历代志上', 13, 7, 23, '以法莲与妻子同房，他的妻子就怀孕，生了一个儿子；以法莲就给他起名叫比利亚，因为他的家遭遇祸患。'),
('CNV', '历代志上', 13, 7, 24, '他的女儿是舍伊拉，就是建造上伯．和仑、下伯．和仑和乌羡．舍伊拉的。'),
('CNV', '历代志上', 13, 7, 25, '比利亚的儿子是利法和利悉；利悉的儿子是他拉，他拉的儿子是他罕，'),
('CNV', '历代志上', 13, 7, 26, '他罕的儿子是拉但，拉但的儿子是亚米忽，亚米忽的儿子是以利沙玛，'),
('CNV', '历代志上', 13, 7, 27, '以利沙玛的儿子是嫩，嫩的儿子是约书亚。'),
('CNV', '历代志上', 13, 7, 28, '以法莲人的地业和居住的地方，是伯特利和属于伯特利的村庄，东边有拿兰，西边有基色和属于基色的村庄；示剑和属于示剑的村庄，直到迦萨和属于迦萨的村庄。'),
('CNV', '历代志上', 13, 7, 29, '靠近玛拿西支派边界的还有：伯．善和属于伯．善的村庄；他纳和属于他纳的村庄；米吉多和属于米吉多的村庄；多珥和属于多珥的村庄。以色列的儿子约瑟的子孙就住在这些地方。'),
('CNV', '历代志上', 13, 7, 30, '亚设的儿子是音拿、亦施瓦、亦施韦和比利亚，还有他们的妹妹西拉。'),
('CNV', '历代志上', 13, 7, 31, '比利亚的儿子是希别和玛结，玛结是比撒威的父亲。'),
('CNV', '历代志上', 13, 7, 32, '希别生雅弗勒、朔默、何坦和他们的妹妹书雅。'),
('CNV', '历代志上', 13, 7, 33, '雅弗勒的儿子是巴萨、宾哈和亚施法；这些人是雅弗勒的儿子。'),
('CNV', '历代志上', 13, 7, 34, '朔默的儿子是亚希、罗迦、耶户巴和亚兰。'),
('CNV', '历代志上', 13, 7, 35, '朔默的兄弟希连的儿子是琐法、音那、示利斯和亚抹。'),
('CNV', '历代志上', 13, 7, 36, '琐法的儿子是书亚、哈尼弗、书阿勒、比利、音拉、'),
('CNV', '历代志上', 13, 7, 37, '比悉、河得、珊玛、施沙、益兰和比拉。'),
('CNV', '历代志上', 13, 7, 38, '益帖的儿子是耶孚尼、毗斯巴和亚拉。'),
('CNV', '历代志上', 13, 7, 39, '乌拉的儿子是亚拉、汉尼业和利写。'),
('CNV', '历代志上', 13, 7, 40, '这都是亚设的子孙，是他们各家族的首领，是杰出英勇的战士，是领袖中的首领；按着家谱登记的数目，能上阵作战的共有二万六千人。'),
('CNV', '历代志上', 13, 8, 1, '便雅悯生了长子比拉、次子亚实别、三子亚哈拉、'),
('CNV', '历代志上', 13, 8, 2, '四子挪哈和五子拉法。'),
('CNV', '历代志上', 13, 8, 3, '比拉的儿子是亚大、基拉、亚比忽、'),
('CNV', '历代志上', 13, 8, 4, '亚比书、乃幔、亚何亚、'),
('CNV', '历代志上', 13, 8, 5, '基拉、示孚汛、户兰。'),
('CNV', '历代志上', 13, 8, 6, '以下这些人是以忽的子孙，他们是迦巴居民各家族的首领，曾被掳到玛拿辖。'),
('CNV', '历代志上', 13, 8, 7, '以忽的儿子是乃幔、亚希亚和基拉；基拉使他们被掳；他生了乌撒和亚希忽。'),
('CNV', '历代志上', 13, 8, 8, '沙哈连遣走户伸和巴拉两位妻子以后，就在摩押地生了儿子。'),
('CNV', '历代志上', 13, 8, 9, '他的妻子贺得给他生了约巴、洗比雅、米沙、玛拉干、'),
('CNV', '历代志上', 13, 8, 10, '耶乌斯、沙迦、米玛；他这些儿子都是家族的首领。'),
('CNV', '历代志上', 13, 8, 11, '户伸也给他生了亚比突、以利巴力。'),
('CNV', '历代志上', 13, 8, 12, '以利巴力的儿子是希伯、米珊和沙麦。沙麦建造了阿挪和罗德二城，以及属于这二城的村庄。'),
('CNV', '历代志上', 13, 8, 13, '还有比利亚和示玛，他们二人是亚雅仑居民各家族的首领，曾把迦特的居民赶走。'),
('CNV', '历代志上', 13, 8, 14, '又有亚希约、沙煞、耶利末、'),
('CNV', '历代志上', 13, 8, 15, '西巴第雅、亚拉得、亚得、'),
('CNV', '历代志上', 13, 8, 16, '米迦勒、伊施巴和约哈，这都是比利亚的儿子。'),
('CNV', '历代志上', 13, 8, 17, '西巴第雅、米书兰、希西基、希伯、'),
('CNV', '历代志上', 13, 8, 18, '伊施米莱、伊斯利亚和约巴，这都是以利巴力的儿子。'),
('CNV', '历代志上', 13, 8, 19, '雅金、细基利、撒底、'),
('CNV', '历代志上', 13, 8, 20, '以利乃、洗勒太、以列、'),
('CNV', '历代志上', 13, 8, 21, '亚大雅、比拉雅和申拉，这都是示每的儿子。'),
('CNV', '历代志上', 13, 8, 22, '伊施班、希伯、以列、'),
('CNV', '历代志上', 13, 8, 23, '亚伯顿、细基利、哈难、'),
('CNV', '历代志上', 13, 8, 24, '哈拿尼雅、以拦、安陀提雅、'),
('CNV', '历代志上', 13, 8, 25, '伊弗底雅和毗努伊勒，这都是沙煞的儿子。'),
('CNV', '历代志上', 13, 8, 26, '珊示莱、示哈利、亚他利雅、'),
('CNV', '历代志上', 13, 8, 27, '雅利西、以利亚和细基利，这都是耶罗罕的儿子。'),
('CNV', '历代志上', 13, 8, 28, '以上这些人照着家谱都是他们家族的首领，是住在耶路撒冷的首领。'),
('CNV', '历代志上', 13, 8, 29, '住在基遍的有基遍的父亲耶利，他的妻子名叫玛迦。'),
('CNV', '历代志上', 13, 8, 30, '他的长子是亚伯顿，其余的儿子是苏珥、基士、巴力、拿答、'),
('CNV', '历代志上', 13, 8, 31, '基多、亚希约、撒迦和米基罗；'),
('CNV', '历代志上', 13, 8, 32, '米基罗生示米暗。这些人也和他们的亲族一同住在耶路撒冷，互相为邻。'),
('CNV', '历代志上', 13, 8, 33, '尼珥生基士；基士生扫罗；扫罗生约拿单、麦基舒亚、亚比拿达和伊施．巴力。'),
('CNV', '历代志上', 13, 8, 34, '约拿单的儿子是米力．巴力；米力．巴力生米迦。'),
('CNV', '历代志上', 13, 8, 35, '米迦的儿子是毗敦、米勒、他利亚和亚哈斯。'),
('CNV', '历代志上', 13, 8, 36, '亚哈斯生耶何阿达；耶何阿达生亚拉篾、亚斯玛威和心利；心利生摩撒；'),
('CNV', '历代志上', 13, 8, 37, '摩撒生比尼亚；比尼亚的儿子是拉法，拉法的儿子是以利亚萨，以利亚萨的儿子是亚悉。'),
('CNV', '历代志上', 13, 8, 38, '亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅和哈难；这都是亚悉的儿子。'),
('CNV', '历代志上', 13, 8, 39, '亚悉的兄弟以设的众子是：长子乌兰、次子耶乌施、三子以利法列。'),
('CNV', '历代志上', 13, 8, 40, '乌兰的儿子都是英勇的战士，是弓箭手；他们有很多子孙，共有一百五十名，都是便雅悯支派的。'),
('CNV', '历代志上', 13, 9, 1, '全体以色列人都照着家谱登记，都写在“以色列诸王记”上；犹大人因为悖逆，就被掳到巴比伦去。'),
('CNV', '历代志上', 13, 9, 2, '那些最先回来，住在自己的地业、自己的城中的，有以色列人、祭司、利未人和作殿役的。'),
('CNV', '历代志上', 13, 9, 3, '在耶路撒冷居住的，有犹大支派、便雅悯支派、以法莲支派和玛拿西支派的人。'),
('CNV', '历代志上', 13, 9, 4, '犹大的儿子法勒斯的子孙中，有乌太；乌太是亚米忽的儿子，亚米忽是暗利的儿子；暗利是音利的儿子，音利是巴尼的儿子。'),
('CNV', '历代志上', 13, 9, 5, '示罗的子孙中，有长子亚帅雅和他的众子。'),
('CNV', '历代志上', 13, 9, 6, '谢拉的子孙中，有耶乌利和他们的亲族，共六百九十人。'),
('CNV', '历代志上', 13, 9, 7, '便雅悯的子孙中，有哈西努的曾孙、何达威雅的孙子、米书兰的儿子撒路；'),
('CNV', '历代志上', 13, 9, 8, '又有耶罗罕的儿子伊比尼雅，米基立的孙子、乌西的儿子以拉，以及伊比尼雅的曾孙、流珥的孙子、示法提雅的儿子米书兰，'),
('CNV', '历代志上', 13, 9, 9, '还有他们的众亲族；按着他们的家谱登记，共有九百五十六人。以上这些人都是他们各家族的首领。'),
('CNV', '历代志上', 13, 9, 10, '祭司中有耶大雅、耶何雅立、雅斤，'),
('CNV', '历代志上', 13, 9, 11, '还有管理神的殿的希勒家的儿子亚萨利雅；希勒家是米书兰的儿子，米书兰是撒督的儿子，撒督是米拉约的儿子，米拉约是亚希突的儿子。'),
('CNV', '历代志上', 13, 9, 12, '又有玛基雅的曾孙、巴施户珥的孙子、耶罗罕的儿子亚大雅，以及亚第业的儿子玛赛；亚第业是雅希细拉的儿子，雅希细拉是米书兰的儿子，米书兰是米实利密的儿子，米实利密是音麦的儿子；'),
('CNV', '历代志上', 13, 9, 13, '以及他们的众亲族，他们家族的首领，共有一千七百六十人，都是有才干，很会作神殿里工作的人。'),
('CNV', '历代志上', 13, 9, 14, '利未支派米拉利的子孙中，有哈沙比雅的曾孙、押利甘的孙子、哈述的儿子示玛雅；'),
('CNV', '历代志上', 13, 9, 15, '又有拔巴甲、黑勒施、迦拉，和亚萨的曾孙、细基利的孙子、米迦的儿子玛探雅；'),
('CNV', '历代志上', 13, 9, 16, '又有耶杜顿的曾孙、迦拉的孙子、示玛雅的儿子俄巴底；还有以利加拿的孙子、亚撒的儿子比利家；他们都住在尼陀法人的村落。'),
('CNV', '历代志上', 13, 9, 17, '守门的有沙龙、亚谷、达们、亚希幔和他们的众亲族；沙龙是他们的首领。'),
('CNV', '历代志上', 13, 9, 18, '直到现在，他们仍是看守东面的王门；他们曾经作过利未营的守门人。'),
('CNV', '历代志上', 13, 9, 19, '可拉的曾孙、以比雅撒的孙子、可利的儿子沙龙，以及他的众亲族可拉人，担任事务的工作，看守会幕的门；他们的祖先曾经管理耶和华的营幕，看守营门。'),
('CNV', '历代志上', 13, 9, 20, '从前以利亚撒的儿子非尼哈，曾经作过他们的领袖，耶和华也与他同在。'),
('CNV', '历代志上', 13, 9, 21, '米施利米雅的儿子撒迦利雅，是看守会幕大门的。'),
('CNV', '历代志上', 13, 9, 22, '这些被选看守殿门的人，共有二百一十二人；他们在自己的村庄里按着家谱登记；他们是大卫和撒母耳先见指派承担这职任的。'),
('CNV', '历代志上', 13, 9, 23, '他们和他们的子孙，按着班次，看守耶和华的殿门，就是会幕的门。'),
('CNV', '历代志上', 13, 9, 24, '在东西南北四方，都有看守的人。'),
('CNV', '历代志上', 13, 9, 25, '他们的亲族，就是住在他们村庄里的，每七天就要来和他们换班。'),
('CNV', '历代志上', 13, 9, 26, '四个殿门的守卫长都是利未人，受托看守神的殿的房间和库房。'),
('CNV', '历代志上', 13, 9, 27, '他们在神的殿的四周住宿，因为他们承担看守的责任，并且每天早晨要负责开门。'),
('CNV', '历代志上', 13, 9, 28, '利未人中有管理器皿的使用的；他们按着数目拿出去，也要按着数目拿进来。'),
('CNV', '历代志上', 13, 9, 29, '他们当中又有人受托管理器具，和管理圣所的一切器具，以及细面、酒、油、乳香、香料。'),
('CNV', '历代志上', 13, 9, 30, '祭司的子孙中，有人用香料配制成香膏。'),
('CNV', '历代志上', 13, 9, 31, '利未人玛他提雅是可拉族沙龙的长子，他的职责是管理在煎盘烤饼的事。'),
('CNV', '历代志上', 13, 9, 32, '他们的亲族哥辖的子孙中，有管理陈设饼的，每安息日要预备摆设。'),
('CNV', '历代志上', 13, 9, 33, '这些是歌唱的人，是利未各家族的首领，住在殿院的房间里，不作别的事，日夜只顾自己的事工。'),
('CNV', '历代志上', 13, 9, 34, '以上这些人都是利未各家族的首领，按他们的家谱都是首领；这些人都住在耶路撒冷。'),
('CNV', '历代志上', 13, 9, 35, '住在基遍的有基遍的父亲耶利，他的妻子名叫玛迦。'),
('CNV', '历代志上', 13, 9, 36, '他的长子是亚伯顿，其余的是苏珥、基士、巴力、尼珥、拿答、'),
('CNV', '历代志上', 13, 9, 37, '基多、亚希约、撒迦利雅、米基罗。'),
('CNV', '历代志上', 13, 9, 38, '米基罗生示米暗。他们也和他们的亲族一同住在耶路撒冷，和他们的亲族为邻。'),
('CNV', '历代志上', 13, 9, 39, '尼珥生基士，基士生扫罗，扫罗生约拿单、麦基舒亚、亚比拿达和伊施．巴力。'),
('CNV', '历代志上', 13, 9, 40, '约拿单的儿子是米力．巴力；米力．巴力生米迦。'),
('CNV', '历代志上', 13, 9, 41, '米迦的儿子是毗敦、米勒、他利亚和亚哈斯。'),
('CNV', '历代志上', 13, 9, 42, '亚哈斯生雅拉；雅拉生亚拉篾、亚斯玛威和心利。心利生摩撒；'),
('CNV', '历代志上', 13, 9, 43, '摩撒生比尼亚；比尼亚的儿子是利法雅，利法雅的儿子是以利亚萨，以利亚萨的儿子是亚悉。'),
('CNV', '历代志上', 13, 9, 44, '亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难；这都是亚悉的儿子。'),
('CNV', '历代志上', 13, 10, 1, '非利士人攻打以色列人；以色列人从非利士人面前逃跑，在基利波山上阵亡的人很多。'),
('CNV', '历代志上', 13, 10, 2, '非利士人紧紧地追赶扫罗和他的儿子；非利士人杀了扫罗的儿子约拿单、亚比拿达和麦基舒亚。'),
('CNV', '历代志上', 13, 10, 3, '攻击扫罗的战役非常激烈；弓箭手发现了他，就把他射伤。'),
('CNV', '历代志上', 13, 10, 4, '扫罗对替他拿兵器的人说：“拔出你的刀来，把我刺透，免得这些未受割礼的人来凌辱我。”但替他拿兵器的人不肯这样作，因为他非常害怕；于是扫罗拿出刀来，自己伏在刀上死了。'),
('CNV', '历代志上', 13, 10, 5, '替他拿兵器的人看见扫罗死了，他也伏在刀上死了。'),
('CNV', '历代志上', 13, 10, 6, '这样，扫罗和他的三个儿子，以及他的全家，都一同死了。'),
('CNV', '历代志上', 13, 10, 7, '所有在山谷的以色列人，看见以色列军逃跑，扫罗和他的儿子都死了，他们就弃城逃跑，非利士人就来住在城中。'),
('CNV', '历代志上', 13, 10, 8, '第二天，非利士人来剥那些被杀的人的衣物的时候，发现扫罗和他的儿子都倒毙在基利波山上。'),
('CNV', '历代志上', 13, 10, 9, '他们就剥了他的衣服，拿了他的头和兵器，又派人到非利士地的各处，去向他们的偶像和人民报信。'),
('CNV', '历代志上', 13, 10, 10, '他们把扫罗的兵器放在他们的神庙里，把他的头挂在大衮庙中。'),
('CNV', '历代志上', 13, 10, 11, '基列．雅比人听见非利士人向扫罗所行的事，'),
('CNV', '历代志上', 13, 10, 12, '所有的勇士就动身，把扫罗的尸体和他儿子的尸体收殓起来，带回雅比，把他们的骸骨埋葬在雅比的橡树下，并且禁食七天。'),
('CNV', '历代志上', 13, 10, 13, '扫罗死了，因为他悖逆耶和华，没有听从他的话，也因为他去求问那交鬼的，'),
('CNV', '历代志上', 13, 10, 14, '没有求问耶和华，所以耶和华把他杀死了，把国位转给耶西的儿子大卫。'),
('CNV', '历代志上', 13, 11, 1, '那时，以色列众人聚集到希伯仑去见大卫，说：“看哪，我们原是你的骨肉。'),
('CNV', '历代志上', 13, 11, 2, '从前扫罗作王的时候，是你率领以色列人出入征战；耶和华你的神曾对你说过：‘你要牧养我的人民以色列，你要作我的人民以色列的领袖。’”'),
('CNV', '历代志上', 13, 11, 3, '于是以色列的众长老都来到希伯仑见大卫王，大卫就在希伯仑，在耶和华面前与他们立约，他们就按照耶和华藉着撒母耳所说的话，膏立大卫作王治理以色列。'),
('CNV', '历代志上', 13, 11, 4, '大卫和以色列众人来到耶路撒冷，耶路撒冷就是耶布斯。那时，当地的居民耶布斯人住在那里。'),
('CNV', '历代志上', 13, 11, 5, '耶布斯的居民对大卫说：“你不能进这里来。”可是大卫占领了锡安的堡垒，锡安就是大卫城。'),
('CNV', '历代志上', 13, 11, 6, '大卫说：“谁首先攻打耶布斯人，谁就必作首领和元帅。”洗鲁雅的儿子约押首先上去，就作了首领。'),
('CNV', '历代志上', 13, 11, 7, '大卫住在堡垒中，因此人把那堡垒称为大卫城。'),
('CNV', '历代志上', 13, 11, 8, '大卫又重建四周的城墙，从米罗起，以至城的周围；那城其余的部分由约押修建。'),
('CNV', '历代志上', 13, 11, 9, '大卫日渐强盛，因为万军之耶和华与他同在。'),
('CNV', '历代志上', 13, 11, 10, '以下这些人是大卫众勇士的首领，就是全力帮助他得国的，又与以色列人照着耶和华对以色列人所说的话一同立他作王。'),
('CNV', '历代志上', 13, 11, 11, '这是大卫众勇士的数目：哈革摩尼的儿子雅朔班，是军官的首领；他挥舞矛枪，只一次就杀死了三百人。'),
('CNV', '历代志上', 13, 11, 12, '其次是亚合人朵多的儿子以利亚撒，他是三勇士之一；'),
('CNV', '历代志上', 13, 11, 13, '他从前与大卫在巴斯．达闵，非利士人聚集在那里预备作战。那里有块长满大麦的田；众人从非利士人面前逃跑了。'),
('CNV', '历代志上', 13, 11, 14, '他们却站在那块田中间，保护了那块田，击杀了非利士人；这样耶和华拯救了以色列人，使他们获得极大的胜利。'),
('CNV', '历代志上', 13, 11, 15, '三十个首领中有三个，下到亚杜兰洞附近的磐石那里去见大卫；非利士人的军队在利乏音谷安营。'),
('CNV', '历代志上', 13, 11, 16, '那时大卫在山寨中，非利士人的驻军在伯利恒。'),
('CNV', '历代志上', 13, 11, 17, '大卫渴望说：“谁能把伯利恒城门旁边池中的水，拿来给我喝！”'),
('CNV', '历代志上', 13, 11, 18, '这三个勇士就冲过非利士人的军营，从伯利恒城门旁边的池里取水，带到大卫那里去，大卫却不肯喝，把水倾在耶和华面前，'),
('CNV', '历代志上', 13, 11, 19, '说：“在我的神面前，我绝对不可以这样作，我怎能喝这些冒生命危险的人的血呢？因为这是他们冒生命危险取回来的。”因此大卫不肯喝这水。这是三个勇士所行的事。'),
('CNV', '历代志上', 13, 11, 20, '约押的兄弟亚比筛，是三个勇士的首领；他挥舞矛枪刺死了三百人，因此在三个勇士中赢得了名声。'),
('CNV', '历代志上', 13, 11, 21, '他在这三个勇士中，是最尊贵的，所以作他们的首领；只是还不及前三个勇士。'),
('CNV', '历代志上', 13, 11, 22, '耶何耶大的儿子比拿雅，是甲薛族的勇士，曾有伟大的作为；他击杀了摩押人亚利伊勒的两个儿子，又在下雪的日子，下到坑中去击杀了一只狮子。'),
('CNV', '历代志上', 13, 11, 23, '他又杀死了一个身高两百多公分的埃及人。这埃及人手里拿着矛枪，好像织布机轴，比拿雅只拿着棍子下去会他，竟从那埃及人手中把矛枪夺了过来，再用他的矛枪把他杀死。'),
('CNV', '历代志上', 13, 11, 24, '这是耶何耶大的儿子比拿雅所行的事，因此在三个勇士中赢得名声。'),
('CNV', '历代志上', 13, 11, 25, '他比那三十个勇士更有声望，只是还不及前三个勇士。大卫立他作侍卫长。'),
('CNV', '历代志上', 13, 11, 26, '军中勇士有约押的兄弟亚撒黑、伯利恒人朵多的儿子伊勒哈难、'),
('CNV', '历代志上', 13, 11, 27, '哈如珥人沙玛、比伦人希利斯、'),
('CNV', '历代志上', 13, 11, 28, '提哥亚人益吉的儿子以拉、亚拿突人亚比以谢、'),
('CNV', '历代志上', 13, 11, 29, '户沙人亚比该、亚合人以来、'),
('CNV', '历代志上', 13, 11, 30, '尼陀法人玛哈莱、尼陀法人巴拿的儿子希立、'),
('CNV', '历代志上', 13, 11, 31, '便雅悯子孙基比亚人利拜的儿子以太、比拉顿人比拿雅、'),
('CNV', '历代志上', 13, 11, 32, '来自迦实溪的户莱、亚拉巴人亚比、'),
('CNV', '历代志上', 13, 11, 33, '巴路米人押斯玛弗、沙本人以利雅哈巴、'),
('CNV', '历代志上', 13, 11, 34, '基孙人哈深的众子，哈拉人沙基的儿子约拿单，'),
('CNV', '历代志上', 13, 11, 35, '哈拉人沙甲的儿子亚希暗、吾珥的儿子以利法勒，'),
('CNV', '历代志上', 13, 11, 36, '米基拉人希弗、比伦人亚希雅、'),
('CNV', '历代志上', 13, 11, 37, '迦密人希斯罗、伊斯拜的儿子拿莱、'),
('CNV', '历代志上', 13, 11, 38, '拿单的兄弟约珥、哈基利的儿子弥伯哈、'),
('CNV', '历代志上', 13, 11, 39, '亚扪人洗勒、比录人拿哈莱；拿哈莱是替洗鲁雅的儿子约押拿兵器的。'),
('CNV', '历代志上', 13, 11, 40, '以帖人以拉、以帖人迦立、'),
('CNV', '历代志上', 13, 11, 41, '赫人乌利亚、亚莱的儿子撒拔、'),
('CNV', '历代志上', 13, 11, 42, '流本支派示撒的儿子亚第拿，他是流本支派的一个首领，有三十人跟随他。'),
('CNV', '历代志上', 13, 11, 43, '玛迦的儿子哈难、弥特尼人约沙法、'),
('CNV', '历代志上', 13, 11, 44, '亚施他拉人乌西亚、亚罗珥人何坦的儿子沙玛和耶利、'),
('CNV', '历代志上', 13, 11, 45, '提洗人申利的儿子耶叠和他的兄弟约哈、'),
('CNV', '历代志上', 13, 11, 46, '玛哈未人以利业、伊利拿安的儿子耶利拜和约沙未雅、摩押人伊特玛、'),
('CNV', '历代志上', 13, 11, 47, '以利业、俄备得和米琐八人雅西业。'),
('CNV', '历代志上', 13, 12, 1, '大卫因为基士的儿子扫罗的缘故，躲在洗革拉的时候，以下这些人就来到大卫那里；他们都是勇士，在战争中帮助他。'),
('CNV', '历代志上', 13, 12, 2, '他们配备弓箭，能用左右两手开弓甩石射箭；他们都属便雅悯支派，是扫罗的亲族。'),
('CNV', '历代志上', 13, 12, 3, '他们的首领是亚希以谢，其次是约阿施，都是基比亚人示玛的儿子；还有亚斯玛威的儿子耶薛和毗力；又有比拉迦和亚拿突人耶户，'),
('CNV', '历代志上', 13, 12, 4, '以及基遍人以实买雅，他在三十人中是个勇士，并且统领那三十人，又有耶利米、雅哈悉、约哈难和基得拉人约撒拔（“又有耶利米⋯⋯约撒拔”在《马索拉文本》为12:5）、'),
('CNV', '历代志上', 13, 12, 5, '伊利乌赛、耶利摩、比亚利雅、示玛利雅、哈律弗人示法提雅；（本节在《马索拉文本》为12:6）'),
('CNV', '历代志上', 13, 12, 6, '可拉人有以利加拿、耶西亚、亚萨列、约以谢和雅朔班、'),
('CNV', '历代志上', 13, 12, 7, '基多人耶罗罕的儿子犹拉和西巴第雅。'),
('CNV', '历代志上', 13, 12, 8, '迦得支派中，有些人走到旷野的山寨去投奔大卫，他们都是英勇的战士，善于作战，能使用盾牌和长枪；他们的面貌好像狮子，他们敏捷得好像山上的羚羊。'),
('CNV', '历代志上', 13, 12, 9, '第一个是以薛，第二是俄巴底雅，第三是以利押，'),
('CNV', '历代志上', 13, 12, 10, '第四是弥施玛拿，第五是耶利米，'),
('CNV', '历代志上', 13, 12, 11, '第六是亚太，第七是以利业，'),
('CNV', '历代志上', 13, 12, 12, '第八是约哈难，第九是以利萨巴，'),
('CNV', '历代志上', 13, 12, 13, '第十是耶利米，第十一是末巴奈。'),
('CNV', '历代志上', 13, 12, 14, '这些都是迦得支派中的军长，最小的一个能抵挡一百人，最大的一个能抵挡一千人。'),
('CNV', '历代志上', 13, 12, 15, '在正月，约旦河水涨过两岸的时候，这些人过了河，使全平原的人都东奔西逃。'),
('CNV', '历代志上', 13, 12, 16, '便雅悯支派和犹大支派中也有人来到山寨投奔大卫。'),
('CNV', '历代志上', 13, 12, 17, '大卫出去迎见他们，对他们说：“你们若是存着和平的心到我这里来帮助我，我就与你们结盟，但你们若是把我这无辜的人出卖给我的敌人，就愿我们列祖的神鉴察和审判。”'),
('CNV', '历代志上', 13, 12, 18, '当时，神的灵降在那三十个勇士的首领亚玛撒身上，他就说：“大卫啊，我们是来归从你；耶西的儿子啊，我们是来跟随你；愿你平平安安，愿帮助你的人也都平安，因为你的神帮助了你。”于是大卫收留了他们，立他们作军长。'),
('CNV', '历代志上', 13, 12, 19, '大卫从前与非利士人一起，要去攻击扫罗的时候，有些玛拿西支派的人投奔大卫；但他们没有帮助非利士人，因为非利士人的领袖商议后把他遣回，说：“恐怕大卫带着我们的首级归向他的主人扫罗。”'),
('CNV', '历代志上', 13, 12, 20, '大卫回到洗革拉的时候，玛拿西支派的押拿、约撒拔、耶叠、米迦勒、约撒拔、以利户、洗勒太来投奔他，他们都是玛拿西支派中的千夫长。'),
('CNV', '历代志上', 13, 12, 21, '他们帮助大卫，与他一同攻击贼匪；他们全是英勇的战士，是军队的领袖。'),
('CNV', '历代志上', 13, 12, 22, '那时，天天都有人投奔大卫，要帮助他，以致成了一支大军，好像神的军兵一样。'),
('CNV', '历代志上', 13, 12, 23, '预备作战的首领来到希伯仑见大卫，要照着耶和华的命令把扫罗的国位转归大卫，他们的数目如下：'),
('CNV', '历代志上', 13, 12, 24, '犹大支派的子孙拿盾牌和长枪的，共有六千八百人，都预备好作战。'),
('CNV', '历代志上', 13, 12, 25, '西缅支派的子孙能作战的英勇战士，共有七千一百人。'),
('CNV', '历代志上', 13, 12, 26, '利未支派的子孙中，共有四千六百人。'),
('CNV', '历代志上', 13, 12, 27, '耶何耶大是亚伦家的领袖，跟随他的，共有三千七百人。'),
('CNV', '历代志上', 13, 12, 28, '还有一个年轻的英勇战士撒督和他家族的二十二个领袖。'),
('CNV', '历代志上', 13, 12, 29, '便雅悯支派的子孙中，扫罗的亲族也有三千人，直到现在他们多半支持扫罗家。'),
('CNV', '历代志上', 13, 12, 30, '以法莲支派的子孙中，在自己家族中有名声的英勇的战士，共有二万零八百人。'),
('CNV', '历代志上', 13, 12, 31, '玛拿西半个支派中有记名的，共一万八千人，都来拥立大卫为王。'),
('CNV', '历代志上', 13, 12, 32, '以萨迦支派的子孙中，通晓时势和知道以色列当怎样行的，共有二百个首领；他们所有的亲族都听从他们的命令。'),
('CNV', '历代志上', 13, 12, 33, '西布伦支派的子孙中，能出去作战、可以使用各种兵器，行军整齐、不生二心的，共有五万人。'),
('CNV', '历代志上', 13, 12, 34, '拿弗他利支派的子孙中，有一千个领袖；跟随他们拿着盾牌和矛枪的，共有三万七千人。'),
('CNV', '历代志上', 13, 12, 35, '但支派的子孙中能作战的，共有二万八千六百人。'),
('CNV', '历代志上', 13, 12, 36, '亚设支派的子孙中，能出去上阵作战的，共有四万人。'),
('CNV', '历代志上', 13, 12, 37, '在约旦河东岸，流本支派、迦得支派和玛拿西半个支派的人中，能拿各种兵器作战的，共有十二万。'),
('CNV', '历代志上', 13, 12, 38, '以上这些战士，行军齐整，一心一意来到希伯仑，要立大卫作以色列王；其余的以色列人也都一心一意要立大卫为王。'),
('CNV', '历代志上', 13, 12, 39, '他们在那里三天，与大卫在一起吃喝，因为他们的亲族给他们预备好了。'),
('CNV', '历代志上', 13, 12, 40, '在他们附近的人，甚至以萨迦、西布伦和拿弗他利支派的人，都用驴、骆驼、骡子和牛，给他们带来了很多食物：面饼、无花果饼、葡萄饼干、酒、油和许多牛羊，以色列全境就充满欢乐。'),
('CNV', '历代志上', 13, 13, 1, '大卫与千夫长、百夫长和所有的领袖商议。'),
('CNV', '历代志上', 13, 13, 2, '然后大卫对以色列全体会众说：“你们如果认为好，认为这事是出于耶和华我们的神，我们就差遣人走遍各地，去见留在以色列各地的兄弟，以及和他们在一起住在那些有草场的城的祭司和利未人，叫他们都聚集到我们这里来。'),
('CNV', '历代志上', 13, 13, 3, '我们可以把我们神的约柜运到我们这里来，因为在扫罗的日子，我们都没有在约柜前求问神。”'),
('CNV', '历代志上', 13, 13, 4, '全体会众都同意这样行，因为这事众人都认为对。'),
('CNV', '历代志上', 13, 13, 5, '于是大卫把以色列众人，从埃及的西曷河直到哈马口，都招聚来，要把神的约柜从基列．耶琳运来。'),
('CNV', '历代志上', 13, 13, 6, '大卫和以色列众人去到巴拉，就是属犹大的基列．耶琳，要从那里把神的约柜运回来；这约柜是以坐在二基路伯上面的耶和华而起名的。'),
('CNV', '历代志上', 13, 13, 7, '他们把神的约柜，从亚比拿达家里抬出来，放在一辆新车上，乌撒和亚希约负责赶车。'),
('CNV', '历代志上', 13, 13, 8, '大卫和以色列众人在神面前，用诗歌，以及弹琴鼓瑟、敲手鼓、响钹和吹号，尽情欢庆。'),
('CNV', '历代志上', 13, 13, 9, '他们到了基顿禾场的时候，因为牛失蹄绊倒，乌撒就伸手扶住约柜。'),
('CNV', '历代志上', 13, 13, 10, '于是耶和华向乌撒发怒，因为乌撒伸手把约柜扶住，所以神把他击杀，他就在那里死在神面前。'),
('CNV', '历代志上', 13, 13, 11, '大卫因耶和华忽然杀死乌撒，非常不悦，就称那地方为毗列斯．乌撒，直到今日。'),
('CNV', '历代志上', 13, 13, 12, '那天，大卫惧怕神，说：“我怎可以把神的约柜运到我这里来呢？”'),
('CNV', '历代志上', 13, 13, 13, '所以，大卫没有把约柜运到大卫城他自己那里去，却转运到迦特人俄别．以东的家里去。'),
('CNV', '历代志上', 13, 13, 14, '神的约柜存放在俄别．以东的家里三个月，耶和华赐福给俄别．以东的家和他的一切。'),
('CNV', '历代志上', 13, 14, 1, '推罗王希兰派使者来见大卫，给他送上香柏木、石匠和木匠，要为他建造宫殿。'),
('CNV', '历代志上', 13, 14, 2, '那时，大卫知道耶和华已经坚立他作王统治以色列，又为了以色列民的缘故，使他的国高举。'),
('CNV', '历代志上', 13, 14, 3, '大卫在耶路撒冷又娶了多位妻子，并且生了很多儿女。'),
('CNV', '历代志上', 13, 14, 4, '以下这些就是他在耶路撒冷所生的孩子的名字：沙母亚、朔罢、拿单、所罗门、'),
('CNV', '历代志上', 13, 14, 5, '益辖、以利书亚、以法列、'),
('CNV', '历代志上', 13, 14, 6, '挪迦、尼斐、雅非亚、'),
('CNV', '历代志上', 13, 14, 7, '以利沙玛、以利雅大和以利法列。'),
('CNV', '历代志上', 13, 14, 8, '非利士人听见了大卫受膏作王统治以色列人，就全体上来搜寻大卫；大卫听见了，就出来迎击他们。'),
('CNV', '历代志上', 13, 14, 9, '非利士人来到，侵进了利乏音谷。'),
('CNV', '历代志上', 13, 14, 10, '大卫求问神说：“我可以上去攻打非利士人吗？你把他们交在我手里吗？”耶和华对他说：“你可以上去，我必把他们交在你的手里。”'),
('CNV', '历代志上', 13, 14, 11, '非利士人上到巴力．毗拉心来，大卫在那里击败了他们。大卫说：“神藉着我击溃我的敌人，好像水冲破堤岸一般。”因此他们给那地方起名叫巴力．毗拉心。'),
('CNV', '历代志上', 13, 14, 12, '非利士人把他们的神像遗弃在那里，大卫吩咐人用火把它们烧了。'),
('CNV', '历代志上', 13, 14, 13, '非利士人又再入侵那山谷。'),
('CNV', '历代志上', 13, 14, 14, '大卫又求问神，神对他说：“不可在后面追赶他们，要绕过他们，从桑林对面攻打他们。'),
('CNV', '历代志上', 13, 14, 15, '你一听见桑林树梢上有脚步的声音，就要出战，因为神已经在你前面出去击杀非利士人的军队了。”'),
('CNV', '历代志上', 13, 14, 16, '于是大卫照着神所吩咐他的去作，他们攻击非利士人的军队，从基遍起，一直攻打到基色。'),
('CNV', '历代志上', 13, 14, 17, '因此大卫的名声传遍各地，耶和华使万国都惧怕他。'),
('CNV', '历代志上', 13, 15, 1, '大卫在大卫城为自己建造宫殿，又为神的约柜预备地方，就是为它支搭帐幕。'),
('CNV', '历代志上', 13, 15, 2, '那时大卫说：“神的约柜，除了利未人以外，没有人可以抬，因为耶和华拣选了他们抬神的约柜，并且永远事奉他。”'),
('CNV', '历代志上', 13, 15, 3, '于是，大卫把以色列人都招聚到耶路撒冷，要把耶和华的约柜抬上来，到大卫给它预备好的地方去。'),
('CNV', '历代志上', 13, 15, 4, '大卫又聚集了亚伦的子孙和利未人：'),
('CNV', '历代志上', 13, 15, 5, '哥辖子孙中有作领袖的乌列和他的亲族一百二十人；'),
('CNV', '历代志上', 13, 15, 6, '米拉利子孙中有作领袖的亚帅雅和他的亲族二百二十人；'),
('CNV', '历代志上', 13, 15, 7, '革顺的子孙中有作领袖的约珥和他的亲族一百三十人；'),
('CNV', '历代志上', 13, 15, 8, '以利撒反的子孙中有作领袖的示玛雅和他的亲族二百人；'),
('CNV', '历代志上', 13, 15, 9, '希伯仑子孙中有作领袖的以列和他的亲族八十人；'),
('CNV', '历代志上', 13, 15, 10, '乌薛子孙中有作领袖的亚米拿达和他的亲族一百一十二人。'),
('CNV', '历代志上', 13, 15, 11, '大卫把撒督和亚比亚他两位祭司，以及乌列、亚帅雅、约珥、示玛雅、以列和亚米拿达几位利未人，召了来，'),
('CNV', '历代志上', 13, 15, 12, '对他们说：“你们是利未人各家族的首领，你们和你们的亲族都要自洁，好把以色列的神耶和华的约柜抬上来，到我为它预备的地方去。'),
('CNV', '历代志上', 13, 15, 13, '先前没有你们，耶和华我们的神就击打我们，因为我们没有按照定例寻求他。”'),
('CNV', '历代志上', 13, 15, 14, '于是祭司和利未人自洁，好把以色列的神耶和华的约柜抬上来。'),
('CNV', '历代志上', 13, 15, 15, '利未支派的子孙照着耶和华的话，就是摩西所吩咐的，用肩和杠来抬神的约柜。'),
('CNV', '历代志上', 13, 15, 16, '大卫又吩咐利未支派的领袖，要指派他们的亲族负责歌唱，用琴瑟响钹各种乐器，欢欢喜喜高声歌唱。'),
('CNV', '历代志上', 13, 15, 17, '于是利未人指派了约珥的儿子希幔和他的亲族中比利家的儿子亚萨，以及他们的亲族米拉利的子孙中古沙雅的儿子以探。'),
('CNV', '历代志上', 13, 15, 18, '和他们一起的还有作第二班的，他们的亲族：撒迦利雅、便、雅薛、示米拉末、耶歇、乌尼、以利押、比拿雅、玛西雅、玛他提雅、以利斐利户、弥克尼雅，以及守门的俄别．以东和耶利。'),
('CNV', '历代志上', 13, 15, 19, '歌唱的希幔、亚萨和以探敲打铜钹，发出响亮的声音；'),
('CNV', '历代志上', 13, 15, 20, '撒迦利雅、雅薛、示米拉末、耶歇、乌尼、以利押、玛西雅和比拿雅敲瑟，调用女高音；'),
('CNV', '历代志上', 13, 15, 21, '玛他提雅、以利斐利户、弥克尼雅、俄别．以东、耶利和亚撒西雅弹琴领导，调用男低音。'),
('CNV', '历代志上', 13, 15, 22, '利未支派的领袖基拿尼雅专责音乐，又教人音乐，因为他精通音乐。'),
('CNV', '历代志上', 13, 15, 23, '比利家、以利加拿作看守约柜的人。'),
('CNV', '历代志上', 13, 15, 24, '示巴尼、约沙法、拿坦业、亚玛赛、撒迦利雅、比拿亚和以利以谢几位祭司，在神的约柜前吹号；俄别．以东和耶希亚也作看守约柜的人。'),
('CNV', '历代志上', 13, 15, 25, '于是大卫和以色列的众长老，以及千夫长一起前去，从俄别．以东的家欢欢喜喜地把耶和华的约柜抬上来。'),
('CNV', '历代志上', 13, 15, 26, '神帮助了那些抬耶和华约柜的利未人，他们就献上七头公牛和七只公绵羊。'),
('CNV', '历代志上', 13, 15, 27, '大卫和所有抬约柜的利未人，以及歌唱的人和歌唱的人的领袖基拿尼雅，都穿上细麻布的外袍；大卫另外穿上细麻布的以弗得。'),
('CNV', '历代志上', 13, 15, 28, '这样，以色列人欢呼、吹角、吹号、敲钹、鼓瑟、弹琴，大声奏乐，把耶和华的约柜抬了上来。'),
('CNV', '历代志上', 13, 15, 29, '耶和华的约柜进了大卫城的时候，扫罗的女儿米甲从窗户往下观看，看见大卫王跳跃嬉笑，心里就鄙视他。'),
('CNV', '历代志上', 13, 16, 1, '他们把神的约柜抬了进去，安放在大卫为它所搭的会幕中间，然后在神面前献上了燔祭和平安祭。'),
('CNV', '历代志上', 13, 16, 2, '大卫献上了燔祭和平安祭以后，就奉耶和华的名给人民祝福。'),
('CNV', '历代志上', 13, 16, 3, '他又分给以色列众人，无论男女，每人一个饼、一块肉、一个葡萄饼。'),
('CNV', '历代志上', 13, 16, 4, '大卫派了一部分利未人，在耶和华的约柜前事奉、颂扬、称谢和赞美耶和华以色列的神。'),
('CNV', '历代志上', 13, 16, 5, '领导的人是亚萨，其次是撒迦利雅、耶利、示米拉末、耶歇、玛他提雅、以利押、比拿雅、俄别．以东和耶利，他们鼓瑟弹琴，亚萨敲打响钹。'),
('CNV', '历代志上', 13, 16, 6, '比拿雅和雅哈悉两位祭司在神的约柜前不住地吹号。'),
('CNV', '历代志上', 13, 16, 7, '那一天，大卫初次指定亚萨和他的亲族，以诗歌称谢耶和华，说：'),
('CNV', '历代志上', 13, 16, 8, '“你们要称谢耶和华，呼求他的名，在万民中宣扬他的作为。'),
('CNV', '历代志上', 13, 16, 9, '要向他歌唱，向他颂扬，述说他一切奇妙的作为。'),
('CNV', '历代志上', 13, 16, 10, '要以他的圣名为荣，愿寻求耶和华的人，心中喜乐。'),
('CNV', '历代志上', 13, 16, 11, '要寻求耶和华和他的能力，常常寻求他的面。'),
('CNV', '历代志上', 13, 16, 12, '他的仆人以色列的后裔啊，他所拣选的雅各的子孙啊，你们要记念他奇妙的作为、他的奇事和他口中的判语。'),
('CNV', '历代志上', 13, 16, 14, '他是耶和华我们的神，他的判语达到全地。'),
('CNV', '历代志上', 13, 16, 15, '你们要记念他的约，直到永远；不可忘记他吩咐的话，直到千代。'),
('CNV', '历代志上', 13, 16, 16, '就是他与亚伯拉罕所立的约，他向以撒所起的誓。'),
('CNV', '历代志上', 13, 16, 17, '他把这约向雅各定为律例，向以色列定为永约，'),
('CNV', '历代志上', 13, 16, 18, '说：‘我必把迦南地赐给你，作你们的产业的分。'),
('CNV', '历代志上', 13, 16, 19, '那时你们人丁单薄，数目很少，又是在那地作寄居的。’'),
('CNV', '历代志上', 13, 16, 20, '他们从这国走到那国，从一族走到另一族。'),
('CNV', '历代志上', 13, 16, 21, '耶和华不容许任何人欺压他们，曾为了他们的缘故责备君王，'),
('CNV', '历代志上', 13, 16, 22, '说：‘不可伤害我所膏的人，不可恶待我的先知。’'),
('CNV', '历代志上', 13, 16, 23, '全地都要向耶和华歌唱，天天传扬他的救恩。'),
('CNV', '历代志上', 13, 16, 24, '在列国中述说他的荣耀，在万民中述说他奇妙的作为。'),
('CNV', '历代志上', 13, 16, 25, '因为耶和华是伟大的，当受极大的赞美；他当受敬畏，远在万神之上。'),
('CNV', '历代志上', 13, 16, 26, '万民的偶像算不得什么，唯独耶和华创造诸天。'),
('CNV', '历代志上', 13, 16, 27, '尊荣和威严在他面前，能力和欢乐在他的圣所。'),
('CNV', '历代志上', 13, 16, 28, '万族万民啊，你们要归给耶和华，要把荣耀和能力归给耶和华。'),
('CNV', '历代志上', 13, 16, 29, '要把耶和华的名应得的荣耀归给他，拿着礼物到他面前来，要以圣洁的装饰敬拜耶和华。'),
('CNV', '历代志上', 13, 16, 30, '全地要在他面前战栗；他使世界坚定，不致摇动。'),
('CNV', '历代志上', 13, 16, 31, '愿天欢喜，愿地欢呼，愿人在万国中说：‘耶和华作王了！’'),
('CNV', '历代志上', 13, 16, 32, '愿海和充满海中的都澎湃，愿田和田中的一切都欢欣。'),
('CNV', '历代志上', 13, 16, 33, '那时树林中的树木，必在耶和华面前欢呼，因为他来要审判全地。'),
('CNV', '历代志上', 13, 16, 34, '你们要称谢耶和华，因他是良善的，他的慈爱永远常存。'),
('CNV', '历代志上', 13, 16, 35, '你们要说：‘拯救我们的神啊，求你拯救我们，招聚我们，从万国中救我们出来，好使我们称谢你的圣名，以赞美你为夸耀。’'),
('CNV', '历代志上', 13, 16, 36, '耶和华以色列的神是应当称颂的，从永远直到永远。”全体人民都说阿们，并且赞美耶和华。'),
('CNV', '历代志上', 13, 16, 37, '于是在那里，就是耶和华的约柜前，大卫留下亚萨和他的亲族，照着每日的本分，在约柜前不断地事奉。'),
('CNV', '历代志上', 13, 16, 38, '又留下俄别．以东和他们的亲族六十八人，以及耶杜顿的儿子俄别．以东和何萨作守门的。'),
('CNV', '历代志上', 13, 16, 39, '又留下撒督祭司和他的亲族，都是作祭司的。在基遍的高地主的帐幕前，'),
('CNV', '历代志上', 13, 16, 40, '每日早晚不住地在燔祭坛上，把燔祭献给耶和华，全是照着耶和华吩咐以色列人的律法书上所写的。'),
('CNV', '历代志上', 13, 16, 41, '和他们一起的有希幔、耶杜顿和其余被选出，有记名的人，都称谢耶和华，因为他的慈爱永远常存。'),
('CNV', '历代志上', 13, 16, 42, '希幔、耶杜顿和他们一起吹号敲钹，以及演奏各种乐器，大声歌颂神。耶杜顿的子孙负责守门。'),
('CNV', '历代志上', 13, 16, 43, '于是众民都回去，各人回自己的家；大卫也回去给自己的家人祝福。'),
('CNV', '历代志上', 13, 17, 1, '大卫住在自己宫中的时候，他对拿单先知说：“看哪，我住在香柏木做的王宫，耶和华的约柜却在帐幕里。”'),
('CNV', '历代志上', 13, 17, 2, '拿单对大卫说：“你可以照你的心意去作，因为神与你同在。”'),
('CNV', '历代志上', 13, 17, 3, '当夜，神的话临到拿单，说：'),
('CNV', '历代志上', 13, 17, 4, '“你去对我的仆人大卫说：‘耶和华这样说：你不可建殿给我居住。'),
('CNV', '历代志上', 13, 17, 5, '因为自从我领以色列人上来那天起，直到今日，我都未曾住过殿宇，只是从这帐幕到那帐幕，从这帐棚到那帐棚。'),
('CNV', '历代志上', 13, 17, 6, '我和以色列众人，无论走到什么地方，从没有向以色列的哪一个士师，就是我所吩咐牧养我的子民的，说：你们为什么不给我建造香柏木的殿宇呢？’'),
('CNV', '历代志上', 13, 17, 7, '现在你要对我的仆人大卫说：‘万军之耶和华这样说：我把你从羊圈中选召出来，使你不再跟随羊群，使你作领袖管治我的子民以色列。'),
('CNV', '历代志上', 13, 17, 8, '无论你到哪里去，我总与你同在；在你面前消灭你所有的仇敌；我必使你获得名声，好像世上伟人的名声一样。'),
('CNV', '历代志上', 13, 17, 9, '我要为我的子民以色列人选定一个地方，栽培他们，使他们住在自己的地方，不再受搅扰，也不再像从前被恶徒苦害他们，'),
('CNV', '历代志上', 13, 17, 10, '好像我吩咐士师统治我的子民以色列人的日子一样。我必制伏你所有的仇敌，并且我告诉你，耶和华必为你建立家室。'),
('CNV', '历代志上', 13, 17, 11, '你的寿数满足，归你列祖那里的时候，我必兴起你的后裔接替你，他是你的众子中的一位；我必坚立他的国。'),
('CNV', '历代志上', 13, 17, 12, '他要为我建造殿宇，我必坚立他的王位，直到永远。'),
('CNV', '历代志上', 13, 17, 13, '我要作他的父亲，他要作我的儿子；我的慈爱必不离开他，像离开在你以前的那位一样；'),
('CNV', '历代志上', 13, 17, 14, '我却要把他坚立在我的家里和我的国里，直到永远；他的王位必永远坚立。’”'),
('CNV', '历代志上', 13, 17, 15, '拿单就按着这一切话和他所见的一切，告诉了大卫。'),
('CNV', '历代志上', 13, 17, 16, '于是大卫王进去，坐在耶和华面前，说：“耶和华神啊，我是什么人？我的家算什么，你竟带领我到这个地步？'),
('CNV', '历代志上', 13, 17, 17, '神啊，这在你眼中看为小事，你对你仆人的家的未来发出应许！耶和华神啊，你看我好像一个高贵的人。'),
('CNV', '历代志上', 13, 17, 18, '你把荣耀加在你仆人身上，我还有什么话可以对你说呢？你认识你的仆人。'),
('CNV', '历代志上', 13, 17, 19, '耶和华啊，为了你仆人的缘故，也是按着你的心意，你行了这一切大事，为要使人知道这一切大事。'),
('CNV', '历代志上', 13, 17, 20, '耶和华啊，照着我们耳中所听见的，没有谁能与你相比；除你以外，再没有别的神。'),
('CNV', '历代志上', 13, 17, 21, '世上有哪一个国能比得上你的子民以色列呢？神亲自把他们救赎出来，作自己的子民，又在你从埃及所救赎出来的子民面前驱逐列国，以大而可畏的事建立自己的名。'),
('CNV', '历代志上', 13, 17, 22, '你使你的子民以色列永远作你的子民；耶和华啊，你也作了他们的神。'),
('CNV', '历代志上', 13, 17, 23, '耶和华啊，现在求你永远坚立你应许你仆人和他的家的话，照着你所说的实行吧。'),
('CNV', '历代志上', 13, 17, 24, '愿你的名永远坚立、尊大，以致人人都说：‘万军之耶和华以色列的神，实在是以色列人的神。’这样，你仆人大卫的家就在你面前得到坚立了。'),
('CNV', '历代志上', 13, 17, 25, '我的神啊，因为你启示了你的仆人，说要为他建立王朝（“王朝”直译作“家”），所以你仆人才敢在你面前这样祷告。'),
('CNV', '历代志上', 13, 17, 26, '耶和华啊，唯有你是神，你曾应许把这福气赐给你的仆人；'),
('CNV', '历代志上', 13, 17, 27, '现在请你赐福你仆人的家，使它在你面前永远存留。耶和华啊，因为你已经赐福了你仆人的家，它必永远蒙福。”'),
('CNV', '历代志上', 13, 18, 1, '这事以后，大卫攻打非利士人，征服了他们，从非利士人手中夺了迦特和属于迦特的村庄。'),
('CNV', '历代志上', 13, 18, 2, '又攻打摩押，摩押人就归服大卫，给他进贡。'),
('CNV', '历代志上', 13, 18, 3, '琐巴王哈大底谢到幼发拉底河去，要建立自己的势力的时候，大卫就攻打他，直到哈马。'),
('CNV', '历代志上', 13, 18, 4, '大卫掳获了他的战车一千辆，马兵七千，步兵二万名。大卫把所有战车的马的蹄筋都砍断，只留下一百辆战车的马（“大卫把所有战车的马的蹄筋都砍断，只留下一百辆战车的马”或译：“大卫毁坏了所有战车，只留下一百辆战车”）。'),
('CNV', '历代志上', 13, 18, 5, '大马士革的亚兰人来帮助琐巴王哈大底谢的时候，大卫就杀了二万二千名亚兰人。'),
('CNV', '历代志上', 13, 18, 6, '于是大卫在大马士革的亚兰地驻军，亚兰人就臣服大卫，给他进贡。大卫无论到什么地方去，耶和华都使他得胜。'),
('CNV', '历代志上', 13, 18, 7, '大卫夺取了哈大底谢臣仆所拿的金盾牌，带回耶路撒冷。'),
('CNV', '历代志上', 13, 18, 8, '大卫又从属于哈大底谢的提巴和均二城中，夺取了大量的铜；后来所罗门用这些铜来制造铜海、铜柱和一切铜器。'),
('CNV', '历代志上', 13, 18, 9, '哈马王陀乌听见大卫击败了琐巴王哈大底谢的全军，'),
('CNV', '历代志上', 13, 18, 10, '就差派自己的儿子哈多兰去见大卫王，给他问安，祝贺他，因为他与哈大底谢交战，击败了哈大底谢。原来陀乌与哈大底谢常有争战。哈多兰送来了各样金、银、铜制的器皿。'),
('CNV', '历代志上', 13, 18, 11, '大卫王把这些器皿，连同从各国夺取的金银，就是从以东、摩押、亚扪人、非利士人和亚玛力人夺取的，都分别为圣献给耶和华。'),
('CNV', '历代志上', 13, 18, 12, '洗鲁雅的儿子亚比筛在盐谷击杀了以东人一万八千名。'),
('CNV', '历代志上', 13, 18, 13, '大卫在以东设立驻防营，所有以东人就都臣服大卫。大卫无论到什么地方去，耶和华都使他得胜。'),
('CNV', '历代志上', 13, 18, 14, '大卫作王统治全以色列，以公平和正义对待所有的人。'),
('CNV', '历代志上', 13, 18, 15, '洗鲁雅的儿子约押作军队的元帅，亚希律的儿子约沙法作史官，'),
('CNV', '历代志上', 13, 18, 16, '亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长，沙威沙作书记；'),
('CNV', '历代志上', 13, 18, 17, '耶何耶大的儿子比拿雅统管基利提人和比利提人；大卫的众子都在王的左右作领袖。'),
('CNV', '历代志上', 13, 19, 1, '后来，亚扪人的王拿辖死了，他的儿子接续他作王。'),
('CNV', '历代志上', 13, 19, 2, '大卫说：“我要恩待拿辖的儿子哈嫩，因为他的父亲曾恩待我。”于是大卫差派使者去为了他丧父的事安慰他。大卫的臣仆到了亚扪人境内，去见哈嫩要安慰他。'),
('CNV', '历代志上', 13, 19, 3, '但亚扪人的众领袖对哈嫩说：“大卫差派这些慰问的人到你这里来，你以为他是尊敬你父亲吗？他的臣仆来见你，不是为了窥探、倾覆、侦察这地吗？”'),
('CNV', '历代志上', 13, 19, 4, '于是，哈嫩拿住大卫的臣仆，剃去他们的胡须，又把他们的衣服，从臀部以下割去半截，然后才放他们走。'),
('CNV', '历代志上', 13, 19, 5, '有人去把这些人遭遇的事告诉大卫，他就派人去迎接他们；因为他们非常羞耻，王就说：“你们可以住在耶利哥，等到你们的胡须长长了才回来。”'),
('CNV', '历代志上', 13, 19, 6, '亚扪人看见自己与大卫结了仇恨，哈嫩和亚扪人就派人用三万公斤银子，从米所波大米、亚兰玛迦和琐巴去雇战车和马兵。'),
('CNV', '历代志上', 13, 19, 7, '他们雇了三万二千辆战车，以及玛迦王和他的军队；他们都来在米底巴前面安营。亚扪人也从他们的各城聚集起来，出来作战。'),
('CNV', '历代志上', 13, 19, 8, '大卫听见了，就差派约押和全体勇士出去。'),
('CNV', '历代志上', 13, 19, 9, '亚扪人出来，在城门前摆阵；前来助阵的列王，也在田野摆阵。'),
('CNV', '历代志上', 13, 19, 10, '约押看见自己前后受敌，就从以色列所有的精兵中，挑选一部分出来，使他们摆阵去迎战亚兰人，'),
('CNV', '历代志上', 13, 19, 11, '他把其余的人交在他兄弟亚比筛手下，使他们摆阵去迎战亚扪人。'),
('CNV', '历代志上', 13, 19, 12, '约押对亚比筛说：“如果亚兰人比我强，你就来帮助我；如果亚扪人比你强，我就去帮助你。'),
('CNV', '历代志上', 13, 19, 13, '你当刚强；为了我们的人民和我们神的众城镇，我们要刚强；愿耶和华成全他看为美的行事。”'),
('CNV', '历代志上', 13, 19, 14, '于是约押和他的军队前进，预备作战攻打亚兰人；亚兰人却在约押面前逃跑了。'),
('CNV', '历代志上', 13, 19, 15, '亚扪人看见亚兰人逃跑，他们也在约押的兄弟亚比筛面前逃跑，退回城里。约押就回耶路撒冷去了。'),
('CNV', '历代志上', 13, 19, 16, '亚兰人看见自己在以色列人面前被打败，就差派使者去把大河那边的亚兰人调过来，有哈大底谢的元帅朔法率领他们。'),
('CNV', '历代志上', 13, 19, 17, '大卫得到报告，就招聚以色列众人，渡过约旦河，来到亚兰人那里，向他们摆阵。大卫摆好阵迎战亚兰人，亚兰人就与他交战。'),
('CNV', '历代志上', 13, 19, 18, '亚兰人在以色列人面前逃跑；大卫杀了亚兰人七千辆战车上的军兵和四万步兵。又杀了亚兰人的元帅朔法。'),
('CNV', '历代志上', 13, 19, 19, '哈大底谢的臣仆看见自己在以色列人面前被打败了，就与大卫议和，臣服了他；于是亚兰人不敢再帮助亚扪人。'),
('CNV', '历代志上', 13, 20, 1, '过了年，在列王出征的时候，约押带领军兵，毁坏了亚扪人的地方，然后去围困拉巴。那时大卫住在耶路撒冷。约押攻打拉巴，把城摧毁。'),
('CNV', '历代志上', 13, 20, 2, '大卫从米勒公神像的头上取下金冠，发现金子重三十公斤，又有一块宝石嵌在上面；有人把这冠冕戴在大卫的头上；大卫从城里夺走了大批战利品。'),
('CNV', '历代志上', 13, 20, 3, '又把城里的众民拉出来，要他们用锯子、铁铲和斧子作工；大卫待亚扪各城的人都是这样。后来大卫和众民都回耶路撒冷去了。'),
('CNV', '历代志上', 13, 20, 4, '这事以后，以色列人在基色与非利士人交战；那时户沙人西比该击杀了巨人的一个儿子细派，非利士人就被制伏了。'),
('CNV', '历代志上', 13, 20, 5, '后来，以色列人与非利士人再次交战，睚珥的儿子伊勒哈难，击杀了迦特人歌利亚的兄弟拉哈米；这人的枪杆好像织布机轴一样。'),
('CNV', '历代志上', 13, 20, 6, '后来，在迦特又有战事；那里有一个身材高大的人，手脚各有六指，共有二十四根指头；他也是巨人的儿子。'),
('CNV', '历代志上', 13, 20, 7, '这人侮辱以色列人，大卫的哥哥示米亚的儿子约拿单就把他击杀了。'),
('CNV', '历代志上', 13, 20, 8, '这些人是迦特巨人的儿子，都死在大卫和他仆人的手下。'),
('CNV', '历代志上', 13, 21, 1, '撒但起来攻击以色列人，引诱大卫去数点以色列人的数目。'),
('CNV', '历代志上', 13, 21, 2, '于是大卫对约押和民众的领袖说：“你们去数点以色列人，从别是巴直到但，然后回来见我，让我知道他们的数目。”'),
('CNV', '历代志上', 13, 21, 3, '约押说：“愿耶和华使他的子民比现在增加百倍。我主我王啊，他们不都是我主的仆人吗？我主为什么要作这事呢？为什么使以色列人陷在罪里呢？”'),
('CNV', '历代志上', 13, 21, 4, '但王坚持他的命令，约押不敢违抗；约押就出去，走遍以色列各地，然后回到耶路撒冷。'),
('CNV', '历代志上', 13, 21, 5, '约押把数点人民的数目呈报大卫：全以色列能拿刀的人，共有一百一十万；犹大能拿刀的人，共有四十七万。'),
('CNV', '历代志上', 13, 21, 6, '唯有利未人和便雅悯人，他没有数点在内，因为约押厌恶王这个命令。'),
('CNV', '历代志上', 13, 21, 7, '神不喜悦这事，所以他击打以色列人。'),
('CNV', '历代志上', 13, 21, 8, '大卫对神说：“我犯了重罪，因为我行了这事；现在求你除去你仆人的罪孽，因我作了十分愚昧的事。”'),
('CNV', '历代志上', 13, 21, 9, '耶和华告诉大卫的先见迦得，说：'),
('CNV', '历代志上', 13, 21, 10, '“你去告诉大卫，说：‘耶和华这样说：我给你提出三件事，你可以选择一件，我好向你施行。’”'),
('CNV', '历代志上', 13, 21, 11, '于是迦得来见大卫，对他说：“耶和华这样说：‘你可以选择：'),
('CNV', '历代志上', 13, 21, 12, '或是三年的饥荒；或是在你敌人面前逃亡，被你仇敌的刀剑追杀三个月；或是耶和华的刀攻击三天，就是在国中发生瘟疫三日，耶和华的使者在以色列的四境施行毁灭。’现在你考虑一下，我该用什么话回覆那差派我来的。”'),
('CNV', '历代志上', 13, 21, 13, '大卫对迦得说：“我十分作难，我情愿落在耶和华的手里，因为他有极丰盛的怜悯，我不愿落在人的手里。”'),
('CNV', '历代志上', 13, 21, 14, '于是耶和华使瘟疫降在以色列人身上；以色列人死了七万人。'),
('CNV', '历代志上', 13, 21, 15, '神差派一位使者到耶路撒冷去，要毁灭那城；正要施行毁灭的时候，耶和华看见了，就后悔所要降的这灾，于是对施行毁灭的天使说：“够了！住手吧！”那时，耶和华的使者正站在耶布斯人阿珥楠的禾场附近。'),
('CNV', '历代志上', 13, 21, 16, '大卫举目看见耶和华的使者站在天地之间，手里拿着出了鞘的刀，指向耶路撒冷。大卫和众长老都穿上麻布，脸伏于地。'),
('CNV', '历代志上', 13, 21, 17, '大卫对神说：“吩咐统计这人民的不是我吗？是我犯了罪，行了这大恶；但这羊群作了什么呢？耶和华我的神啊，愿你的手攻击我和我的家族，不可把瘟疫降在你子民的身上。”'),
('CNV', '历代志上', 13, 21, 18, '耶和华的使者吩咐迦得去告诉大卫，叫他上去，在耶布斯人阿珥楠的禾场上，为耶和华筑一座祭坛。'),
('CNV', '历代志上', 13, 21, 19, '大卫就照着迦得奉耶和华的名所说的话上去了。'),
('CNV', '历代志上', 13, 21, 20, '那时阿珥楠正在打麦子；阿珥楠转过身来看见了天使，就和他的四个儿子一起躲藏起来。'),
('CNV', '历代志上', 13, 21, 21, '大卫来到阿珥楠那里，阿珥楠看见大卫，就从禾场上出来，脸伏于地，向大卫下拜。'),
('CNV', '历代志上', 13, 21, 22, '大卫对阿珥楠说：“请把这块禾场的地让给我，我要在这里为耶和华筑一座祭坛，请你算足价银让给我，使民间的瘟疫可以止息。”'),
('CNV', '历代志上', 13, 21, 23, '阿珥楠对大卫说：“只管拿去吧，我主我王看怎样好就怎样行吧；你看，我把牛给你作燔祭，把打禾的用具当柴烧，拿麦子作素祭；这一切我都送给你。”'),
('CNV', '历代志上', 13, 21, 24, '大卫王对阿珥楠说：“不，我必照足价银向你买；我不能拿你的东西献给耶和华，也不能把没有付代价的东西献上作燔祭。”'),
('CNV', '历代志上', 13, 21, 25, '于是大卫称了六千八百四十克金子给阿珥楠，买了那块地。'),
('CNV', '历代志上', 13, 21, 26, '大卫在那里为耶和华筑了一座祭坛，献上燔祭和平安祭；他呼求耶和华，耶和华就应允他，从天上降火在燔祭坛上。'),
('CNV', '历代志上', 13, 21, 27, '耶和华吩咐使者，他就收刀入鞘。'),
('CNV', '历代志上', 13, 21, 28, '那时，大卫见耶和华在耶布斯人阿珥楠的禾场上应允了他，就在那里献祭。'),
('CNV', '历代志上', 13, 21, 29, '摩西在旷野所做耶和华的帐幕和燔祭坛，那时都在基遍的高地，'),
('CNV', '历代志上', 13, 21, 30, '只是大卫不敢上去求问神，因为惧怕耶和华使者的刀。'),
('CNV', '历代志上', 13, 21, 31, '于是大卫说：“这就是耶和华神的殿，这就是给以色列人献燔祭的坛。”'),
('CNV', '历代志上', 13, 22, 1, '大卫吩咐人召集住在以色列地的外族人，又派石匠开凿石头，要建造神的殿。'),
('CNV', '历代志上', 13, 22, 2, '大卫预备了大量的铁，做门扇上的钉子和钩子；又预备了大量的铜，多得无法可称；'),
('CNV', '历代志上', 13, 22, 3, '又预备了无数的香柏木，因为西顿人和推罗人给大卫运来了很多香柏木。'),
('CNV', '历代志上', 13, 22, 4, '大卫心里说：“我的儿子所罗门年幼识浅，要为耶和华建造的殿宇，必须宏伟辉煌，名声荣耀传遍各地，因此我必须为这殿预备材料。”于是大卫在未死以前，预备了很多材料。'),
('CNV', '历代志上', 13, 22, 5, '大卫把他的儿子所罗门召了来，吩咐他要为耶和华以色列的神建造殿宇。'),
('CNV', '历代志上', 13, 22, 6, '大卫对所罗门说：“我儿啊，我心里原想为耶和华我的神的名建造殿宇，'),
('CNV', '历代志上', 13, 22, 7, '只是耶和华的话临到我说：‘你流了许多人的血，打了很多大仗；你不可为我的名建造殿宇，因为你在我面前流了许多人的血在地上。'),
('CNV', '历代志上', 13, 22, 8, '看哪，你必生一个儿子；他是个和平的人，我必使他得享太平，不被四围所有的仇敌骚扰；他的名字要叫所罗门，他在位的日子，我必把太平和安宁赐给以色列人。'),
('CNV', '历代志上', 13, 22, 9, '他要为我的名建造殿宇；他要作我的儿子，我要作他的父亲；我必坚立他的国位，永远统治以色列。’'),
('CNV', '历代志上', 13, 22, 10, '我儿啊，现在愿耶和华与你同在，使你亨通，照着他应许你，建造耶和华你的神的殿宇。'),
('CNV', '历代志上', 13, 22, 11, '深愿耶和华赐你聪明和智慧，使你治理以色列的时候，谨守耶和华你的神的律法。'),
('CNV', '历代志上', 13, 22, 12, '如果你谨守遵行耶和华吩咐摩西向以色列人颁布的律例和典章，这样你就必亨通。你要坚强勇敢，不要惧怕，也不要惊惶。'),
('CNV', '历代志上', 13, 22, 13, '看哪，我辛辛苦苦为耶和华的殿预备了金子三千四百公吨，银子三万四千公吨，铜和铁多得无法可称；我又预备了木材和石头；你还可以增添。'),
('CNV', '历代志上', 13, 22, 14, '此外，你也有很多匠人：凿石的人、石匠、木匠和能作各样工作的巧手工人，'),
('CNV', '历代志上', 13, 22, 15, '以及金匠、银匠、铜匠、铁匠，多得无法可数；你当起来作工，愿耶和华与你同在！”'),
('CNV', '历代志上', 13, 22, 16, '大卫又吩咐以色列的众领袖帮助他的儿子所罗门，说：'),
('CNV', '历代志上', 13, 22, 17, '“耶和华你们的神不是与你们同在吗？不是使你们四境都安宁吗？因为他已经把这地的居民交在我手中；这地在耶和华和他的子民面前被治服了。'),
('CNV', '历代志上', 13, 22, 18, '现在你们要立定心意，寻求耶和华你们的神；你们当起来，建造耶和华神的圣所，好把耶和华的约柜和神的神圣器皿，都搬进为耶和华的名所建造的殿宇中。”'),
('CNV', '历代志上', 13, 23, 1, '大卫年老，寿数将尽的时候，就立他的儿子所罗门作王统治以色列。'),
('CNV', '历代志上', 13, 23, 2, '大卫召集了以色列的众领袖、祭司和利未人。'),
('CNV', '历代志上', 13, 23, 3, '利未人自三十岁及以上的都被数点；按统计，他们男丁的数目，共有三万八千人。'),
('CNV', '历代志上', 13, 23, 4, '其中有二万四千人，监管耶和华殿宇的工作；有六千人作官长和审判官；'),
('CNV', '历代志上', 13, 23, 5, '有四千人作守门的，又有四千人用大卫所做（“大卫所做”原文作“我做”）的乐器赞美耶和华。'),
('CNV', '历代志上', 13, 23, 6, '大卫把利未的儿子革顺、哥辖和米拉利的子孙，分成班次。'),
('CNV', '历代志上', 13, 23, 7, '革顺的子孙（“革顺的子孙”直译是“属于革顺人的”）有拉但和示每。'),
('CNV', '历代志上', 13, 23, 8, '拉但的儿子是：长子耶歇，还有西坦和约珥，共三人。'),
('CNV', '历代志上', 13, 23, 9, '示每的儿子有示罗密、哈薛和哈兰，共三人。以上这些人是拉但家族的首领。'),
('CNV', '历代志上', 13, 23, 10, '示每的儿子是雅哈、细拿、耶乌施和比利亚；这四人都是示每的儿子。'),
('CNV', '历代志上', 13, 23, 11, '雅哈是长子，细撒是次子；耶乌施和比利亚的子孙不多，所以合为一个家族，同归一个班次。'),
('CNV', '历代志上', 13, 23, 12, '哥辖的儿子是暗兰、以斯哈、希伯伦和乌薛，共四人。'),
('CNV', '历代志上', 13, 23, 13, '暗兰的儿子是亚伦和摩西。亚伦和他的子孙永远被分别出来，献上至圣之物；在耶和华面前烧香，服事他，奉他的名祝福，直到永远。'),
('CNV', '历代志上', 13, 23, 14, '至于神人摩西，他的子孙记在利未支派的册上。'),
('CNV', '历代志上', 13, 23, 15, '摩西的儿子是革舜和以利以谢。'),
('CNV', '历代志上', 13, 23, 16, '革舜的长子是细布业。'),
('CNV', '历代志上', 13, 23, 17, '以利以谢的第一个儿子是利哈比雅；以利以谢没有别的儿子，利哈比雅却有很多儿子。'),
('CNV', '历代志上', 13, 23, 18, '以斯哈的长子是示罗密。'),
('CNV', '历代志上', 13, 23, 19, '希伯伦的儿子是：长子耶利雅、次子亚玛利亚、三子雅哈悉、四子耶加面。'),
('CNV', '历代志上', 13, 23, 20, '乌薛的儿子是：长子米迦、次子耶西雅。'),
('CNV', '历代志上', 13, 23, 21, '米拉利的儿子是抹利和母示；抹利的儿子是以利亚撒和基士。'),
('CNV', '历代志上', 13, 23, 22, '以利亚撒死了，没有儿子，只有女儿；基士的儿子们，就是他们的亲族，娶了她们为妻。'),
('CNV', '历代志上', 13, 23, 23, '母示的儿子是末力、以得和耶利摩，共三人。'),
('CNV', '历代志上', 13, 23, 24, '以上这些是利未的子孙，按着他们的家族，各家的首领，照着男丁名字的数目被数点，二十岁及以上的，都是办理耶和华殿的事务的。'),
('CNV', '历代志上', 13, 23, 25, '因为大卫曾说：“耶和华以色列的神已经使他的子民得享安宁，他自己永远住在耶路撒冷。'),
('CNV', '历代志上', 13, 23, 26, '利未人不必再抬帐幕和其中所使用的一切器皿了。”'),
('CNV', '历代志上', 13, 23, 27, '按着大卫临终所吩咐的话，利未人从二十岁起的都被数点了。'),
('CNV', '历代志上', 13, 23, 28, '他们的职任是协助亚伦的子孙，办理耶和华殿的事务，管理院子、厢房和洁净一切圣物，以及办理神殿的事务；'),
('CNV', '历代志上', 13, 23, 29, '又管理陈设饼、素祭细面，或无酵薄饼，或是煎盘烤的，或是用油调和的，以及管理各种量度的器具。'),
('CNV', '历代志上', 13, 23, 30, '每天早晨要侍立称谢和赞美耶和华，每天晚上也要这样；'),
('CNV', '历代志上', 13, 23, 31, '又要在安息日，每月初一日和指定的节日，按着数目照着规例，把燔祭不住地献在耶和华面前。'),
('CNV', '历代志上', 13, 23, 32, '他们要看守会幕和圣所，以及看管他们在耶和华殿里办事的亲族，亚伦的子孙。'),
('CNV', '历代志上', 13, 24, 1, '亚伦子孙的班次如下：亚伦的儿子是拿答、亚比户、以利亚撒和以他玛。'),
('CNV', '历代志上', 13, 24, 2, '拿答和亚比户比他们的父亲早死，又没有儿子；所以以利亚撒和以他玛作了祭司。'),
('CNV', '历代志上', 13, 24, 3, '大卫和以利亚撒的子孙撒督，以及以他玛的子孙亚希米勒，把他们的亲族分开班次，按着他们的职责服事。'),
('CNV', '历代志上', 13, 24, 4, '后来发现以利亚撒的子孙中，比以他玛的子孙有更多作首领的，就把他们分开班次；以利亚撒子孙中作首领的，按着他们的家族有十六人；以他玛子孙中作首领的，按着他们的家族有八人。'),
('CNV', '历代志上', 13, 24, 5, '以抽签的方式平均地把他们分开，因为在以利亚撒的子孙中和以他玛的子孙中都有人在圣所作领袖，以及在神面前作领袖。'),
('CNV', '历代志上', 13, 24, 6, '作书记的利未人拿坦业的儿子示玛雅，在君王、领袖、撒督祭司、亚比亚他的儿子亚希米勒，以及众祭司家族和利未家族的首领面前，把他们的名字记录下来。在以利亚撒的子孙中，有一家族被选取了；在以他玛的子孙中，也有一家族被选取了。'),
('CNV', '历代志上', 13, 24, 7, '第一签抽出来的是耶何雅立，第二签是耶大雅，'),
('CNV', '历代志上', 13, 24, 8, '第三签是哈琳，第四签是梭琳，'),
('CNV', '历代志上', 13, 24, 9, '第五签是玛基雅，第六签是米雅民，'),
('CNV', '历代志上', 13, 24, 10, '第七签是哈歌斯，第八签是亚比雅，'),
('CNV', '历代志上', 13, 24, 11, '第九签是耶书亚，第十签是示迦尼，'),
('CNV', '历代志上', 13, 24, 12, '第十一签是以利亚实，第十二签是雅金，'),
('CNV', '历代志上', 13, 24, 13, '第十三签是胡巴，第十四签是耶是比押，'),
('CNV', '历代志上', 13, 24, 14, '第十五签是璧迦，第十六签是音麦，'),
('CNV', '历代志上', 13, 24, 15, '第十七签是希悉，第十八签是哈辟悉，'),
('CNV', '历代志上', 13, 24, 16, '第十九签是毗他希雅，第二十签是以西结，'),
('CNV', '历代志上', 13, 24, 17, '第二十一签是雅斤，第二十二签是迦末，'),
('CNV', '历代志上', 13, 24, 18, '第二十三签是第来雅，第二十四签是玛西亚。'),
('CNV', '历代志上', 13, 24, 19, '这就是他们的班次，是照着耶和华以色列的神藉着他们的祖宗亚伦所吩咐的条例，进入耶和华的殿，办理事务。'),
('CNV', '历代志上', 13, 24, 20, '利未还有其他子孙：暗兰的子孙中有书巴业；书巴业的子孙中有耶希底亚。'),
('CNV', '历代志上', 13, 24, 21, '至于利哈比雅：利哈比雅的众子中，长子是伊示雅。'),
('CNV', '历代志上', 13, 24, 22, '以斯哈的众子中有示罗摩；示罗摩的众子中有雅哈。'),
('CNV', '历代志上', 13, 24, 23, '希伯伦的儿子是：长子耶利雅（按照《马索拉文本》，“希伯伦的儿子是：长子耶利雅”作“耶利雅的儿子”；现参照《七十士译本》的一些文本和两份希伯来文文本翻译；参代上23:19）、次子亚玛利亚、三子雅哈悉、四子耶加面。'),
('CNV', '历代志上', 13, 24, 24, '乌薛的众子中有米迦；米迦的众子中有沙密。'),
('CNV', '历代志上', 13, 24, 25, '米迦的兄弟是耶西雅；耶西雅的众子中有撒迦利雅。'),
('CNV', '历代志上', 13, 24, 26, '米拉利的儿子是抹利、母示、雅西雅；雅西雅的儿子是比挪。'),
('CNV', '历代志上', 13, 24, 27, '米拉利的众子中有雅西雅的儿子比挪、朔含、撒刻和伊比利。'),
('CNV', '历代志上', 13, 24, 28, '抹利的儿子是以利亚撒；以利亚撒没有儿子。'),
('CNV', '历代志上', 13, 24, 29, '至于基士：基士的众子中有耶拉篾。'),
('CNV', '历代志上', 13, 24, 30, '母示的儿子是末力、以得和耶利摩；以上这些都是利未的子孙，按着他们的家族记录。'),
('CNV', '历代志上', 13, 24, 31, '他们在大卫王、撒督、亚希米勒，以及祭司和利未人的家族首领面前也抽了签，好像他们的亲族亚伦的子孙一样；各家族首领和他们年幼的兄弟都一样抽了签。'),
('CNV', '历代志上', 13, 25, 1, '大卫和军队的领袖，也给亚萨、希幔和耶杜顿的子孙分派了任务，叫他们用琴瑟响钹说预言。他们任职的人数如下：'),
('CNV', '历代志上', 13, 25, 2, '亚萨的儿子有撒刻、约瑟、尼探雅和亚萨利拉；亚萨的儿子都归亚萨指挥，遵照王的旨意说预言。'),
('CNV', '历代志上', 13, 25, 3, '至于耶杜顿，他的儿子有基大利、西利、耶筛亚、示每、哈沙比雅和玛他提雅，共六人，都归他们的父亲耶杜顿指挥。耶杜顿用琴说预言，称谢和赞美耶和华。'),
('CNV', '历代志上', 13, 25, 4, '至于希幔，他的儿子有布基雅、玛探雅、乌薛、细布业、耶利摩、哈拿尼雅、哈拿尼、以利亚他、基大利提、罗幔提．以谢、约施比加沙、玛罗提、何提和玛哈秀。'),
('CNV', '历代志上', 13, 25, 5, '这些人都是希幔的儿子；希幔是王的先见，照着神的话高举他（“高举他”原文作“高举角”）。神赐给希幔十四个儿子，三个女儿。'),
('CNV', '历代志上', 13, 25, 6, '这些人都归他们的父亲指挥，在耶和华的殿里歌颂，用响钹和琴瑟在神的殿事奉。亚萨、耶杜顿和希幔都是由王指挥的。'),
('CNV', '历代志上', 13, 25, 7, '他们和他们的亲族，在歌颂耶和华的事上受过特别训练，精于歌唱的，人数共有二百八十八人。'),
('CNV', '历代志上', 13, 25, 8, '这些人，无论大小，不分师生，都一同抽签分班次。'),
('CNV', '历代志上', 13, 25, 9, '第一签抽出来的是亚萨的儿子约瑟；第二签是基大利，他和他的兄弟、儿子，共十二人；'),
('CNV', '历代志上', 13, 25, 10, '第三签是撒刻，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 11, '第四签是伊洗利，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 12, '第五签是尼探雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 13, '第六签是布基雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 14, '第七签是耶撒利拉，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 15, '第八签是耶筛亚，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 16, '第九签是玛探雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 17, '第十签是示每，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 18, '第十一签是亚萨烈，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 19, '第十二签是哈沙比雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 20, '第十三签是书巴业，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 21, '第十四签是玛他提雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 22, '第十五签是耶利摩，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 23, '第十六签是哈拿尼雅，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 24, '第十七签是约施比加沙，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 25, '第十八签是哈拿尼，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 26, '第十九签是玛罗提，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 27, '第二十签是以利亚他，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 28, '第二十一签是何提，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 29, '第二十二签是基大利提，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 30, '第二十三签是玛哈秀，他和他的儿子、兄弟，共十二人；'),
('CNV', '历代志上', 13, 25, 31, '第二十四签是罗幔提．以谢，他和他的儿子、兄弟，共十二人。'),
('CNV', '历代志上', 13, 26, 1, '守门的人的班次如下：可拉家族，亚萨的子孙中，有可利的儿子米施利米雅。'),
('CNV', '历代志上', 13, 26, 2, '米施利米雅有几个儿子：长子是撒迦利雅、次子是耶叠、三子是西巴弟雅、四子是耶提聂、'),
('CNV', '历代志上', 13, 26, 3, '五子是以拦、六子是约哈难、七子是以利约乃。'),
('CNV', '历代志上', 13, 26, 4, '俄别．以东有几个儿子：长子是示玛雅、次子是约萨拔、三子是约亚，四子是沙甲、五子是拿坦业、'),
('CNV', '历代志上', 13, 26, 5, '六子是亚米利、七子是以萨迦、八子是毗乌利太；神实在赐福给俄别．以东。'),
('CNV', '历代志上', 13, 26, 6, '他的儿子示玛雅也生了几个儿子，都是管治他们的家族的，因为他们都是英勇的战士。'),
('CNV', '历代志上', 13, 26, 7, '示玛雅的儿子是俄得尼、利法益、俄备得和以利萨巴。以利萨巴的兄弟以利户和西玛迦都是勇士。'),
('CNV', '历代志上', 13, 26, 8, '这些人都是俄别．以东的子孙，他们和他们的儿子、兄弟，都是有能力办事的人。俄别．以东的子孙，共有六十二人。'),
('CNV', '历代志上', 13, 26, 9, '米施利米雅有儿子和兄弟，都是勇士，共十八人。'),
('CNV', '历代志上', 13, 26, 10, '米拉利的子孙何萨有几个儿子，长子是申利（申利原不是长子，是他父亲立他作长子的）、'),
('CNV', '历代志上', 13, 26, 11, '次子是希勒家、三子是底巴利雅、四子是撒迦利亚。何萨所有的儿子和兄弟共十三人。'),
('CNV', '历代志上', 13, 26, 12, '以上这些都是守门人的班次；无论是首领或是他们的亲族，都在耶和华的殿里按班供职。'),
('CNV', '历代志上', 13, 26, 13, '他们无论大小，都按着他们的家族抽签，看守各门。'),
('CNV', '历代志上', 13, 26, 14, '抽出守东门的签的是示利米雅。他的儿子撒迦利亚是个聪明的谋士，他们为他抽出了守北面的签。'),
('CNV', '历代志上', 13, 26, 15, '俄别．以东守南门；他的儿子守库房。'),
('CNV', '历代志上', 13, 26, 16, '书聘和何萨守西门，以及在斜路上的沙利基门；守卫的人相对而立。'),
('CNV', '历代志上', 13, 26, 17, '守东门的有六个利未人，守北门的每日有四人，守南门的每日有四人，守库房的两人一组。'),
('CNV', '历代志上', 13, 26, 18, '在西面的前廊有四人在大路上，在前廊那里有两个人。'),
('CNV', '历代志上', 13, 26, 19, '以上这些人是可拉子孙和米拉利子孙守门的人的班次。'),
('CNV', '历代志上', 13, 26, 20, '他们其他的利未亲族，就管理神殿里的库房和圣物的库房。'),
('CNV', '历代志上', 13, 26, 21, '革顺家族拉但的子孙中作首领的，有革顺家族拉但的子孙耶希伊利。'),
('CNV', '历代志上', 13, 26, 22, '耶希伊利的儿子西坦和他的兄弟约珥，掌管耶和华殿里的库房。'),
('CNV', '历代志上', 13, 26, 23, '至于暗兰家族、以斯哈家族、希伯伦家族和乌薛家族，也各有职守。'),
('CNV', '历代志上', 13, 26, 24, '摩西的孙子、革顺的儿子细布业作库房的总管。'),
('CNV', '历代志上', 13, 26, 25, '细布业的兄弟是以利以谢；以利以谢的儿子是利哈比雅，利哈比雅的儿子是耶筛亚，耶筛亚的儿子是约兰，约兰的儿子是细基利，细基利的儿子是示罗密。'),
('CNV', '历代志上', 13, 26, 26, '这示罗密和他的兄弟掌管库房里的一切圣物，就是大卫王、众家族首领、千夫长、百夫长和军长所献的圣物。'),
('CNV', '历代志上', 13, 26, 27, '他们把在战场上掠夺的财物献上，用作修建耶和华的殿。'),
('CNV', '历代志上', 13, 26, 28, '撒母耳先见、基士的儿子扫罗、尼珥的儿子押尼珥和洗鲁雅的儿子约押所分别为圣的一切，以及一切分别为圣的物，都归示罗密和他的众兄弟掌管。'),
('CNV', '历代志上', 13, 26, 29, '以斯哈家族有基拿尼雅和他的众子在圣殿外作官长和审判官，治理以色列人。'),
('CNV', '历代志上', 13, 26, 30, '希伯伦家族有哈沙比雅和他的亲族，共一千七百人，都是勇士，主管约旦河西以色列地主的一切职事和王的任务。'),
('CNV', '历代志上', 13, 26, 31, '希伯伦家族中有作首领的耶利雅，是按着他们家族的族谱作希伯伦家族的首领的。大卫在位第四十年，经过调查，在基列的雅谢从这家族中找到英勇的战士。'),
('CNV', '历代志上', 13, 26, 32, '耶利雅的亲族有二千七百人，都是勇士，各家族的首领；大卫王派他们管理流本支派、迦得支派和玛拿西半个支派一切有关神和王的事务。'),
('CNV', '历代志上', 13, 27, 1, '以色列人各家族的首领、千夫长、百夫长和服事王的所有官长，都按着他们的数目分定班次，每年按月轮班，每班有二万四千人。'),
('CNV', '历代志上', 13, 27, 2, '负责正月第一班的，是撒巴第业的儿子雅朔班，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 3, '他是法勒斯子孙中的首领，统管正月那一班所有的军长。'),
('CNV', '历代志上', 13, 27, 4, '负责二月那一班的是亚哈希人朵代，他那一班还有副官密基罗，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 5, '三月第三班的军长是大祭司耶何耶大的儿子比拿雅，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 6, '这比拿雅是那三十位勇士中的一位，管理那三十人；他那一班还有他的儿子暗米萨拔。'),
('CNV', '历代志上', 13, 27, 7, '四月第四班的军长是约押的兄弟亚撒黑，接续他的是他的儿子西巴第雅；他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 8, '五月第五班的军长是伊斯拉人珊合，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 9, '六月第六班的军长是提哥亚人益吉的儿子以拉，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 10, '七月第七班的军长是以法莲子孙中比伦人希利斯，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 11, '八月第八班的军长是谢拉家族户沙人西比该，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 12, '九月第九班的军长是便雅悯支派亚拿突人亚比以谢，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 13, '十月第十班的军长是谢拉家族尼陀法人玛哈莱，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 14, '十一月第十一班的军长是以法莲子孙中的比拉顿人比拿雅，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 15, '十二月第十二班的军长是俄陀聂家族尼陀法人黑玳，他那一班有二万四千人。'),
('CNV', '历代志上', 13, 27, 16, '掌管以色列各支派的记在下面：流本支派的首领是细基利的儿子以利以谢；西缅支派的首领是玛迦的儿子示法提雅；'),
('CNV', '历代志上', 13, 27, 17, '利未支派的首领是基母利的儿子哈沙比雅；亚伦子孙的首领是撒督；'),
('CNV', '历代志上', 13, 27, 18, '犹大支派的首领是大卫的哥哥以利户；以萨迦支派的首领是米迦勒的儿子暗利；'),
('CNV', '历代志上', 13, 27, 19, '西布伦支派的首领是俄巴第雅的儿子伊施玛雅；拿弗他利支派的首领是亚斯列的儿子耶利摩；'),
('CNV', '历代志上', 13, 27, 20, '以法莲支派的首领是阿撒细雅的儿子何细亚；玛拿西半个支派的首领是毗大雅的儿子约珥；'),
('CNV', '历代志上', 13, 27, 21, '基列地玛拿西那半个支派的首领是撒迦利亚的儿子易多；便雅悯支派的首领是押尼珥的儿子雅西业；'),
('CNV', '历代志上', 13, 27, 22, '但支派的首领是耶罗罕的儿子亚萨列。以上这些人是以色列各支派的领袖。'),
('CNV', '历代志上', 13, 27, 23, '以色列人二十岁以下的，大卫都没有登记他们的数目，因为耶和华曾经说过要增添以色列人的数目，好像天上的星那样多。'),
('CNV', '历代志上', 13, 27, 24, '洗鲁雅的儿子约押开始数点，但还没有完成，为了这事耶和华的忿怒就临到以色列人身上，所以以色列的人数没有记在大卫王的年录上。'),
('CNV', '历代志上', 13, 27, 25, '管理王的库房的，是亚叠的儿子押斯马威；管理郊野、城市、乡村和望楼的仓库的，是乌西雅的儿子约拿单；'),
('CNV', '历代志上', 13, 27, 26, '管理耕田种地的，是基绿的儿子以斯利；'),
('CNV', '历代志上', 13, 27, 27, '管理葡萄园的，是拉玛人示每；管理园里酒库的，是实弗米人撒巴底；'),
('CNV', '历代志上', 13, 27, 28, '管理高原橄榄树和桑树的，是基第利人巴力．哈南；管理油库的，是约阿施；'),
('CNV', '历代志上', 13, 27, 29, '管理在沙仑牧放的牛群的，是沙仑人施提赉；管理在山谷的牛群的，是亚第赉的儿子沙法；'),
('CNV', '历代志上', 13, 27, 30, '管理骆驼的，是以实玛利人阿比勒；管理驴群的，是米仑人耶希底亚；'),
('CNV', '历代志上', 13, 27, 31, '管理羊群的，是夏甲人雅悉。以上这些人都是给大卫王管理产业的官员。'),
('CNV', '历代志上', 13, 27, 32, '大卫的叔父约拿单是一个谋士；这人很有智慧，又是一个经学家；哈摩尼的儿子耶歇是王众子的老师。'),
('CNV', '历代志上', 13, 27, 33, '亚希多弗也是王的谋士；亚基人户筛是王的朋友；'),
('CNV', '历代志上', 13, 27, 34, '亚希多弗以后，有比拿雅的儿子耶何耶大和亚比亚他，接续他作谋士；约押作王的元帅。'),
('CNV', '历代志上', 13, 28, 1, '大卫把以色列的众领袖：各支派的领袖、轮班服事王的领袖、千夫长、百夫长、掌管王和王子们一切财产与牲畜的领袖，以及太监、显贵和所有英勇的战士，都召集到耶路撒冷来。'),
('CNV', '历代志上', 13, 28, 2, '大卫王站起来，说：“我的兄弟，我的人民哪，你们要听我的话；我心里有意要建造一所安放耶和华的约柜的殿宇，作我们的神的脚凳，并且我已经准备好要建造。'),
('CNV', '历代志上', 13, 28, 3, '可是神对我说：‘你不可为我的名建造殿宇，因为你是个战士，曾杀人流血。’'),
('CNV', '历代志上', 13, 28, 4, '然而耶和华以色列的神，在我父的全家拣选了我作以色列人的王，直到永远；因为他拣选了犹大作领袖；在犹大家中拣选了我的父家；在我父亲的众子中，他喜悦我，立我作全以色列的王；'),
('CNV', '历代志上', 13, 28, 5, '在我的众子中（因为耶和华赐给我许多儿子），他拣选了我的儿子所罗门，坐耶和华的国位，统治以色列。'),
('CNV', '历代志上', 13, 28, 6, '耶和华对我说：‘你的儿子所罗门要建造我的殿宇和庭院；因为我已经拣选他作我的儿子，我也要作他的父亲。'),
('CNV', '历代志上', 13, 28, 7, '如果他坚心遵行我的诫命和典章，像今日一样，我必坚立他的国，直到永远。’'),
('CNV', '历代志上', 13, 28, 8, '所以现今在耶和华的会众，全体以色列人面前，我们的神也在垂听，你们务要谨守和寻求耶和华你们神的一切诫命，使你们可以承受那美地，并且遗留给你们以后的子孙，永远作为产业。'),
('CNV', '历代志上', 13, 28, 9, '“至于你，我儿所罗门哪，你要认识耶和华你父亲的神，一心乐意事奉他，因为耶和华鉴察万人的心，知道人的一切心思意念。你若是寻求他，就必寻见；你若是离弃他，他必永远丢弃你。'),
('CNV', '历代志上', 13, 28, 10, '现在你当谨慎，因为耶和华拣选了你建造殿宇，作为圣所；你要勇敢地去作。”'),
('CNV', '历代志上', 13, 28, 11, '大卫把殿的走廊、房屋、库房、阁楼、内殿和安放施恩座的圣所的图样，都交给他的儿子所罗门；'),
('CNV', '历代志上', 13, 28, 12, '又把他心中所想的图样，就是耶和华殿的院子、四周所有的房屋、神殿里的库房和圣物库房的图样，都指示了他；'),
('CNV', '历代志上', 13, 28, 13, '又把祭司和利未人的班次，耶和华殿里各样的职事和耶和华殿里一切需用的器皿，都指示了他；'),
('CNV', '历代志上', 13, 28, 14, '大卫又指示了他用多少金子做各样需用的金器；用多少银子做各样需用的银器；'),
('CNV', '历代志上', 13, 28, 15, '用多少金子做金灯台和台上的金灯；用多少金子做每盏金灯台和台上的金灯；用多少银子做银灯台和台上的银灯。每盏银灯台和台上的银灯用多少银子，都按照每盏灯台的用途；'),
('CNV', '历代志上', 13, 28, 16, '用多少金子做陈设饼的桌子；用多少银子做银桌子；'),
('CNV', '历代志上', 13, 28, 17, '用多少纯金做叉、盘和壶；用多少金子做金碗，每只碗重量多少；用多少银子做银碗，每只碗重量多少；'),
('CNV', '历代志上', 13, 28, 18, '用多少精金做香坛；又用金子做基路伯，像车的样子；基路伯展开翅膀，遮盖着耶和华的约柜。'),
('CNV', '历代志上', 13, 28, 19, '大卫说：“以上这一切，就是一切工作的样式，都是耶和华用手写给我，使我明白的。”'),
('CNV', '历代志上', 13, 28, 20, '大卫又对他的儿子所罗门说：“你要坚强勇敢地去作，不要惧怕，也不要惊惶，因为耶和华神，就是我的神，与你同在；他必不撇下你，也不丢弃你，直到耶和华殿的一切工作都完成。'),
('CNV', '历代志上', 13, 28, 21, '你看，有祭司和利未人的各班次，办理神殿里的一切事务；又有各种的巧匠，在各样的工作上，乐意帮助你，并且众领袖和所有的人民，都听从你的一切命令。”'),
('CNV', '历代志上', 13, 29, 1, '大卫王对全体会众说：“我的儿子所罗门，是神所拣选的，现在还年幼识浅，而这工程非常浩大；因为这殿宇不是为人建造，而是为耶和华神建造的。'),
('CNV', '历代志上', 13, 29, 2, '我为我神的殿已经尽了我的力量，预备了金子做金器，银子做银器，铜做铜器，铁做铁器，木做木器；还有红玛瑙、用作镶嵌的宝石、彩石和各样的宝石，以及很多大理石。'),
('CNV', '历代志上', 13, 29, 3, '不但这样，因我爱慕我神的殿，就在我为建造圣殿预备的一切以外，又把我自己积蓄的金银献给我神的殿：'),
('CNV', '历代志上', 13, 29, 4, '就是俄斐金一百多公吨，精炼的银子约两百四十公吨，用来贴殿里的墙壁；'),
('CNV', '历代志上', 13, 29, 5, '金子做金器，银子做银器，以及匠人手所作的各样巧工。今日有谁愿意奉献给耶和华呢？”'),
('CNV', '历代志上', 13, 29, 6, '于是各家族的领袖、以色列各支派的领袖、千夫长、百夫长和管理王的事务的领袖，都乐意奉献。'),
('CNV', '历代志上', 13, 29, 7, '为了神殿里的需用，他们奉献了金子一百七十多公吨，银子三百四十多公吨，铜约六百二十公吨和铁三千四百公吨。'),
('CNV', '历代志上', 13, 29, 8, '有宝石的，都交到耶和华殿这库房，由革顺人耶歇经办。'),
('CNV', '历代志上', 13, 29, 9, '人民因这些人自愿奉献而欢喜，因为他们一心乐意奉献给耶和华，大卫王也非常欢喜。'),
('CNV', '历代志上', 13, 29, 10, '所以大卫在全体会众面前称颂耶和华，说：“耶和华我们的祖先以色列的神，是应当称颂的，从亘古直到永远。'),
('CNV', '历代志上', 13, 29, 11, '耶和华啊，尊大、能力、荣耀、胜利和威严，都是你的；因为天上地下的万有都是你的；耶和华啊，国度是你的，你是至高的，是万有之首。'),
('CNV', '历代志上', 13, 29, 12, '富足和尊荣都从你而来，你也统治万有。在你的手里有力量和权能；人的尊大、强盛都是出于你的手。'),
('CNV', '历代志上', 13, 29, 13, '我们的神啊，现在我们要称颂你，赞美你荣耀的名。'),
('CNV', '历代志上', 13, 29, 14, '我算什么？我的人民又算什么？竟有力量这样乐意奉献？因为万物都是从你而来，我们只是把从你手里得来的，奉献给你。'),
('CNV', '历代志上', 13, 29, 15, '我们在你面前是客旅，是寄居的，像我们的列祖一样；我们在世上的日子好像影儿，没有指望。'),
('CNV', '历代志上', 13, 29, 16, '耶和华我们的神啊，我们预备的这一切财物，要为你的圣名建造殿宇，都是从你而来的，也都是属于你的。'),
('CNV', '历代志上', 13, 29, 17, '我的神啊，我知道你察验人心，喜悦正直；至于我，我以正直的心甘愿奉献这一切；现在我也非常欢喜看见你在这里的人民，都甘愿奉献给你。'),
('CNV', '历代志上', 13, 29, 18, '耶和华我们列祖亚伯拉罕、以撒、以色列的神啊，求你永远保守这一件事，就是使你的子民常存这心思意念，坚定他们的心归向你。'),
('CNV', '历代志上', 13, 29, 19, '求你赐给我的儿子所罗门专一的心，谨守你的诫命、法度和律例，作成这一切事，用我所预备的一切来建造殿宇。”'),
('CNV', '历代志上', 13, 29, 20, '大卫对全体会众说：“你们应当称颂耶和华你们的神。”于是全体会众就称颂耶和华他们列祖的神，俯伏敬拜耶和华和王。'),
('CNV', '历代志上', 13, 29, 21, '第二天，他们向耶和华献祭，他们向耶和华献上燔祭；那一天他们献了公牛一千头、公绵羊一千只、羊羔一千只，以及同献的奠祭，又为以色列众人献了许多祭。'),
('CNV', '历代志上', 13, 29, 22, '那一天，他们十分喜乐地在耶和华面前吃喝。他们再次表示拥立大卫的儿子所罗门作王，膏他为耶和华作君王，又膏撒督作祭司。'),
('CNV', '历代志上', 13, 29, 23, '于是所罗门坐在耶和华所赐的位上，接续他父亲大卫作王；他凡事亨通，以色列众人都听从他。'),
('CNV', '历代志上', 13, 29, 24, '众领袖和勇士，以及大卫王的众子，都顺服所罗门王。'),
('CNV', '历代志上', 13, 29, 25, '耶和华使所罗门在以色列众人面前非常尊大，又赐给他君王的威严，胜过在他以前所有的以色列王。'),
('CNV', '历代志上', 13, 29, 26, '耶西的儿子大卫作全以色列的王。'),
('CNV', '历代志上', 13, 29, 27, '大卫作王统治以色列的日子共四十年；他在希伯仑作王七年，在耶路撒冷作王三十三年。'),
('CNV', '历代志上', 13, 29, 28, '大卫年纪老迈，寿数满足，享尽富足和尊荣才去世；他的儿子所罗门接续他作王。'),
('CNV', '历代志上', 13, 29, 29, '大卫王一生始末的事迹，都记在撒母耳先见的书上、拿单先知的书上和迦得先见的书上。'),
('CNV', '历代志上', 13, 29, 30, '还有他治理的一切国事，他的英勇事迹，以及在他身上和以色列并各地列国发生的事迹，都记在这些书上。'),
('CNV', '历代志下', 14, 1, 1, '大卫的儿子所罗门巩固了他对以色列的统治，耶和华他的神也和他同在，使他十分尊大。'),
('CNV', '历代志下', 14, 1, 2, '所罗门召唤全体以色列人、千夫长、百夫长、审判官、以色列的各领袖和众家族的首领。'),
('CNV', '历代志下', 14, 1, 3, '所罗门和全体会众一同到基遍的高地去，因为那里有神的会幕，就是耶和华的仆人摩西在旷野所做的。'),
('CNV', '历代志下', 14, 1, 4, '至于神的约柜，大卫已经从基列．耶琳抬到他预备好的地方，因为他曾在耶路撒冷为约柜盖搭了一个帐幕。'),
('CNV', '历代志下', 14, 1, 5, '户珥的孙子、乌利的儿子比撒列所做的铜祭坛也在那里，在耶和华的会幕前面；所罗门和会众同去求问耶和华。'),
('CNV', '历代志下', 14, 1, 6, '所罗门上到耶和华会幕前面的铜祭坛旁边，在坛上献上了一千只燔祭牲。'),
('CNV', '历代志下', 14, 1, 7, '那一夜，神向所罗门显现，对他说：“你无论求什么，我必赐给你。”'),
('CNV', '历代志下', 14, 1, 8, '所罗门对神说：“你曾经向我的父亲大卫大施慈爱，使我接续他作王。'),
('CNV', '历代志下', 14, 1, 9, '耶和华神啊，现在求你实现你向我的父亲大卫应许的话；因为你立了我作王统治这好像地上的尘土那么多的人民。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '历代志下', 14, 1, 10, '现在求你赐我智慧和知识，使我可以领导这人民；否则，谁能治理你这众多的人民呢？”'),
('CNV', '历代志下', 14, 1, 11, '神对所罗门说：“你既然有这个心意：不求富足、财产、尊荣，也不求你敌人的性命，又不求长寿，只为自己求智慧和知识，好治理我的子民，就是我立你作王统治的人民，'),
('CNV', '历代志下', 14, 1, 12, '因此，智慧和知识必赐给你，我也把富足、财产和尊荣赐给你；在你以前的列王从没有这样，在你以后的也必没有这样。”'),
('CNV', '历代志下', 14, 1, 13, '于是，所罗门从基遍高地的会幕（按照《马索拉文本》，“从基遍高地的会幕”作“到基遍的高地，从会幕”；现参照《七十士译本》和《武加大译本》翻译）回到耶路撒冷，统治以色列。'),
('CNV', '历代志下', 14, 1, 14, '所罗门召集了战车和马兵：他有战车一千四百辆，马兵一万二千名；他把这些车马安置在囤车城，或在耶路撒冷，和王在一起。'),
('CNV', '历代志下', 14, 1, 15, '王在耶路撒冷积存的金银好像石头那么多，积存的香柏木好像平原的桑树那么多。'),
('CNV', '历代志下', 14, 1, 16, '所罗门拥有的马，都是从埃及和古厄运来的，是王的商人从古厄照价买来的。'),
('CNV', '历代志下', 14, 1, 17, '他们从埃及运上来的车，每辆价银六千八百四十克；马每匹一千七百一十克。赫人众王和亚兰众王的车马，也都是这样经这些商人的手买来的。'),
('CNV', '历代志下', 14, 2, 1, '所罗门决意要为耶和华的名建造殿宇，又为自己建造王宫。（本节在《马索拉文本》为1:18）'),
('CNV', '历代志下', 14, 2, 2, '于是，所罗门选派了七万人作挑夫，八万人在山上凿石，三千六百人作督工。（本节在《马索拉文本》为2:1）'),
('CNV', '历代志下', 14, 2, 3, '所罗门派人去见推罗王希兰说：“你怎样待我的父亲大卫，给他运来香柏木，为他建造宫殿居住，请你也这样待我。'),
('CNV', '历代志下', 14, 2, 4, '现在我要为耶和华我神的名建造殿宇，分别为圣献给他，在他面前焚烧芬芳的香，经常摆上陈设饼，每日早晚、安息日、初一，以及耶和华我们的神所定的节日，都献上燔祭；这是以色列人永远的定例。'),
('CNV', '历代志下', 14, 2, 5, '我要建造的殿宇必须宏伟，因为我们的神伟大，超过众神。'),
('CNV', '历代志下', 14, 2, 6, '但谁能为他建造殿宇呢？天和天上的天也容不下他；我是谁，怎能为他建造殿宇？我不过在他面前烧香罢了。'),
('CNV', '历代志下', 14, 2, 7, '现在请你派一个巧匠到我这里来，他要精于使用金、银、铜、铁和紫色朱红色蓝色线工作，并且懂得雕刻，好与我的父亲大卫在犹大和耶路撒冷预备的巧匠一同工作。'),
('CNV', '历代志下', 14, 2, 8, '又请你从黎巴嫩运送香柏木、松木和檀香木到我这里来，因为我知道你的臣仆善于砍伐黎巴嫩的树木；我的臣仆可以和你的臣仆一同工作。'),
('CNV', '历代志下', 14, 2, 9, '给我预备大量的木材，因为我要建造的那殿宇，将会十分宏伟。'),
('CNV', '历代志下', 14, 2, 10, '至于你的仆人，就是砍伐树木的人，我必给他们食物，就是小麦四百万公升、大麦四百万公升、酒四十万公升、油四十万公升。”'),
('CNV', '历代志下', 14, 2, 11, '推罗王希兰回信给所罗门说：“耶和华因为爱自己的子民，所以立你作他们的王。”'),
('CNV', '历代志下', 14, 2, 12, '希兰又说：“创造天地的耶和华以色列的神，是应当称颂的！因为他赐给大卫王一个有智慧的儿子，有聪明有见识，可以为耶和华建造殿宇，为自己建造王宫。'),
('CNV', '历代志下', 14, 2, 13, '现在我派一个技艺精巧、满有聪明的人来，他是我父亲希兰的匠人。'),
('CNV', '历代志下', 14, 2, 14, '他是但支派一个妇人的儿子，他的父亲是推罗人。他精于使用金、银、铜、铁、石、木，以及紫色蓝色朱红色线和细麻作工，也能作各样雕刻的工作，又能设计各样交托他们的巧工。这人可以和你的巧匠，以及我主你父亲大卫的巧匠一同工作。'),
('CNV', '历代志下', 14, 2, 15, '我主所说的小麦、大麦、酒和油，请派人运来给众仆人。'),
('CNV', '历代志下', 14, 2, 16, '我们必照着你所需要的，从黎巴嫩砍下树木，扎成木筏，从海上运到约帕，你可以从那里把它们运上耶路撒冷。”'),
('CNV', '历代志下', 14, 2, 17, '所罗门按照他父亲大卫数点的数目，又数点了住在以色列地所有的外族人，他们共有十五万三千六百人。'),
('CNV', '历代志下', 14, 2, 18, '他选派七万人作挑夫，八万人在山上凿石头，三千六百人作监工，督促人民工作。'),
('CNV', '历代志下', 14, 3, 1, '所罗门在耶路撒冷，在耶和华向他父亲大卫显现过的摩利亚山上，就是在耶布斯人阿珥楠的禾场上，大卫预备的地方，开工建造耶和华的殿。'),
('CNV', '历代志下', 14, 3, 2, '所罗门执政后第四年二月初二开始建造。'),
('CNV', '历代志下', 14, 3, 3, '所罗门建造神殿宇的根基是这样：按古时的尺寸，长二十七公尺，宽九公尺。'),
('CNV', '历代志下', 14, 3, 4, '殿前走廊长九公尺，与殿的宽度相等；高九公尺（“高九公尺”原文作“高一百二十”；现参照古译本修译）；里面贴上纯金。'),
('CNV', '历代志下', 14, 3, 5, '大殿的墙都盖上松木，又贴上精金，又在上面刻上棕树和链子。'),
('CNV', '历代志下', 14, 3, 6, '又用宝石装饰殿墙，十分华美；金子都是巴瓦音的金子。'),
('CNV', '历代志下', 14, 3, 7, '正殿和殿的栋梁、门槛、墙壁和门扇，都贴上金子；墙上刻上基路伯。'),
('CNV', '历代志下', 14, 3, 8, '他又建造了至圣所，长九公尺，和殿的宽度相等，宽度也是九公尺；里面都贴上精金，共用了二十公吨金子。'),
('CNV', '历代志下', 14, 3, 9, '钉子共重五百七十克金子。阁楼也贴上金子。'),
('CNV', '历代志下', 14, 3, 10, '在至圣所里，雕刻了两个基路伯，都包上金子。'),
('CNV', '历代志下', 14, 3, 11, '两个基路伯的翅膀共长九公尺；一个基路伯的一边翅膀长两公尺两公寸，触着殿墙；另一边翅膀也长两公尺两公寸，和另一个基路伯的翅膀相接。'),
('CNV', '历代志下', 14, 3, 12, '另一个基路伯的一边翅膀也长两公尺两公寸，触着殿墙；另一边的翅膀也长两公尺两公寸，和前一个基路伯的翅膀相接。'),
('CNV', '历代志下', 14, 3, 13, '这两个基路伯的翅膀都张开，共长九公尺；这两个基路伯都面向殿内站立。'),
('CNV', '历代志下', 14, 3, 14, '所罗门又用蓝色紫色朱红色线和细麻做幔子，上面绣上基路伯。'),
('CNV', '历代志下', 14, 3, 15, '在殿的前面又做了两根柱子，高十五公尺半，每根柱上面的柱顶，高两公尺两公寸。'),
('CNV', '历代志下', 14, 3, 16, '又做了像项链（按照《马索拉文本》，“像项链”作“在内殿”，意思不明确，可能是“像项链”的误写）的链子，安放在柱头上；又做了石榴一百个，安放在链子上。'),
('CNV', '历代志下', 14, 3, 17, '他把这两根柱子立在殿前，一根在左面，一根在右面；右面的叫雅斤，左面的叫波阿斯。'),
('CNV', '历代志下', 14, 4, 1, '他又做了一座铜坛，长九公尺，宽九公尺，高四公尺半。'),
('CNV', '历代志下', 14, 4, 2, '又铸造了一个铜海，直径有四公尺半，是圆形的，高两公尺两公寸，圆周有十三公尺两公寸。'),
('CNV', '历代志下', 14, 4, 3, '铜海底下四周有形状像牛的装饰物；每四十五公分十个，共分二行，是和铜海一体铸成的。'),
('CNV', '历代志下', 14, 4, 4, '有十二头铜牛驮着铜海：三头向北，三头向西，三头向南，三头向东。铜海在牛背上面，牛尾部向内。'),
('CNV', '历代志下', 14, 4, 5, '铜海厚七公分半，边缘像杯边的做法，形状似百合花，容量有六万公升。'),
('CNV', '历代志下', 14, 4, 6, '他又做了十个洗濯盆：五个放在铜海的右边，五个放在左边，用来清洗东西；献燔祭所用的东西要在盆内清洗，但铜海是给祭司洗濯的。'),
('CNV', '历代志下', 14, 4, 7, '又照着规定的样式做了十个金灯台，放在殿内；五个在右边，五个在左边。'),
('CNV', '历代志下', 14, 4, 8, '又做了十张桌子，安放在殿内；五张在右边，五张在左边。又做了一百个金碗。'),
('CNV', '历代志下', 14, 4, 9, '又建造祭司院、大院和大院的门；门都包上铜。'),
('CNV', '历代志下', 14, 4, 10, '又把铜海放在殿的右边，就是东南方。'),
('CNV', '历代志下', 14, 4, 11, '户兰又做了锅、铲和碗。这样，户兰为所罗门王完成了神殿的工程，'),
('CNV', '历代志下', 14, 4, 12, '就是两根柱子和在柱子上面两个碗形柱顶，以及两个网子，遮盖柱子上面两个碗形的柱顶，'),
('CNV', '历代志下', 14, 4, 13, '又有四百个石榴，安放在两个网子上，每个网子有两行石榴，遮盖柱子上头两个碗形的柱顶。'),
('CNV', '历代志下', 14, 4, 14, '又做了十个盆座和盆座上的十个洗濯盆，'),
('CNV', '历代志下', 14, 4, 15, '还有一个铜海和铜海底下的十二头铜牛。'),
('CNV', '历代志下', 14, 4, 16, '锅、铲、肉叉和一切相关的器皿，都是户兰用磨光的铜给所罗门王，为耶和华的殿所做的。'),
('CNV', '历代志下', 14, 4, 17, '是王在约旦平原，在疏割和撒利但之间，用胶泥模铸成的。'),
('CNV', '历代志下', 14, 4, 18, '所罗门所做的这一切器皿，数量很多；铜的重量无法估计。'),
('CNV', '历代志下', 14, 4, 19, '所罗门又做了神殿里的一切器具，就是金坛和放陈设饼的桌子，'),
('CNV', '历代志下', 14, 4, 20, '用纯金做的灯台和灯盏，按定例在内殿门前燃点，'),
('CNV', '历代志下', 14, 4, 21, '还有灯花、灯盏和烛剪，都是精金做的。'),
('CNV', '历代志下', 14, 4, 22, '又有剪刀、盘子、调羹和火鼎，都是用精金做的。殿门，就是进入至圣所里面的门和正殿的门，都是金的。'),
('CNV', '历代志下', 14, 5, 1, '所罗门为耶和华的殿所作的一切工程完成了以后，就把他父亲大卫分别为圣的东西：金银和一切器皿，都带来存放在神殿的库房里。'),
('CNV', '历代志下', 14, 5, 2, '那时，所罗门把以色列的长老、各支派的首领和以色列人各家族的首领，都召集到耶路撒冷，要把耶和华的约柜从大卫城，就是锡安运上来。'),
('CNV', '历代志下', 14, 5, 3, '于是，以色列众人在七月的节期来到时，都聚集到王那里。'),
('CNV', '历代志下', 14, 5, 4, '以色列的众长老来到了，利未人就抬起约柜。'),
('CNV', '历代志下', 14, 5, 5, '他们把约柜、会幕和会幕里的一切神圣器皿都抬上来；是祭司和利未人把它们抬上来的。'),
('CNV', '历代志下', 14, 5, 6, '所罗门王和那些聚集到他那里的以色列全体会众，都在约柜前献上牛羊为祭，数量无法计算，不能数点。'),
('CNV', '历代志下', 14, 5, 7, '众祭司把耶和华的约柜抬进放约柜的地方，就是内殿，至圣所里面，放在两个基路伯的翅膀底下。'),
('CNV', '历代志下', 14, 5, 8, '基路伯在约柜上面张开翅膀，遮盖着约柜和抬约柜的杠。'),
('CNV', '历代志下', 14, 5, 9, '那两根杠很长，在内殿前可以看见约柜那里的杠头，在殿外却看不见；直到今日，那两根杠还在那里。'),
('CNV', '历代志下', 14, 5, 10, '约柜里只有两块石版，就是以色列人出埃及以后，耶和华和他们立约的时候，摩西在何烈山放进去的。'),
('CNV', '历代志下', 14, 5, 11, '众祭司从圣所里出来的时候（因为所有在场的祭司，不分班次地全都自洁），'),
('CNV', '历代志下', 14, 5, 12, '全体负责歌唱的利未人和亚萨、希幔、耶杜顿，以及他们的儿子和亲族，都穿着细麻布的衣服，站在祭坛的东边，敲钹、鼓瑟、弹琴；和他们在一起的，还有一百二十个祭司吹号；'),
('CNV', '历代志下', 14, 5, 13, '吹号的和歌唱的都一致同声地赞美称谢耶和华。他们吹号、敲钹，用各种乐器高声赞美耶和华，说：“耶和华是良善的，他的慈爱永远长存。”那时云彩充满了那殿，就是耶和华的殿。'),
('CNV', '历代志下', 14, 5, 14, '由于那云彩的缘故，祭司都不能侍立供职，因为神的殿充满了耶和华的荣光。'),
('CNV', '历代志下', 14, 6, 1, '那时所罗门说：“耶和华曾说他要住在幽暗之中。'),
('CNV', '历代志下', 14, 6, 2, '我已经为你建造了巍峨的殿宇，作你永远居住的地方。”'),
('CNV', '历代志下', 14, 6, 3, '然后王转过来，给以色列全体会众祝福，以色列全体会众都站着。'),
('CNV', '历代志下', 14, 6, 4, '所罗门说：“耶和华以色列的神是应当称颂的！他亲口对我的父亲大卫应许的，已亲手作成了，他说：'),
('CNV', '历代志下', 14, 6, 5, '‘自从我领我的子民从埃及地出来的那天，我没有在以色列众支派中，拣选一座城建造殿宇，使我的名留在那里；我也没有拣选一个人作领袖，统治我的子民以色列。'),
('CNV', '历代志下', 14, 6, 6, '我却拣选了耶路撒冷，使我的名留在那里；也拣选了大卫，统治我的子民以色列。’'),
('CNV', '历代志下', 14, 6, 7, '我的父亲大卫有心要为耶和华以色列的神的名建造殿宇。'),
('CNV', '历代志下', 14, 6, 8, '耶和华却对我的父亲大卫说：‘你心想要为我的名建造殿宇，你心意很好；'),
('CNV', '历代志下', 14, 6, 9, '不过不是由你建造殿宇，而是你的儿子，你亲生的儿子，他必为我的名建殿。’'),
('CNV', '历代志下', 14, 6, 10, '现在耶和华实现了他所说过的话，我已经起来接续我的父亲大卫，坐上了以色列的王位，就像耶和华所说的；我为耶和华以色列的神的名建造了这殿。'),
('CNV', '历代志下', 14, 6, 11, '我也把约柜安放在殿里，约柜中有耶和华和以色列人所立的约。”'),
('CNV', '历代志下', 14, 6, 12, '所罗门在以色列全体会众面前，站在耶和华的祭坛前，张开双手；'),
('CNV', '历代志下', 14, 6, 13, '原来所罗门做了一座铜台，长两公尺两公寸，宽两公尺两公寸，高一公尺三公寸，安放在外院中。那时他站在铜台上，在以色列全体会众面前，屈膝下跪，向天张开双手，'),
('CNV', '历代志下', 14, 6, 14, '说：“耶和华以色列的神啊，天上地下没有神可以和你相比的，你向那些一心行在你面前的仆人，常是守约施慈爱的；'),
('CNV', '历代志下', 14, 6, 15, '你对你的仆人我父亲大卫所应许的，你都遵守了，你亲口应许，也亲手成全，就像今日一样。'),
('CNV', '历代志下', 14, 6, 16, '耶和华以色列的神啊，你应许你的仆人我父亲大卫说：‘只要你的子孙谨守他们的行为，遵守我的律法，像你在我面前所行的一样，你就不会断人在我面前坐上以色列的王位。’现在求你应验这话吧。'),
('CNV', '历代志下', 14, 6, 17, '耶和华以色列的神啊，现在求你实现你向你的仆人大卫应许的话吧！'),
('CNV', '历代志下', 14, 6, 18, '“神真的要和人住在地上吗？看哪，天和天上的天也容不下你，何况我建造的这殿呢？'),
('CNV', '历代志下', 14, 6, 19, '耶和华我的神啊，求你垂注你仆人的祷告和祈求，聆听你仆人在你面前所发的呼喊和祷告。'),
('CNV', '历代志下', 14, 6, 20, '求你张开眼睛，昼夜看顾这殿，就是看顾你所说要立你名的地方；求你垂听你仆人向着这地方所发的祷告。'),
('CNV', '历代志下', 14, 6, 21, '求你垂听你的仆人和你的子民以色列的祈求，就是他们向着这地方所发的祷告；求你从天上，从你的居所垂听，垂听和赦免。'),
('CNV', '历代志下', 14, 6, 22, '“人若是得罪了邻舍，有人要他起誓，他就来到这殿，在你的祭坛前起誓；'),
('CNV', '历代志下', 14, 6, 23, '求你从天上垂听，施行你的作为，审判你的仆人，照着恶人所行的报应在他头上；宣告义人无罪，照着他的义行赏赐他。'),
('CNV', '历代志下', 14, 6, 24, '“如果你的子民以色列得罪了你，以致在仇敌面前被击败；后来回心转意，承认你的名，在这殿里向你祷告祈求，'),
('CNV', '历代志下', 14, 6, 25, '求你从天上垂听，赦免你子民以色列的罪，领他们归回你赐给他们和他们列祖的土地。'),
('CNV', '历代志下', 14, 6, 26, '“你的子民因得罪了你，你惩罚他们，使天闭塞不下雨；如果他们向着这地方祷告，承认你的名，离开他们的罪，'),
('CNV', '历代志下', 14, 6, 27, '求你在天上垂听，赦免你的仆人和你的子民以色列的罪，把他们当行的正道指教他们，降雨在你的地上，就是你赐给你的子民作产业的地上。'),
('CNV', '历代志下', 14, 6, 28, '“国中若是有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或是有仇敌围困城镇，或是有什么灾祸，什么疾病，'),
('CNV', '历代志下', 14, 6, 29, '你的子民以色列，无论是个别或是全体，自知自己的灾祸和痛苦，向着这殿张开双手祷告或祈求，'),
('CNV', '历代志下', 14, 6, 30, '求你从天上你的居所垂听和赦免他们，你是知道人心的，你必照着各人所行的报应各人；因为只有你知道世人的心。'),
('CNV', '历代志下', 14, 6, 31, '使他们在你赐给我们列祖的地上，一生一世敬畏你，遵行你的道路。'),
('CNV', '历代志下', 14, 6, 32, '“至于在你的子民以色列以外的外族人，他们为了你的大名、你大能的手和伸出来的膀臂，从远方而来；他们来向着这殿祷告的时候，'),
('CNV', '历代志下', 14, 6, 33, '求你从天上，从你的居所垂听他们，照着外族人向你呼求的一切而行，使地上万民都认识你的名，敬畏你，像你的子民以色列一样；又使他们知道我建造的这殿，是奉为你名的所在。'),
('CNV', '历代志下', 14, 6, 34, '“如果你的子民在你派他们出去的路上，和仇敌作战，他们向着你拣选的这城，和向着我为你的名建造的这殿向你祷告，'),
('CNV', '历代志下', 14, 6, 35, '求你从天上垂听他们的祷告祈求，使他们得胜。'),
('CNV', '历代志下', 14, 6, 36, '“如果你的子民得罪了你（因为世上没有不犯罪的人），你向他们发怒，把他们交在仇敌面前，以致仇敌把他们掳到外地或远或近；'),
('CNV', '历代志下', 14, 6, 37, '如果他们在被掳去的地方回心转意，在被掳去的地方祈求你说：‘我们犯了罪了，我们作了孽了，我们行了恶了。’'),
('CNV', '历代志下', 14, 6, 38, '如果他们在被掳去的地方一心一意归向你，又向着他们自己的地，就是你赐给他们列祖的地，和向着你拣选的这城，以及向着我为你的名建造的这殿祷告，'),
('CNV', '历代志下', 14, 6, 39, '求你从天上，从你的居所垂听他们的祷告祈求，为他们伸冤，赦免得罪了你的那些子民。'),
('CNV', '历代志下', 14, 6, 40, '“我的神啊，现在求你张开眼睛，求你的耳朵垂听在这地方献上的祷告。'),
('CNV', '历代志下', 14, 6, 41, '现在，耶和华神啊，求你起来，愿你和你有大能的约柜进入你安息的地方；耶和华神啊，愿你的祭司都披上救恩；愿你的圣民在福乐中欢欣。'),
('CNV', '历代志下', 14, 6, 42, '耶和华神啊，求你不要转脸不顾你所膏的人：愿你记念你向你仆人大卫所施的慈爱。”'),
('CNV', '历代志下', 14, 7, 1, '所罗门祷告完了，有火从天上降下来，烧尽了燔祭和其他的祭品；耶和华的荣光充满了那殿。'),
('CNV', '历代志下', 14, 7, 2, '因为耶和华的荣光充满了耶和华的殿，祭司都不能进入耶和华的殿。'),
('CNV', '历代志下', 14, 7, 3, '那火降下，耶和华的荣光停在殿上的时候，以色列众人都看见；于是他们在铺石地跪下，俯伏在地，敬拜称颂耶和华说：“耶和华是良善的，他的慈爱永远长存。”'),
('CNV', '历代志下', 14, 7, 4, '王和全体人民都在耶和华面前献祭。'),
('CNV', '历代志下', 14, 7, 5, '所罗门王献上了二万二千头牛、十二万只羊为祭。这样，王和全体人民为神的殿举行了奉献礼。'),
('CNV', '历代志下', 14, 7, 6, '祭司都站在自己的岗位上；利未人也站着，拿着大卫王所做的耶和华的乐器，称颂耶和华，因为他的慈爱永远长存；大卫藉着他们赞美耶和华的时候，祭司在众人前面吹号；以色列众人都站着。'),
('CNV', '历代志下', 14, 7, 7, '所罗门把耶和华殿前院子当中的地方分别为圣，在那里献上了燔祭和平安祭的脂肪，因为所罗门所做的铜坛容不下所有的燔祭、素祭和脂肪。'),
('CNV', '历代志下', 14, 7, 8, '那时，所罗门和全体以色列人，就是来自哈马口，直到埃及小河的一群极大的会众，一起举行了七天的节期。'),
('CNV', '历代志下', 14, 7, 9, '第八天举行了严肃会，又举行献坛礼七天，举行了七天的节期。'),
('CNV', '历代志下', 14, 7, 10, '七月二十三日，王遣散众民回家；他们因看见耶和华向大卫、所罗门和他的子民以色列所施的恩惠，心里都欢喜快乐。'),
('CNV', '历代志下', 14, 7, 11, '这样，所罗门完成了耶和华的殿宇和王宫。在耶和华的殿里或所罗门的宫中，所罗门心里要作的，都顺利地作成了。'),
('CNV', '历代志下', 14, 7, 12, '夜间，耶和华向所罗门显现，对他说：“我已经听了你的祷告，也为我自己选择了这地方作献祭的殿。'),
('CNV', '历代志下', 14, 7, 13, '如果我使天闭塞不下雨，或吩咐蝗虫吞吃这地的土产，或差遣瘟疫到我的子民中间来；'),
('CNV', '历代志下', 14, 7, 14, '这称为我名下的子民，若是谦卑、祷告、寻求我的面，转离他们的恶行，我必从天上垂听，赦免他们的罪，医治他们的地。'),
('CNV', '历代志下', 14, 7, 15, '现在我的眼睛必张开，我的耳朵必垂听在这地所发的祷告。'),
('CNV', '历代志下', 14, 7, 16, '现在我拣选了这殿，把它分别为圣，使我的名永远在这殿中；我的眼和我的心也常常留在那里。'),
('CNV', '历代志下', 14, 7, 17, '至于你，你若是在我面前行事为人像你的父亲大卫所行的那样，遵行我吩咐你的一切话，谨守我的律例和典章，'),
('CNV', '历代志下', 14, 7, 18, '我就必巩固你的国位，好像我和你父亲大卫所立的约说：‘你的子孙必不会断人作君王统治以色列。’'),
('CNV', '历代志下', 14, 7, 19, '“可是，如果你们转离我，丢弃我在你们面前颁布的律例和诫命，去事奉和敬拜别的神，'),
('CNV', '历代志下', 14, 7, 20, '我就必把以色列人从我赐给他们的土地上拔出来，并且我为自己的名分别为圣的这殿，我也必从我面前舍弃，使这殿在万民中成为笑谈和讥笑的对象。'),
('CNV', '历代志下', 14, 7, 21, '这殿虽然高大，但将来经过的人，都必惊讶，说：‘耶和华为什么这样对待这地和这殿呢？’'),
('CNV', '历代志下', 14, 7, 22, '人必回答说：‘是因为这地的人离弃了耶和华他们列祖的神，就是领他们从埃及地出来的神，去亲近别的神，敬拜和事奉他们；所以，耶和华使这一切灾祸临到他们。’”'),
('CNV', '历代志下', 14, 8, 1, '所罗门建造耶和华的殿和自己的王宫，用了二十年才完成。'),
('CNV', '历代志下', 14, 8, 2, '所罗门又修筑希兰送给他的那些城市，使以色列人住在那里。'),
('CNV', '历代志下', 14, 8, 3, '所罗门到哈玛琐巴去，占领了那地方。'),
('CNV', '历代志下', 14, 8, 4, '所罗门又修筑了在旷野的达莫，和他在哈玛建造的一切贮藏货物的城市。'),
('CNV', '历代志下', 14, 8, 5, '他又建造上伯．和仑和下伯．和仑，成了有墙、有门和有闩的设防城；'),
('CNV', '历代志下', 14, 8, 6, '又建造巴拉和所罗门拥有的一切贮藏货物的城市，以及一切囤放战车的城市，马兵驻扎的城市，和所罗门在耶路撒冷、黎巴嫩，以及他统治的全境内喜爱建造的一切。'),
('CNV', '历代志下', 14, 8, 7, '至于以色列人以外的赫人、亚摩利人、比利洗人、希未人和耶布斯人剩下来的人民，'),
('CNV', '历代志下', 14, 8, 8, '他们的子孙仍然留在那地，以色列人没有消灭他们。于是，所罗门征召他们作苦工，直到今日。'),
('CNV', '历代志下', 14, 8, 9, '唯独以色列人，所罗门没有驱使他们为他的工程作奴仆；他们作了他的战士、军长、车兵长和马兵长。'),
('CNV', '历代志下', 14, 8, 10, '所罗门王有二百五十名监工，监督工人。'),
('CNV', '历代志下', 14, 8, 11, '所罗门把法老的女儿从大卫城，带到他为她建造的宫里去；因为他说：“我的妻子不可住在以色列王大卫的宫里，因为耶和华的约柜所到的地方都是神圣的。”'),
('CNV', '历代志下', 14, 8, 12, '那时，所罗门在耶和华的坛上，就是在走廊前面他建筑的坛上，向耶和华献上燔祭，'),
('CNV', '历代志下', 14, 8, 13, '又照着摩西的吩咐，在安息日、初一和一年三次特定的节期，就是除酵节、七七节、住棚节，献上每日当献的。'),
('CNV', '历代志下', 14, 8, 14, '所罗门又照着他父亲大卫所定的，设立了祭司的班次，执行他们的事奉，又派遣利未人，各守本职，赞美耶和华，在祭司面前照着每日的本分事奉。又派守门的按着班次看守各门。因为这是神人大卫的吩咐。'),
('CNV', '历代志下', 14, 8, 15, '王对祭司和利未人所吩咐的，无论是什么事务，或是有关库房的事，他们都没有违抗。'),
('CNV', '历代志下', 14, 8, 16, '从耶和华的殿奠基的日子起，直到建成，所罗门的一切工程都进行顺利。这样，耶和华的殿就完成了。'),
('CNV', '历代志下', 14, 8, 17, '那时，所罗门往以东地，到靠近海边的以旬．迦别和以禄去了。'),
('CNV', '历代志下', 14, 8, 18, '希兰派他的臣仆，把船只和熟悉航海的仆人，送到所罗门那里。他们和所罗门的仆人一同去到俄斐，从那里得了一万五千公斤金子，运到所罗门王那里。'),
('CNV', '历代志下', 14, 9, 1, '示巴女王听见所罗门的名声，就来到耶路撒冷，要用难题试试所罗门。跟随她的人很多，又有骆驼驮着香料、大批黄金和宝石。她来到所罗门那里，就把她心里所有的难题，都对所罗门说出来。'),
('CNV', '历代志下', 14, 9, 2, '所罗门把她的一切难题，都给她解答了；没有一样难倒所罗门，不能给她解答的。'),
('CNV', '历代志下', 14, 9, 3, '示巴女王看见所罗门的智慧和他建造的宫殿，'),
('CNV', '历代志下', 14, 9, 4, '他席上的食物，群臣的座位，仆人的侍候和他们的服饰，酒政和酒政的服饰，以及所罗门在耶和华殿里所献的燔祭，就十分惊讶。'),
('CNV', '历代志下', 14, 9, 5, '于是她对王说：“我在本国听见关于你的事和你的智慧，实在是真的。'),
('CNV', '历代志下', 14, 9, 6, '我先前不信他们的话，等到我来了，亲眼看见了，才知道你智慧的伟大，人告诉我的还不到一半。你实在是见面胜似闻名。'),
('CNV', '历代志下', 14, 9, 7, '属你的人是有福的，你的臣仆是有福的，因为他们可以常常侍立在你面前，聆听你的智慧。'),
('CNV', '历代志下', 14, 9, 8, '耶和华你的神是应当称颂的，因他喜悦你，使你坐在他的王位上，为耶和华你的神作王；因为你的神爱以色列人，要永远坚立他们，所以立你作他们的王，好秉公行义。”'),
('CNV', '历代志下', 14, 9, 9, '于是示巴女王把约四千公斤金子、大批香料和宝石送给所罗门王；示巴女王送给所罗门王的香料，是犹大地从来没有过的。'),
('CNV', '历代志下', 14, 9, 10, '希兰的仆人和所罗门的仆人从俄斐把黄金运来，也把檀香木和宝石运了来。'),
('CNV', '历代志下', 14, 9, 11, '王用檀香木为耶和华的殿和王宫作了台阶，又为唱歌的人作了琴瑟；像这样的东西，是在犹大地从来没有见过的。'),
('CNV', '历代志下', 14, 9, 12, '所罗门王按着示巴女王带来给他的，回送她礼物；此外，还把女王所愿所求的，都送给她，于是女王和她的臣仆都返回本国去了。'),
('CNV', '历代志下', 14, 9, 13, '所罗门每年所得的金子，共重两万三千公斤，'),
('CNV', '历代志下', 14, 9, 14, '另外，还有从商人和行商运来的，阿拉伯诸王和本国的各总督，都把金银运来给所罗门。'),
('CNV', '历代志下', 14, 9, 15, '所罗门王用锤炼好的金子做了二百面大盾牌，每一面大盾牌用锤炼好的金子七公斤。'),
('CNV', '历代志下', 14, 9, 16, '又用锤炼好的金子做了三百面小盾牌，每一面小盾牌用锤炼好的金子约三公斤；王把这些盾牌都放在黎巴嫩林宫。'),
('CNV', '历代志下', 14, 9, 17, '王用象牙做了一个大宝座，包上纯金。'),
('CNV', '历代志下', 14, 9, 18, '宝座有六级台阶，又用金脚凳和宝座相连，座位两边都有扶手，扶手旁边各有一只狮子站立。'),
('CNV', '历代志下', 14, 9, 19, '六级台阶上共有十二只狮子站立；每级两只，一左一右；在列国中都没有这样做的。'),
('CNV', '历代志下', 14, 9, 20, '所罗门王的一切杯爵都是金的；黎巴嫩林宫里的一切器皿都是精金做的；在所罗门的时代，银子算不得什么。'),
('CNV', '历代志下', 14, 9, 21, '因为王的船只和希兰的仆人一同到他施去；往他施的船只每三年回来一次，载着金银、象牙、猿猴和孔雀回来。'),
('CNV', '历代志下', 14, 9, 22, '所罗门王的财富和智慧，胜过世上的列王。'),
('CNV', '历代志下', 14, 9, 23, '世上的列王都求见所罗门的面，要听神赐给他的智慧。'),
('CNV', '历代志下', 14, 9, 24, '他们各人带来的礼物有：银器、金器、衣服、兵器、香料、骡马；每年都有一定的数量。'),
('CNV', '历代志下', 14, 9, 25, '所罗门有四千马廊的车马，还有马兵一万二千，他把这些人马安置在囤车城和耶路撒冷，就是与王在一起。'),
('CNV', '历代志下', 14, 9, 26, '所罗门统治列王，从幼发拉底河到非利士地，直到埃及的边界。'),
('CNV', '历代志下', 14, 9, 27, '王在耶路撒冷使银子好像石头，使香柏木好像平原的桑树那么多。'),
('CNV', '历代志下', 14, 9, 28, '人们从埃及和各地把马匹运到所罗门那里。'),
('CNV', '历代志下', 14, 9, 29, '所罗门其余的事迹，一生的始末，不是都记在拿单先知的记录上，示罗人亚希雅的预言上，以及先见易多论到尼八的儿子耶罗波安的启示录上吗？'),
('CNV', '历代志下', 14, 9, 30, '所罗门在耶路撒冷作王统治全以色列共四十年。'),
('CNV', '历代志下', 14, 9, 31, '所罗门和他的列祖同睡，埋葬在他父亲大卫的城里；他的儿子罗波安接续他作王。'),
('CNV', '历代志下', 14, 10, 1, '罗波安到示剑去，因为全体以色列人都去了示剑，要立他作王。'),
('CNV', '历代志下', 14, 10, 2, '那时，尼八的儿子耶罗波安，因为逃避所罗门王，住在埃及；他一听见这事，就从埃及回来。'),
('CNV', '历代志下', 14, 10, 3, '他们派人去叫耶罗波安回来；他就和全体以色列人来见罗波安，对他说：'),
('CNV', '历代志下', 14, 10, 4, '“你父亲使我们所负的轭甚重，现在求你减轻你父亲加在我们身上的劳役和重轭，我们就服事你。”'),
('CNV', '历代志下', 14, 10, 5, '罗波安对他们说：“三天以后你们再来见我吧！”众人就离去了。'),
('CNV', '历代志下', 14, 10, 6, '罗波安王和一些在他父亲所罗门在世的时候，侍立在所罗门面前的老人商议，说：“你们有什么提议，我好回覆这班民众呢？”'),
('CNV', '历代志下', 14, 10, 7, '他们对他说：“如果王善待人民，使他们喜悦，对他们说好话，他们就必永远作你的仆人。”'),
('CNV', '历代志下', 14, 10, 8, '王不接受这些老人的意见，却去和那些同他一起长大，侍立在他面前的年轻人商议，'),
('CNV', '历代志下', 14, 10, 9, '问他们：“这人民对我说：求你减轻你父亲加在我们身上的重轭吧。你们有什么提议，我好回覆他们呢？”'),
('CNV', '历代志下', 14, 10, 10, '那些同他一起长大的年轻人对他说：“这人民对王说：‘你父亲使我们所负的轭甚重，现在求你减轻些吧。’王要这样对他们说：‘我的小拇指比我父亲的腰还粗呢。'),
('CNV', '历代志下', 14, 10, 11, '我父亲把重轭加在你们身上，我必使你们负更重的轭；我父亲用鞭打你们，我却要用蝎子鞭责打你们。’”'),
('CNV', '历代志下', 14, 10, 12, '耶罗波安和全体人民都遵照罗波安王所说“你们第三天再来见我”的话，第三天来见罗波安。'),
('CNV', '历代志下', 14, 10, 13, '罗波安王很严厉地回答他们。罗波安王不接受老人的意见，'),
('CNV', '历代志下', 14, 10, 14, '却照着年轻人的主意对他们说：“我父亲使你们负重轭，我必使你们负更重的轭；我父亲用鞭子责打你们，我却要用蝎子鞭责打你们。”'),
('CNV', '历代志下', 14, 10, 15, '王不听从人民的要求，这事原是出于神，为要实现耶和华藉着示罗人亚希雅对尼八的儿子耶罗波安所说的话。'),
('CNV', '历代志下', 14, 10, 16, '以色列人见王不听他们的要求，就对王说：“我们和大卫有什么关系呢？我们和耶西的儿子并不相干。以色列人哪，各回各家去吧，大卫啊，现在只顾你自己的家吧。”于是全体以色列人都回自己的家去了。'),
('CNV', '历代志下', 14, 10, 17, '只有那些住在犹大众城镇的以色列人，罗波安仍然作他们的王。'),
('CNV', '历代志下', 14, 10, 18, '罗波安王差派了监管苦工的哈多兰（“哈多兰”是“亚多尼兰”或“亚多兰”的另一种写法﹔参王上4:6，12:18）到以色列人那里去，以色列人就用石头把他打死了。罗波安王急忙上车，逃回耶路撒冷去了。'),
('CNV', '历代志下', 14, 10, 19, '这样，以色列人背叛了大卫家，直到今日。'),
('CNV', '历代志下', 14, 11, 1, '罗波安回到耶路撒冷，就召集犹大家和便雅悯家，共十八万人，都是精兵，要和以色列人交战，好把王国夺回，再归自己。'),
('CNV', '历代志下', 14, 11, 2, '但耶和华的话临到神人示玛雅，说：'),
('CNV', '历代志下', 14, 11, 3, '“你要告诉所罗门的儿子、犹大王罗波安，以及所有住在犹大和便雅悯的以色列人，说：'),
('CNV', '历代志下', 14, 11, 4, '‘耶和华这样说：你们不可上去，也不可和你们的兄弟交战。你们各自回家去吧，因为这事是出于我。’”于是他们听从耶和华的话，都回家，不去攻打耶罗波安。'),
('CNV', '历代志下', 14, 11, 5, '罗波安住在耶路撒冷，他在犹大建造了多座设防城。'),
('CNV', '历代志下', 14, 11, 6, '他修筑了伯利恒、以坦、提哥亚、'),
('CNV', '历代志下', 14, 11, 7, '伯．夙、梭哥、亚杜兰、'),
('CNV', '历代志下', 14, 11, 8, '迦特、玛利沙、西弗、'),
('CNV', '历代志下', 14, 11, 9, '亚多莱音、拉吉、亚西加、'),
('CNV', '历代志下', 14, 11, 10, '琐拉、亚雅仑、希伯仑；这些都是犹大和便雅悯境内的设防城。'),
('CNV', '历代志下', 14, 11, 11, '他又巩固这些设防城，在城里设军长，贮备粮食、油和酒。'),
('CNV', '历代志下', 14, 11, 12, '又在各城装备了大盾牌和矛枪，使这些城市十分坚固。这样，犹大和便雅悯都在他统治之下。'),
('CNV', '历代志下', 14, 11, 13, '全以色列的祭司和利未人，都从各地来归向罗波安。'),
('CNV', '历代志下', 14, 11, 14, '利未人放弃了他们的草场和产业，来到犹大和耶路撒冷，是因为耶罗波安和他的儿子排斥他们，不准他们作祭司事奉耶和华。'),
('CNV', '历代志下', 14, 11, 15, '耶罗波安为邱坛、公山羊神，以及他铸造的牛犊，自己设立了祭司。'),
('CNV', '历代志下', 14, 11, 16, '以色列众支派中所有定意寻求耶和华以色列的神的，都随着利未人来到耶路撒冷，向耶和华他们列祖的神献祭。'),
('CNV', '历代志下', 14, 11, 17, '这样，他们就加强了犹大国的势力，使所罗门的儿子罗波安强盛了三年，因为他们在这三年，跟随了大卫和所罗门的道路。'),
('CNV', '历代志下', 14, 11, 18, '罗波安娶了大卫的儿子耶利摩的女儿玛哈拉作妻子，她也就是耶西的儿子以利押的女儿亚比孩的女儿；'),
('CNV', '历代志下', 14, 11, 19, '她给罗波安生了几个儿子，就是耶乌施、示玛利雅和撒罕。'),
('CNV', '历代志下', 14, 11, 20, '后来，罗波安又娶了押沙龙的外孙女玛迦；玛迦给他生了亚比雅、亚太、细撒和示罗密。'),
('CNV', '历代志下', 14, 11, 21, '罗波安共娶了十八个妻子和六十个妾；共生了二十八个儿子，六十个女儿；他却爱押沙龙的外孙女玛迦，胜过其他的妻妾。'),
('CNV', '历代志下', 14, 11, 22, '于是罗波安立了玛迦的儿子亚比雅作太子，在他的兄弟中为首，因为罗波安想立他继承王位。'),
('CNV', '历代志下', 14, 11, 23, '罗波安很有智慧地把自己的儿子分散在犹大和便雅悯各地的设防城中，供给他们大批粮食，又为他们娶了多位妻子。'),
('CNV', '历代志下', 14, 12, 1, '罗波安的王位稳定，他也强盛起来，就离弃了耶和华的律法，全体以色列人也都跟随他。'),
('CNV', '历代志下', 14, 12, 2, '罗波安王第五年，埃及王示撒上来攻打耶路撒冷，因为他们得罪了耶和华。'),
('CNV', '历代志下', 14, 12, 3, '示撒率领战车一千二百辆，马兵六万，和他一同从埃及出来的路比人、苏基人和古实人，多得无法数算。'),
('CNV', '历代志下', 14, 12, 4, '他攻取了犹大境内的设防城，然后来到耶路撒冷。'),
('CNV', '历代志下', 14, 12, 5, '那时，犹大的众领袖，因为示撒的缘故，就聚集在耶路撒冷；示玛雅先知就来见罗波安和众领袖，对他们说：“耶和华这样说：‘你们既然离弃了我，所以我也离弃你们，把你们交在示撒的手里。’”'),
('CNV', '历代志下', 14, 12, 6, '于是以色列的众领袖和君王，都谦卑下来，说：“耶和华是公义的。”'),
('CNV', '历代志下', 14, 12, 7, '耶和华看见他们谦卑下来，耶和华的话就临到示玛雅，说：“他们既然谦卑下来，我就不灭绝他们；我必使他们暂时得救，我必不藉着示撒把我的烈怒倾倒在耶路撒冷。'),
('CNV', '历代志下', 14, 12, 8, '虽然这样，他们仍必作示撒的仆人，好使他们知道，服事我和服事世上的列国有什么分别。”'),
('CNV', '历代志下', 14, 12, 9, '于是埃及王示撒上来攻打耶路撒冷，夺取了耶和华殿和王宫里的宝物，把它们全部带走，又夺去了所罗门所做的金盾牌。'),
('CNV', '历代志下', 14, 12, 10, '罗波安王做了一些铜盾牌代替那些金盾牌，交给那些看守宫门的守卫长看管。'),
('CNV', '历代志下', 14, 12, 11, '每逢王进耶和华殿的时候，守卫就来拿这些盾牌，事后又把盾牌送回守卫房那里。'),
('CNV', '历代志下', 14, 12, 12, '王既然谦卑下来，耶和华的烈怒就止息，没有把他完全消灭。何况在犹大中还有善事。'),
('CNV', '历代志下', 14, 12, 13, '罗波安王在耶路撒冷渐渐强盛，继续作王。罗波安登基的时候是四十一岁；他在耶和华从以色列众支派中选出来，立下他名的耶路撒冷城中，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。'),
('CNV', '历代志下', 14, 12, 14, '罗波安行恶，因为他没有定意寻求耶和华。'),
('CNV', '历代志下', 14, 12, 15, '罗波安的事迹，一生的始末，不是都记在示玛雅先知，和先见易多有关家谱的记录上么？罗波安和耶罗波安二人常有争战。'),
('CNV', '历代志下', 14, 12, 16, '罗波安和他的列祖同睡，埋葬在大卫城里。他的儿子亚比雅（“亚比雅”是“亚比央”的另一种写法﹔参王上14:31）接续他作王。'),
('CNV', '历代志下', 14, 13, 1, '耶罗波安王第十八年，亚比雅登基作犹大王。'),
('CNV', '历代志下', 14, 13, 2, '他在耶路撒冷作王三年；他母亲名叫米该亚（“米该亚”是“玛迦”的另一种写法﹔参王上15:2），是基比亚人乌列的女儿。亚比雅和耶罗波安常有争战。'),
('CNV', '历代志下', 14, 13, 3, '有一次，亚比雅带着精兵四十万，都是英勇的战士，准备开战；耶罗波安也带着八十万精兵，都是英勇的战士，列阵对抗亚比雅。'),
('CNV', '历代志下', 14, 13, 4, '亚比雅起来站在以法莲山地中的洗玛脸山上，说：“耶罗波安和以色列众民哪，你们要听我的话。'),
('CNV', '历代志下', 14, 13, 5, '耶和华以色列的神曾经立了盐约，要把以色列国永远赐给大卫和他的子孙，你们不知道吗？'),
('CNV', '历代志下', 14, 13, 6, '可是大卫的儿子所罗门的仆人，尼八的儿子耶罗波安，却起来背叛了他的主。'),
('CNV', '历代志下', 14, 13, 7, '有些无赖匪徒结集跟从他，欺负所罗门的儿子罗波安；那时罗波安还年幼，心里惊怯，所以不能抵挡他们。'),
('CNV', '历代志下', 14, 13, 8, '现在你们有意要反抗大卫子孙手下的耶和华的国；你们人数众多，你们那里也有金牛犊，就是耶罗波安为你们所做，当作神的。'),
('CNV', '历代志下', 14, 13, 9, '你们不是驱逐了耶和华的祭司，亚伦的子孙和利未人吗？你们不是像世上万民为自己立祭司吗？无论什么人牵来一头公牛犊和七只公绵羊，自己授圣职，就可以作那本不是神的祭司。'),
('CNV', '历代志下', 14, 13, 10, '至于我们，耶和华是我们的神，我们并没有离弃他；我们有事奉耶和华的祭司，都是亚伦的子孙，并且有利未人负责工作。'),
('CNV', '历代志下', 14, 13, 11, '他们每日早晚向耶和华献燔祭，焚烧芬芳的香；在清洁的桌子上摆上陈设饼；每天晚上燃点金灯台的灯盏；我们谨守耶和华我们的神的吩咐，你们却离弃了他。'),
('CNV', '历代志下', 14, 13, 12, '“看哪，神和我们同在，率领我们；他的祭司拿着号筒向你们大声吹响。以色列人哪，你们不可和耶和华你们列祖的神作战，因为你们必不能得胜。”'),
('CNV', '历代志下', 14, 13, 13, '耶罗波安却派伏兵绕到犹大人的背后。这样，犹大人前面有以色列人，他们背后也有伏兵。'),
('CNV', '历代志下', 14, 13, 14, '犹大人转身，看见自己前后受敌，就呼求耶和华，祭司也都吹号。'),
('CNV', '历代志下', 14, 13, 15, '于是犹大人大声吶喊；犹大人大声吶喊的时候，神就在亚比雅和犹大人面前，使耶罗波安和以色列众人大败而逃。'),
('CNV', '历代志下', 14, 13, 16, '以色列人在犹大人面前逃跑；神把他们交在犹大人手里。'),
('CNV', '历代志下', 14, 13, 17, '亚比雅和他的人民大大地击杀以色列人；以色列人中倒毙的精兵共有五十万。'),
('CNV', '历代志下', 14, 13, 18, '那时，以色列人被击败了，犹大人获得胜利，因为他们倚靠耶和华他们列祖的神。'),
('CNV', '历代志下', 14, 13, 19, '亚比雅追赶耶罗波安，夺取了他的几座城，就是伯特利和属于伯特利的乡镇，耶沙拿和属于耶沙拿的乡镇，以法拉音和属于以法拉音的乡镇。'),
('CNV', '历代志下', 14, 13, 20, '亚比雅在世的日子，耶罗波安不再强盛。耶和华击打他，他就死了。'),
('CNV', '历代志下', 14, 13, 21, '亚比雅却不断强盛起来，娶了十四个妻妾，生了二十二个儿子，十六个女儿。'),
('CNV', '历代志下', 14, 13, 22, '亚比雅其余的事迹和他的言行，都记在易多先知的传记上。'),
('CNV', '历代志下', 14, 14, 1, '亚比雅和他的列祖同睡，埋葬在大卫城里，他的儿子亚撒接续他作王。亚撒在世的日子，国中太平了十年。（本节在《马索拉文本》为13:23）'),
('CNV', '历代志下', 14, 14, 2, '亚撒行耶和华他的神看为善为正的事。（本节在《马索拉文本》为14:1）'),
('CNV', '历代志下', 14, 14, 3, '他除掉外族人的祭坛和邱坛，打断神柱，砍下亚舍拉，'),
('CNV', '历代志下', 14, 14, 4, '吩咐犹大人寻求耶和华他们列祖的神，遵行他的律法和诫命。'),
('CNV', '历代志下', 14, 14, 5, '他又在犹大各城中，除掉邱坛和香坛。那时全国在他的统治下享受太平。'),
('CNV', '历代志下', 14, 14, 6, '他又在犹大建造了几座设防城，因为国中太平，多年没有战争，耶和华使他享受安宁。'),
('CNV', '历代志下', 14, 14, 7, '他对犹大人说：“我们要建造这些城，在四周筑墙，建造城楼，安设城门，制作门闩。这地还属于我们，是因为我们寻求耶和华我们的神；我们既然寻求他，他就使我们四境平安。”于是他们兴工建造，事事顺利。'),
('CNV', '历代志下', 14, 14, 8, '亚撒的军队，拿大盾牌和矛枪的犹大人，共有三十万；拿小盾牌和拉弓的便雅悯人，共有二十八万；他们都是英勇的战士。'),
('CNV', '历代志下', 14, 14, 9, '那时有古实人谢拉率领一百万军队，战车三百辆，前来攻打犹大人；他来到了玛利沙。'),
('CNV', '历代志下', 14, 14, 10, '于是亚撒出去迎战；他们就在玛利沙的洗法谷列阵相对。'),
('CNV', '历代志下', 14, 14, 11, '亚撒呼求耶和华他的神说：“耶和华啊，强弱悬殊，除你以外没有别的帮助。耶和华我们的神啊，求你帮助我们。因为我们倚靠你，奉你的名去对抗这大军。耶和华啊，你是我们的神，不要让人胜过你。”'),
('CNV', '历代志下', 14, 14, 12, '于是耶和华在亚撒和犹大人面前，使古实人大败，古实人就逃跑。'),
('CNV', '历代志下', 14, 14, 13, '亚撒和跟随他的人民追赶他们，直到基拉耳；古实人被杀的很多，不能恢复强盛；因为他们在耶和华和他的军队面前被击溃了；犹大人夺取了极多战利品。'),
('CNV', '历代志下', 14, 14, 14, '他们又攻击基拉耳周围的一切城市，因为各城的人都惧怕耶和华。犹大人又把各城洗掠一空，因为城中的财物甚多。'),
('CNV', '历代志下', 14, 14, 15, '他们又毁坏了牲畜的棚，牵走了很多的羊和骆驼，然后回耶路撒冷去了。'),
('CNV', '历代志下', 14, 15, 1, '神的灵降在俄德的儿子亚撒利雅身上，'),
('CNV', '历代志下', 14, 15, 2, '亚撒利雅就出来迎接亚撒，对他说：“亚撒和犹大、便雅悯所有的人哪！请听我说。你们跟随耶和华，耶和华就和你们同在；你们寻求他，就必给你们寻见；你们离弃他，他必离弃你们。'),
('CNV', '历代志下', 14, 15, 3, '以色列人没有真神，没有教导他们的祭司，没有律法，已经很久了。'),
('CNV', '历代志下', 14, 15, 4, '但他们在遭难的时候，回转归向耶和华以色列的神，寻求他，他就给他们寻见。'),
('CNV', '历代志下', 14, 15, 5, '那时，出入的人都没有平安，因为各国的居民都遭遇动乱。'),
('CNV', '历代志下', 14, 15, 6, '这国攻击那国，这城攻击那城，因为神用各样灾难使他们纷乱。'),
('CNV', '历代志下', 14, 15, 7, '但你们要坚强，不要胆怯，因为你们所行的，必有赏报。”'),
('CNV', '历代志下', 14, 15, 8, '亚撒听了这些话，和俄德的儿子亚撒利雅先知所说的预言以后，就勇敢起来，在犹大、便雅悯全地，以及以法莲山地夺取的各城，把可憎的偶像除去，又在耶和华殿的走廊前面，重新修造耶和华的祭坛。'),
('CNV', '历代志下', 14, 15, 9, '他又召聚了犹大和便雅悯所有的人，以及在他们中间寄居的以法莲人、玛拿西人、西缅人。以色列人看见了耶和华亚撒的神和他同在，就有很多人投奔亚撒。'),
('CNV', '历代志下', 14, 15, 10, '亚撒在位第十五年三月，他们聚集在耶路撒冷。'),
('CNV', '历代志下', 14, 15, 11, '那一天，他们从夺回来的战利品当中，把七百头牛，七千只羊，献给耶和华为祭，'),
('CNV', '历代志下', 14, 15, 12, '他们也立约，要一心一意寻求耶和华他们列祖的神。'),
('CNV', '历代志下', 14, 15, 13, '不寻求耶和华以色列的神的，无论男女老幼，都必处死。'),
('CNV', '历代志下', 14, 15, 14, '他们就大声欢呼，吹起号角，向耶和华起誓。'),
('CNV', '历代志下', 14, 15, 15, '犹大众人都为了所起的誓快乐，因为他们一心起誓，尽意寻求耶和华，耶和华就给他们寻见，并且使他们四境安宁。'),
('CNV', '历代志下', 14, 15, 16, '亚撒王也废掉他的祖母玛迦太后的位，因为她曾给亚舍拉做了可憎的像；亚撒把她那可憎的像砍了下来，捣得粉碎，烧在汲沦溪旁。'),
('CNV', '历代志下', 14, 15, 17, '只是邱坛还没有从以色列中除掉，但亚撒的心一生都完全忠于耶和华。'),
('CNV', '历代志下', 14, 15, 18, '亚撒把他父亲所分别为圣，和他自己所分别为圣的金银和器皿，都送进神的殿里。'),
('CNV', '历代志下', 14, 15, 19, '从那时，直到亚撒在位第三十五年，都没有战争。'),
('CNV', '历代志下', 14, 16, 1, '亚撒在位第三十六年，以色列王巴沙上来攻打犹大，修筑拉玛，不许人离开或进入犹大王亚撒的国境。'),
('CNV', '历代志下', 14, 16, 2, '于是亚撒从耶和华的殿和王宫的库房里取出金银来，送给住在大马士革的亚兰王便．哈达，说：'),
('CNV', '历代志下', 14, 16, 3, '“你父亲和我父亲曾经立约，你和我也要立约。现在我把金银送给你，请你去废除你和以色列王巴沙订立的约，好使他离开我而去。”'),
('CNV', '历代志下', 14, 16, 4, '便．哈达听从了亚撒王的话，就派遣他属下的众军长去攻击以色列的城市，他们攻陷了以云、但、亚伯．玛音和拿弗他利一切贮藏货物的城市。'),
('CNV', '历代志下', 14, 16, 5, '巴沙听见了，就停止修筑拉玛，把工程都停止了。'),
('CNV', '历代志下', 14, 16, 6, '于是亚撒王带领犹大众人，把巴沙修筑拉玛所用的石头和木材都搬走，用来修筑迦巴和米斯巴。'),
('CNV', '历代志下', 14, 16, 7, '那时，先见哈拿尼来见犹大王亚撒，对他说：“因你倚靠亚兰王，没有倚靠耶和华你的神，所以亚兰王的军队才可以脱离你的手。'),
('CNV', '历代志下', 14, 16, 8, '古实人和路比人不是有强大的军队吗？战车和马兵不是极多吗？只因你倚靠耶和华，耶和华就把他们交在你手里。'),
('CNV', '历代志下', 14, 16, 9, '耶和华的眼目遍察全地，一心归向他的，他必以大能扶助他们；你作这事太愚昧了。从今以后，你必常有战争。”'),
('CNV', '历代志下', 14, 16, 10, '于是亚撒对先见发怒，把他囚在监里，因为亚撒为了这事很恼怒他。同时亚撒也压迫人民。'),
('CNV', '历代志下', 14, 16, 11, '亚撒所行的事迹，一生的始末，都记在犹大和以色列诸王记上。'),
('CNV', '历代志下', 14, 16, 12, '亚撒在位第三十九年，患了脚病，病情严重；可是，连他患病的时候，也没有寻求耶和华，只管寻求医生。'),
('CNV', '历代志下', 14, 16, 13, '亚撒作王四十一年以后死了，和他的列祖同睡。'),
('CNV', '历代志下', 14, 16, 14, '人把他埋葬在大卫城里他为自己所凿的坟墓中。他们把他放在堆满按著作香的方法调和的各样香料的床上，又为他烧了很多香料。'),
('CNV', '历代志下', 14, 17, 1, '亚撒的儿子约沙法接续他作王；约沙法发愤图强，对抗以色列人。'),
('CNV', '历代志下', 14, 17, 2, '他把军队安置在犹大的一切设防城里，又在犹大地和他父亲亚撒占领的以法莲各城里驻扎防军。'),
('CNV', '历代志下', 14, 17, 3, '耶和华和约沙法同在，因为他遵行了他祖先大卫最初所行的道路，没有寻求巴力。'),
('CNV', '历代志下', 14, 17, 4, '只寻求他父亲的神，遵行神的诫命，没有随从以色列人的行为。'),
('CNV', '历代志下', 14, 17, 5, '因此，耶和华使他统治的国稳固；犹大各地都给他进贡，所以约沙法的财富很多，极有尊荣。'),
('CNV', '历代志下', 14, 17, 6, '他勇敢地遵行耶和华的道路，并且从犹大地中除掉邱坛和亚舍拉。'),
('CNV', '历代志下', 14, 17, 7, '他作王第三年，就差派他的大臣便．亥伊勒、俄巴底、撒迦利雅、拿坦业、米该亚，到犹大各城去教训人。'),
('CNV', '历代志下', 14, 17, 8, '和他们同去的，还有示玛雅、尼探雅、西巴第雅、亚撒黑、示米拉末、约拿单、亚多尼雅、多比雅和驼．巴多尼雅等几位利未人；又有以利沙玛和约兰两位祭司和他们同去。'),
('CNV', '历代志下', 14, 17, 9, '他们带着耶和华的律法书，在犹大教训人；他们走遍犹大各城，在民间教训人。'),
('CNV', '历代志下', 14, 17, 10, '犹大地周围的列国都惧怕耶和华，不敢和约沙法交战。'),
('CNV', '历代志下', 14, 17, 11, '有些非利士人送礼和纳贡银给约沙法；阿拉伯人也送给他公绵羊七千七百只，公山羊七千七百只。'),
('CNV', '历代志下', 14, 17, 12, '约沙法逐渐变得十分强大，在犹大建造了几座堡垒和贮藏货物的城市。'),
('CNV', '历代志下', 14, 17, 13, '他在犹大各城中储备了大批物资；在耶路撒冷也有不少战士，都是英勇的战士。'),
('CNV', '历代志下', 14, 17, 14, '他们的数目，按着他们的家族记在下面：犹大支派的千夫长中，有押拿军长，率领英勇的战士三十万；'),
('CNV', '历代志下', 14, 17, 15, '在押拿底下，是约哈难军长，率领二十八万人；'),
('CNV', '历代志下', 14, 17, 16, '在约哈难底下，是细基利的儿子亚玛斯雅，他是个甘愿献身给耶和华的人，率领英勇的战士二十万。'),
('CNV', '历代志下', 14, 17, 17, '便雅悯支派中有英勇的战士以利雅大，率领配备弓箭和盾牌的人二十万，'),
('CNV', '历代志下', 14, 17, 18, '在以利雅大底下是约萨拔，率领常备军十八万。'),
('CNV', '历代志下', 14, 17, 19, '这些人都是服事王的；还有王在犹大全地各设防城里安置的，没有计算在内。'),
('CNV', '历代志下', 14, 18, 1, '约沙法的财富很多，极有尊荣，他和亚哈也结了亲。'),
('CNV', '历代志下', 14, 18, 2, '过了几年，他下到撒玛利亚去见亚哈。亚哈为他和跟从他的人宰了很多牛羊，又怂恿他一同上去攻打基列的拉末。'),
('CNV', '历代志下', 14, 18, 3, '以色列王亚哈问犹大王约沙法：“你愿意和我一同到基列的拉末去吗？”他回答：“你我不分彼此；我的人民就是你的人民；我必和你一同作战。”'),
('CNV', '历代志下', 14, 18, 4, '约沙法对以色列王说：“请你先求问耶和华的话。”'),
('CNV', '历代志下', 14, 18, 5, '于是以色列王召集了四百位先知，问他们：“我们可以到基列的拉末去作战吗？还是不要去呢？”他们回答：“你可以上去，神必把那城交在王的手里。”'),
('CNV', '历代志下', 14, 18, 6, '约沙法问：“这里不是还有一位耶和华的先知吗？我们也可以向他求问。”'),
('CNV', '历代志下', 14, 18, 7, '以色列王回答约沙法说：“还有一个人，我们可以向他求问耶和华；只是我恨他，因为他对我说的预言，都是凶话，不是吉话。这人就是音拉的儿子米该雅。”约沙法说：“王不要这样说。”'),
('CNV', '历代志下', 14, 18, 8, '于是以色列王召了一个太监来，说：“快去把音拉的儿子米该雅召来。”'),
('CNV', '历代志下', 14, 18, 9, '那时，以色列王和犹大王约沙法各自坐在王位上，穿着朝服，坐在撒玛利亚城门口的广场上；所有的先知都在他们面前说预言。'),
('CNV', '历代志下', 14, 18, 10, '基拿拿的儿子西底家为自己做了些铁角，说：“耶和华这样说：‘你要用这些铁角抵触亚兰人，直到把他们完全消灭。’”'),
('CNV', '历代志下', 14, 18, 11, '所有的先知也都这样预言说：“你可以上基列的拉末去，必得胜利！因为耶和华必把那城交在王的手里。”'),
('CNV', '历代志下', 14, 18, 12, '那去召米该雅的使者对米该雅说：“看哪，这里的众先知都异口同声地对王说吉话，请你与他们一样说吉话。”'),
('CNV', '历代志下', 14, 18, 13, '米该雅说：“我指着永活的耶和华起誓，我的神说什么，我就说什么。”'),
('CNV', '历代志下', 14, 18, 14, '米该雅来到王那里，王问他：“米该雅啊，我们可以到基列的拉末作战吗？还是不要去呢？”他回答：“可以上去，一定得胜，他们必交在你们手里。”'),
('CNV', '历代志下', 14, 18, 15, '王对他说：“我要嘱咐你多少次，你才会奉耶和华的名对我只说真话呢？”'),
('CNV', '历代志下', 14, 18, 16, '米该雅说：“我看见以色列人四散在山上，好像没有牧人的羊群一样。耶和华说：‘这些人既然没有主人，使他们平平安安各自回家去吧！’”'),
('CNV', '历代志下', 14, 18, 17, '以色列王对约沙法说：“我不是早告诉你，他对我说的预言，总没有吉话，只说凶话吗？”'),
('CNV', '历代志下', 14, 18, 18, '米该雅说：“所以你们要听耶和华的话。我看见耶和华坐在宝座上，天上的万军侍立在他左右。'),
('CNV', '历代志下', 14, 18, 19, '耶和华说：‘谁去引诱以色列王亚哈上去，好使他倒毙在基列的拉末呢？’有人这样说，也有人那样说。'),
('CNV', '历代志下', 14, 18, 20, '后来有一个灵出来，站在耶和华面前，说：‘我去引诱他。’耶和华问他：‘你怎样引诱他呢？’'),
('CNV', '历代志下', 14, 18, 21, '他回答：‘我要出去，在他众先知的口里成为谎言的灵。’耶和华说：‘你必能引诱他，并且可以成功；你去这样行吧。’'),
('CNV', '历代志下', 14, 18, 22, '所以现在耶和华把谎言的灵放在你这些先知的口里，并且耶和华已宣告灾祸必临到你。”'),
('CNV', '历代志下', 14, 18, 23, '基拿拿的儿子西底家走前来，打米该雅的脸，说：“耶和华的灵是怎样离开了我，去与你说话呢？”'),
('CNV', '历代志下', 14, 18, 24, '米该雅说：“你进密室躲藏的那一天，就必看见了。”'),
('CNV', '历代志下', 14, 18, 25, '以色列王说：“把米该雅带回去，交给市长亚们和王的儿子约阿施，'),
('CNV', '历代志下', 14, 18, 26, '说：‘王这样吩咐：把这人囚在监里，少给他食物和水，直到我平平安安回来。’”'),
('CNV', '历代志下', 14, 18, 27, '米该雅说：“如果你真的可以平平安安回来，那么耶和华就没有藉着我说话了。”他又说：“众民啊，你们都要听！”'),
('CNV', '历代志下', 14, 18, 28, '于是，以色列王和犹大王约沙法上基列的拉末去了。'),
('CNV', '历代志下', 14, 18, 29, '以色列王对约沙法说：“我要改装上阵，你可以仍穿朝服。”于是以色列王改了装，他们就上阵去了。'),
('CNV', '历代志下', 14, 18, 30, '原来亚兰王曾经吩咐他的战车队长说：“无论是大小的将兵，你们都不要和他们交战，只管攻击以色列王。”'),
('CNV', '历代志下', 14, 18, 31, '众战车队长看见约沙法，就都心里说：“这必是以色列王。”于是都绕过去攻击他。约沙法呼救，耶和华就帮助他；神又使敌人离开他。'),
('CNV', '历代志下', 14, 18, 32, '众战车队长见他不是以色列王，就转回去，不再追击他了。'),
('CNV', '历代志下', 14, 18, 33, '有一人随意拉弓，竟射进了以色列王的铠甲中间的缝隙里。王对驾车的说：“你把车转过来，载我出阵吧，因为我受了重伤。”'),
('CNV', '历代志下', 14, 18, 34, '那天战事越来越激烈；以色列王勉强站在战车上，对抗亚兰人，直到黄昏。日落的时候，王就死了。'),
('CNV', '历代志下', 14, 19, 1, '犹大王约沙法平平安安回到耶路撒冷自己的王宫里去。'),
('CNV', '历代志下', 14, 19, 2, '先见哈拿尼的儿子耶户出来迎见约沙法王，对他说：“你怎能帮助恶人，喜爱那恨恶耶和华的人呢？因此耶和华的忿怒必临到你身上。'),
('CNV', '历代志下', 14, 19, 3, '可是你还有善行，因为你从国中除掉亚舍拉，并且决心寻求神。”'),
('CNV', '历代志下', 14, 19, 4, '约沙法住在耶路撒冷，后来又出巡民间，从别是巴到以法莲山地，领人民归向耶和华他们列祖的神。'),
('CNV', '历代志下', 14, 19, 5, '他又在犹大境内的一切设防城中，都设立审判官；'),
('CNV', '历代志下', 14, 19, 6, '他对他们说：“你们行事，必须谨慎；因为你们审判，不是为人，而是为耶和华；你们审判的时候，耶和华必和你们同在。'),
('CNV', '历代志下', 14, 19, 7, '现在你们要敬畏耶和华；你们要谨慎行事，因为耶和华我们的神没有不义，不偏待人，也不受贿赂。”'),
('CNV', '历代志下', 14, 19, 8, '约沙法又在耶路撒冷，从利未人、祭司和以色列各家族的首领中设立了一些人，替耶和华施行审判，为耶路撒冷的居民处理诉讼。'),
('CNV', '历代志下', 14, 19, 9, '约沙法吩咐他们说：“你们要以敬畏耶和华的心，忠心和尽心办事。'),
('CNV', '历代志下', 14, 19, 10, '你们住在各城里的同胞带到你们面前的一切诉讼，无论是流血的事件，或是有关律法、诫命、律例和典章的诉讼，你们总要警告他们，免得他们得罪耶和华，以致耶和华的烈怒临到你们和你们的同胞身上；你们必须这样行，就没有罪了。'),
('CNV', '历代志下', 14, 19, 11, '所有属于耶和华的事，有大祭司亚玛利雅管理你们；所有属于王的事，有犹大家的领袖以实玛利的儿子西巴第雅管理你们；在你们面前也有利未人作官长。你们要勇敢行事；愿耶和华和良善的人同在。”'),
('CNV', '历代志下', 14, 20, 1, '后来，摩押人、亚扪人和一些米乌尼人（按照《马索拉文本》，“米乌尼人”作“亚扪人”；现参照《七十士译本》的一些文本翻译；参代下26:7），一同来攻击约沙法。'),
('CNV', '历代志下', 14, 20, 2, '有人来向约沙法报告说：“从海的对岸，就是从以东（按照《马索拉文本》的绝大部分文本，“以东”作“亚兰”，大概是手民之误﹔两者在原文非常相似﹐但按地理应作“以东”），有大军前来攻击你；现在他们在哈洗逊．他玛。”哈洗逊．他玛就是隐．基底。'),
('CNV', '历代志下', 14, 20, 3, '于是约沙法害怕起来，定意要寻求耶和华，就在犹大全地宣告禁食。'),
('CNV', '历代志下', 14, 20, 4, '于是犹大人集合起来，寻求耶和华的帮助；犹大各城中都有人出来寻求耶和华。'),
('CNV', '历代志下', 14, 20, 5, '约沙法就在犹大和耶路撒冷的会众中，站在耶和华殿的新院子前面，'),
('CNV', '历代志下', 14, 20, 6, '说：“耶和华我们列祖的神啊，你不是天上的神吗？你不是统治列邦万国的吗？你手中有大能大力，没有人能抵挡你。'),
('CNV', '历代志下', 14, 20, 7, '我们的神啊，你不是曾经把这地的居民从你的子民以色列人面前赶走，把这地赐给你的朋友亚伯拉罕的后裔永远作产业吗？'),
('CNV', '历代志下', 14, 20, 8, '他们住在这地，又在这里为你的名建造了一座圣所，说：'),
('CNV', '历代志下', 14, 20, 9, '‘如果有灾祸临到我们，无论是刀剑、刑罚、瘟疫、饥荒，我们在急难的时候，站在这殿和你的面前，向你呼求，你必垂听和施行拯救，因为你的名是在这殿内。’'),
('CNV', '历代志下', 14, 20, 10, '现在这里有亚扪人、摩押人和西珥山的人，从前以色列人从埃及地出来的时候，你不许以色列人侵犯他们。那时，以色列人就离开了他们，不除灭他们。'),
('CNV', '历代志下', 14, 20, 11, '现在你看，他们怎样报复我们；他们要来把我们从你赐给我们承受作产业的地赶出去。'),
('CNV', '历代志下', 14, 20, 12, '我们的神啊，你不惩罚他们吗？因为我们没有力量抵挡这来攻打我们的大军；我们也不知道该作什么；我们的眼睛只有仰望你。”'),
('CNV', '历代志下', 14, 20, 13, '那时全犹大的人，连他们的婴孩、妻子和儿女，都站在耶和华面前。'),
('CNV', '历代志下', 14, 20, 14, '当时，耶和华的灵在会众中临到利未人亚萨的后裔，玛探雅的玄孙、耶利的曾孙、比拿雅的孙子、撒迦利亚的儿子雅哈悉；'),
('CNV', '历代志下', 14, 20, 15, '他就说：“全犹大的人、耶路撒冷的居民和约沙法王啊，你们要留意！耶和华这样对你们说：‘你们不要因这大军惧怕和惊慌，因为战争的胜负不是在于你们，而是在于神。'),
('CNV', '历代志下', 14, 20, 16, '明天你们要下去攻击他们，他们会从洗斯的斜坡上来，你们必在耶鲁伊勒旷野东面的谷口遇见他们。'),
('CNV', '历代志下', 14, 20, 17, '犹大人和耶路撒冷人哪，这次你们不必出战，只要稳守阵地，站立不动，看耶和华为你们施行的拯救。’你们不要惧怕，也不要惊慌；明天要出去攻击他们，耶和华必和你们同在。”'),
('CNV', '历代志下', 14, 20, 18, '于是约沙法面伏于地，全犹大的人和耶路撒冷的居民都俯伏在耶和华面前，敬拜耶和华。'),
('CNV', '历代志下', 14, 20, 19, '哥辖子孙中和可拉子孙中的利未人，都站起来高声赞美耶和华以色列的神。'),
('CNV', '历代志下', 14, 20, 20, '第二天早晨，众人清早起来，出发到提哥亚的旷野去；他们正出去的时候，约沙法站起来，说：“犹大人和耶路撒冷的居民哪，你们要听我的话；信靠耶和华你们的神，你们就必坚立；信靠他的先知，你们就必亨通。”'),
('CNV', '历代志下', 14, 20, 21, '约沙法和人民商议好了，就指派向耶和华歌唱的人，使他们身穿圣洁的服饰，走在军队的前面，赞美耶和华，说：“你们要称颂耶和华，因他的慈爱永远长存。”'),
('CNV', '历代志下', 14, 20, 22, '当他们开始欢呼赞美的时候，耶和华就派出伏兵，击杀那前来攻打犹大人的亚扪人、摩押人和西珥山的人，他们就被击溃了。'),
('CNV', '历代志下', 14, 20, 23, '原来亚扪人和摩押人起来攻击住西珥山的人，把他们杀尽灭绝；他们灭尽了住西珥山的人以后，竟又自相残杀。'),
('CNV', '历代志下', 14, 20, 24, '犹大人来到旷野的瞭望楼，向那大军观望，只见伏尸遍地，没有一个逃脱的。'),
('CNV', '历代志下', 14, 20, 25, '约沙法和他的人民就来掠夺敌人的财物，在尸首中见许多财物、衣服和珍宝。他们剥脱下来据为己有的，多得不能携带；因为掠物甚多，所以掠夺了三天。'),
('CNV', '历代志下', 14, 20, 26, '第四日，他们聚集在比拉迦谷，在那里称颂耶和华，因此那地方名叫比拉迦谷，直到今日。'),
('CNV', '历代志下', 14, 20, 27, '事后，犹大和耶路撒冷所有的人，在约沙法率领下，都欢欢喜喜回耶路撒冷去了，耶和华使他们因胜过仇敌欢喜快乐。'),
('CNV', '历代志下', 14, 20, 28, '他们拿着琴瑟和号筒来到耶路撒冷，进了耶和华的殿。'),
('CNV', '历代志下', 14, 20, 29, '世上列国一听见耶和华战败了以色列的仇敌，就都惧怕神。'),
('CNV', '历代志下', 14, 20, 30, '这样，约沙法的国得享太平，因为他的神使他四境安宁。'),
('CNV', '历代志下', 14, 20, 31, '约沙法登基统治犹大的时候，是三十五岁；他在耶路撒冷作王共二十五年。他的母亲名叫阿苏巴，是示利希的女儿。'),
('CNV', '历代志下', 14, 20, 32, '约沙法遵行他父亲亚撒的道路，总不偏离，行耶和华看为正的事。'),
('CNV', '历代志下', 14, 20, 33, '只是邱坛还没有除掉，人民仍然没有定意归向他们列祖的神。'),
('CNV', '历代志下', 14, 20, 34, '约沙法其余的事迹，一生的始末，都记在哈拿尼的儿子耶户的言行录上；这言行录又收录在以色列诸王记上。'),
('CNV', '历代志下', 14, 20, 35, '后来，犹大王约沙法和作恶多端的以色列王亚哈谢结盟。'),
('CNV', '历代志下', 14, 20, 36, '约沙法和他合伙建造船只，开往他施去；他们是在以旬．迦别建造船只。'),
('CNV', '历代志下', 14, 20, 37, '那时，玛利沙人多大瓦的儿子以利以谢说预言攻击约沙法，说：“因为你和亚哈谢结盟，耶和华必破坏你建造的船只。”后来那些船只果然受到破坏，不能开往他施去。'),
('CNV', '历代志下', 14, 21, 1, '约沙法和他的列祖同睡，和他的列祖一起葬在大卫城里；他的儿子约兰接续他作王。'),
('CNV', '历代志下', 14, 21, 2, '约兰有几个兄弟，就是约沙法的儿子亚撒利雅、耶歇、撒迦利雅、亚撒利雅、米迦勒和示法提雅；这些人都是犹大王约沙法的儿子。'),
('CNV', '历代志下', 14, 21, 3, '他们的父亲把许多礼物，就是金、银、财宝，以及犹大地的几座设防城都赐给了他们，却把王位赐给了约兰，因为他是长子。'),
('CNV', '历代志下', 14, 21, 4, '约兰一登上了他父亲的王位，巩固了自己的权势以后，就用刀杀了他所有的兄弟和犹大的一些领袖。'),
('CNV', '历代志下', 14, 21, 5, '约兰登基的时候是三十二岁，他在耶路撒冷作王共八年。'),
('CNV', '历代志下', 14, 21, 6, '他随从众以色列王的道路，好像亚哈家所行的一样，因为他娶了亚哈的女儿作妻子，行耶和华看为恶的事。'),
('CNV', '历代志下', 14, 21, 7, '耶和华因为自己和大卫所立的约，不愿消灭大卫家；却照着他应许的，永远赐灯光给大卫和他的子孙。'),
('CNV', '历代志下', 14, 21, 8, '约兰在位的日子，以东人反叛，脱离了犹大的统治，自立一王统治他们。'),
('CNV', '历代志下', 14, 21, 9, '约兰率领他的众军长和所有的战车一同前去；他夜间起来，攻击那些包围他的以东人和战车队长。'),
('CNV', '历代志下', 14, 21, 10, '从此，以东人反叛，脱离了犹大的统治，直到今日。那时，立拿人也反叛了，因为约兰离弃了耶和华他列祖的神。'),
('CNV', '历代志下', 14, 21, 11, '他又在犹大众山上建筑邱坛，使耶路撒冷的居民行邪淫，引诱犹大人。'),
('CNV', '历代志下', 14, 21, 12, '以利亚先知有信送给约兰，说：“耶和华你的先祖大卫的神这样说：‘因为你没有遵行你父亲约沙法的道路，也没有遵行犹大王亚撒的道路，'),
('CNV', '历代志下', 14, 21, 13, '却随从了以色列诸王的道路，使犹大人和耶路撒冷的居民行邪淫，好像亚哈家行邪淫一样；又杀了你父家比你良善的众兄弟；'),
('CNV', '历代志下', 14, 21, 14, '所以耶和华要用极大的灾祸击打你的人民、妻子和儿女，以及你的一切财产。'),
('CNV', '历代志下', 14, 21, 15, '至于你，你的肠脏必患严重的病，直到因病情日益严重，你的肠子都流出来了。’”'),
('CNV', '历代志下', 14, 21, 16, '后来，耶和华激动了非利士人和靠近古实的阿拉伯人的心，和约兰作对。'),
('CNV', '历代志下', 14, 21, 17, '他们上来攻打犹大，侵入境内，掠去了王宫的一切财物，又掳去了他的众子和妻妾；除了他最小的儿子约哈斯以外，没有给他留下一个儿子。'),
('CNV', '历代志下', 14, 21, 18, '这些事以后，耶和华击打约兰，使他的肠脏患了不治之症。'),
('CNV', '历代志下', 14, 21, 19, '他病了很久。过了二年，他的肠子因病重流了出来，他就病死了；他的人民没有为他烧火，好像从前为他的列祖烧火一样。'),
('CNV', '历代志下', 14, 21, 20, '约兰登基的时候是三十二岁；他在耶路撒冷作王共八年；他离世的时候，没有人哀悼他。人把他埋葬在大卫城里，可是没有葬在众王的陵墓里。'),
('CNV', '历代志下', 14, 22, 1, '耶路撒冷的居民立了约兰的小儿子亚哈谢接续他作王；因为那些和阿拉伯人同来攻营的匪徒，把亚哈谢的哥哥全都杀了。这样，犹大王约兰的儿子亚哈谢就作了王。'),
('CNV', '历代志下', 14, 22, 2, '亚哈谢登基的时候是二十二岁（“二十二岁”原文作“四十二岁”；现参照古译本和王下8:26修译）；他在耶路撒冷作王一年。他的母亲名叫亚他利雅，是暗利的孙女。'),
('CNV', '历代志下', 14, 22, 3, '亚哈谢也随从亚哈家的道路，因为他母亲教唆他行恶。'),
('CNV', '历代志下', 14, 22, 4, '他行耶和华看为恶的事，好像亚哈家一样，因为他的父亲死了以后，亚哈家的人就教唆他，好使他灭亡。'),
('CNV', '历代志下', 14, 22, 5, '他随从了他们的计谋，和以色列王亚哈的儿子约兰一同到基列的拉末去，和亚兰王哈薛交战；亚兰人击伤了约兰。'),
('CNV', '历代志下', 14, 22, 6, '于是约兰回到耶斯列去，医治他在拉末和亚兰王交战的时候所受的伤。犹大王约兰的儿子亚哈谢，因亚哈的儿子约兰病了，就下到耶斯列去看他。'),
('CNV', '历代志下', 14, 22, 7, '亚哈谢去见约兰，就遇了害，这原是出于神；因为他去到以后，就和约兰一同出去攻击宁示的孙子耶户。这耶户就是耶和华所膏的，为要除灭亚哈家。'),
('CNV', '历代志下', 14, 22, 8, '耶户讨伐亚哈家的罪的时候，遇见了犹大的众领袖和亚哈谢的兄弟的儿子，他们都是侍候亚哈谢的，耶户把他们都杀了。'),
('CNV', '历代志下', 14, 22, 9, '耶户追寻亚哈谢。那时，亚哈谢躲藏在撒玛利亚，有人捉住他，把他带到耶户那里，耶户就杀了他，却把他埋葬了，因为他们说：“他是约沙法的孙子；这约沙法是一心寻求耶和华的。”这样，亚哈谢的家没有一人有能力可以保持王权的。'),
('CNV', '历代志下', 14, 22, 10, '亚哈谢的母亲亚他利雅见自己的儿子死了，就起来杀尽犹大家中所有王族的后裔。'),
('CNV', '历代志下', 14, 22, 11, '但是王的女儿约示巴，把亚哈谢的儿子约阿施从那些将要被杀的王子中偷出来，把他和他的乳母都藏在卧房里。约兰王的女儿约示巴是大祭司耶何耶大的妻子，把约阿施收藏起来，躲避亚他利雅，免得被亚他利雅杀死，因为约示巴是亚哈谢的妹妹。'),
('CNV', '历代志下', 14, 22, 12, '约阿施和他们在神的殿里一同躲藏了六年；那时亚他利雅统治犹大地。'),
('CNV', '历代志下', 14, 23, 1, '到了第七年，耶何耶大奋勇图强，召来耶罗罕的儿子亚撒利雅、约哈难的儿子以实玛利、俄备得的儿子亚撒利雅、亚大雅的儿子玛西雅和细基利的儿子以利沙法等几位百夫长，和他们立约。'),
('CNV', '历代志下', 14, 23, 2, '他们就走遍犹大，从犹大各城召集利未人和以色列各家族的首领；他们就来到耶路撒冷。'),
('CNV', '历代志下', 14, 23, 3, '全体会众在神的殿里与王立约。耶何耶大对他们说：“王的儿子应当按照耶和华应许大卫的子孙的话作王。'),
('CNV', '历代志下', 14, 23, 4, '你们要这样行：你们中间每逢安息日来值班的祭司和利未人，三分之一要把守各门；'),
('CNV', '历代志下', 14, 23, 5, '三分之一要在王宫，三分之一要在基址门；全体人民都要在耶和华殿的院子里。'),
('CNV', '历代志下', 14, 23, 6, '除了祭司和供职的利未人以外，任何人不得进入耶和华的殿，只有他们可以进去，因为他们是分别为圣的；全体人民都要遵守耶和华的吩咐。'),
('CNV', '历代志下', 14, 23, 7, '利未人要在周围环绕君王，各人手里拿着武器；擅自进殿的，都必被处死；王出入的时候，你们都要随着他。”'),
('CNV', '历代志下', 14, 23, 8, '利未人和犹大众人都照着耶何耶大祭司吩咐的一切去行；他们各人带着在安息日值班或在安息日下班的人来，因为耶何耶大祭司不准他们下班。'),
('CNV', '历代志下', 14, 23, 9, '于是耶何耶大祭司把神的殿里，原本属于大卫王的矛枪、大盾和小盾，交给了众百夫长；'),
('CNV', '历代志下', 14, 23, 10, '他又分派众民，手中各拿兵器，守在祭坛和殿的四周，从殿的右面到殿的左面，环绕着王。'),
('CNV', '历代志下', 14, 23, 11, '于是他们把王子领出来，给他戴上王冠，又把约书交给他，立他为王；耶何耶大和他的众子用膏膏他，并且说：“愿王万岁！”'),
('CNV', '历代志下', 14, 23, 12, '亚他利雅听见人民奔跑和赞美王的声音，就进了耶和华的殿，到众民那里去。'),
('CNV', '历代志下', 14, 23, 13, '她一观看，见王站在殿门口的柱旁，众官长和吹号的人在王的周围；国民都欢乐吹号，又有歌唱的人用各种乐器领导众人歌颂。于是亚他利雅撕裂衣服，说：“反了！反了！”'),
('CNV', '历代志下', 14, 23, 14, '耶何耶大祭司把管辖军队的众百夫长叫出来，对他们说：“把她从各班次中间赶出去；跟随她的人，都要用刀杀死。”因为祭司说：“不可在耶和华的殿内杀死她。”'),
('CNV', '历代志下', 14, 23, 15, '她走到王宫的马门入口的时候，众兵就把她拿住，在那里把她杀死了。'),
('CNV', '历代志下', 14, 23, 16, '耶何耶大与众民和王立约，要他们作耶和华的子民。'),
('CNV', '历代志下', 14, 23, 17, '于是众民都去到巴力庙，把庙拆毁，打碎祭坛和偶像，又在祭坛前杀了巴力的祭司玛坦。'),
('CNV', '历代志下', 14, 23, 18, '耶何耶大把看守耶和华殿的责任，交在利未支派的祭司手里；这些利未支派的祭司是大卫分派在耶和华的殿中，照着摩西的律法所记的，给耶和华献燔祭，又照着大卫所定的，欢乐歌唱。'),
('CNV', '历代志下', 14, 23, 19, '他又设立守门的看守耶和华殿的各门，无论为了什么事，不洁净的人，都不能进去。'),
('CNV', '历代志下', 14, 23, 20, '他率领百夫长、贵族、民间的官长和国民，又把王从耶和华的殿领下来，从“上门”进入王宫，拥立王坐在王位上。'),
('CNV', '历代志下', 14, 23, 21, '于是全国的人民都欢乐，全城也都宁静；因为他们把亚他利雅用刀杀了。'),
('CNV', '历代志下', 14, 24, 1, '约阿施登基的时候是七岁，在耶路撒冷作王共四十年。他的母亲名叫西比亚，是别是巴人。'),
('CNV', '历代志下', 14, 24, 2, '耶何耶大祭司在世的日子，约阿施行耶和华看为正的事。'),
('CNV', '历代志下', 14, 24, 3, '耶何耶大为他娶了两个妻子，他就生了一些儿女。'),
('CNV', '历代志下', 14, 24, 4, '此后，约阿施有意重修耶和华的殿，'),
('CNV', '历代志下', 14, 24, 5, '就召集了众祭司和利未人，对他们说：“你们要去到犹大各城，向所有以色列人募捐金钱，可以年年修建你们神的殿；你们应急速办理这事。”可是利未人却不急速办理。'),
('CNV', '历代志下', 14, 24, 6, '于是王把大祭司耶何耶大召来，对他说：“你为什么不命令利未人把耶和华的仆人摩西和以色列的会众，为法柜的会幕规定的税款，从犹大和耶路撒冷征收回来，作修殿的费用呢？”'),
('CNV', '历代志下', 14, 24, 7, '原来那恶妇亚他利雅的众子曾经拆毁神的殿，又把耶和华殿中一切分别为圣的物品用来供奉巴力。'),
('CNV', '历代志下', 14, 24, 8, '于是王下令，他们就造了一个柜，放在耶和华殿的门外；'),
('CNV', '历代志下', 14, 24, 9, '又在犹大和耶路撒冷发出通告，叫人把神的仆人摩西，在旷野规定以色列人缴交的税款带来，献给耶和华。'),
('CNV', '历代志下', 14, 24, 10, '众领袖和人民都欢欢喜喜把税款带来，投进柜中，直到他们都投完了。'),
('CNV', '历代志下', 14, 24, 11, '利未人把银柜抬到王指定负责这事的人那里的时候，他们看见税银很多，王的书记和大祭司的属员就来把银柜倒空，然后抬回原处。天天都是这样，所以收集了很多银子。'),
('CNV', '历代志下', 14, 24, 12, '王和耶何耶大把银子交给耶和华殿的办事人员，他们就雇了石匠和木匠，重建耶和华的殿，又雇了铁匠和铜匠，重建耶和华的殿。'),
('CNV', '历代志下', 14, 24, 13, '作工的人不住工作，重修的工程在他们手下顺利进行；他们把神的殿重建得和先前一样，并且非常坚固。'),
('CNV', '历代志下', 14, 24, 14, '他们完工以后，就把剩下的银子送到王和耶何耶大面前，用来制造耶和华殿里的器皿、供奉和献祭所用的器皿、盘子，以及各种金银器皿。耶何耶大在世的日子，众人都常在耶和华的殿里献燔祭。'),
('CNV', '历代志下', 14, 24, 15, '耶何耶大年纪老了，寿数满足就死了；他死的时候，是一百三十岁。'),
('CNV', '历代志下', 14, 24, 16, '他和列王一同埋葬在大卫城里，因为他在以色列为神和神的殿作了美善的事。'),
('CNV', '历代志下', 14, 24, 17, '耶何耶大死后，犹大的领袖们来朝拜王；王听从了他们的主意。'),
('CNV', '历代志下', 14, 24, 18, '他们离弃了耶和华他们列祖的神的殿，去事奉亚舍拉和偶像。因为他们的罪，神的忿怒临到犹大和耶路撒冷。'),
('CNV', '历代志下', 14, 24, 19, '但耶和华仍然差派先知到他们中间，引导他们归向耶和华；这些先知虽然警告他们，他们却不肯听从。'),
('CNV', '历代志下', 14, 24, 20, '那时，神的灵临到耶何耶大祭司的儿子撒迦利亚身上，他就站在比众民高的地方，对他们说：“神这样说：‘你们为什么违背耶和华的诫命，使你们不得亨通呢？因为你们离弃了耶和华，所以耶和华也离弃你们。’”'),
('CNV', '历代志下', 14, 24, 21, '众人要杀害撒迦利亚，于是照着王的命令，在耶和华殿的院子里用石头把他打死。'),
('CNV', '历代志下', 14, 24, 22, '约阿施王没有记念撒迦利亚的父亲耶何耶大对他所施的恩，反而杀了他的儿子。撒迦利亚临死的时候，说：“愿耶和华鉴察，并且责问你！”'),
('CNV', '历代志下', 14, 24, 23, '过了年，亚兰的军队上来攻打约阿施；他们侵入犹大和耶路撒冷，杀了民间的领袖，又把他们的一切战利品都送到大马士革王那里去。'),
('CNV', '历代志下', 14, 24, 24, '亚兰的军队虽然只来了一小队人，耶和华却把一支庞大的军队交在他们手里；因为犹大人离弃了耶和华他们列祖的神，亚兰人向约阿施执行了惩罚。'),
('CNV', '历代志下', 14, 24, 25, '亚兰人离开约阿施的时候，他们丢下约阿施，因为他受了重伤，他的臣仆要杀害他，为了报复耶何耶大祭司的儿子流血的仇；他们在床上杀死他，他就死了；有人把他埋葬在大卫城里，只是没有埋葬在列王的陵墓里。'),
('CNV', '历代志下', 14, 24, 26, '谋害他的是亚扪妇人示米押的儿子撒拔和摩押妇人示米利的儿子约萨拔。'),
('CNV', '历代志下', 14, 24, 27, '至于约阿施的众子，以及许多警戒他的话，还有他重建神的殿的事，都记在列王记的注释上。约阿施的儿子亚玛谢接续他作王。'),
('CNV', '历代志下', 14, 25, 1, '亚玛谢登基的时候是二十五岁，他在耶路撒冷作王二十九年。他的母亲名叫约耶但，是耶路撒冷人。'),
('CNV', '历代志下', 14, 25, 2, '亚玛谢行耶和华看为正的事，只是心不专一。'),
('CNV', '历代志下', 14, 25, 3, '他巩固了王位以后，就把击杀他父王的臣仆杀了。'),
('CNV', '历代志下', 14, 25, 4, '他却没有处死他们的儿子，因为照着摩西律法书上所记，耶和华曾吩咐：“不可因儿子的罪处死父亲，也不可因父亲的罪处死儿子；各人要因自己的罪被处死。”'),
('CNV', '历代志下', 14, 25, 5, '亚玛谢召集了犹大人，按着他们的家族为全犹大和便雅悯人，设立千夫长和百夫长，又数点他们的数目，从二十岁起，能出去打仗，能拿枪持盾的精兵，共有三十万。'),
('CNV', '历代志下', 14, 25, 6, '又用了三千四百公斤银子，从以色列中雇了十万英勇的战士。'),
('CNV', '历代志下', 14, 25, 7, '有一位神人来见亚玛谢，说：“王啊，请不要领以色列的军队和你同去，因为耶和华不和以色列人，不和任何以法莲的子孙同在。'),
('CNV', '历代志下', 14, 25, 8, '即使你一定要去，奋勇争战，神也会使你在敌人面前覆灭，因为神有能力帮助人，也有能力使人覆灭。”'),
('CNV', '历代志下', 14, 25, 9, '亚玛谢问神人：“我给以色列雇佣兵的那三千四百公斤银子怎么办呢？”神人回答：“耶和华能把比这更多赐给你。”'),
('CNV', '历代志下', 14, 25, 10, '于是亚玛谢把那从以法莲来的雇佣兵解散了，遣送他们回家；因此他们非常恼怒犹大人，就气冲冲地回家去了。'),
('CNV', '历代志下', 14, 25, 11, '亚玛谢鼓起勇气，率领他的人民到盐谷去，击杀了一万西珥人。'),
('CNV', '历代志下', 14, 25, 12, '犹大人又生擒了一万人，带到一处崖顶，从崖顶把他们抛下去，使他们都摔得肢离破碎。'),
('CNV', '历代志下', 14, 25, 13, '但亚玛谢打发回去、不许和他一同作战的雇佣兵，竟侵入犹大各城，从撒玛利亚直到伯．和仑，击杀了三千人，又掠去了很多财物。'),
('CNV', '历代志下', 14, 25, 14, '亚玛谢击败了以东人回来的时候，把西珥人的神像也带回来，立为自己的神，在它们面前叩拜，又向它们烧香。'),
('CNV', '历代志下', 14, 25, 15, '因此，耶和华向亚玛谢发怒，于是差派一位先知去见他，对他说：“这民族的神不能拯救自己的人民脱离你的手，你为什么还寻求它们呢？”'),
('CNV', '历代志下', 14, 25, 16, '先知向王讲话的时候，王对他说：“我们立了你作王的谋士吗？住口吧！你要挨打吗？”先知就住口，可是又说：“我知道神已定意消灭你，因为你作了这事，又不听从我的劝戒。”'),
('CNV', '历代志下', 14, 25, 17, '犹大王亚玛谢和群臣商议以后，就派人去见耶户的孙子、约哈斯的儿子、以色列王约阿施，说：“来吧，我们在战场上相见吧！”'),
('CNV', '历代志下', 14, 25, 18, '以色列王约阿施派人去见犹大王亚玛谢，说：“黎巴嫩的蒺藜派人去见黎巴嫩的香柏树，说：‘把你的女儿给我的儿子作妻子吧！’后来有一只黎巴嫩的野兽从那里经过，把蒺藜践踏了。'),
('CNV', '历代志下', 14, 25, 19, '你心里说你击败了以东人，你就心里骄傲，以这事夸口。现在你留在家里吧，为什么要惹祸，使犹大和你一同覆亡呢？”'),
('CNV', '历代志下', 14, 25, 20, '亚玛谢却不听从；这原是出于神，好把他们交在约阿施手里，因为他们寻求以东的神。'),
('CNV', '历代志下', 14, 25, 21, '于是以色列王约阿施上来，在犹大的伯．示麦，和犹大王亚玛谢相会于战场上。'),
('CNV', '历代志下', 14, 25, 22, '犹大人在以色列人面前被击败，各自逃回家去了。'),
('CNV', '历代志下', 14, 25, 23, '以色列王约阿施在伯．示麦捉住了约哈斯的孙子、约阿施的儿子、犹大王亚玛谢，把他带到耶路撒冷，又拆毁耶路撒冷的城墙，从以法莲门直到角门，共两百公尺。'),
('CNV', '历代志下', 14, 25, 24, '又把俄别．以东负责看守神殿里的一切金银和一切器皿，以及王宫里的宝物都掠去，又掳走人质，然后回撒玛利亚去了。'),
('CNV', '历代志下', 14, 25, 25, '以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢还活了十五年。'),
('CNV', '历代志下', 14, 25, 26, '亚玛谢其余的事迹，一生的始末，不是都记在犹大和以色列诸王记上吗？'),
('CNV', '历代志下', 14, 25, 27, '自从亚玛谢离弃耶和华以后，在耶路撒冷有人要谋害他；他就逃到拉吉去。谋害他的人派人追到拉吉，在那里把他杀死。'),
('CNV', '历代志下', 14, 25, 28, '然后用马把他的尸体运回来，埋葬在大卫城（按照《马索拉文本》的大部份文本，“大卫”作“犹大”；现参照其他文本和各古译本翻译；参王下14:20）里，和他的列祖一起。'),
('CNV', '历代志下', 14, 26, 1, '全犹大的人民立乌西雅（“乌西雅”又名“亚撒利雅”；参王下14:21）接续他的父亲亚玛谢作王，那时他才十六岁。'),
('CNV', '历代志下', 14, 26, 2, '亚玛谢王和列祖同睡以后，乌西雅重建以禄，并且收归犹大所有。'),
('CNV', '历代志下', 14, 26, 3, '乌西雅登基的时候，是十六岁；他在耶路撒冷作王共五十二年。他的母亲名叫耶可利雅，是耶路撒冷人。'),
('CNV', '历代志下', 14, 26, 4, '乌西雅行耶和华看为正的事，像他的父亲亚玛谢一切所行的。'),
('CNV', '历代志下', 14, 26, 5, '撒迦利亚在世的日子，教导乌西雅敬畏神，所以乌西雅常常寻求神；乌西雅寻求神的时候，神就使他亨通。'),
('CNV', '历代志下', 14, 26, 6, '他出去攻打非利士人，拆毁了迦特的城墙、雅比尼的城墙和亚实突的城墙；又在亚实突境内非利士人中，建造了几座城。'),
('CNV', '历代志下', 14, 26, 7, '神帮助他攻打非利士人和住在姑珥．巴力的阿拉伯人，以及米乌尼人。'),
('CNV', '历代志下', 14, 26, 8, '亚扪人给乌西雅进贡，他的名声传到埃及的边境，因为他极其强盛。'),
('CNV', '历代志下', 14, 26, 9, '乌西雅在耶路撒冷的角门、谷门和城墙转角的地方，建筑了城楼，这些城楼非常坚固。'),
('CNV', '历代志下', 14, 26, 10, '他又在旷野建造了一些瞭望楼，挖了许多贮水池，因为他在高原和平原上有很多牲畜；又因为他喜爱种植，所以在山地上和果园里，雇有农夫和修剪葡萄树的工人。'),
('CNV', '历代志下', 14, 26, 11, '乌西雅又有善于作战的军队，照着书记耶利和官长玛西雅数点的数目，由王的一个将军哈拿尼雅指挥，编队上阵。'),
('CNV', '历代志下', 14, 26, 12, '这些英勇战士中的各家族首领，总数共二千六百人。'),
('CNV', '历代志下', 14, 26, 13, '在他们指挥下的军队，共有三十万七千五百人，都是大有能力，善于作战的，能帮助王攻打仇敌。'),
('CNV', '历代志下', 14, 26, 14, '乌西雅给全队军兵配备了盾牌、矛枪、头盔、铠甲、弓箭和用机弦甩的石头。'),
('CNV', '历代志下', 14, 26, 15, '他又在耶路撒冷制造巧匠发明的器械，安放在城楼和城角上，用来发射利箭和大石。乌西雅的名声传到远方，因为他得了非常的帮助，使他十分强盛。'),
('CNV', '历代志下', 14, 26, 16, '乌西雅强盛起来，就心高气傲，以致自寻毁灭，竟冒犯耶和华他的神；他进了耶和华的殿，要在香坛上烧香。'),
('CNV', '历代志下', 14, 26, 17, '跟随乌西雅进去的，有亚撒利雅祭司，还有耶和华的祭司八十个，都是英勇的人。'),
('CNV', '历代志下', 14, 26, 18, '他们阻止乌西雅王，对他说：“乌西雅啊，给耶和华烧香不是你应作的事，而是亚伦的子孙作祭司的事，他们是分别为圣作烧香的事；请离开圣所吧，因为你作了不应该作的事了，你必不能从耶和华神那里得着尊荣。”'),
('CNV', '历代志下', 14, 26, 19, '于是乌西雅十分忿怒，手里拿着香炉正要烧香，他向众祭司发怒的时候，就在耶和华的殿里香坛旁边众祭司的面前，他的额上忽然长出了大痲风。'),
('CNV', '历代志下', 14, 26, 20, '大祭司亚撒利雅和众祭司看着他，忽然见他的额上长了大痲风，就急忙催他出殿；他自己也急忙出去，因为耶和华击打了他。'),
('CNV', '历代志下', 14, 26, 21, '乌西雅王长大痲风直到死的时候；他既然长了大痲风，就住在一间隔离的房子里，不能进耶和华的殿。他的儿子约坦执掌朝政，治理国民。'),
('CNV', '历代志下', 14, 26, 22, '乌西雅其余的事迹，一生的始末，亚摩斯的儿子以赛亚先知都记下来了。'),
('CNV', '历代志下', 14, 26, 23, '乌西雅和他的列祖同睡；由于有人说：“他是个长大痲风的人”，所以把他埋葬在王陵的田间，和他的列祖一起。他的儿子约坦接续他作王。'),
('CNV', '历代志下', 14, 27, 1, '约坦登基的时候，是二十五岁；他在耶路撒冷作王共十六年；他的母亲名叫耶路沙，是撒督的女儿。'),
('CNV', '历代志下', 14, 27, 2, '约坦行耶和华看为正的事，像他父亲乌西雅一切所行的，只是没有进入耶和华的殿；但人民还是行败坏的事。'),
('CNV', '历代志下', 14, 27, 3, '约坦建造了耶和华殿的上门；在俄斐勒的城墙上，他也有很多建设。'),
('CNV', '历代志下', 14, 27, 4, '他在犹大山地建造城市，又在树林中建造一些营寨和瞭望楼。'),
('CNV', '历代志下', 14, 27, 5, '约坦和亚扪人的王交战，战胜了他们；那一年，亚扪人就献给他三千四百公斤银子，一千公吨小麦，一千公吨大麦；第二年和第三年，亚扪人也献给他这个数目。'),
('CNV', '历代志下', 14, 27, 6, '约坦在耶和华他的神面前坚守正道，所以日渐强盛。'),
('CNV', '历代志下', 14, 27, 7, '约坦其余的事迹，他的一切战争和作为，都记在以色列和犹大列王记上。'),
('CNV', '历代志下', 14, 27, 8, '他登基的时候是二十五岁；他在耶路撒冷作王共十六年。'),
('CNV', '历代志下', 14, 27, 9, '约坦和他的列祖同睡，埋葬在大卫城里；他的儿子亚哈斯接续他作王。'),
('CNV', '历代志下', 14, 28, 1, '亚哈斯登基的时候，是二十岁；他在耶路撒冷作王十六年。他不像他的祖先大卫一样，行耶和华看为正的事，'),
('CNV', '历代志下', 14, 28, 2, '他却随从以色列诸王的道路，又为巴力铸造偶像；'),
('CNV', '历代志下', 14, 28, 3, '并且在欣嫩子谷烧香，用火焚烧自己的儿女，像耶和华在以色列人面前驱走的外族人所行可厌恶的事一样；'),
('CNV', '历代志下', 14, 28, 4, '又在邱坛上、山冈上和各青翠树下，献祭烧香。'),
('CNV', '历代志下', 14, 28, 5, '因此，耶和华他的神把他交在亚兰王手里；亚兰王击败了他，掳走了他很多人民，带到大马士革去。神又把他交在以色列王手里，以色列王就在犹大进行大屠杀。'),
('CNV', '历代志下', 14, 28, 6, '利玛利的儿子比加在犹大一天之内杀了十二万人，全是勇士，因为他们离弃了耶和华他们列祖的神。'),
('CNV', '历代志下', 14, 28, 7, '有一个以法莲的勇士，名叫细基利，杀了王的儿子玛西雅、王宫的总管押斯利甘和王的宰相以利加拿。'),
('CNV', '历代志下', 14, 28, 8, '以色列人从他们的兄弟中掳走妇孺共二十万人；又从他们中间夺取了很多战利品，带回撒玛利亚去。'),
('CNV', '历代志下', 14, 28, 9, '那里有一位耶和华的先知名叫俄德，出来迎接回到撒玛利亚来的军队，对他们说：“耶和华你们列祖的神因为恼怒犹大人，才把他们交在你们手里，你们却怒气冲天，杀戮了他们。'),
('CNV', '历代志下', 14, 28, 10, '现在你们又想强迫犹大人和耶路撒冷人作你们的奴婢。难道你们自己就没有得罪耶和华你们的神吗？'),
('CNV', '历代志下', 14, 28, 11, '你们现在要听我的话，把你们掳回来的兄弟释放回去，因为耶和华的震怒已经临到你们身上了。”'),
('CNV', '历代志下', 14, 28, 12, '于是以法莲人的几个首领，就是约哈难的儿子亚撒利雅、米实利末的儿子比利家、沙龙的儿子耶希西家和哈得莱的儿子亚玛撒，起来阻挡从战场回来的军队，'),
('CNV', '历代志下', 14, 28, 13, '对他们说：“你们不可把这些俘虏带进来，因为我们已经得罪了耶和华，你们想增加我们的罪恶和过犯，我们的过犯实在严重，耶和华的震怒临到以色列人身上了。”'),
('CNV', '历代志下', 14, 28, 14, '于是，军队把俘虏和战利品都留在众领袖和全体会众的面前。'),
('CNV', '历代志下', 14, 28, 15, '上面提过的那些人就起来，领走那些俘虏，从战利品中拿出衣服给所有赤身的穿着，给他们穿上鞋，给他们吃喝，又给他们抹油，又把所有疲弱的人放在驴子上，把他们送回棕树城耶利哥他们的兄弟那里，然后就回撒玛利亚去了。'),
('CNV', '历代志下', 14, 28, 16, '那时，亚哈斯王派人去求亚述王（按照《马索拉文本》的绝大部分文本，“王”作“诸王”；现参照另一份文本和各古译本翻译；参20节和王下16:7）帮助他，'),
('CNV', '历代志下', 14, 28, 17, '因为以东人又来攻打犹大，掳走了许多人。'),
('CNV', '历代志下', 14, 28, 18, '非利士人也侵入了高原和犹大南面的众城，占领了伯．示麦、亚雅仑、基低罗、梭哥和属于梭哥的村庄，亭纳和属于亭纳的村庄，瑾琐和属于瑾琐的村庄，并且住在那里。'),
('CNV', '历代志下', 14, 28, 19, '因为犹大王亚哈斯在犹大放纵邪恶，大大地冒犯了耶和华，所以耶和华使犹大卑微。'),
('CNV', '历代志下', 14, 28, 20, '亚述王提革拉．毗尼色来到他那里，不但没有援助他，反倒欺压他。'),
('CNV', '历代志下', 14, 28, 21, '亚哈斯取了耶和华殿里和王宫中，以及众领袖家里的财宝，给了亚述王，但也无济于事。'),
('CNV', '历代志下', 14, 28, 22, '这亚哈斯王在急难的时候，竟越发冒犯耶和华。'),
('CNV', '历代志下', 14, 28, 23, '他向击败了他的大马士革的神献祭，说：“亚兰王的神帮助了他们，我也向它们献祭，使它们也帮助我。”它们却使他和以色列人灭亡。'),
('CNV', '历代志下', 14, 28, 24, '亚哈斯把神殿里的器皿收集起来，把这些神殿里的器皿都击碎了，又封闭了耶和华殿的各门，并且在耶路撒冷的各个角落建造祭坛。'),
('CNV', '历代志下', 14, 28, 25, '他又在犹大各城建造邱坛，向别的神烧香，惹怒他列祖的神。'),
('CNV', '历代志下', 14, 28, 26, '亚哈斯其余的事迹和他一切所行的，以及一生的始末，都记在犹大和以色列诸王记上。'),
('CNV', '历代志下', 14, 28, 27, '亚哈斯和他的列祖同睡，埋葬在耶路撒冷城里，但没有葬在以色列诸王的陵墓里。他的儿子希西家接续他作王。'),
('CNV', '历代志下', 14, 29, 1, '希西家登基的时候，是二十五岁；他在耶路撒冷作王二十九年。他的母亲名叫亚比雅（“亚比雅”是“亚比”的另一种写法；参王下18:2），是撒迦利雅的女儿。'),
('CNV', '历代志下', 14, 29, 2, '希西家行耶和华看为正的事，像他祖先大卫一切所行的。'),
('CNV', '历代志下', 14, 29, 3, '他在位的元年正月，开了耶和华殿的门，重新修理。'),
('CNV', '历代志下', 14, 29, 4, '他把祭司和利未人都召了来，聚集在东面的广场上，'),
('CNV', '历代志下', 14, 29, 5, '对他们说：“利未人哪，你们要听我的话；现在你们要自洁，又要洁净耶和华你们列祖的神的殿，把污秽之物从圣所中除去。'),
('CNV', '历代志下', 14, 29, 6, '我们的列祖冒犯了神，行了耶和华我们的神看为恶的事，离弃了他，转脸不顾耶和华的居所，以背向他。'),
('CNV', '历代志下', 14, 29, 7, '他们又封闭廊门，熄灭灯火，不在圣所中向以色列的神烧香或献燔祭。'),
('CNV', '历代志下', 14, 29, 8, '因此，耶和华的震怒临到犹大和耶路撒冷的居民身上，使他们成为令人恐惧、惊骇和嗤笑的对象，就像你们亲眼看见的一样。'),
('CNV', '历代志下', 14, 29, 9, '所以我们的列祖倒在刀下；我们的儿女和妻子也都因此作了俘虏。'),
('CNV', '历代志下', 14, 29, 10, '现在我心中有意要和耶和华以色列的神立约，好使他的震怒转离我们。'),
('CNV', '历代志下', 14, 29, 11, '我的孩子们，你们现在不要懈怠，因为耶和华拣选了你们站在他面前事奉他，为要作他的仆人，向他烧香。”'),
('CNV', '历代志下', 14, 29, 12, '于是，利未人哥辖的子孙亚玛赛的儿子玛哈、亚撒利雅的儿子约珥；米拉利的子孙亚伯底的儿子基士、耶哈利勒的儿子亚撒利雅；革顺的子孙薪玛的儿子约亚、约亚的儿子伊甸；'),
('CNV', '历代志下', 14, 29, 13, '以利撒反的子孙申利和耶利；亚萨的子孙撒迦利亚和玛探雅；'),
('CNV', '历代志下', 14, 29, 14, '希幔的子孙耶歇和示每；耶杜顿的子孙示玛雅和乌薛都起来，'),
('CNV', '历代志下', 14, 29, 15, '集合他们的亲族，洁净自己，照着王的吩咐，根据耶和华的命令，进去洁净耶和华的殿。'),
('CNV', '历代志下', 14, 29, 16, '祭司进入耶和华殿的里面进行洁净，他们在耶和华殿里发现的一切污秽之物，都搬到耶和华殿的院子里；利未人接过，就搬到城外的汲沦溪边。'),
('CNV', '历代志下', 14, 29, 17, '他们在正月初一开始洁净圣殿，第八日去到耶和华殿的走廊；他们用了八日洁净耶和华的殿，到了正月十六日才完工。'),
('CNV', '历代志下', 14, 29, 18, '于是他们进王宫见希西家王，说：“我们已经把整个耶和华的殿、燔祭坛和坛的一切器皿、陈设饼的桌子和桌子上的一切器皿，都洁净了。'),
('CNV', '历代志下', 14, 29, 19, '亚哈斯王在位，他得罪神的时候丢弃的一切器皿，我们都预备齐全，也都洁净好了；现在都放在耶和华的祭坛前。”'),
('CNV', '历代志下', 14, 29, 20, '希西家王清早起来，召集城中的领袖，上耶和华的殿去。'),
('CNV', '历代志下', 14, 29, 21, '他们牵来了七头公牛、七只公绵羊、七只羊羔和七只公山羊，要为国家、为圣所和为犹大人作赎罪祭；王吩咐亚伦的子孙众祭司把它们献在耶和华的坛上。'),
('CNV', '历代志下', 14, 29, 22, '他们宰了公牛，祭司把血接过来，洒在祭坛上；他们又宰了公绵羊，把血洒在祭坛上；他们又宰了羊羔，也把血洒在祭坛上。'),
('CNV', '历代志下', 14, 29, 23, '最后把作赎罪祭的公山羊，牵到王和会众面前，王和会众就按手在公山羊的身上。'),
('CNV', '历代志下', 14, 29, 24, '祭司宰了公山羊，把血洒在祭坛上作赎罪祭，为所有以色列人赎罪；因为王曾经吩咐要为所有以色列人献上燔祭和赎罪祭。'),
('CNV', '历代志下', 14, 29, 25, '王又指派在耶和华殿中的利未人拿着响钹和琴瑟，是照着大卫、王的先见迦得和拿单先知所吩咐的，就是耶和华藉他的先知所吩咐的。'),
('CNV', '历代志下', 14, 29, 26, '利未人拿着大卫的乐器，祭司持着号筒，一同站着。'),
('CNV', '历代志下', 14, 29, 27, '希西家吩咐在祭坛上献上燔祭。开始献燔祭的时候，就开始向耶和华歌唱，并且用号筒和以色列王大卫的乐器伴奏。'),
('CNV', '历代志下', 14, 29, 28, '全体会众都叩拜，歌唱的歌唱，吹号的吹号，直到燔祭都献完了。'),
('CNV', '历代志下', 14, 29, 29, '献完了祭，王和所有在场的人，都屈膝叩拜。'),
('CNV', '历代志下', 14, 29, 30, '希西家王和众领袖，又吩咐利未人用大卫和先见亚萨的诗词赞美耶和华，于是他们欢欢喜喜地赞美耶和华，低头敬拜。'),
('CNV', '历代志下', 14, 29, 31, '希西家说：“你们现在归耶和华为圣了。请前来，把祭物和感恩祭带到耶和华的殿里来。”于是会众把祭物和感恩祭带来；凡是甘心乐意的，都把燔祭带来。'),
('CNV', '历代志下', 14, 29, 32, '会众带来的燔祭数目如下：公牛七十头、公绵羊一百只、羊羔二百只。这些都是作燔祭献给耶和华的。'),
('CNV', '历代志下', 14, 29, 33, '还有分别为圣之物：公牛六百头、绵羊三千只。'),
('CNV', '历代志下', 14, 29, 34, '只是祭司太少，不能把所有燔祭牲剥皮，所以他们的亲族利未人协助他们，直到剥皮的工作完了，又等到其他祭司自洁完了，因为利未人在自洁的事上比众祭司更加诚心。'),
('CNV', '历代志下', 14, 29, 35, '此外，还有很多燔祭牲和平安祭牲的脂肪，以及和燔祭同献的奠祭很多。这样，耶和华殿里的事奉就重新恢复了。'),
('CNV', '历代志下', 14, 29, 36, '因为事情很快办完，希西家和全体人民因神为他的子民所预备的，都甚欢乐。'),
('CNV', '历代志下', 14, 30, 1, '希西家派人走遍以色列和犹大，又写信给以法莲人和玛拿西人，叫他们到耶路撒冷耶和华的殿来，守逾越节记念耶和华以色列的神。'),
('CNV', '历代志下', 14, 30, 2, '因为王和众领袖，以及耶路撒冷的全体会众曾经商议，要在二月守逾越节。'),
('CNV', '历代志下', 14, 30, 3, '（但他们不能如期守逾越节，因为自洁的祭司不够，人民也没有齐集在耶路撒冷。）'),
('CNV', '历代志下', 14, 30, 4, '王和全体会众都认为这计划很好，'),
('CNV', '历代志下', 14, 30, 5, '于是下了命令，通告全以色列，从别是巴直到但，叫人民来耶路撒冷守逾越节记念耶和华以色列的神，因为照着所记的定例举行这节的人不多。'),
('CNV', '历代志下', 14, 30, 6, '信差就带着王和众领袖发出的书信，走遍全以色列和犹大，照着王的吩咐，宣告说：“以色列人哪，你们应当转向耶和华，亚伯拉罕、以撒和以色列的神，使他也转向你们这些在亚述王手中逃脱的余民。'),
('CNV', '历代志下', 14, 30, 7, '你们不要像你们的列祖和你们的亲族，他们得罪了耶和华他们列祖的神，以致耶和华使他们成为令人惊骇的对象，就像你们自己所见的。'),
('CNV', '历代志下', 14, 30, 8, '现在你们不可顽固，像你们的列祖那样；要顺服耶和华，进入他永远分别为圣的圣所，事奉耶和华你们的神，使他的烈怒转离你们。'),
('CNV', '历代志下', 14, 30, 9, '如果你们是归向耶和华，你们的亲族和儿女就必在俘掳他们的人面前蒙怜悯，可以返回这地；因为耶和华你们的神是有恩惠有怜悯；如果你们归向他，他必不转脸不顾你们。”'),
('CNV', '历代志下', 14, 30, 10, '信差从这城到那城，走遍了以法莲和玛拿西各地，直到西布伦；那里的人却戏弄他们，讥笑他们。'),
('CNV', '历代志下', 14, 30, 11, '可是在亚设、玛拿西和西布伦中，也有人愿意谦卑，来到耶路撒冷。'),
('CNV', '历代志下', 14, 30, 12, '神的能力也帮助犹大人，使他们一心遵行王和众领袖奉耶和华的命令发出的吩咐。'),
('CNV', '历代志下', 14, 30, 13, '二月，有很多人在耶路撒冷聚集，要举行无酵节，集合了一大群会众。'),
('CNV', '历代志下', 14, 30, 14, '他们起来，把耶路撒冷城中的祭坛和一切香坛，尽都除去，抛在汲沦溪中。'),
('CNV', '历代志下', 14, 30, 15, '二月十四日，他们宰了逾越节的羊羔。祭司和利未人都觉得惭愧，就自洁，把燔祭带到耶和华的殿里。'),
('CNV', '历代志下', 14, 30, 16, '他们遵照神人摩西的律法，按着定例，站在自己的岗位上。祭司从利未人手里把血接过来，洒在祭坛上。'),
('CNV', '历代志下', 14, 30, 17, '因为会众中有很多人还没有自洁，所以利未人必须为所有不洁的人宰杀逾越节的羊羔，使他们在耶和华面前成为圣洁。'),
('CNV', '历代志下', 14, 30, 18, '原来有一大群人，很多是从以法莲、玛拿西、以萨迦和西布伦来的，还没有自洁，就吃逾越节的羊羔，不遵照所记的定例；因此，希西家为他们祷告说：“凡是立定心意，专一寻求神耶和华他们列祖的神的，虽然没有照着圣所洁净的礼自洁，愿良善的耶和华也饶恕他们。”'),
('CNV', '历代志下', 14, 30, 20, '耶和华垂听了希西家的祷告，就饶恕（“饶恕”原文作“医治”）众民。'),
('CNV', '历代志下', 14, 30, 21, '在耶路撒冷的以色列人，都十分欢乐地守除酵节七天；利未人和祭司天天赞美耶和华，用响亮的乐器赞美耶和华。'),
('CNV', '历代志下', 14, 30, 22, '希西家慰勉所有善于事奉耶和华的利未人；众人吃节筵七日，又献上平安祭，称颂耶和华他们列祖的神。'),
('CNV', '历代志下', 14, 30, 23, '全体会众商议好了，要再守节期七天，于是他们欢欢喜喜地又举行了七天。'),
('CNV', '历代志下', 14, 30, 24, '犹大王希西家送给会众公牛一千头，羊七千只；众领袖也送给会众公牛一千头，羊一万只；并且有很多祭司自洁。'),
('CNV', '历代志下', 14, 30, 25, '犹大的全体会众、祭司和利未人、从以色列来的全体会众，以及在以色列地寄居的人和在犹大寄居的人，都非常欢乐。'),
('CNV', '历代志下', 14, 30, 26, '这样，在耶路撒冷有极大的欢乐，自从以色列王大卫的儿子所罗门的日子以来，在耶路撒冷都没有像这样的欢乐。'),
('CNV', '历代志下', 14, 30, 27, '那时，利未支派的祭司起来，给人民祝福；他们的声音蒙了垂听，他们的祷告达到天上神的圣所那里。'),
('CNV', '历代志下', 14, 31, 1, '这一切都作完了，所有在那里的以色列人就都出去，到犹大的各城，打碎神柱，砍下亚舍拉；又在犹大、便雅悯、以法莲和玛拿西各地，把邱坛和祭坛完全拆毁。然后以色列众人都各回各城，各归自己的地业去了。'),
('CNV', '历代志下', 14, 31, 2, '希西家指派祭司和利未人的班次，使祭司和利未人照着自己的班次，各按各职献燔祭和平安祭，又在耶和华殿门内事奉，称谢和赞美耶和华。'),
('CNV', '历代志下', 14, 31, 3, '王又在自己的财物中定出一份作燔祭，就是早晚的燔祭，安息日、月朔和节期的燔祭，都是照着耶和华律法上所记的。'),
('CNV', '历代志下', 14, 31, 4, '王又吩咐住在耶路撒冷的人民，要把祭司和利未人应得的一份给他们，使他们专心执行耶和华的律法。'),
('CNV', '历代志下', 14, 31, 5, '这命令一发出，以色列人就送来很多初熟的五谷、新酒、油和蜜，以及田间各样的出产，又把各物品的十分之一，大批送来。'),
('CNV', '历代志下', 14, 31, 6, '住在犹大各城的以色列人和犹大人，也把牛羊的十分之一，和分别为圣归耶和华他们的神的圣物的十分之一，都送了来，囤积成堆。'),
('CNV', '历代志下', 14, 31, 7, '从三月开始囤积，到七月才完毕。'),
('CNV', '历代志下', 14, 31, 8, '希西家和众领袖来了，看见这些囤积物品，就称颂耶和华，又为耶和华的子民以色列祝福。'),
('CNV', '历代志下', 14, 31, 9, '希西家向祭司和利未人询问这些囤积物品的时候，'),
('CNV', '历代志下', 14, 31, 10, '撒督家的大祭司亚撒利雅回答他，说：“自从人民把供物送进耶和华殿以来，我们就可以吃饱，并且还有很多剩下来。因为耶和华赐福给他的子民，所以剩下的才这样丰盛。”'),
('CNV', '历代志下', 14, 31, 11, '希西家吩咐人在耶和华的殿里预备仓房，他们就预备了。'),
('CNV', '历代志下', 14, 31, 12, '他们很忠心地把供物、各物品的十分之一和分别为圣之物，都搬进仓里去。利未人歌楠雅总管这些物品，他的兄弟示每作副总管。'),
('CNV', '历代志下', 14, 31, 13, '耶歇、亚撒细雅、拿哈、亚撒黑、耶利末、约撒拔、以利、伊斯玛基雅、玛哈、比拿雅在歌楠雅和他的兄弟示每手下，负责监督的工作，他们都是由希西家王和神殿的总管亚撒利雅委派的。'),
('CNV', '历代志下', 14, 31, 14, '看守东门的利未人音拿的儿子可利，掌管自愿献给神的礼物，分发献与耶和华的供物和至圣之物。'),
('CNV', '历代志下', 14, 31, 15, '在他手下有伊甸、珉雅珉、耶书亚、示玛雅、亚玛利雅和示迦尼雅，在祭司的各城里，按着班次，无论大小，把供物分发给他们的亲族。'),
('CNV', '历代志下', 14, 31, 16, '此外，按着家谱，三十岁（“三十岁”原文作“三岁”）及以上的男子：凡是每日按着班次，照着本分进耶和华的殿供职的，也分发给他们。'),
('CNV', '历代志下', 14, 31, 17, '又分发给按着家族登记在家谱上的祭司，也按着班次职责分给二十岁及以上的利未人。'),
('CNV', '历代志下', 14, 31, 18, '又按照家谱的登记，分给他们的全体的小孩、妻子和儿女，因为他们忠心地自洁成圣。'),
('CNV', '历代志下', 14, 31, 19, '至于住在各城郊野作祭司的亚伦的子孙，在各城里都有按名字指定的人，把应得的分分发给祭司中所有的男子，和所有登记在家谱中的利未人。'),
('CNV', '历代志下', 14, 31, 20, '希西家在犹大全地都这样行，他在耶和华他的神面前行良善、正直和诚实的事。'),
('CNV', '历代志下', 14, 31, 21, '他经办的一切事，无论是关于神殿的事奉，或是关于律法和诫命的遵行，他都寻求他的神。因为他尽心去行，所以尽都顺利。'),
('CNV', '历代志下', 14, 32, 1, '在希西家行了这些忠诚的事以后，亚述王西拿基立入侵犹大，围困犹大的设防城，企图攻陷占领。'),
('CNV', '历代志下', 14, 32, 2, '希西家见西拿基立有意攻打耶路撒冷，'),
('CNV', '历代志下', 14, 32, 3, '就与众领袖和众勇士商议，要把城外各道水泉堵塞，他们都赞同。'),
('CNV', '历代志下', 14, 32, 4, '于是有一大班人集合起来，堵塞了一切泉源和流通那地的溪流，他们说：“为什么要让亚述王得着充沛的水源呢？”'),
('CNV', '历代志下', 14, 32, 5, '希西家发愤图强，重建所有拆毁了的城墙，墙上筑起瞭望楼，又建造一道外墙，并且巩固大卫城内的米罗，又制造了很多兵器和盾牌。'),
('CNV', '历代志下', 14, 32, 6, '他又委派军长统管众民，集合他们到城门的广场那里去见他；他鼓励他们说：'),
('CNV', '历代志下', 14, 32, 7, '“你们要坚强勇敢，不要因亚述王和他统领的大军惧怕惊慌；因为和我们同在的，比和他们同在的更多。'),
('CNV', '历代志下', 14, 32, 8, '和他们同在的，不过是人血肉的手臂；和我们同在的，却是耶和华我们的神，他必帮助我们，为我们作战。”众民因犹大王希西家的话都得着鼓励了。'),
('CNV', '历代志下', 14, 32, 9, '随后，亚述王西拿基立和他统领的全军攻打拉吉的时候，就差派他的臣仆到耶路撒冷来见犹大王希西家和所有在耶路撒冷的犹大人，说：'),
('CNV', '历代志下', 14, 32, 10, '“亚述王西拿基立这样说：‘你们现在还在耶路撒冷受困，你们可倚靠什么呢？'),
('CNV', '历代志下', 14, 32, 11, '希西家曾对你们说：耶和华我们的神必拯救我们脱离亚述王的手。他不是迷惑你们，使你们因饥渴而死吗？'),
('CNV', '历代志下', 14, 32, 12, '这希西家不是曾经把耶和华的邱坛和祭坛除去，吩咐犹大和耶路撒冷的人说：你们要在一个坛前敬拜，要在它上面烧香吗？'),
('CNV', '历代志下', 14, 32, 13, '我和我列祖向各地的民族所行的，你们不知道吗？各地列国的神能拯救他们的国脱离我的手吗？'),
('CNV', '历代志下', 14, 32, 14, '我列祖消灭的那些国的众神，有哪一个能拯救自己的子民脱离我的手呢？难道你们的神能拯救你们脱离我的手吗？'),
('CNV', '历代志下', 14, 32, 15, '所以，你们现在不要让希西家这样欺骗、迷惑你们；你们也不要信他；因为无论哪一邦哪一国的神，都不能拯救自己的子民脱离我的手和我列祖的手，你们的神不是更不能拯救你们脱离我的手吗？’”'),
('CNV', '历代志下', 14, 32, 16, '西拿基立的臣仆还说了别的话毁谤耶和华神和他的仆人希西家。'),
('CNV', '历代志下', 14, 32, 17, '西拿基立又写信来辱骂耶和华以色列的神，讥诮他说：“各地列国的神没有拯救它们的子民脱离我的手，希西家的神也照样不能拯救他的子民脱离我的手。”'),
('CNV', '历代志下', 14, 32, 18, '亚述王的臣仆用犹大语，向城墙上的耶路撒冷人民大声呼叫，要惊吓他们，使他们慌乱，好攻取那城。'),
('CNV', '历代志下', 14, 32, 19, '他们论到耶路撒冷的神，就好像世上万民的神一样，把他当作是人手所做的。'),
('CNV', '历代志下', 14, 32, 20, '希西家王和亚摩斯的儿子以赛亚先知为了这事祷告，向天呼求。'),
('CNV', '历代志下', 14, 32, 21, '耶和华就差派一位使者，进入亚述王的军营中，把所有英勇的战士、官长和将帅，尽都消灭了。亚述王满面羞愧返回本国去了。他进入自己的神庙的时候，他亲生的儿子在那里用刀把他杀了。'),
('CNV', '历代志下', 14, 32, 22, '这样，耶和华拯救了希西家和耶路撒冷的居民，脱离了亚述王西拿基立的手，和其他仇敌的手，又使他们四境平安。'),
('CNV', '历代志下', 14, 32, 23, '有很多人把供物带到耶路撒冷献给耶和华，又把很多宝物送给犹大王希西家；从此，希西家受到各国的尊重。'),
('CNV', '历代志下', 14, 32, 24, '那时，希西家患病垂危，就祷告耶和华；耶和华应允了他，又赐他一个征兆。'),
('CNV', '历代志下', 14, 32, 25, '希西家却没有照着他蒙受的恩惠报答耶和华；因为他心高气傲，所以耶和华的忿怒临到他，以及犹大和耶路撒冷的人身上。'),
('CNV', '历代志下', 14, 32, 26, '但希西家因为自己心高气傲而谦卑下来，他和耶路撒冷的居民都谦卑下来，因此耶和华的忿怒，在希西家在世的日子，没有临到他们身上。'),
('CNV', '历代志下', 14, 32, 27, '希西家的财富甚多，尊荣极大；他为自己建造库房，收藏金银、宝石、香料、盾牌和各样的珍宝；'),
('CNV', '历代志下', 14, 32, 28, '又建造仓库，收藏五谷、新酒和油；又为各类牲畜盖棚栏、羊圈。'),
('CNV', '历代志下', 14, 32, 29, '他又为自己建造城镇，并且拥有大批牛羊牲口，因为神赐给他极多的财物。'),
('CNV', '历代志下', 14, 32, 30, '这希西家堵塞了基训泉上游的水，引水直下，流到大卫城的西边。希西家所行的一切事，尽都亨通。'),
('CNV', '历代志下', 14, 32, 31, '唯有巴比伦王的使者奉派来见希西家，询问犹大地发生的奇事的时候，神就离开了他，为要试验他，好知道他心中的一切。'),
('CNV', '历代志下', 14, 32, 32, '希西家其余的事迹和他的善行，都记在亚摩斯的儿子以赛亚先知的异象书上，以及犹大和以色列诸王记上。'),
('CNV', '历代志下', 14, 32, 33, '希西家和他的列祖同睡，埋葬在大卫子孙墓地的高层；他死的时候，犹大众人和耶路撒冷的居民都向他致敬。他的儿子玛拿西接续他作王。'),
('CNV', '历代志下', 14, 33, 1, '玛拿西登基的时候，是十二岁；他在耶路撒冷作王共五十五年。'),
('CNV', '历代志下', 14, 33, 2, '他行耶和华看为恶的事，随从耶和华在以色列人面前赶走的列国所行可厌恶的事。'),
('CNV', '历代志下', 14, 33, 3, '他重新建造他父亲希西家拆毁的邱坛，又为巴力立坛，制造亚舍拉，并且敬拜和事奉天上的万象。'),
('CNV', '历代志下', 14, 33, 4, '他又在耶和华的殿中筑坛，耶和华曾经指着这殿说：“我的名必永远留在耶路撒冷。”'),
('CNV', '历代志下', 14, 33, 5, '玛拿西在耶和华殿的两院中，为天上的万象筑坛，'),
('CNV', '历代志下', 14, 33, 6, '并且在欣嫩子谷把自己的儿女用火烧为祭，又占卜、行邪术、用法术、交鬼和通灵；作了很多耶和华看为恶的事，惹他发怒。'),
('CNV', '历代志下', 14, 33, 7, '他又把他所做的雕像立在神的殿中，神曾经指着这殿，对大卫和他的儿子所罗门说：“我要在这殿里，和在我从以色列各支派中拣选的耶路撒冷中，立我的名，直到永远。'),
('CNV', '历代志下', 14, 33, 8, '只要以色列人谨守遵行我藉着摩西吩咐他们的一切律法、律例和典章，我就决不再使他们的脚离开我赐给他们列祖的地。”'),
('CNV', '历代志下', 14, 33, 9, '可是玛拿西却引诱犹大人和耶路撒冷的居民行恶，比耶和华在以色列人面前除灭的列国更厉害。'),
('CNV', '历代志下', 14, 33, 10, '耶和华曾警告玛拿西和他的人民，他们却不理会。'),
('CNV', '历代志下', 14, 33, 11, '因此耶和华领亚述王的将帅来攻打他们，用钩子钩着玛拿西，用铜链锁住他，把他带到巴比伦去。'),
('CNV', '历代志下', 14, 33, 12, '玛拿西在急难的时候，就恳求耶和华他的神，并且在他列祖的神面前非常谦卑。'),
('CNV', '历代志下', 14, 33, 13, '他向耶和华祷告，耶和华应允他的恳求，垂听他的祈求，使他归回耶路撒冷，恢复他的王位。玛拿西这才知道只有耶和华是神。'),
('CNV', '历代志下', 14, 33, 14, '此后，玛拿西在大卫城外，从谷中的基训西边起直到鱼门口，建了一道城墙，围绕着俄斐勒，他把城墙建得很高；又在犹大各设防城里，派驻军长。'),
('CNV', '历代志下', 14, 33, 15, '又从耶和华的殿中除掉外族人的神和偶像，又把他在耶和华殿的山和在耶路撒冷所筑的一切坛，都抛出城外。'),
('CNV', '历代志下', 14, 33, 16, '玛拿西重修了耶和华的祭坛，在坛上献上平安祭和感恩祭，又吩咐犹大人事奉耶和华以色列的神。'),
('CNV', '历代志下', 14, 33, 17, '可是人民仍然在邱坛上献祭，尽管只向耶和华他们的神献祭。'),
('CNV', '历代志下', 14, 33, 18, '玛拿西其余的事迹，包括他对他的神的祷告，和那些先见奉耶和华以色列的神的名向他所说的话，都记在以色列诸王记上。'),
('CNV', '历代志下', 14, 33, 19, '他的祷告，神怎样应允他的恳求，他谦卑下来以前的一切罪恶和过犯，以及他在什么地方建筑邱坛，设立亚舍拉和偶像，都记在先见（按照《马索拉文本》的绝大部分文本，“先见”作“何赛”，原文与“先见”相似；现参照另一份文本和《七十士译本》翻译）的言行录上。'),
('CNV', '历代志下', 14, 33, 20, '玛拿西和他的列祖同睡，埋葬在他的宫中；他的儿子亚们接续他作王。'),
('CNV', '历代志下', 14, 33, 21, '亚们登基的时候，是二十二岁；他在耶路撒冷作王共两年。'),
('CNV', '历代志下', 14, 33, 22, '他行耶和华看为恶的事，像他父亲玛拿西所行的一样；亚们向他父亲玛拿西所做的一切雕像献祭，并且事奉它们。'),
('CNV', '历代志下', 14, 33, 23, '他没有在耶和华面前谦卑，像他父亲玛拿西谦卑一样；这亚们所犯的罪过越来越多。'),
('CNV', '历代志下', 14, 33, 24, '后来，他的臣仆阴谋造反，在宫中把他杀死了。'),
('CNV', '历代志下', 14, 33, 25, '但犹大的人民把所有反叛亚们王的人都击杀了，并且立他的儿子约西亚接续他作王。'),
('CNV', '历代志下', 14, 34, 1, '约西亚登基的时候是八岁；他在耶路撒冷作王共三十一年。'),
('CNV', '历代志下', 14, 34, 2, '他行耶和华看为正的事，效法他先祖大卫所行的，不偏左，也不偏右。'),
('CNV', '历代志下', 14, 34, 3, '他在位第八年，还是年幼的时候，就开始寻求他先祖大卫的神。到了第十二年，他就开始洁净犹大和耶路撒冷，除掉邱坛、亚舍拉、雕像和铸像。'),
('CNV', '历代志下', 14, 34, 4, '众人在他面前拆毁了巴力的祭坛，他亲自打碎了坛上高高的香坛，又把亚舍拉、雕像和铸像砍碎成灰，撒在向这些偶像献过祭的人的坟上。'),
('CNV', '历代志下', 14, 34, 5, '他把祭司的骨头烧在他们的祭坛上，这样就洁净了犹大和耶路撒冷。'),
('CNV', '历代志下', 14, 34, 6, '他又在玛拿西、以法莲、西缅，以至拿弗他利的各城，以及它们周围荒废的地方，都这样行。'),
('CNV', '历代志下', 14, 34, 7, '他拆毁了祭坛，把亚舍拉和雕刻的偶像打碎，破碎了以色列全地所有的香坛，就回耶路撒冷去了。'),
('CNV', '历代志下', 14, 34, 8, '约西亚在位第十八年，洁净犹大地和圣殿以后，就差派亚萨利雅的儿子沙番、市长玛西雅和约哈斯的儿子史官约亚，去修筑耶和华他的神的殿。'),
('CNV', '历代志下', 14, 34, 9, '于是他们来见大祭司希勒家，把献给神的殿的银子交给他。这银子都是守门的利未人，从玛拿西、以法莲和以色列所有的余民，以及犹大、便雅悯和耶路撒冷的居民那里收集来的。'),
('CNV', '历代志下', 14, 34, 10, '他们又把银子交给在耶和华殿里负责监察的人；他们又把银子发给在耶和华殿里作工的工人，去修补圣殿。'),
('CNV', '历代志下', 14, 34, 11, '他们把银子交给木匠和石匠，去购买凿好的石头和作木架与横梁的木材，修补犹大列王毁坏了的殿宇。'),
('CNV', '历代志下', 14, 34, 12, '这些人忠心地工作；管理他们的督工是利未人米拉利的子孙雅哈和俄巴底；监管他们的是哥辖的子孙撒迦利雅和米书兰；还有所有精通乐器的利未人，'),
('CNV', '历代志下', 14, 34, 13, '管理扛抬的，并且监管所有作各种工作的人；利未人中，也有作书记、作职员和作守门的。'),
('CNV', '历代志下', 14, 34, 14, '他们把献给耶和华殿的银子拿出来的时候，希勒家祭司发现了耶和华藉摩西所传的律法书。'),
('CNV', '历代志下', 14, 34, 15, '希勒家对书记沙番说：“我在耶和华的殿里发现了律法书。”希勒家就把书交给沙番。'),
('CNV', '历代志下', 14, 34, 16, '沙番把书带到王那里，同时向王报告：“你交托你仆人的事，他们都办妥了。'),
('CNV', '历代志下', 14, 34, 17, '他们把在耶和华殿里的银子倒出来，交给监督和作工的人。”'),
('CNV', '历代志下', 14, 34, 18, '书记沙番又告诉王，说：“希勒家祭司还交给我一卷书卷。”于是沙番在王面前诵读那书。'),
('CNV', '历代志下', 14, 34, 19, '王一听见律法书上的话，就撕裂自己的衣服，'),
('CNV', '历代志下', 14, 34, 20, '吩咐希勒家和沙番的儿子亚希甘、米迦的儿子亚比顿、书记沙番，以及王的臣仆亚撒雅，说：'),
('CNV', '历代志下', 14, 34, 21, '“你们去，为我、也为以色列和犹大的余民，求问耶和华关于我们发现的这书上的话；因为我们的列祖没有谨守耶和华的话，也没有照着这书上所记的一切去行，所以耶和华才向我们大发烈怒。”'),
('CNV', '历代志下', 14, 34, 22, '于是希勒家和王所差派的人（《马索拉文本》没有“差派的人”）去见女先知户勒大。户勒大是掌管礼服的沙龙的妻子；沙龙是哈斯拉的孙子、特瓦的儿子；户勒大住在耶路撒冷第二区；他们对户勒大这样说了。'),
('CNV', '历代志下', 14, 34, 23, '她就回答他们：“耶和华以色列的神这样说：‘你们对那差你们来见我的人说：'),
('CNV', '历代志下', 14, 34, 24, '耶和华这样说：我要按着在犹大王面前诵读的那卷书上所写的一切咒诅，降灾在这地和这地的居民身上。'),
('CNV', '历代志下', 14, 34, 25, '因为他们离弃了我，向别的神烧香，用他们手所做的惹我发怒，所以我的忿怒必倾倒在这地上，总不熄灭。'),
('CNV', '历代志下', 14, 34, 26, '至于那派你们来求问耶和华的犹大王，你们要这样对他说：耶和华以色列的神这样说：论到你听见的话；'),
('CNV', '历代志下', 14, 34, 27, '因为你听了我指着这地方和这里的居民所说的话，就心里感动，在神面前谦卑；你既然在我的面前谦卑，又撕裂衣服，在我的面前哭泣，所以我就垂听你的祷告；这是耶和华的宣告。'),
('CNV', '历代志下', 14, 34, 28, '我必使你归到你的列祖那里去，你必平平安安归入你的坟墓。我所要降在这地方和这地上的居民身上的一切灾祸，你必不会亲眼看见。’”他们就把这番话回覆王去了。'),
('CNV', '历代志下', 14, 34, 29, '于是王派人把犹大和耶路撒冷的众长老都召集了来。'),
('CNV', '历代志下', 14, 34, 30, '王和犹大众人、耶路撒冷的居民、祭司、利未人，以及所有的人民，无论大小，都一同上耶和华的殿去；王就把在耶和华殿里发现的约书上的一切话，都诵读给他们听。'),
('CNV', '历代志下', 14, 34, 31, '王站在他的位上，在耶和华面前立约，要一心一意跟随耶和华，谨守他的诫命、法度和律例，实行这书上所记立约的誓言。'),
('CNV', '历代志下', 14, 34, 32, '他又使所有在耶路撒冷和便雅悯的人，都顺从这约。于是耶路撒冷的居民，都遵照他们列祖的神的约而行。'),
('CNV', '历代志下', 14, 34, 33, '约西亚在以色列人所属的各地，把一切可憎的物尽都除掉，使所有在以色列的人都事奉耶和华他们的神。约西亚在世的日子，人民都跟随耶和华他们列祖的神，总不离开。'),
('CNV', '历代志下', 14, 35, 1, '约西亚在耶路撒冷守逾越节记念耶和华；正月十四日他们宰了逾越节的羊羔。'),
('CNV', '历代志下', 14, 35, 2, '王指派各祭司的职务，又鼓励他们去作耶和华殿的事务。'),
('CNV', '历代志下', 14, 35, 3, '他又对那些教导以色列众人，分别为圣归耶和华的利未人说：“你们要把圣约柜安放在以色列王大卫的儿子所罗门建造的殿里；不必再用肩膀扛抬。现在你们要服事耶和华你们的神，服事他的子民以色列。'),
('CNV', '历代志下', 14, 35, 4, '你们要按着家族和照着班次，根据以色列王大卫所写的和他儿子所罗门所写的，自己好好预备。'),
('CNV', '历代志下', 14, 35, 5, '你们要按着你们的亲族这平民的家族的班次，侍立在圣所；每个班次中要有几个利未家族的人。'),
('CNV', '历代志下', 14, 35, 6, '你们要宰逾越节的羊羔，洁净自己，为你们的亲族预备一切，遵守耶和华藉摩西吩咐的话。”'),
('CNV', '历代志下', 14, 35, 7, '于是约西亚送出绵羊羔和山羊羔共三万只，还有公牛三千头，给所有在场的人民作逾越节的祭牲；这些都是取自王的财产。'),
('CNV', '历代志下', 14, 35, 8, '约西亚手下的众领袖也自愿把祭牲送给人民、祭司和利未人；又有神殿的总管希勒家、撒迦利亚和耶歇，也把羔羊二千六百只和公牛三百头，送给祭司作逾越节的祭牲。'),
('CNV', '历代志下', 14, 35, 9, '利未人的领袖歌楠雅和他的两个兄弟示玛雅和拿坦业，以及哈沙比雅、耶利和约撒拔，也把羊羔五千只和公牛五百头，送给利未人作逾越节的祭牲。'),
('CNV', '历代志下', 14, 35, 10, '这样，事奉的职务安排好了以后，他们照着王的吩咐，祭司站在自己的岗位，利未人也按着自己的班次侍立。'),
('CNV', '历代志下', 14, 35, 11, '利未人宰了逾越节的羊羔，祭司从他们的手里把血接过来，洒在坛上，利未人剥了祭牲的皮，'),
('CNV', '历代志下', 14, 35, 12, '把作燔祭的部分拿去，按着各家族的系别分给众民，使他们可以照着摩西的书上所写的，奉献给耶和华。奉献公牛也是这样。'),
('CNV', '历代志下', 14, 35, 13, '他们按照规矩用火烤逾越节的羊羔，其他的圣物用锅、用釜，或用煎盘煮熟，迅速地送给众民；'),
('CNV', '历代志下', 14, 35, 14, '然后他们才为自己和祭司预备祭物，因为作祭司的亚伦的子孙忙于献上燔祭和脂肪，直到晚上，利未人才为自己和祭司亚伦的子孙预备祭物。'),
('CNV', '历代志下', 14, 35, 15, '歌唱的亚萨的子孙，照着大卫、亚萨、希幔和王的先见耶杜顿的吩咐，站在自己的岗位上；守门的看守各门，不用离开自己的职务，因为他们的利未亲族为他们预备了祭物。'),
('CNV', '历代志下', 14, 35, 16, '这样，当日一切事奉耶和华的职务都安排好了，就照着约西亚王的吩咐守逾越节，和在耶和华的祭坛上献上燔祭。'),
('CNV', '历代志下', 14, 35, 17, '当时在场的以色列人守逾越节，又守除酵节七天。'),
('CNV', '历代志下', 14, 35, 18, '自从撒母耳先知的日子以来，在以色列中没有守过像这样的逾越节；以色列诸王也都没有守过这样的逾越节，像约西亚、祭司、利未人、犹大众人和在场的以色列人，以及耶路撒冷的居民守的。'),
('CNV', '历代志下', 14, 35, 19, '这逾越节是约西亚在位第十八年守的。'),
('CNV', '历代志下', 14, 35, 20, '约西亚整理好圣殿的一切事以后，埃及王尼哥上来，帮助靠近幼发拉底河的迦基米施；约西亚就出去阻挡他。'),
('CNV', '历代志下', 14, 35, 21, '尼哥差派使者来见约西亚说：“犹大王啊，我和你有什么关系呢？我现在不是来攻击你，而是要攻击和我交战的那国家；并且神吩咐我要赶快，你不可干预神的事，免得他毁灭你，因为神和我同在。”'),
('CNV', '历代志下', 14, 35, 22, '约西亚却不肯离开他，反而改了装要和他作战，不听从神藉尼哥所说的话；于是他去到米吉多平原和尼哥交战。'),
('CNV', '历代志下', 14, 35, 23, '弓箭手射中了约西亚王；王对他的臣仆说：“你们把我带走吧，因为我受了重伤。”'),
('CNV', '历代志下', 14, 35, 24, '他的臣仆把他从战车上扶下来，放在他的第二辆战车上，把他送回耶路撒冷去，他跟着就死了，埋葬在他列祖的坟墓里。犹大和耶路撒冷的众人都为约西亚哀悼。'),
('CNV', '历代志下', 14, 35, 25, '耶利米为约西亚作了哀歌；所有歌唱的男女都唱哀歌，哀悼约西亚，直到今日；甚至在以色列中成了定例。这歌记在哀歌书上。'),
('CNV', '历代志下', 14, 35, 26, '约西亚其余的事迹，和他按着耶和华律法上所记而行的善事，'),
('CNV', '历代志下', 14, 35, 27, '以及他一生的始末，都记在以色列和犹大列王记上。'),
('CNV', '历代志下', 14, 36, 1, '犹大地的人民选了约西亚的儿子约哈斯，立他在耶路撒冷接续他父亲作王。'),
('CNV', '历代志下', 14, 36, 2, '约哈斯登基的时候，是二十三岁；他在耶路撒冷作王共三个月。'),
('CNV', '历代志下', 14, 36, 3, '埃及王在耶路撒冷把他废了，又罚犹大地缴纳三千四百公斤银子，三十四公斤金子。'),
('CNV', '历代志下', 14, 36, 4, '后来埃及王立了约哈斯的兄弟以利雅敬作王，统治犹大和耶路撒冷，又给他改名叫约雅敬；尼哥却把约雅敬的兄弟约哈斯带到埃及去了。'),
('CNV', '历代志下', 14, 36, 5, '约雅敬登基的时候，是二十五岁；他在耶路撒冷作王共十一年，行耶和华他的神看为恶的事。'),
('CNV', '历代志下', 14, 36, 6, '巴比伦王尼布甲尼撒上来攻打他，用铜链锁住他，把他带到巴比伦去。'),
('CNV', '历代志下', 14, 36, 7, '尼布甲尼撒又把耶和华殿里一部分的器皿带回巴比伦，放在巴比伦他的神庙里。'),
('CNV', '历代志下', 14, 36, 8, '约雅敬其余的事迹，和他所行可憎的事，以及他的遭遇，都记在以色列和犹大列王记上。他的儿子约雅斤接续他作王。'),
('CNV', '历代志下', 14, 36, 9, '约雅斤登基的时候，是八岁；他在耶路撒冷作王共三个月零十天，行耶和华看为恶的事。'),
('CNV', '历代志下', 14, 36, 10, '过了年，尼布甲尼撒派人去把约雅斤和耶和华殿里的珍贵的器皿，一起带到巴比伦来。他立了约雅斤的叔叔西底家，作犹大和耶路撒冷的王。'),
('CNV', '历代志下', 14, 36, 11, '西底家登基的时候，是二十一岁；他在耶路撒冷作王共十一年，')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '历代志下', 14, 36, 12, '他行耶和华他的神看为恶的事；耶利米先知奉耶和华的命令警戒他，他仍不在耶利米面前谦卑下来。'),
('CNV', '历代志下', 14, 36, 13, '尼布甲尼撒王曾经使他指着神起誓，他还是背叛了尼布甲尼撒；他顽固执拗，不肯归向耶和华以色列的神。'),
('CNV', '历代志下', 14, 36, 14, '此外，所有的祭司长和人民也都大大地得罪神，随从列国所行一切可憎的事；他们污秽了耶和华在耶路撒冷分别为圣的殿。'),
('CNV', '历代志下', 14, 36, 15, '耶和华他们列祖的神，因为爱惜自己的子民和居所，就常常差派使者警戒他们。'),
('CNV', '历代志下', 14, 36, 16, '他们却戏弄神的使者，藐视他的话，讥诮他的先知，以致耶和华的忿怒临到他的子民身上，直到无法挽救。'),
('CNV', '历代志下', 14, 36, 17, '耶和华使迦勒底人的王上来攻打他们，在他们的圣殿里用刀杀了他们的壮丁，少男和少女以及年老衰弱的，他们都不怜惜；耶和华把所有这些人都交在迦勒底王的手里。'),
('CNV', '历代志下', 14, 36, 18, '迦勒底王把神殿里所有的器皿，无论大小，和耶和华殿里的财宝，以及王和众领袖的财宝，都带到巴比伦去。'),
('CNV', '历代志下', 14, 36, 19, '迦勒底人烧了神的殿，拆毁了耶路撒冷的城墙，用火烧了城里所有的宫殿，又毁坏了城里一切珍贵的器皿。'),
('CNV', '历代志下', 14, 36, 20, '脱离刀剑的人，迦勒底王都把他们掳到巴比伦去，作他和他的子孙的奴仆，直到波斯国兴起的时候。'),
('CNV', '历代志下', 14, 36, 21, '这样，就应验了耶和华藉耶利米所说的话：直到这地享满了安息，因为这地在荒凉的日子，就享安息，直到满了七十年。'),
('CNV', '历代志下', 14, 36, 22, '波斯王古列元年，耶和华为要应验他藉耶利米所说的话，就感动波斯王古列的心，使他通告全国，并且下诏书说：'),
('CNV', '历代志下', 14, 36, 23, '“波斯王古列这样说：‘耶和华天上的神已经把地上万国赐给我。他指派我在犹大的耶路撒冷为他建造殿宇。你们中间凡是他的子民，都可以上去；愿耶和华他的神和他同在！’”'),
('CNV', '以斯拉记', 15, 1, 1, '波斯王古列元年，耶和华为要应验他藉耶利米的口所说的话，就激动波斯王古列的心灵，使他通令全国，传达文告说：'),
('CNV', '以斯拉记', 15, 1, 2, '“波斯王古列这样说：‘耶和华天上的神已经把地上万国赐给我。他指派我在犹大的耶路撒冷为他建造殿宇。'),
('CNV', '以斯拉记', 15, 1, 3, '你们中间凡是他的子民，愿神与他同在的，都可以上犹大的耶路撒冷去，建造耶和华以色列的神的殿，他是在耶路撒冷受敬拜的神。'),
('CNV', '以斯拉记', 15, 1, 4, '所有余民，无论寄居在什么地方，那地方的人都要用金、银、财物、牲畜帮助他，也要为在耶路撒冷神的殿献上甘心的礼物。’”'),
('CNV', '以斯拉记', 15, 1, 5, '于是，犹大和便雅悯的族长、祭司、利未人和所有被神激动了心灵的人，都起来要上去，重建在耶路撒冷耶和华的殿。'),
('CNV', '以斯拉记', 15, 1, 6, '他们四围的人都用银器、金子、财物、牲畜和珍贵的礼物协助他们，另外还有各种甘心奉献的礼物。'),
('CNV', '以斯拉记', 15, 1, 7, '古列王把耶和华殿里的器皿拿出来，就是从前尼布甲尼撒从耶路撒冷拿来放在自己的神庙里的。'),
('CNV', '以斯拉记', 15, 1, 8, '波斯王古列命令司库官米提利达把这些器皿拿出来，按数交给犹大的领袖设巴萨。'),
('CNV', '以斯拉记', 15, 1, 9, '器皿的数目是：金盘三十个、银盘一千个、刀二十九把、'),
('CNV', '以斯拉记', 15, 1, 10, '金碗三十个、次等银碗四百一十个（“次等银碗四百一十个”：本句意义难确定，或译：“银碗二千四百一十个”），其他的器皿一千件。'),
('CNV', '以斯拉记', 15, 1, 11, '全部的金银器皿共有五千四百件。被掳的人从巴比伦上耶路撒冷去的时候，设巴萨把这一切器皿都带上去。'),
('CNV', '以斯拉记', 15, 2, 1, '这些犹大省的人，从前被巴比伦王尼布甲尼撒掳到巴比伦去，现在他们从被掳之地回到耶路撒冷和犹大，各归自己的城镇。'),
('CNV', '以斯拉记', 15, 2, 2, '他们与所罗巴伯、耶书亚、尼希米、西莱雅、利来雅、末底改、必珊、米斯拔、比革瓦伊、利宏和巴拿一同回去。以色列民的男丁数目记在下面：'),
('CNV', '以斯拉记', 15, 2, 3, '巴录的子孙二千一百七十二人；'),
('CNV', '以斯拉记', 15, 2, 4, '示法提雅的子孙三百七十二人；'),
('CNV', '以斯拉记', 15, 2, 5, '亚拉的子孙七百七十五人；'),
('CNV', '以斯拉记', 15, 2, 6, '巴哈．摩押的子孙，就是耶书亚和约押的子孙，二千八百一十二人；'),
('CNV', '以斯拉记', 15, 2, 7, '以拦的子孙一千二百五十四人；'),
('CNV', '以斯拉记', 15, 2, 8, '萨土的子孙九百四十五人；'),
('CNV', '以斯拉记', 15, 2, 9, '萨改的子孙七百六十人；'),
('CNV', '以斯拉记', 15, 2, 10, '巴尼的子孙六百四十二人；'),
('CNV', '以斯拉记', 15, 2, 11, '比拜的子孙六百二十三人；'),
('CNV', '以斯拉记', 15, 2, 12, '押甲的子孙一千二百二十二人；'),
('CNV', '以斯拉记', 15, 2, 13, '亚多尼干的子孙六百六十六人；'),
('CNV', '以斯拉记', 15, 2, 14, '比革瓦伊的子孙二千零五十六人；'),
('CNV', '以斯拉记', 15, 2, 15, '亚丁的子孙四百五十四人；'),
('CNV', '以斯拉记', 15, 2, 16, '亚特的子孙，就是希西家的子孙，九十八人；'),
('CNV', '以斯拉记', 15, 2, 17, '比宰的子孙三百二十三人；'),
('CNV', '以斯拉记', 15, 2, 18, '约拉的子孙一百一十二人；'),
('CNV', '以斯拉记', 15, 2, 19, '哈顺的子孙二百二十三人；'),
('CNV', '以斯拉记', 15, 2, 20, '吉罢珥的子孙九十五人；'),
('CNV', '以斯拉记', 15, 2, 21, '伯利恒人一百二十三人。'),
('CNV', '以斯拉记', 15, 2, 22, '尼陀法人五十六人。'),
('CNV', '以斯拉记', 15, 2, 23, '亚拿突人一百二十八人。'),
('CNV', '以斯拉记', 15, 2, 24, '亚斯玛弗人四十二人。'),
('CNV', '以斯拉记', 15, 2, 25, '基列．耶琳人、基非拉人和比录人，共七百四十三人。'),
('CNV', '以斯拉记', 15, 2, 26, '拉玛人和迦巴人共六百二十一人。'),
('CNV', '以斯拉记', 15, 2, 27, '默玛人一百二十二人。'),
('CNV', '以斯拉记', 15, 2, 28, '伯特利人和艾人共二百二十三人。'),
('CNV', '以斯拉记', 15, 2, 29, '尼波人五十二人。'),
('CNV', '以斯拉记', 15, 2, 30, '玛革比士的子孙一百五十六人。'),
('CNV', '以斯拉记', 15, 2, 31, '另外一个以拦的子孙一千二百五十四人。'),
('CNV', '以斯拉记', 15, 2, 32, '哈琳的子孙三百二十人。'),
('CNV', '以斯拉记', 15, 2, 33, '罗德、哈第和阿挪的子孙共七百二十五人。'),
('CNV', '以斯拉记', 15, 2, 34, '耶利哥的子孙三百四十五人。'),
('CNV', '以斯拉记', 15, 2, 35, '西拿的子孙三千六百三十人。'),
('CNV', '以斯拉记', 15, 2, 36, '祭司的数目记在下面：耶书亚家的耶大雅的子孙九百七十三人。'),
('CNV', '以斯拉记', 15, 2, 37, '音麦的子孙一千零五十二人。'),
('CNV', '以斯拉记', 15, 2, 38, '巴施户珥的子孙一千二百四十七人。'),
('CNV', '以斯拉记', 15, 2, 39, '哈琳的子孙一千零一十七人。'),
('CNV', '以斯拉记', 15, 2, 40, '利未人的数目记在下面：何达威雅的子孙，就是耶书亚和甲篾的子孙，七十四人。'),
('CNV', '以斯拉记', 15, 2, 41, '负责歌唱的：亚萨的子孙一百二十八人。'),
('CNV', '以斯拉记', 15, 2, 42, '负责守门的：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙和朔拜的子孙，共一百三十九人。'),
('CNV', '以斯拉记', 15, 2, 43, '殿役的数目记在下面：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、'),
('CNV', '以斯拉记', 15, 2, 44, '基绿的子孙、西亚的子孙、巴顿的子孙、'),
('CNV', '以斯拉记', 15, 2, 45, '利巴拿的子孙、哈迦巴的子孙、亚谷的子孙、'),
('CNV', '以斯拉记', 15, 2, 46, '哈甲的子孙、萨买的子孙、哈难的子孙、'),
('CNV', '以斯拉记', 15, 2, 47, '吉德的子孙、迦哈的子孙、利亚雅的子孙、'),
('CNV', '以斯拉记', 15, 2, 48, '利汛的子孙、尼哥大的子孙、迦散的子孙、'),
('CNV', '以斯拉记', 15, 2, 49, '乌撒的子孙、巴西亚的子孙、比塞的子孙、'),
('CNV', '以斯拉记', 15, 2, 50, '押拿的子孙、米乌宁的子孙、尼普心的子孙、'),
('CNV', '以斯拉记', 15, 2, 51, '巴卜的子孙、哈古巴的子孙、哈忽的子孙、'),
('CNV', '以斯拉记', 15, 2, 52, '巴洗律的子孙、米希大的子孙、哈沙的子孙、'),
('CNV', '以斯拉记', 15, 2, 53, '巴柯的子孙、西西拉的子孙、答玛的子孙、'),
('CNV', '以斯拉记', 15, 2, 54, '尼细亚的子孙和哈提法的子孙。'),
('CNV', '以斯拉记', 15, 2, 55, '所罗门仆人的子孙的数目记在下面：琐太的子孙、琐斐列的子孙、比路大的子孙、'),
('CNV', '以斯拉记', 15, 2, 56, '雅拉的子孙、达昆的子孙、吉德的子孙、'),
('CNV', '以斯拉记', 15, 2, 57, '示法提雅的子孙、哈替的子孙、玻黑列．哈斯巴音的子孙和亚米的子孙。'),
('CNV', '以斯拉记', 15, 2, 58, '作殿役的和所罗门仆人的子孙共三百九十二人。'),
('CNV', '以斯拉记', 15, 2, 59, '以下这些人是从特．米拉、特．哈萨、基绿、押但、音麦上来的，可是他们无法证明他们的父家或世系是以色列人。'),
('CNV', '以斯拉记', 15, 2, 60, '这些人是第莱雅的子孙、多比雅的子孙和尼哥大的子孙，共六百五十二人。'),
('CNV', '以斯拉记', 15, 2, 61, '祭司的子孙中，有哈巴雅的子孙、哈哥斯的子孙和巴西莱的子孙；巴西莱娶了基列人巴西莱的一个女儿为妻，所以起名叫巴西莱。'),
('CNV', '以斯拉记', 15, 2, 62, '这些人查考族谱的记录，却找不着，因此他们算为不洁净，不能作祭司。'),
('CNV', '以斯拉记', 15, 2, 63, '省长告诉他们不可吃至圣之物，直等到有能用乌陵和土明来决疑的祭司兴起来。'),
('CNV', '以斯拉记', 15, 2, 64, '全体会众共有四万二千三百六十人。'),
('CNV', '以斯拉记', 15, 2, 65, '此外，还有他们的仆婢七千三百三十七人；又有男女歌唱者二百人。'),
('CNV', '以斯拉记', 15, 2, 66, '他们有马七百三十六匹，骡子二百四十五匹，'),
('CNV', '以斯拉记', 15, 2, 67, '骆驼四百三十五匹和驴子六千七百二十头。'),
('CNV', '以斯拉记', 15, 2, 68, '当一些族长到达耶路撒冷耶和华殿的原址的时候，就为神的殿甘心献上礼物，要把殿在原址重建起来。'),
('CNV', '以斯拉记', 15, 2, 69, '他们按照自己的力量奉到工程库里的，有金子五百公斤和银子两千八百公斤，以及祭司的礼服一百件。'),
('CNV', '以斯拉记', 15, 2, 70, '于是祭司、利未人、歌唱者、守门的、作殿役的，和一部分人民住在城里；以色列众人都住在自己的城里。'),
('CNV', '以斯拉记', 15, 3, 1, '到了七月，各城里的以色列人，如同一人，都在耶路撒冷聚集。'),
('CNV', '以斯拉记', 15, 3, 2, '约萨达的儿子耶书亚和作祭司的亲族，撒拉铁的儿子所罗巴伯和他的兄弟都起来，建筑以色列神的祭坛，为要照着神人摩西律法书上所写的，在祭坛上献燔祭。'),
('CNV', '以斯拉记', 15, 3, 3, '因为他们惧怕当地的居民，就在殿的原有根基上建立祭坛，在祭坛上向耶和华献燔祭，就是早晚的燔祭。'),
('CNV', '以斯拉记', 15, 3, 4, '他们又按照律法上所记载的守住棚节，每天照着规定的数目献上当天的燔祭。'),
('CNV', '以斯拉记', 15, 3, 5, '另外，又献常献的燔祭、月朔献的燔祭和一切耶和华的圣节所献的燔祭，以及甘心乐意的人向耶和华所献的甘心祭。'),
('CNV', '以斯拉记', 15, 3, 6, '从七月一日起，他们就开始向耶和华献燔祭，但是那时耶和华的殿还没有立定根基，'),
('CNV', '以斯拉记', 15, 3, 7, '他们把银子给石匠和木匠，把食物、饮料和油给西顿人和推罗人，叫他们照着波斯王古列所允许的，把香柏木从黎巴嫩经海运送到约帕。'),
('CNV', '以斯拉记', 15, 3, 8, '众人来到耶路撒冷神的殿以后，第二年二月，撒拉铁的儿子所罗巴伯、约萨达的儿子耶书亚和他们其余的兄弟，就是祭司、利未人和所有从被掳之地回到耶路撒冷的人，就开始动工建造；又委派二十岁以上的利未人，监督耶和华殿的工程。'),
('CNV', '以斯拉记', 15, 3, 9, '耶书亚和他的儿子及兄弟，甲篾和他的儿子，就是何达威雅的子孙（“何达威雅的子孙”或译：“犹大人”），同心协力监督建造神殿的工人，有利未人希拿达的儿子和兄弟协助他们。'),
('CNV', '以斯拉记', 15, 3, 10, '建筑工人奠立耶和华殿根基的时候，祭司都穿上礼服，拿着号筒，亚萨子孙的利未人，都拿着响钹，站在自己的位置，按照以色列王大卫所定的仪式赞美耶和华。'),
('CNV', '以斯拉记', 15, 3, 11, '他们赞美和称谢，向耶和华歌唱，说：“耶和华是至善的，他向以色列人所施的慈爱永远长存。”他们赞美耶和华的时候，众人都大声呼喊，因为耶和华殿的根基已经奠定。'),
('CNV', '以斯拉记', 15, 3, 12, '很多年老的祭司、利未人和族长，曾经见过先前的殿，眼见这殿的根基再次奠立，就放声大哭，但也有许多人高声欢呼，'),
('CNV', '以斯拉记', 15, 3, 13, '以致分不清到底是欢呼声或哭声。因为众人都大声呼喊，这声音在很远的地方也可以听见。'),
('CNV', '以斯拉记', 15, 4, 1, '犹大和便雅悯的敌人听见被掳回来的人为耶和华以色列的神重建圣殿，'),
('CNV', '以斯拉记', 15, 4, 2, '就前来见所罗巴伯和众族长，对他们说：“请让我们与你们一起建造吧！因为我们也像你们那样寻求你们的神。自从亚述王以撒哈顿把我们带上这里的日子以来，我们一直向他献祭。”'),
('CNV', '以斯拉记', 15, 4, 3, '但所罗巴伯、耶书亚和以色列其余的族长对他们说：“你们不能与我们一同建筑神的殿，因为波斯王古列王吩咐我们自己为耶和华以色列的神建殿。”'),
('CNV', '以斯拉记', 15, 4, 4, '于是那地方的居民使犹大人的手发软，惊扰他们的建筑工程。'),
('CNV', '以斯拉记', 15, 4, 5, '又在波斯王古列的日子，直到波斯王大利乌在位的时候，常常贿买参谋，来敌对犹大人，要破坏他们的建殿计划。'),
('CNV', '以斯拉记', 15, 4, 6, '亚哈随鲁在位的初期，他们写了诉状，控告犹大和耶路撒冷的居民。'),
('CNV', '以斯拉记', 15, 4, 7, '在亚达薛西年间，比施兰、米特利达、他别和其余的同僚，也上书给波斯王亚达薛西，反对耶路撒冷人，奏文是用亚兰文写成，并且翻译了（“并且翻译了”指为亚达薛西王翻译为波斯文字；参18节）。下面是亚兰文：'),
('CNV', '以斯拉记', 15, 4, 8, '省长利宏和秘书伸帅写奏本给亚达薛西王，控告耶路撒冷。奏文如下：'),
('CNV', '以斯拉记', 15, 4, 9, '省长利宏、秘书伸帅和他们其余的同僚：法官、钦差、议员、官长（“法官、钦差、议员、官长”或译：“底拿人、亚法萨提迦人、他毗拉人、亚法撒人”），亚基卫人、巴比伦人、书珊人，就是以拦人，'),
('CNV', '以斯拉记', 15, 4, 10, '还有伟大尊贵的亚斯那巴掳来安置在撒玛利亚城和河西那边其余地方的居民，呈上奏文。'),
('CNV', '以斯拉记', 15, 4, 11, '这就是他们呈给亚达薛西王的奏文副本：“你的臣仆，就是河西那边的人，上奏亚达薛西王：'),
('CNV', '以斯拉记', 15, 4, 12, '奏知大王：从你那里上到我们这里来的犹大人，已经到了耶路撒冷这座叛逆和邪恶的城；他们进行建造，并且已经修好根基，开始建造城墙。'),
('CNV', '以斯拉记', 15, 4, 13, '现在奏知大王：如果这城建成，墙垣筑好，他们就不再缴税、进贡和纳粮，王的国库收入必定受损。'),
('CNV', '以斯拉记', 15, 4, 14, '现在我们既食王家的盐，不该见王受剥夺，因此上奏禀告王，'),
('CNV', '以斯拉记', 15, 4, 15, '请王查考先王的记录，从记录中查知这城是叛逆的城，对列王和各省都有损害，自古以来，城中常有造反的事，因此这城被拆毁。'),
('CNV', '以斯拉记', 15, 4, 16, '我们告知王，如果这城建成，墙垣筑好，河西那边的地方就不再是王的了。”'),
('CNV', '以斯拉记', 15, 4, 17, '王把谕旨送交省长利宏、秘书伸帅，以及其余住在撒玛利亚和河西的同僚，说：“愿你们平安。'),
('CNV', '以斯拉记', 15, 4, 18, '你们呈给我们的奏本已经在我面前翻译和诵读了。'),
('CNV', '以斯拉记', 15, 4, 19, '我下令考查，发现这城自古以来反叛列王，城中常有造反叛乱的事。'),
('CNV', '以斯拉记', 15, 4, 20, '从前大能的君王统治耶路撒冷，治理河西那边的全地，接受他们缴税、进贡和纳粮。'),
('CNV', '以斯拉记', 15, 4, 21, '现在你们要下令叫这些人停工，不得重建这城，等候我的谕令。'),
('CNV', '以斯拉记', 15, 4, 22, '你们要留心，不可疏忽这事，使王的亏损增加。”'),
('CNV', '以斯拉记', 15, 4, 23, '当亚达薛西王谕旨的副本在利宏和秘书伸帅，以及他们的同僚面前宣读出来以后，他们就急忙去耶路撒冷到犹大人那里，用武力强迫他们停工。'),
('CNV', '以斯拉记', 15, 4, 24, '所以，在耶路撒冷的神殿的工程就停止了，直到波斯王大利乌在位的第二年。'),
('CNV', '以斯拉记', 15, 5, 1, '那时，哈该先知和易多的儿子撒迦利亚先知奉以色列神的名，向在犹大地和耶路撒冷的犹大人传讲信息。'),
('CNV', '以斯拉记', 15, 5, 2, '于是，撒拉铁的儿子所罗巴伯和约萨达的儿子耶书亚都起来，开始重建在耶路撒冷的神的殿，神的先知们和他们在一起，帮助他们。'),
('CNV', '以斯拉记', 15, 5, 3, '当时，河西那边的总督达乃和示他．波斯乃，以及他们的同僚来到他们那里，这样问他们说：“谁下令叫你们重建这殿，完成这工程呢？”'),
('CNV', '以斯拉记', 15, 5, 4, '他们又这样问：“负责这建筑工程的人叫什么名字？”'),
('CNV', '以斯拉记', 15, 5, 5, '但是神的眼目看顾犹大人的长老，以致总督等人没有阻止他们建造；直到这事奏告大利乌王，得着有关这事的回谕为止。'),
('CNV', '以斯拉记', 15, 5, 6, '这就是河西那边的省长达乃和示他．波斯乃，以及他们的同僚，就是在河西那边的亚法萨迦人，呈给大利乌王的奏文副本。'),
('CNV', '以斯拉记', 15, 5, 7, '他们在呈给王的奏文中这样写：“愿大利乌王万事平安。'),
('CNV', '以斯拉记', 15, 5, 8, '奏知大王：我们去过这犹大省，到了伟大神的殿，见殿正用光滑石块修建，梁木插入墙内；这工程在他们手里进行得审慎而迅速。'),
('CNV', '以斯拉记', 15, 5, 9, '于是，我们就这样问那些长老，对他们说：‘谁下令叫你们重建这殿，完成这工程呢？’'),
('CNV', '以斯拉记', 15, 5, 10, '为了奏知大王，就问他们的名字，记录他们首领的名。'),
('CNV', '以斯拉记', 15, 5, 11, '他们这样答覆我们，说：‘我们是天地之神的仆人，正在重建这多年以前已经建好的殿，就是一位以色列伟大的君王所建成的。'),
('CNV', '以斯拉记', 15, 5, 12, '但因为我们的祖先激怒了天上的神，神就把他们交在迦勒底人巴比伦王尼布甲尼撒的手中；尼布甲尼撒就拆毁这殿，把人民掳到巴比伦去。'),
('CNV', '以斯拉记', 15, 5, 13, '然而在巴比伦王古列元年，古列王下令重建这神的殿。'),
('CNV', '以斯拉记', 15, 5, 14, '至于从前尼布甲尼撒从耶路撒冷的殿里掠夺，带到巴比伦庙里的神殿中的金银器皿，古列王也从巴比伦的庙中拿出来，把它们交给一位名叫设巴萨的人，委任他为总督。'),
('CNV', '以斯拉记', 15, 5, 15, '又吩咐他说：把这些器皿带去，存放在耶路撒冷的殿中；使神的殿在原来的地方重建起来。'),
('CNV', '以斯拉记', 15, 5, 16, '于是，这设巴萨回来，奠立了在耶路撒冷神的殿的根基；从那时起，到现在一直在建造，还没有完成。’'),
('CNV', '以斯拉记', 15, 5, 17, '现在王若是以为好，就请查考王在巴比伦的库房，看看那里有没有古列王下令，重建这在耶路撒冷神的殿的谕旨，并请指示我们王对这事的旨意。”'),
('CNV', '以斯拉记', 15, 6, 1, '于是，大利乌王下令考查在巴比伦库房的档案，'),
('CNV', '以斯拉记', 15, 6, 2, '在玛代省的亚马他宫中，发现了一卷书卷。其中写着这样的一段记录：'),
('CNV', '以斯拉记', 15, 6, 3, '“古列王元年，古列王颁发有关在耶路撒冷神的殿的命令，要把这殿重建起来，作献祭的地方；要奠立殿的根基。殿高二十七公尺，宽二十七公尺。'),
('CNV', '以斯拉记', 15, 6, 4, '三层光滑石块，一层新木头，所有费用由王库支付。'),
('CNV', '以斯拉记', 15, 6, 5, '至于从前尼布甲尼撒从耶路撒冷的殿里掠夺，带到巴比伦的神殿中的金银器皿，都要归还，送到耶路撒冷的殿，各按原来的地方放在神的殿中。”'),
('CNV', '以斯拉记', 15, 6, 6, '于是大利乌王下令说：“现在，河西那边的总督达乃和示他．波斯乃，以及你们的同僚，就是在河西那边的亚法萨迦人，你们要远离那里；'),
('CNV', '以斯拉记', 15, 6, 7, '不要干涉这神殿的工程，让犹大人的总督和犹大人的长老在原来的地方重建神的这殿。'),
('CNV', '以斯拉记', 15, 6, 8, '我又下令你要协助这些犹大人的长老重建神的殿，你要作这事：从河西那边交给王库的税收中，拨出充足的经费给他们，免得工程停顿。'),
('CNV', '以斯拉记', 15, 6, 9, '他们需用的什么东西，包括作燔祭献给天上神的公牛犊、公绵羊和绵羊羔；还有麦子、盐、酒和油，都要照着在耶路撒冷的祭司们所说，天天供给他们，不可疏忽，'),
('CNV', '以斯拉记', 15, 6, 10, '好让他们可以献馨香的祭给天上的神，为王和王的子孙祈求长寿。'),
('CNV', '以斯拉记', 15, 6, 11, '我又下令：无论什么人更改这命令，就要从他的房屋中拆出一根梁木，把他挂起，钉在木上；又使他的房屋成为粪堆。'),
('CNV', '以斯拉记', 15, 6, 12, '愿那使自己的名居住在那里的神，毁灭所有伸手更改这命令，或要毁坏这在耶路撒冷神的殿的君王和人民。我大利乌下令，必须彻底遵行。”'),
('CNV', '以斯拉记', 15, 6, 13, '于是河西那边的总督达乃、示他．波斯乃和他们的同僚，彻底遵照大利乌王的指示。'),
('CNV', '以斯拉记', 15, 6, 14, '犹大人的长老因着哈该先知和易多的孙子撒迦利亚的信息，迅速重建。他们遵照以色列神的命令，波斯王古列、大利乌和亚达薛西的命令，完成重建圣殿的工作。'),
('CNV', '以斯拉记', 15, 6, 15, '这殿在大利乌王在位的第六年亚达月初三日，完成了。'),
('CNV', '以斯拉记', 15, 6, 16, '以色列祭司和利未人，以及其余被掳归回的人都欢欢喜喜举行奉献这神殿的典礼。'),
('CNV', '以斯拉记', 15, 6, 17, '在奉献这神殿的典礼中，他们献上公牛一百头、公绵羊二百只、绵羊羔四百只；又照着以色列支派的数目献上公山羊十二只，作全以色列的赎罪祭。'),
('CNV', '以斯拉记', 15, 6, 18, '他们又照着摩西书上所写，委派祭司按着编制，利未人按着班次，在耶路撒冷神的殿中事奉。'),
('CNV', '以斯拉记', 15, 6, 19, '正月十四日，被掳归回的人守逾越节。'),
('CNV', '以斯拉记', 15, 6, 20, '祭司和利未人一起行洁净仪式，他们就全都洁净了；于是利未人为所有被掳归回的人和他们作祭司的众亲族，以及他们自己，宰杀了逾越节的羊羔。'),
('CNV', '以斯拉记', 15, 6, 21, '被掳归回的以色列人和所有脱离当地民族的污秽的人，一同吃这羊羔，寻求耶和华以色列的神。'),
('CNV', '以斯拉记', 15, 6, 22, '他们欢欢喜喜地守除酵节七天，因为耶和华使他们欢喜，又使亚述王的心转向他们，坚固他们的手作以色列神殿的工程。'),
('CNV', '以斯拉记', 15, 7, 1, '这些事以后，波斯王亚达薛西在位的时候，有位以斯拉，是西莱雅的儿子，西莱雅是亚撒利雅的儿子，亚撒利雅是希勒家的儿子，'),
('CNV', '以斯拉记', 15, 7, 2, '希勒家是沙龙的儿子，沙龙是撒督的儿子，撒督是亚希突的儿子，'),
('CNV', '以斯拉记', 15, 7, 3, '亚希突是亚玛利雅的儿子，亚玛利雅是亚撒利雅的儿子，亚撒利雅是米拉约的儿子，'),
('CNV', '以斯拉记', 15, 7, 4, '米拉约是西拉希雅的儿子，西拉希雅是乌西的儿子，乌西是布基的儿子，'),
('CNV', '以斯拉记', 15, 7, 5, '布基是亚比书的儿子，亚比书是非尼哈的儿子，非尼哈是以利亚撒的儿子，以利亚撒是大祭司亚伦的儿子。'),
('CNV', '以斯拉记', 15, 7, 6, '这位以斯拉是一位经学家，精通耶和华以色列的神赐给摩西的律法；因为耶和华他神的手帮助他，所以王赐他所求的一切，他就从巴比伦上来。'),
('CNV', '以斯拉记', 15, 7, 7, '在亚达薛西王第七年，一些以色列人和一些祭司、利未人、歌唱的、守门的和作殿役的，和他一起上耶路撒冷去。'),
('CNV', '以斯拉记', 15, 7, 8, '王第七年五月来到耶路撒冷。'),
('CNV', '以斯拉记', 15, 7, 9, '正月初一，以斯拉开始从巴比伦上来；五月初一来到耶路撒冷，他神施恩的手帮助他，'),
('CNV', '以斯拉记', 15, 7, 10, '因为以斯拉专心寻求研究耶和华的律法，并且遵行，在以色列中教导律例和典章。'),
('CNV', '以斯拉记', 15, 7, 11, '亚达薛西王颁发谕旨给以斯拉；以斯拉是一位祭司和经学家，精通耶和华的诫命和赐给以色列之律例；谕旨内容是这样：'),
('CNV', '以斯拉记', 15, 7, 12, '“诸王之王亚达薛西赐谕旨给以斯拉祭司，精通天上神律法的经学家，愿你平安。'),
('CNV', '以斯拉记', 15, 7, 13, '现在我下令：住在我国中的以色列人中，愿意上到耶路撒冷去的祭司和利未人，他们都可以与你同去。'),
('CNV', '以斯拉记', 15, 7, 14, '你既然是王和他七位顾问所派去的，就要照着你手中神的律法书，查察犹大和耶路撒冷的情况。'),
('CNV', '以斯拉记', 15, 7, 15, '你要把王和他顾问甘心献的金银带去，奉献给住在耶路撒冷之以色列的神；'),
('CNV', '以斯拉记', 15, 7, 16, '也要带着你在巴比伦全省所得的金银，连同人民和祭司甘心乐意献给在耶路撒冷神的殿的礼物，'),
('CNV', '以斯拉记', 15, 7, 17, '使你可以用这些银子审慎地购买公牛、公绵羊、绵羊羔，以及与祭牲同献的素祭和奠祭，献在耶路撒冷你们神的殿的祭坛上。'),
('CNV', '以斯拉记', 15, 7, 18, '剩余的金银，你和你的族人看怎么办好，就怎么用；只要照着你们神的旨意去作就是了。'),
('CNV', '以斯拉记', 15, 7, 19, '至于交给你为你神殿中事奉用的器皿，你要放在耶路撒冷的神面前。'),
('CNV', '以斯拉记', 15, 7, 20, '如果你需要支付你神的殿其余的费用，你可以从王的库房里支付。'),
('CNV', '以斯拉记', 15, 7, 21, '我亚达薛西王下令给在河西那边所有的库官：无论以斯拉祭司，这位精通天上神律法的经学家，向你们要求什么，你们都要审慎照办。'),
('CNV', '以斯拉记', 15, 7, 22, '他可以要银子三千四百公斤，麦子一百公斤，酒二千二百公升，油二千二百公升，盐却不受限制。'),
('CNV', '以斯拉记', 15, 7, 23, '天上的神命令的，就要为天上神的殿热心去作，免得忿怒临到王和王的子孙的国。'),
('CNV', '以斯拉记', 15, 7, 24, '我要你们知道，凡是祭司、利未人、歌唱的、守门的，作殿役的和在这神的殿里作仆人的，都不可以向他们征收税款、贡物和粮食。'),
('CNV', '以斯拉记', 15, 7, 25, '至于你以斯拉，你要照着你手中神的智慧书，委任法官和官吏，治理在河西那边所有明白你神的律法的人民，那些不晓得律法的人，你要教导他们。'),
('CNV', '以斯拉记', 15, 7, 26, '不遵守你神的律法和王的律法的，就要审慎地判决处分，或是处死、或是放逐、或是没收家产、或是囚禁。”'),
('CNV', '以斯拉记', 15, 7, 27, '以斯拉说：“耶和华我们列祖的神是应该称颂的，因为他把这样的意念放在君王的心里，使他修饰那在耶路撒冷的耶和华的殿；'),
('CNV', '以斯拉记', 15, 7, 28, '又使我在王和谋士，以及王手下有权势的领袖面前蒙恩。因为耶和华我神的手帮助我，我就有勇气，召集以色列中一些首领，与我一同上来。”'),
('CNV', '以斯拉记', 15, 8, 1, '“亚达薛西王在位的时候，与我从巴比伦一同上来的人，他们的族长和他们的族谱记载如下：'),
('CNV', '以斯拉记', 15, 8, 2, '属非尼哈的子孙有革顺，属以他玛的子孙有但以理，属大卫的子孙有哈突，'),
('CNV', '以斯拉记', 15, 8, 3, '属示迦尼的子孙，就是属巴录的子孙有撒迦利亚，与他一起登记在族谱里的男丁有一百五十人。'),
('CNV', '以斯拉记', 15, 8, 4, '属巴哈．摩押的子孙有西拉希雅的儿子以利约乃，与他在一起的男丁有二百人。'),
('CNV', '以斯拉记', 15, 8, 5, '属示迦尼的子孙有雅哈悉的儿子（《七十士译本》作“属萨土的子孙有雅哈悉的儿子示迦尼”），与他在一起的男丁有三百人。'),
('CNV', '以斯拉记', 15, 8, 6, '属亚丁的子孙有约拿单的儿子以别，与他在一起的男丁有五十人。'),
('CNV', '以斯拉记', 15, 8, 7, '属以拦的子孙有亚他利雅的儿子耶筛亚，与他在一起的男丁有七十人。'),
('CNV', '以斯拉记', 15, 8, 8, '属示法提雅的子孙有米迦勒的儿子西巴第雅，与他在一起的男丁有八十人。'),
('CNV', '以斯拉记', 15, 8, 9, '属约押的子孙有耶歇的儿子俄巴底亚，与他在一起的男丁有二百一十八人。'),
('CNV', '以斯拉记', 15, 8, 10, '属示罗密的子孙有约细斐的儿子（《七十士译本》作“属巴尼的子孙有约细斐的儿子示罗密”），与他在一起的男丁有一百六十人。'),
('CNV', '以斯拉记', 15, 8, 11, '属比拜的子孙有比拜的儿子撒迦利亚，与他在一起的男丁有二十八人。'),
('CNV', '以斯拉记', 15, 8, 12, '属押甲的子孙有哈加坦的儿子约哈难，与他在一起的男丁有一百一十人。'),
('CNV', '以斯拉记', 15, 8, 13, '属亚多尼干的子孙，就是最后的，他们的名字是：以利法列、耶利和示玛雅，与他们在一起的男丁有六十人。'),
('CNV', '以斯拉记', 15, 8, 14, '属比革瓦伊的子孙有乌太和撒布，与他们在一起的男丁有七十人。'),
('CNV', '以斯拉记', 15, 8, 15, '“我召集他们到那条流往亚哈瓦的河边；我们在那里安营住了三天。当我视察民众和祭司的时候，发现没有利未人在那里。'),
('CNV', '以斯拉记', 15, 8, 16, '于是我把首领以利以谢、亚列、示玛雅、以利拿单、雅立、以利拿单、拿单、撒迦利亚和米书兰召来，也把有学问的教师约雅立和以利拿单召来，'),
('CNV', '以斯拉记', 15, 8, 17, '差派他们到迦西斐雅的地方那里去见首领易多，又把他们在迦西斐雅的地方，对易多和他作殿役的亲族所当说的话都告诉他们，请他们为我们神的殿打发仆人到我们这里来。'),
('CNV', '以斯拉记', 15, 8, 18, '因为我们神施恩的手帮助我们，他们就从以色列的曾孙、利未的孙子、抹利的子孙中带一个敏悟的人到我们这里来；还有示利比和他的儿子，以及他们的兄弟，共十八人。'),
('CNV', '以斯拉记', 15, 8, 19, '又有哈沙比雅和与他在一起的米拉利的子孙耶筛亚，以及他的兄弟和他们的儿子共二十人。'),
('CNV', '以斯拉记', 15, 8, 20, '还有从前大卫和众领袖分派去服事利未人的殿役中，带来了二百二十人，全都是按名呼召的。'),
('CNV', '以斯拉记', 15, 8, 21, '“那时，我在亚哈瓦河边那里宣告禁食，为要在我们的神面前谦卑下来，为自己和我们的孩子，以及我们所有的财物寻求神指示一条畅通的道路。'),
('CNV', '以斯拉记', 15, 8, 22, '我羞于请求王派遣步兵和马兵帮助我们抵御路上的仇敌，因为我们曾告诉王说：‘我们神的手必帮助所有寻求他的人，赐福给他们，但他的能力和忿怒必攻击所有离弃他的人。’'),
('CNV', '以斯拉记', 15, 8, 23, '所以我们禁食，寻求我们的神，他就应允我们。'),
('CNV', '以斯拉记', 15, 8, 24, '“我从祭司首领中选派了十二人，以及示利比、哈沙比雅和与他们在一起的十位兄弟，'),
('CNV', '以斯拉记', 15, 8, 25, '把金子、银子和器皿，就是王和他的谋士、领袖，以及在那里的以色列众人献给我们神殿的礼物，都称了交给他们。'),
('CNV', '以斯拉记', 15, 8, 26, '我称了交在他们手中的银子，有二十二公吨，银器重三千四百公斤、金子三千四百公斤。'),
('CNV', '以斯拉记', 15, 8, 27, '金碗二十个，价值八公斤半；上好而发亮的铜器两个，像黄金那样宝贵。'),
('CNV', '以斯拉记', 15, 8, 28, '“我对他们说：‘你们是归耶和华为圣的，器皿也是神圣的，金银是甘心献给耶和华你们列祖的神的礼物。'),
('CNV', '以斯拉记', 15, 8, 29, '你们要谨慎看守，直到你们在耶路撒冷耶和华殿的库房里，在祭司长和利未人的领袖，以及以色列人的族长面前，过了秤。’'),
('CNV', '以斯拉记', 15, 8, 30, '于是祭司和利未人把称过了的金银和器皿收下，带到耶路撒冷我们神的殿里。'),
('CNV', '以斯拉记', 15, 8, 31, '“正月十二日，我们从亚哈瓦河启程，往耶路撒冷去。我们的神的手保佑我们，拯救我们脱离仇敌和在路上埋伏的人的手。'),
('CNV', '以斯拉记', 15, 8, 32, '我们到了耶路撒冷，在那里住了三天；'),
('CNV', '以斯拉记', 15, 8, 33, '第四天，在我们神的殿里，金银和器皿都过了秤，交在乌利亚祭司的儿子米利末的手中；与他在一起的有非尼哈的儿子以利亚撒；与他们在一起的还有利未人耶书亚的儿子约撒拔和宾内的儿子挪亚底。'),
('CNV', '以斯拉记', 15, 8, 34, '一切物品按着数目称过；同时每件的重量都记录下来。'),
('CNV', '以斯拉记', 15, 8, 35, '“那时，从被掳归回的人都向以色列的神献燔祭，就是为全以色列献公牛十二头、公绵羊九十六只、绵羊羔七十七只；又献公山羊十二只作赎罪祭；这一切都是献给耶和华的燔祭。'),
('CNV', '以斯拉记', 15, 8, 36, '他们把王的命令交给王的总督和河西那边的省长，他们就帮助民众和神殿的需要。”'),
('CNV', '以斯拉记', 15, 9, 1, '“完成这些事以后，众领袖前来见我，说：‘以色列民、祭司和利未人没有从当地的民族中分别出来，他们随从迦南人、赫人、比利洗人、耶布斯人、亚扪人、摩押人、埃及人和亚摩利人行可憎的事。'),
('CNV', '以斯拉记', 15, 9, 2, '他们为自己和自己的儿子娶了这些外族的女子为妻，以致圣洁的种族与当地的民族混杂了；而领袖和官长竟是这不忠的事的罪魁。’'),
('CNV', '以斯拉记', 15, 9, 3, '我一听见这事，就撕裂我的衣服和外袍，拔掉头上的头发和胡须，惊惧地坐着。'),
('CNV', '以斯拉记', 15, 9, 4, '所有因着以色列神针对被掳归回的人之不忠、对他们所说的话而战兢的人，都聚集到我面前。我惊惧地坐着，直到献晚祭的时候。'),
('CNV', '以斯拉记', 15, 9, 5, '“献晚祭的时候，我在禁食中起来，穿着撕裂了的衣服和外袍，双膝跪下，向耶和华我的神张开双手，'),
('CNV', '以斯拉记', 15, 9, 6, '祷告说：‘我的神啊，我感觉羞耻惭愧，不敢向我的神你仰面；因为我们的罪孽多至灭顶，我们的罪过滔天。'),
('CNV', '以斯拉记', 15, 9, 7, '从我们列祖的日子直到今日，我们罪恶深重，由于我们的罪孽，我们和我们的王，以及祭司，都被交在各地的列王手中：被刀杀、被掳掠、被抢夺，丢脸蒙羞，就像今天的光景一样。'),
('CNV', '以斯拉记', 15, 9, 8, '现在，耶和华我们的神恩待我们片时，给我们存留一些逃脱的人，使我们像钉子钉在他的圣所那样的安稳，让我们的神光照我们的眼睛，使我们在所受的奴役中稍得复兴。'),
('CNV', '以斯拉记', 15, 9, 9, '虽然我们是奴隶，但在奴役中，我们的神仍然没有撇弃我们，反而使我们在波斯列王面前得蒙恩惠，使我们复兴，建立我们神的殿，重修毁坏的地方，使我们在犹大和耶路撒冷有墙垣。'),
('CNV', '以斯拉记', 15, 9, 10, '我们的神啊，现在，我们还可以说什么呢？只能说：我们又离弃了你的诫命，'),
('CNV', '以斯拉记', 15, 9, 11, '就是你曾藉着你的仆人众先知所吩咐的。你说：你们进去要得为业之地是污秽的，充满了当地民族的污秽，他们可憎的事使这地从这边到那边都充满了他们的不洁。'),
('CNV', '以斯拉记', 15, 9, 12, '所以，你们不可把你们的女儿嫁给他们的儿子，也不可为你们的儿子娶他们的女儿。你们永远不可寻求他们的平安和他们的利益；这样，你们就可以强盛，吃这地的美物，把这地留给你们的子孙作产业，直到永远。'),
('CNV', '以斯拉记', 15, 9, 13, '虽然因着我们许多的恶行和重大的罪过，这一切就临到我们身上，但我们的神啊，你惩罚我们实在轻于我们的罪孽所应得的，还给我们留下这些逃脱的人。'),
('CNV', '以斯拉记', 15, 9, 14, '我们怎可以再违背你的诫命，与这些行可憎事的民族通婚呢？如果我们这样行，你岂不向我们发怒，消灭我们，以致没有一个剩余，或是逃脱的人吗？'),
('CNV', '以斯拉记', 15, 9, 15, '耶和华以色列的神啊，你是公义的！我们现今才可以留下，成为逃脱的人。看哪，我们在你面前是有罪过的，因此没有人能在你面前站立得住。’”'),
('CNV', '以斯拉记', 15, 10, 1, '以斯拉祷告、认罪、哭泣，俯伏在神的殿前的时候，有一大群以色列人，包括男女小孩，在他面前聚集；众人也都痛哭。'),
('CNV', '以斯拉记', 15, 10, 2, '属以拦的子孙、耶歇的儿子示迦尼对以斯拉说：“我们对神不忠，娶了这地这外族女子为妻。虽然这样，以色列现在还有希望。'),
('CNV', '以斯拉记', 15, 10, 3, '现在，我们应当与我们的神立约，按着我主和那些因我们神的诫命而战兢的人所议定的，照着律法而行，送走这些妻子和她们所生的儿女。'),
('CNV', '以斯拉记', 15, 10, 4, '你起来！因为这事全在你身上，我们支持你，你当坚强地去作。”'),
('CNV', '以斯拉记', 15, 10, 5, '于是以斯拉起来，使祭司首领、利未人和以色列众人起誓要照着这话去行；他们就起誓。'),
('CNV', '以斯拉记', 15, 10, 6, '以斯拉就从神的殿前起来，走进以利亚实的儿子约哈难的屋里去；他在那里不吃饭，也不喝水，因为他为了被掳归回的人的不忠而悲伤。'),
('CNV', '以斯拉记', 15, 10, 7, '于是，领袖们就在犹大和耶路撒冷向所有被掳归回的人发出通告，叫他们到耶路撒冷聚集。'),
('CNV', '以斯拉记', 15, 10, 8, '所有不照着众领袖和众长老所议定，在三日之内来到的人，所有的财物都要充公，也要从被掳归回之人的会中被逐出。'),
('CNV', '以斯拉记', 15, 10, 9, '于是犹大和便雅悯众人，三日之内都在耶路撒冷聚集，那时是九月二十日，众人坐在神殿的广场上；因为这事，又因为天下大雨的缘故，大家就都战栗发抖。'),
('CNV', '以斯拉记', 15, 10, 10, '以斯拉祭司站起来，对他们说：“你们对神不忠，娶了外族的女子为妻，增添了以色列的罪过。'),
('CNV', '以斯拉记', 15, 10, 11, '现在你们要向耶和华你们列祖的神认罪，遵行他所喜悦的旨意，与这地的民族和外族的女子分离。”'),
('CNV', '以斯拉记', 15, 10, 12, '全体会众都大声回答说：“你怎么说，我们就怎么行。'),
('CNV', '以斯拉记', 15, 10, 13, '可是人太多，又逢下大雨的季节，我们不能停留在外面；这又不是一两天可以完成的事，因为我们很多人在这事上犯了罪！'),
('CNV', '以斯拉记', 15, 10, 14, '让我们的领袖代表全体会众站在耶和华面前，所有在我们的城中娶了外族女子为妻的人，也都要在指定的日期，与本城的长老和审判官一起来，解决了这事，好使神因这事所发的烈怒离开我们。”'),
('CNV', '以斯拉记', 15, 10, 15, '只有亚撒黑的儿子约拿单和特瓦的儿子雅哈谢起来反对这提议，还有米书兰和利未人沙比太支持他们。'),
('CNV', '以斯拉记', 15, 10, 16, '于是，被掳归回的人就这样行。以斯拉祭司提名选派了一些人，是各宗族的族长，于十月初一他们一同坐下来查办这事。'),
('CNV', '以斯拉记', 15, 10, 17, '直到正月初一，他们才完成审查所有娶了外族的女子为妻的人。'),
('CNV', '以斯拉记', 15, 10, 18, '在祭司子孙中，娶了外族的女子为妻的有耶书亚的子孙，约萨达的儿子和他的兄弟玛西雅、以利以谢、雅立、基大利。'),
('CNV', '以斯拉记', 15, 10, 19, '他们举手起誓要送走他们的妻子，并献赎罪祭。他们就献上一只公绵羊，作他们的赎罪祭。'),
('CNV', '以斯拉记', 15, 10, 20, '音麦的子孙中，有哈拿尼和西巴第雅。'),
('CNV', '以斯拉记', 15, 10, 21, '哈琳的子孙中，有玛西雅、以利雅、示玛雅、耶歇和乌西雅。'),
('CNV', '以斯拉记', 15, 10, 22, '巴施户珥的子孙中，有以利约乃、玛西雅、以实玛利、拿坦业、约撒拔和以利亚撒。'),
('CNV', '以斯拉记', 15, 10, 23, '利未人中有约撒拔、示每、基拉雅（又叫基利他），还有毗他希雅、犹大和以利以谢。'),
('CNV', '以斯拉记', 15, 10, 24, '歌唱者中，有以利亚实。守门的人中，有沙龙、提联和乌利。'),
('CNV', '以斯拉记', 15, 10, 25, '属以色列人的巴录的子孙中，有拉米、耶西雅、玛基雅、米雅民、以利亚撒、玛基雅、比拿雅。'),
('CNV', '以斯拉记', 15, 10, 26, '以拦的子孙中，有玛他尼、撒迦利亚、耶歇、押底、耶利末和以利雅。'),
('CNV', '以斯拉记', 15, 10, 27, '萨土的子孙中，有以利约乃、以利亚实、玛他尼、耶利末、撒拔和亚西撒。'),
('CNV', '以斯拉记', 15, 10, 28, '比拜的子孙中，有约哈难、哈拿尼雅、萨拜和亚勒。'),
('CNV', '以斯拉记', 15, 10, 29, '巴尼的子孙中，有米书兰、玛鹿、亚大雅、雅述、示押和耶利末。'),
('CNV', '以斯拉记', 15, 10, 30, '巴哈．摩押的子孙中，有阿底拿、基拉、比拿雅、玛西雅、玛他尼、比撒列、宾内和玛拿西。'),
('CNV', '以斯拉记', 15, 10, 31, '哈琳的子孙中，有以利以谢、伊示雅、玛基雅、示玛雅、西缅、'),
('CNV', '以斯拉记', 15, 10, 32, '便雅悯、玛鹿和示玛利雅。'),
('CNV', '以斯拉记', 15, 10, 33, '哈顺的子孙中，有玛特乃、玛达他、撒拔、以利法列、耶利买、玛拿西和示每。'),
('CNV', '以斯拉记', 15, 10, 34, '巴尼的子孙中，有玛代、暗兰、乌益、'),
('CNV', '以斯拉记', 15, 10, 35, '比拿雅、比底雅、基禄、'),
('CNV', '以斯拉记', 15, 10, 36, '瓦尼雅、米利末、以利亚实、'),
('CNV', '以斯拉记', 15, 10, 37, '玛他尼、玛特乃、雅扫、'),
('CNV', '以斯拉记', 15, 10, 38, '巴尼、宾内、示每、'),
('CNV', '以斯拉记', 15, 10, 39, '示利米雅、拿单、亚大雅、'),
('CNV', '以斯拉记', 15, 10, 40, '玛拿底拜、沙赛、沙赖、'),
('CNV', '以斯拉记', 15, 10, 41, '亚萨利、示利米雅、示玛利雅、'),
('CNV', '以斯拉记', 15, 10, 42, '沙龙、亚玛利雅、约瑟。'),
('CNV', '以斯拉记', 15, 10, 43, '尼波的子孙中，有耶利、玛他提雅、撒拔、西比拿、雅玳、约珥和比拿雅。'),
('CNV', '以斯拉记', 15, 10, 44, '这些人都娶了外族的女子为妻，但他们都把妻子和儿女送走了（本节经文残缺，意义难确定，或译：“有的妻子也生了儿女”）。'),
('CNV', '尼希米记', 16, 1, 1, '哈迦利亚的儿子尼希米的言行录：亚达薛西王二十年基斯流月，我在书珊宫中，'),
('CNV', '尼希米记', 16, 1, 2, '我的一位兄弟哈拿尼和几个人一起从犹大来到；我询问他们关于那些从被掳逃脱的犹大余民和关于耶路撒冷的景况。'),
('CNV', '尼希米记', 16, 1, 3, '他们对我说：“那些从被掳剩下的余民，在犹大省那里遭遇大患难，受到凌辱。耶路撒冷的城墙倒塌，城门也被火烧毁。”'),
('CNV', '尼希米记', 16, 1, 4, '我听见了这些事，就坐下哭泣，悲伤了好几天，在天上的神面前禁食祷告，'),
('CNV', '尼希米记', 16, 1, 5, '说：“耶和华天上的神，伟大可畏的神啊，你向那些爱你，遵守你诫命的人，守约施慈爱。'),
('CNV', '尼希米记', 16, 1, 6, '求你侧着耳，睁着眼的，垂听你仆人的祷告，我今天在你面前昼夜为着你的仆人以色列人祷告，承认以色列人所犯的罪，就是我与我父的家向你所犯的罪。'),
('CNV', '尼希米记', 16, 1, 7, '我们故意行极大的恶事得罪你，没有遵守你吩咐你仆人摩西的诫命、律例和典章。'),
('CNV', '尼希米记', 16, 1, 8, '求你记念你吩咐你仆人摩西的话，说：‘你们若是不忠，我就把你们分散在万民中。'),
('CNV', '尼希米记', 16, 1, 9, '但如果你们回心转意归向我，谨守遵行我的诫命，即使在你们被赶逐的天边，我也必从那里把他们招聚回来，带他们到我选择给我的名居住的地方那里去。’'),
('CNV', '尼希米记', 16, 1, 10, '这些都是你的仆人，你的子民，是你用你的大能和你强而有力的手所救赎的。'),
('CNV', '尼希米记', 16, 1, 11, '主啊，求你留意听你仆人的祷告，也听那些喜爱敬畏你名的仆人的祷告；求你使你的仆人今天顺利，使他在这人面前蒙怜悯。”那时我是王的酒政。'),
('CNV', '尼希米记', 16, 2, 1, '亚达薛西王二十年尼散月，王面前摆上了酒席，我拿酒来奉给王。我在他面前素来没有露出愁容。'),
('CNV', '尼希米记', 16, 2, 2, '王却问我：“你既然没有病，为什么面带愁容呢？这没有别的可能，必是心中愁烦。”我就非常惧怕，'),
('CNV', '尼希米记', 16, 2, 3, '对王说：“愿王万岁，我列祖坟墓所在的城成了荒芜之地，城门被火焚毁，我怎能不面带愁容呢？”'),
('CNV', '尼希米记', 16, 2, 4, '王问我：“你想要什么呢？”我就向天上的神祷告，'),
('CNV', '尼希米记', 16, 2, 5, '然后对王说：“如果王认为好，仆人能在你面前蒙恩宠，就请你差派我往犹大，到我列祖坟墓所在的城去，让我重建那城。”'),
('CNV', '尼希米记', 16, 2, 6, '那时，王后坐在王的旁边。王问我：“你的行程需时多久？你什么时候回来？”王既然认为好，就差派我去，我也定了一个归期。'),
('CNV', '尼希米记', 16, 2, 7, '我又问王：“王若是认为好，请赐给我诏书，通知河西那边的省长准我经过，直至我到达犹大；'),
('CNV', '尼希米记', 16, 2, 8, '又赐诏书，给看守王的园林的亚萨，吩咐他给我木材，建造圣殿的营楼大门的横梁，以及建造城墙和我要入住的房屋。”因为我的神施恩的手帮助我，王就赐给我这一切。'),
('CNV', '尼希米记', 16, 2, 9, '于是我到了河西那边的省长那里去，把王的诏书交给他们；王又派了军长和马兵护送我。'),
('CNV', '尼希米记', 16, 2, 10, '和伦人参巴拉和作臣仆的亚扪人多比雅听见有人来到，要为以色列求利益，他们就非常恼怒。'),
('CNV', '尼希米记', 16, 2, 11, '我到了耶路撒冷，在那里停留了三天。'),
('CNV', '尼希米记', 16, 2, 12, '我在夜间起来，和几个人一起出去，我没有告诉任何人我的神使我定意要为耶路撒冷作的事，除了我所骑的一头牲口以外，没有带着别的牲口。'),
('CNV', '尼希米记', 16, 2, 13, '我夜间出了谷门，向着龙泉走去，到了粪门，视察耶路撒冷破坏了的城墙和被火焚毁的城门。'),
('CNV', '尼希米记', 16, 2, 14, '我又往前走，到了泉门和王池，因为地方不够让我骑着牲口过去，'),
('CNV', '尼希米记', 16, 2, 15, '我只得在夜间沿溪而上，视察城墙，然后转回，经过谷门，回到城里。'),
('CNV', '尼希米记', 16, 2, 16, '没有一个官长知道我去过什么地方，作了什么事。我也一直没有告诉犹大人、或祭司、或贵胄、或官长，或其余作工的人。'),
('CNV', '尼希米记', 16, 2, 17, '后来我对他们说：“你们都看见我们遭遇的患难：耶路撒冷成了荒芜之地，城门被火焚毁，你们都来吧！让我们重建耶路撒冷的城墙，免得我们再受凌辱。”'),
('CNV', '尼希米记', 16, 2, 18, '我告诉他们，我的神施恩的手怎样帮助我，以及王对我所说的话；他们就说：“我们要起来建造！”于是他们奋勇着手作这善工。'),
('CNV', '尼希米记', 16, 2, 19, '但和伦人参巴拉和作臣仆的亚扪人多比雅，以及阿拉伯人基善听见了，就讥笑我们，藐视我们，说：“你们在干什么？你们要背叛王吗？”'),
('CNV', '尼希米记', 16, 2, 20, '我回答他们说：“天上的神必使我们成功；我们是他的仆人，我们要起来建造，但你们在耶路撒冷无分、无权，无人记念。”'),
('CNV', '尼希米记', 16, 3, 1, '那时，大祭司以利亚实起来，和他一起作祭司的众兄弟都起来，重建了羊门；他们装上门扇，就把它分别为圣，又建造城墙，直到哈米亚城楼和哈楠业城楼，把城分别为圣；'),
('CNV', '尼希米记', 16, 3, 2, '接着的一段由耶利哥人建造；再接着的一段由音利的儿子撒刻建造。'),
('CNV', '尼希米记', 16, 3, 3, '哈西拿的子孙建造鱼门，他们安置横梁，装上门扇、门插和门闩。'),
('CNV', '尼希米记', 16, 3, 4, '接着的一段由哈哥斯的孙子、乌利亚的儿子米利末修筑；再接着的一段由米示萨别的孙子、比利迦的儿子米书兰修筑；再接着的一段由巴拿的儿子撒督修筑。'),
('CNV', '尼希米记', 16, 3, 5, '接着这一段的是由提哥亚人修筑；但是他们的贵族不愿肩负他们的主的工作。'),
('CNV', '尼希米记', 16, 3, 6, '巴西亚的儿子耶何耶大和比所玳的儿子米书兰修筑古门；他们安置横梁，装上门扇、门插和门闩。'),
('CNV', '尼希米记', 16, 3, 7, '接着的一段由基遍人米拉提、米仑人雅顿、基遍人和河西那边省长所管辖的米斯巴人修筑。'),
('CNV', '尼希米记', 16, 3, 8, '再接着的一段由金匠哈海雅的儿子乌薛修筑。接着这一段的是由作香料的哈拿尼雅修筑。他们修葺耶路撒冷的城墙，直到宽墙。'),
('CNV', '尼希米记', 16, 3, 9, '接着的一段由管理半个耶路撒冷的区长，户珥的儿子利法雅修筑。'),
('CNV', '尼希米记', 16, 3, 10, '再接着的一段由哈路抹的儿子耶大雅修筑，就是他自己房屋对面的那段。接着这一段的是由哈沙尼的儿子哈突修筑。'),
('CNV', '尼希米记', 16, 3, 11, '哈琳的儿子玛基雅和巴哈．摩押的儿子哈述修筑另一段城墙和炉楼。'),
('CNV', '尼希米记', 16, 3, 12, '接着的一段由管理半个耶路撒冷的区长哈罗黑的儿子沙龙和他的女儿们修筑。'),
('CNV', '尼希米记', 16, 3, 13, '哈嫩和撒挪亚城的居民修筑谷门。他们重建那门，装上门扇、门插和门闩；又修筑城墙四百四十公尺，直至粪门。'),
('CNV', '尼希米记', 16, 3, 14, '粪门是由管理伯．哈基琳的区长，利甲的儿子玛基雅修筑；他重建那门，装上门扇、门插和门闩。'),
('CNV', '尼希米记', 16, 3, 15, '管理米斯巴的区长各荷西的儿子沙仑修筑泉门。他重建那门，加盖门顶，装上门扇、门插和门闩；又重建靠近王园的西罗亚池的城墙，直到从大卫城下来的台阶。'),
('CNV', '尼希米记', 16, 3, 16, '下一段由管理半个伯．夙的区长，押卜的儿子尼希米修筑，直到大卫墓地的对面，又到人工池和勇士之家。'),
('CNV', '尼希米记', 16, 3, 17, '再下一段由利未人巴尼的儿子利宏修筑；接着的一段由管理半个基伊拉的区长哈沙比雅为他本区修筑。'),
('CNV', '尼希米记', 16, 3, 18, '下一段由他们的兄弟，管理另一半基伊拉的区长，希拿达的儿子宾内（按照《马索拉文本》的大部分抄本，“宾内”作“巴瓦伊”，大概是手民之误；两者在原文非常相似，现参照其他抄本和古译本翻译；参24节）修筑。'),
('CNV', '尼希米记', 16, 3, 19, '管理米斯巴的区长耶书亚的儿子以谢修筑接着的一段，对着军械库的斜坡、城墙转角的地方。'),
('CNV', '尼希米记', 16, 3, 20, '下一段，就是萨拜的儿子巴录竭力修筑的另一段，从城墙转角的地方，直到大祭司以利亚实住宅的门口。'),
('CNV', '尼希米记', 16, 3, 21, '再下一段，就是哈哥斯的孙子、乌利亚的儿子米利末修筑的另一段，从以利亚实住宅的门口，直到以利亚实住宅的尽头。'),
('CNV', '尼希米记', 16, 3, 22, '这一段之后是由住在约旦河平原的祭司修筑。'),
('CNV', '尼希米记', 16, 3, 23, '下一段是由便雅悯和哈述，修筑他们自己房屋对面的那段。再下一段由亚难尼的孙子、玛西雅的儿子亚撒利雅，修筑他自己的房屋旁边的那段。'),
('CNV', '尼希米记', 16, 3, 24, '这一段之后是希拿达的儿子宾内修筑的另一段，从亚撒利雅的房屋，直到城墙的转角，就是城角的地方。'),
('CNV', '尼希米记', 16, 3, 25, '乌赛的儿子巴拉修筑对着城墙的转角的地方，以及王宫突出高耸的城楼靠近护卫院的一段。下一段由巴录的儿子毗大雅修筑。'),
('CNV', '尼希米记', 16, 3, 26, '居住在俄斐勒的殿役，修筑直到东面水门对面和突出的城楼那一段墙。'),
('CNV', '尼希米记', 16, 3, 27, '再下一段，就是由提哥亚人修筑的另一段，从那突出来的大城楼对面，直到俄斐勒的城墙。'),
('CNV', '尼希米记', 16, 3, 28, '从马门往上的一段，祭司们各人修筑自己房屋对面的城墙。'),
('CNV', '尼希米记', 16, 3, 29, '下一段由音麦的儿子撒督修筑自己房屋对面的那段。再下一段由看守东门示迦尼的儿子示玛雅修筑。'),
('CNV', '尼希米记', 16, 3, 30, '这一段之后是由示利米雅的儿子哈拿尼雅和萨拉的第六子哈嫩修筑的另一段，下一段就是比利迦的儿子米书兰修筑自己住宅对面的那一段。'),
('CNV', '尼希米记', 16, 3, 31, '再下一段由金匠玛基雅修筑，直到殿役和商人的房屋，对着哈米弗甲门，直到城的角楼。'),
('CNV', '尼希米记', 16, 3, 32, '金匠和商人修筑城的角楼和羊门之间的那一段。'),
('CNV', '尼希米记', 16, 4, 1, '当参巴拉听见我们正在重建城墙，就很忿怒，非常恼恨，并且讥讽犹大人。'),
('CNV', '尼希米记', 16, 4, 2, '在他的兄弟和撒玛利亚的军队面前，说：“这些软弱的犹大人在作什么呢？想自己修筑城墙吗？想要献祭吗？想要在一天之内完成吗？想要使废土堆中被火烧过的石头复活吗？”'),
('CNV', '尼希米记', 16, 4, 3, '亚扪人多比雅在参巴拉旁边说：“这些人建造的，只要一只狐狸走上去，石墙就崩塌。”'),
('CNV', '尼希米记', 16, 4, 4, '“我们的神啊，求你垂听，我们被藐视，求你使他们的毁谤归到他们头上，使他们在被掳之地成为掠物。'),
('CNV', '尼希米记', 16, 4, 5, '不要遮蔽他们的罪孽，也不要从你面前涂抹他们的罪恶，因为他们在这些建造的人面前惹你发怒。”'),
('CNV', '尼希米记', 16, 4, 6, '这样，我们重建城墙，把全部城墙连接起来，城墙达到一半的高度，因为众人都全心作工。（本章第1~6节《马索拉文本》为3:33~38）'),
('CNV', '尼希米记', 16, 4, 7, '当参巴拉、多比雅、阿拉伯人、亚扪人、亚实突人听见耶路撒冷城墙重修工程仍然进行，已经堵塞城墙的缺口，就非常忿怒。（本节在《马索拉文本》为4:1）'),
('CNV', '尼希米记', 16, 4, 8, '他们就一同计划阴谋要来攻击耶路撒冷，制造混乱。'),
('CNV', '尼希米记', 16, 4, 9, '所以我们向我们的神祷告，又因他们的缘故，设立守卫，日夜防备他们。'),
('CNV', '尼希米记', 16, 4, 10, '犹大人说：“搬运的人气力已经衰弱，但瓦砾仍多，我们不能再建城墙了！”'),
('CNV', '尼希米记', 16, 4, 11, '同时我们的敌人说：“趁着他们不知道，还未看见之前，我们就进入他们中间，杀死他们，使那工程停止。”'),
('CNV', '尼希米记', 16, 4, 12, '住在他们附近的一些犹大人，也曾十次前来通知我们说：“他们将从各方上来攻击你们。”（或译：“他们十次从各方来对我们说：‘你们来到我们这里吧！’”本节颇残缺，意义难确定。）'),
('CNV', '尼希米记', 16, 4, 13, '所以我分派众人站岗，在低洼或高处，在城墙后隐蔽处或空旷的地方，叫他们按着家族，带着刀、枪和弓。'),
('CNV', '尼希米记', 16, 4, 14, '我巡视之后，就起来，对贵族、官长和其余的人民说：“不要怕他们，要记得主是伟大可畏的，要为你们的兄弟、儿女、妻子和你们的家争战。”'),
('CNV', '尼希米记', 16, 4, 15, '我们的仇敌既然听见我们知道了这阴谋，神也破坏了他们的计谋，就不敢来了。我们全都回到城墙那里，各人回到原来的工作岗位。'),
('CNV', '尼希米记', 16, 4, 16, '从那天起，我的仆人一半工作，一半紧握着枪、盾牌、弓和盔甲。众领袖都站在犹大全家的后面。'),
('CNV', '尼希米记', 16, 4, 17, '那些建造城墙，搬运重物的，都是一只手作工，一只手紧握兵器。'),
('CNV', '尼希米记', 16, 4, 18, '建造的人，都腰间佩着刀来建造；吹号角的人在我旁边。'),
('CNV', '尼希米记', 16, 4, 19, '我对贵族、官长和其余的人民说：“这工程浩大，范围广阔；我们在城墙上彼此相隔很远。'),
('CNV', '尼希米记', 16, 4, 20, '所以你们无论在什么地方，一听见号角声，就要集合到我们那里来。我们的神必为我们争战。”'),
('CNV', '尼希米记', 16, 4, 21, '我们就这样作工；一半人紧握着枪，从黎明直到星宿出现的时候。'),
('CNV', '尼希米记', 16, 4, 22, '那时，我又对众人说：“各人和他的仆人都要在耶路撒冷城中过夜，这样他们可以在夜间作我们的守卫，日间工作。”'),
('CNV', '尼希米记', 16, 4, 23, '这样，我与我的兄弟、我的仆人和跟随我的人，都不脱衣服，各人带自己的兵器去打水（“各人带自己的兵器去打水”原文意思不明确，或译：“各人时常右手拿着自己的兵器”）。'),
('CNV', '尼希米记', 16, 5, 1, '那时，民众和他们的妻子大声呼冤，控告自己的同胞犹大人。'),
('CNV', '尼希米记', 16, 5, 2, '有些人说：“我们和儿女人口众多，给我们五谷餬口，可以存活。”'),
('CNV', '尼希米记', 16, 5, 3, '有些人说：“我们抵押了自己的田地、葡萄园和房屋，为要在饥荒中买到五谷。”'),
('CNV', '尼希米记', 16, 5, 4, '有些人说：“我们为了要借钱向王纳税，只好抵押了我们的田地和葡萄园。'),
('CNV', '尼希米记', 16, 5, 5, '虽然我们的身体与我们同胞的身体一样，我们的儿女与他们的儿女也相同，可是我们却要强迫自己的儿女去作仆婢，而且我们的女儿有些已经作了奴婢，我们却无能为力，因为我们的田地和葡萄园已经属于别人了。”'),
('CNV', '尼希米记', 16, 5, 6, '我听见他们的哀叫和所讲的这些事，就十分忿怒。'),
('CNV', '尼希米记', 16, 5, 7, '我心中筹算一番以后，就谴责贵族和官长，对他们说：“你们各人向自己的同胞贷款，竟然索取高利！”于是我召开大会攻击他们。'),
('CNV', '尼希米记', 16, 5, 8, '我对他们说：“我们已尽了我们的能力，把那些卖了给外族人的同胞犹大人买赎回来，而你们还想要出卖你们的同胞，好让我们再把他们买回来吗？”他们都默不作声，无话可说。'),
('CNV', '尼希米记', 16, 5, 9, '我又说：“你们这事作得不对。你们岂不应怀着敬畏我们神的心行事为人，免遭我们的仇敌外族人的毁谤吗？'),
('CNV', '尼希米记', 16, 5, 10, '现在我和我的兄弟，以及我的仆人要把银钱和五谷借给他们。让我们大家都放弃放债取利吧！'),
('CNV', '尼希米记', 16, 5, 11, '请你们今天就把他们的田地、葡萄园、橄榄园、房屋，以及你们向他们索取的利息：百分之一的利钱、五谷、新酒和新油，都归还给他们。”'),
('CNV', '尼希米记', 16, 5, 12, '他们就说：“我们必定归还，不再向他们要求利息了，你怎么说，我们愿意照着你说的去行。”我就把祭司们召了来，叫众人起誓必照着这话去行。'),
('CNV', '尼希米记', 16, 5, 13, '我抖着胸前的衣襟说：“不履行这话的，愿神也是这样抖他离开他的家和产业，直到抖空。”全体会众都说：“阿们！”又赞美耶和华。众人都照着这话去行。'),
('CNV', '尼希米记', 16, 5, 14, '自从我奉命在犹大地作他们省长的日子以来，就是从亚达薛西王二十年，直到三十二年，共十二年，我和我的兄弟都没有吃过省长的俸禄。'),
('CNV', '尼希米记', 16, 5, 15, '在我们以先的前任省长，重压人民，每日都向他们索取粮食和酒，以及四百五十六克银子。连他们的仆人也辖制人民，但我因为敬畏神，就不这样行。'),
('CNV', '尼希米记', 16, 5, 16, '我坚持只重修城墙的工程；所以我们不购置田产，我所有的仆人也都聚集在那里工作。'),
('CNV', '尼希米记', 16, 5, 17, '在我桌上吃饭的，有一百五十个犹大人和官长，还有那些从我们四围外族来到我们这里的人；'),
('CNV', '尼希米记', 16, 5, 18, '每天预备牛一头、肥羊六只，又为我预备一些飞禽；每十天供应大量各类的酒。虽然这样，我仍然没有索取省长的俸禄，因为这些人服役已经负担沉重。'),
('CNV', '尼希米记', 16, 5, 19, '“我的神啊，求你记念我，记念我为这人民所作的一切事，施恩给我。”'),
('CNV', '尼希米记', 16, 6, 1, '参巴拉、多比雅、阿拉伯人基善和我们其余的仇敌听见我重建好了城墙，城墙再没有破口。不过那时我还没有在城门上装上门扇。'),
('CNV', '尼希米记', 16, 6, 2, '参巴拉和基善就差派人来见我说：“请你来，我们在阿那平原上的一个村庄会面吧！”其实他们想要谋害我。'),
('CNV', '尼希米记', 16, 6, 3, '于是我差派使者去见他们说：“我正在进行大工程，不能去。我怎能放下这工程，去见你们，使这工程停顿呢？”'),
('CNV', '尼希米记', 16, 6, 4, '他们连续四次这样差派人来见我，我都这样回覆他们。'),
('CNV', '尼希米记', 16, 6, 5, '参巴拉第五次这样差派他的仆人来见我，手里拿着一封没有封口的信。'),
('CNV', '尼希米记', 16, 6, 6, '信上写着：“在各民族中有这样的传说，基善（原文作“迦施慕”，是“基善”的另一种写法；参2:19）也说：‘你和犹大人阴谋造反，所以你才重建城墙，据说，你还想要作他们的王。’'),
('CNV', '尼希米记', 16, 6, 7, '你又设立先知在耶路撒冷指着你宣讲，说：‘犹大有王了。’现在这些话必会传到王那里。所以请你来，我们一起商量商量吧。”'),
('CNV', '尼希米记', 16, 6, 8, '我就回覆他，说：“你说的这些事不是事实，都是你从心里捏造出来的。”'),
('CNV', '尼希米记', 16, 6, 9, '其实他们众人是在恐吓我们，心里说：“他们的手必软弱，不能再作这工程，不会完工了！”现在，坚固我的手。'),
('CNV', '尼希米记', 16, 6, 10, '我来到米希大别的孙子、第来雅的儿子示玛雅的家里；那时，他闭门不出，他说：“我们在神的殿里，在殿的大堂中会面吧！我们要把殿门关起来，因为他们要来杀你，在夜间来杀你。”'),
('CNV', '尼希米记', 16, 6, 11, '我回答：“像我这样的人，怎可以逃跑呢？哪有像我这样的人，进入圣殿里去保全自己的性命呢？我决不进去！”'),
('CNV', '尼希米记', 16, 6, 12, '我看出神并没有差派他，是他自己宣讲这话攻击我，因为多比雅和参巴拉收买了他。'),
('CNV', '尼希米记', 16, 6, 13, '他被收买，是要使我惧怕，照着他说的去作，以致犯罪，他们就破坏我的名声来毁谤我。'),
('CNV', '尼希米记', 16, 6, 14, '“我的神啊，求你记住多比雅和参巴拉，按着他们所行的报应他们；也要报应女先知挪亚底和其余的先知，因为他们恐吓我。”'),
('CNV', '尼希米记', 16, 6, 15, '以禄月二十五日，城墙建成，整个工程共用了五十二天。'),
('CNV', '尼希米记', 16, 6, 16, '我们所有的仇敌听见了，我们四围所有的民族都惧怕，敌人的声势一落千丈，他们都承认这工程是靠着我们神的帮助完成的。'),
('CNV', '尼希米记', 16, 6, 17, '在这段日子，犹大人的贵族写了许多信给多比雅，多比雅也常常回信给他们。'),
('CNV', '尼希米记', 16, 6, 18, '在犹大有许多人与多比雅结盟；因为他是亚拉的儿子、示迦尼的女婿，并且他的儿子约哈难娶了比利迦的儿子米书兰的女儿为妻。'),
('CNV', '尼希米记', 16, 6, 19, '不但这样，他们也常常在我面前提起多比雅的善行，又把我说的话传给他；多比雅又常常寄信来恐吓我。'),
('CNV', '尼希米记', 16, 7, 1, '城墙建成后，我就装上门扇，委派了守门的、歌唱者和利未人，'),
('CNV', '尼希米记', 16, 7, 2, '我委任我的兄弟哈拿尼和营楼长哈拿尼雅，管理耶路撒冷，因为哈拿尼雅是个可信靠的人，敬畏神胜过许多人。'),
('CNV', '尼希米记', 16, 7, 3, '我吩咐他们说：“日上中天时，耶路撒冷的城门也不可长久敞开；太阳还停着未落，守门的人站岗的时候，也要关好门、上好闩，要派耶路撒冷的居民站岗，一些人在哨岗，另一些人在自己的屋前瞭望。”'),
('CNV', '尼希米记', 16, 7, 4, '城既宽阔又广大，但城中的居民稀少；房屋还没有建造起来。'),
('CNV', '尼希米记', 16, 7, 5, '我的神使我的心定意，召集贵族、官长和人民，要照家谱登记。我找到头一次上来的人的家谱，我找到的家谱上面写着：'),
('CNV', '尼希米记', 16, 7, 6, '以下这些犹大省的人，从前巴比伦王尼布甲尼撒掳走他们，现在他们从被掳之地归回耶路撒冷和犹大，各人回到自己的城镇。'),
('CNV', '尼希米记', 16, 7, 7, '他们是跟所罗巴伯、耶书亚、尼希米、亚撒利雅、拉米、拿哈玛尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏和巴拿一同回来的。以色列民的人数记在下面：'),
('CNV', '尼希米记', 16, 7, 8, '巴录的子孙二千一百七十二人。'),
('CNV', '尼希米记', 16, 7, 9, '示法提雅的子孙三百七十二人。'),
('CNV', '尼希米记', 16, 7, 10, '亚拉的子孙六百五十二人。'),
('CNV', '尼希米记', 16, 7, 11, '巴哈．摩押的子孙，就是耶书亚和约押的子孙，二千八百一十八人。'),
('CNV', '尼希米记', 16, 7, 12, '以拦的子孙一千二百五十四人。'),
('CNV', '尼希米记', 16, 7, 13, '萨土的子孙八百四十五人。'),
('CNV', '尼希米记', 16, 7, 14, '萨改的子孙七百六十人。'),
('CNV', '尼希米记', 16, 7, 15, '宾内的子孙六百四十八人。'),
('CNV', '尼希米记', 16, 7, 16, '比拜的子孙六百二十八人。'),
('CNV', '尼希米记', 16, 7, 17, '押甲的子孙二千三百二十二人。'),
('CNV', '尼希米记', 16, 7, 18, '亚多尼干的子孙六百六十七人。'),
('CNV', '尼希米记', 16, 7, 19, '比革瓦伊的子孙二千零六十七人。'),
('CNV', '尼希米记', 16, 7, 20, '亚丁的子孙六百五十五人。'),
('CNV', '尼希米记', 16, 7, 21, '亚特的子孙，就是希西家的子孙，九十八人。'),
('CNV', '尼希米记', 16, 7, 22, '哈顺的子孙三百二十八人。'),
('CNV', '尼希米记', 16, 7, 23, '比宰的子孙三百二十四人。'),
('CNV', '尼希米记', 16, 7, 24, '哈拉的子孙一百一十二人。'),
('CNV', '尼希米记', 16, 7, 25, '基遍的子孙九十五人。'),
('CNV', '尼希米记', 16, 7, 26, '伯利恒人和尼陀法人，共一百八十八人。'),
('CNV', '尼希米记', 16, 7, 27, '亚拿突人一百二十八人。'),
('CNV', '尼希米记', 16, 7, 28, '伯．亚斯玛弗人四十二人。'),
('CNV', '尼希米记', 16, 7, 29, '基列．耶琳人、基非拉人和比录人，共七百四十三人。'),
('CNV', '尼希米记', 16, 7, 30, '拉玛人和迦巴人，共六百二十一人。'),
('CNV', '尼希米记', 16, 7, 31, '默玛人一百二十二人。'),
('CNV', '尼希米记', 16, 7, 32, '伯特利人和艾人，共一百二十三人。'),
('CNV', '尼希米记', 16, 7, 33, '另一个尼波的人五十二人。'),
('CNV', '尼希米记', 16, 7, 34, '另一个以拦的子孙一千二百五十四人。'),
('CNV', '尼希米记', 16, 7, 35, '哈琳的子孙三百二十人。'),
('CNV', '尼希米记', 16, 7, 36, '耶利哥的子孙三百四十五人。'),
('CNV', '尼希米记', 16, 7, 37, '罗得、哈第和阿挪的子孙共七百二十一人。'),
('CNV', '尼希米记', 16, 7, 38, '西拿的子孙三千九百三十人。'),
('CNV', '尼希米记', 16, 7, 39, '祭司的数目记在下面：耶书亚家的耶大雅的子孙九百七十三人。'),
('CNV', '尼希米记', 16, 7, 40, '音麦的子孙一千零五十二人。'),
('CNV', '尼希米记', 16, 7, 41, '巴施户珥的子孙一千二百四十七人。'),
('CNV', '尼希米记', 16, 7, 42, '哈琳的子孙一千零一十七人。'),
('CNV', '尼希米记', 16, 7, 43, '利未人的数目记在下面：何达威的子孙，就是耶书亚和甲篾的子孙，七十四人。'),
('CNV', '尼希米记', 16, 7, 44, '负责歌唱的：亚萨的子孙一百四十八人。'),
('CNV', '尼希米记', 16, 7, 45, '守门的人数：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙和朔拜的子孙，共一百三十八人。'),
('CNV', '尼希米记', 16, 7, 46, '殿役的数目记在下面：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、'),
('CNV', '尼希米记', 16, 7, 47, '基绿的子孙、西亚的子孙、巴顿的子孙、'),
('CNV', '尼希米记', 16, 7, 48, '利巴拿的子孙、哈迦巴的子孙、萨买的子孙、'),
('CNV', '尼希米记', 16, 7, 49, '哈难的子孙、吉德的子孙、迦哈的子孙、'),
('CNV', '尼希米记', 16, 7, 50, '利亚雅的子孙、利汛的子孙、尼哥大的子孙、'),
('CNV', '尼希米记', 16, 7, 51, '迦散的子孙、乌撒的子孙、巴西亚的子孙、'),
('CNV', '尼希米记', 16, 7, 52, '比塞的子孙、米乌宁的子孙、尼普心的子孙、'),
('CNV', '尼希米记', 16, 7, 53, '巴卜的子孙、哈古巴的子孙、哈忽的子孙、'),
('CNV', '尼希米记', 16, 7, 54, '巴洗律的子孙、米希大的子孙、哈沙的子孙、'),
('CNV', '尼希米记', 16, 7, 55, '巴柯的子孙、西西拉的子孙、答玛的子孙、'),
('CNV', '尼希米记', 16, 7, 56, '尼细亚的子孙和哈提法的子孙。'),
('CNV', '尼希米记', 16, 7, 57, '所罗门仆人的子孙的数目记在下面：琐太的子孙、琐斐列的子孙、比路大的子孙、'),
('CNV', '尼希米记', 16, 7, 58, '雅拉的子孙、达昆的子孙、吉德的子孙、'),
('CNV', '尼希米记', 16, 7, 59, '示法提雅的子孙、哈替的子孙、玻黑列．哈斯巴音的子孙和亚们的子孙。'),
('CNV', '尼希米记', 16, 7, 60, '作殿役的和所罗门仆人的子孙共三百九十二人。'),
('CNV', '尼希米记', 16, 7, 61, '以下这些人是从特米拉、特哈萨、基绿、亚顿和音麦上来的，可是他们无法证明他们的父家或世系是以色列人。'),
('CNV', '尼希米记', 16, 7, 62, '这些人是第莱雅的子孙、多比雅的子孙和尼哥大的子孙，共六百四十二人。'),
('CNV', '尼希米记', 16, 7, 63, '祭司中，有哈巴雅的子孙、哈哥斯的子孙和巴西莱的子孙；巴西莱娶了基列人巴西莱的一个女儿为妻，所以起名叫巴西莱。'),
('CNV', '尼希米记', 16, 7, 64, '这些人查考族谱的记录，却找不着，因此他们算为不洁净，不能作祭司。'),
('CNV', '尼希米记', 16, 7, 65, '省长告诉他们不可吃至圣之物，直等到有能用乌陵和土明来决疑的祭司兴起来。'),
('CNV', '尼希米记', 16, 7, 66, '全体会众共有四万二千三百六十人。'),
('CNV', '尼希米记', 16, 7, 67, '此外，还有他们的仆婢七千三百三十七人；又有男女歌唱者二百四十五人。'),
('CNV', '尼希米记', 16, 7, 68, '他们有马七百三十六匹，骡子二百四十五匹（《马索拉文本》的大部分抄本缺68节﹐现参照其他抄本和《七十士译本》修复；参拉2:66），'),
('CNV', '尼希米记', 16, 7, 69, '骆驼四百三十五匹和驴子六千七百二十头。'),
('CNV', '尼希米记', 16, 7, 70, '有些族长为了这工程而捐献；省长捐给库房金子八公斤、碗五十个和祭司的礼服五百三十件；'),
('CNV', '尼希米记', 16, 7, 71, '族长捐给这工程的库房金子一百六十八公斤、银子一千二百五十公斤。'),
('CNV', '尼希米记', 16, 7, 72, '其余的人民捐献金子一百六十八公斤，银子一千一百四十公斤、祭司的礼服六十七件。'),
('CNV', '尼希米记', 16, 7, 73, '于是祭司、利未人、守门的、歌唱者、一部分人民、作殿役的，和以色列众人都住在自己的城里。'),
('CNV', '尼希米记', 16, 8, 1, '到了七月，以色列人都住在自己的城里。（《马索拉文本》以本句为7:73下半节）那时众民如同一人，在水门前的广场聚集，请经学家以斯拉把耶和华藉摩西命令以色列人遵守的律法书带来。'),
('CNV', '尼希米记', 16, 8, 2, '七月初一日，以斯拉祭司把律法书带到所有听了能明白的男女会众面前。'),
('CNV', '尼希米记', 16, 8, 3, '在水门前面的广场，从清早到中午，向众男女和听了能明白的人宣读出来。众民都侧耳倾听这律法书的话。'),
('CNV', '尼希米记', 16, 8, 4, '经学家以斯拉站在为这事特制的木台上；站在他右边的，有玛他提雅、示玛、亚奈雅、乌利亚、希勒家和玛西雅；站在他左边的，有毗大雅、米沙利、玛基雅、哈顺、哈拔大拿、撒迦利亚和米书兰。'),
('CNV', '尼希米记', 16, 8, 5, '以斯拉在众人眼前展开那书卷；他高高地站在众民以上，他把书卷展开，众民就站起来。'),
('CNV', '尼希米记', 16, 8, 6, '以斯拉称颂耶和华至大的神，众民举手应声说：“阿们！阿们！”然后跪下，脸伏在地，敬拜耶和华。'),
('CNV', '尼希米记', 16, 8, 7, '然后利未人耶书亚、巴尼、示利比、雅悯、亚谷、沙比太、荷第雅、玛西雅、基利他、亚撒利雅、约撒拔、哈难和毗莱雅就教导他们明白律法。众人一直站在原处聆听。'),
('CNV', '尼希米记', 16, 8, 8, '他们宣读神的律法，把意义清楚翻译出来，使众民明白所宣读的。'),
('CNV', '尼希米记', 16, 8, 9, '省长尼希米和祭司兼经学家以斯拉，以及教导人民明白律法的利未人对众民说：“今天是耶和华你们的神的圣日，你们不要悲哀哭泣。”因为众人听见律法书上的话，都哭了。'),
('CNV', '尼希米记', 16, 8, 10, '尼希米又对他们说：“你们应当去吃肥美的肉，喝甘甜的酒，把部分饮食分给没有能力预备的人，因为今天是我们的主的圣日；你们不要忧愁，因为靠耶和华而得的喜乐是你们的力量。”'),
('CNV', '尼希米记', 16, 8, 11, '于是利未人使众民安静下来，说：“你们安静吧，因为今天是圣日，也不要再忧愁！”'),
('CNV', '尼希米记', 16, 8, 12, '众民就去吃喝，也把部分饮食与人分享，大大欢乐。因为他们明白教训他们的话。'),
('CNV', '尼希米记', 16, 8, 13, '第二天，众民的族长、祭司和利未人都聚集到经学家以斯拉那里，研究律法的话。'),
('CNV', '尼希米记', 16, 8, 14, '他们发现律法上记载，耶和华曾藉着摩西吩咐以色列人，要在七月的节期中，住在棚里，'),
('CNV', '尼希米记', 16, 8, 15, '并且要在自己的城里和在耶路撒冷宣扬布告说：“你们要上到山上，把橄榄树枝、油木树枝、番石榴枝、棕树枝和树叶繁茂大树的枝子带回来，照着律法所写的搭棚。”'),
('CNV', '尼希米记', 16, 8, 16, '于是众民出去，把树枝带回来，各人在自己的房顶上，在院子里，神的院中，水门的广场，或是在以法莲门的广场搭棚。'),
('CNV', '尼希米记', 16, 8, 17, '从被掳归回的全体会众都搭了棚，并且住在棚里；从嫩的儿子约书亚的时候，直到那日，以色列人都没有这样行过。大家都非常快乐。'),
('CNV', '尼希米记', 16, 8, 18, '从头一天直到最后一天，每天都宣读神的律法书。他们守节七天，第八天照典章有严肃会。'),
('CNV', '尼希米记', 16, 9, 1, '这月二十四日，以色列人聚集，一同禁食，身穿麻衣，头上蒙灰。'),
('CNV', '尼希米记', 16, 9, 2, '以色列的后裔跟所有外族人分离，然后站立，承认自己的罪过和他们列祖的罪孽。'),
('CNV', '尼希米记', 16, 9, 3, '那天四分之一的时间，他们站在自己的地方，宣读耶和华他们的神的律法书；另外四分之一的时间，他们认罪和敬拜耶和华他们的神。'),
('CNV', '尼希米记', 16, 9, 4, '耶书亚、巴尼、甲篾、示巴尼、布尼、示利比、巴尼和基拿尼，站立在利未人的台阶上，向耶和华他们的神大声哀求。'),
('CNV', '尼希米记', 16, 9, 5, '利未人耶书亚、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼和毗他希雅说：“你们要起立，称颂耶和华你们的神，直到永永远远。”“耶和华啊，你荣耀的名是应当称颂的；愿你的名被尊崇，超过一切称颂和赞美。'),
('CNV', '尼希米记', 16, 9, 6, '你，唯独你是耶和华，你造了天，天上的天和天军，地和地上的万物，海和海中的万物，你使这一切生存，天军也都敬拜你。'),
('CNV', '尼希米记', 16, 9, 7, '你是耶和华神，你拣选亚伯兰，带领他出了迦勒底的吾珥，改他的名字为亚伯拉罕。'),
('CNV', '尼希米记', 16, 9, 8, '你见他在你面前心里诚实可靠，就与他立约，要把迦南人、赫人、亚摩利人、比利洗人、耶布斯人和革迦撒人之地，赐给他的后裔；你履行了你的诺言，因为你是公义的。'),
('CNV', '尼希米记', 16, 9, 9, '你看见我们的列祖在埃及所受的困苦，垂听他们在红海的哀求，'),
('CNV', '尼希米记', 16, 9, 10, '因为你知道埃及人怎样狂妄自大地对待他们，所以就对法老和他的一切臣仆，以及他国中所有的人民，施行神迹奇事，为你自己建立了至今仍存的名声。'),
('CNV', '尼希米记', 16, 9, 11, '你又在我们的列祖面前把海分开，使他们在海中的干地上走过去；把追赶他们的人丢在深处，好像石头抛进怒海之中。'),
('CNV', '尼希米记', 16, 9, 12, '日间你用云柱引导他们，夜间用火柱光照他们要行的路。'),
('CNV', '尼希米记', 16, 9, 13, '你降临西奈山上，从天上与他们说话，赐给他们正直的典章、真实的律法、美好的条例与诫命。'),
('CNV', '尼希米记', 16, 9, 14, '你使他们认识你的圣安息，藉你仆人摩西向他们颁布诫命、条例和律法。'),
('CNV', '尼希米记', 16, 9, 15, '你从天上赐下粮食，给他们充饥，吩咐水从磐石流出来给他们解渴；你又吩咐他们进去占领，你举手起誓要赐给他们的那地。'),
('CNV', '尼希米记', 16, 9, 16, '但是我们的列祖狂妄自大，硬着颈项，不听从你的命令。'),
('CNV', '尼希米记', 16, 9, 17, '他们拒绝听从，也不记念你在他们中间所行的奇事，硬着颈项，存心悖逆，自立首领，要回到他们为奴之地去。但你是乐意饶恕的神，你有恩典，有怜悯，不轻易发怒，并有丰盛的慈爱，所以你没有撇弃他们。'),
('CNV', '尼希米记', 16, 9, 18, '他们更为自己铸造了一头牛犊的雕像，说：‘这就是把你们从埃及领上来的神！’他们犯了亵渎大罪，'),
('CNV', '尼希米记', 16, 9, 19, '你还是因着你丰盛的怜悯，没有把他们撇弃在旷野；日间云柱没有离开他们，仍然在路上引导他们；夜间火柱也没有离开他们，还是光照他们要行的路。'),
('CNV', '尼希米记', 16, 9, 20, '你赐下良善的灵教导他们；你没有留住吗哪不给他们吃；你给他们水解渴。'),
('CNV', '尼希米记', 16, 9, 21, '在旷野四十年，你供养他们，他们毫无缺乏，衣服没有穿破，他们的脚也没有肿痛。'),
('CNV', '尼希米记', 16, 9, 22, '你把列国和万民赐给他们，你把列国分给他们作疆界，他们就获得西宏之地，希实本王之地和巴珊王噩之地。'),
('CNV', '尼希米记', 16, 9, 23, '你使他们的子孙众多，像天上的星星那么多；你把他们带进你应许他们的列祖要进去得为业的那地。'),
('CNV', '尼希米记', 16, 9, 24, '于是他们的子孙进去，获得那地；你使那地的迦南居民向他们屈服，又把迦南众王和那地的各民族，都交在以色列人手里，以色列人可以随意对待他们。'),
('CNV', '尼希米记', 16, 9, 25, '他们夺取了坚固的城、肥沃的土地，获得了满载各样财宝的房屋、挖好的水井、葡萄园、橄榄园和很多果树；他们吃得饱足，身体发胖，因你的大恩生活安逸快乐。'),
('CNV', '尼希米记', 16, 9, 26, '“可是他们竟悖逆，背叛你，把你的律法丢在背后，杀害那些控告他们，要他们归向你的先知，犯了亵渎的大罪。'),
('CNV', '尼希米记', 16, 9, 27, '所以你把他们交在敌人的手中，好让他们受困苦；他们受困苦的时候，就向你呼求，你就从天上垂听，按着你丰盛的怜悯，赐给他们拯救者，拯救他们脱离敌人的手。'),
('CNV', '尼希米记', 16, 9, 28, '但他们得享安宁以后，又在你面前行恶，你就撇弃他们在仇敌的手中，让仇敌管辖他们；然而他们回转过来，向你哀求，你就从天上垂听，按着丰盛的怜悯，一次又一次拯救他们。'),
('CNV', '尼希米记', 16, 9, 29, '你警告他们，要他们转向你的律法；但他们狂妄自大，不听从你的诫命，犯罪干犯你的典章。人应遵行这些典章，按照它们生活，他们却固执地扭转肩头，硬着颈项，不肯听从。'),
('CNV', '尼希米记', 16, 9, 30, '你多年容忍他们，你的灵藉着你的众先知劝戒他们，他们还是不侧耳而听，所以你把他们交在各地的民族手中。'),
('CNV', '尼希米记', 16, 9, 31, '然而因你丰富的怜悯，你不把他们灭尽，也不撇弃他们，因为你是有恩典有怜悯的神。'),
('CNV', '尼希米记', 16, 9, 32, '“我们的神啊，你是至大、全能、至可畏、守约施慈爱的神，现在求你不要把我们、我们的君王和领袖、我们的祭司和先知、我们的列祖和你的众民，从亚述列王的日子直到今日所遭遇的一切苦难，看为小事。'),
('CNV', '尼希米记', 16, 9, 33, '在一切临到我们身上的事上，你都是公义的；因为你所行的是信实的，我们所行的是邪恶的。'),
('CNV', '尼希米记', 16, 9, 34, '我们的君王和领袖，我们的祭司和列祖，都没有遵行你的律法，也没有留心听从你的诫命和你向他们郑重的警告。'),
('CNV', '尼希米记', 16, 9, 35, '他们在本国中，享受你赐给他们的大福，在你摆在他们面前这广大肥沃的地上，却不事奉你，不转离他们的恶行。'),
('CNV', '尼希米记', 16, 9, 36, '我们今天竟成了奴仆！就是在你赐给我们列祖享用其上果实和美物之地，我们竟在这地上作了奴仆！'),
('CNV', '尼希米记', 16, 9, 37, '这地丰富的出产都归给列王，就是你因我们的罪派来管辖我们的；他们也随意管辖我们的身体和我们的牲畜；我们遭遇大患难。'),
('CNV', '尼希米记', 16, 9, 38, '现在由于这一切事，我们立下确实的约，写在文件上；我们的领袖、利未人和祭司，都在上面盖了印。”（本节在《马索拉文本》为10:1）'),
('CNV', '尼希米记', 16, 10, 1, '在上面盖印的是：哈迦利亚的儿子省长尼希米，还有西底家；（本节在《马索拉文本》为10:2）'),
('CNV', '尼希米记', 16, 10, 2, '祭司有：西莱雅、亚撒利雅、耶利米、'),
('CNV', '尼希米记', 16, 10, 3, '巴施户珥、亚玛利雅、玛基雅、'),
('CNV', '尼希米记', 16, 10, 4, '哈突、示巴尼、玛鹿、'),
('CNV', '尼希米记', 16, 10, 5, '哈琳、米利末、俄巴底亚、'),
('CNV', '尼希米记', 16, 10, 6, '但以理、近顿、巴录、'),
('CNV', '尼希米记', 16, 10, 7, '米书兰、亚比雅、米雅尼、'),
('CNV', '尼希米记', 16, 10, 8, '玛西亚、璧该、示玛雅；'),
('CNV', '尼希米记', 16, 10, 9, '利未人有：亚散尼的儿子耶书亚、希拿达的子孙宾内和甲篾；'),
('CNV', '尼希米记', 16, 10, 10, '还有他们的兄弟示巴尼、荷第雅、基利他、毗莱雅、哈难、'),
('CNV', '尼希米记', 16, 10, 11, '米迦、利合、哈沙比雅、'),
('CNV', '尼希米记', 16, 10, 12, '撒刻、示利比、示巴尼、'),
('CNV', '尼希米记', 16, 10, 13, '荷第雅、巴尼、比尼努；'),
('CNV', '尼希米记', 16, 10, 14, '民众的首领有：巴录、巴哈．摩押、以拦、萨土、巴尼、'),
('CNV', '尼希米记', 16, 10, 15, '布尼、押甲、比拜、'),
('CNV', '尼希米记', 16, 10, 16, '亚多尼雅、比革瓦伊、亚丁、'),
('CNV', '尼希米记', 16, 10, 17, '亚特、希西家、押朔、'),
('CNV', '尼希米记', 16, 10, 18, '荷第雅、哈顺、比宰、'),
('CNV', '尼希米记', 16, 10, 19, '哈拉、亚拿突、尼拜、'),
('CNV', '尼希米记', 16, 10, 20, '抹比押、米书兰、希悉、'),
('CNV', '尼希米记', 16, 10, 21, '米示萨别、撒督、押杜亚、'),
('CNV', '尼希米记', 16, 10, 22, '毗拉提、哈难、亚奈雅、'),
('CNV', '尼希米记', 16, 10, 23, '何细亚、哈拿尼雅、哈述、'),
('CNV', '尼希米记', 16, 10, 24, '哈罗黑、毗利合、朔百、'),
('CNV', '尼希米记', 16, 10, 25, '利宏、哈沙拿、玛西雅、'),
('CNV', '尼希米记', 16, 10, 26, '亚希雅、哈难、亚难、'),
('CNV', '尼希米记', 16, 10, 27, '玛鹿、哈琳、巴拿。'),
('CNV', '尼希米记', 16, 10, 28, '其余的民众：祭司、利未人、守门的、歌唱的、作殿役的，以及一切跟各地民族分离，归向神律法的和他们的妻子和儿女，所有有知识能够明白的，'),
('CNV', '尼希米记', 16, 10, 29, '都坚持和他们的贵族兄弟参与发咒起誓，必遵行神藉他仆人摩西颁布的律法，必谨守遵行耶和华我们的主的一切诫命、典章和律例；'),
('CNV', '尼希米记', 16, 10, 30, '我们必不把我们的女儿嫁给这地的外族人，也不为我们的儿子娶他们的女儿。'),
('CNV', '尼希米记', 16, 10, 31, '如果这地的外族人带来货物或五谷，在安息日贩卖，我们在安息日或圣日决不向他们买什么；每逢第七年，我们必不耕种田地，并且豁免一切债务。'),
('CNV', '尼希米记', 16, 10, 32, '我们又为自己立下法规，各人每年要缴纳四克银子作我们神的殿的经费，'),
('CNV', '尼希米记', 16, 10, 33, '用来做陈设饼，常献的素祭，常献的燔祭，安息日、初一、定时的节期所献的祭；又为了做各样的圣物和为以色列人赎罪的赎罪祭，以及我们神殿里一切工作的费用。'),
('CNV', '尼希米记', 16, 10, 34, '我们（包括祭司、利未人和民众）抽签决定按照我们的宗族，每年在指定的时间把木柴奉到我们神的殿，好照着律法上所写的，烧在耶和华我们神的坛上。'),
('CNV', '尼希米记', 16, 10, 35, '又定下每年要把我们田地初熟之物，各样果树上一切初熟的果子，都带到耶和华的殿。'),
('CNV', '尼希米记', 16, 10, 36, '又要照着律法所写的，把我们头胎的儿子和牲畜，就是我们头胎的牛羊，都带到我们神的殿，交给在我们神的殿供职的祭司。'),
('CNV', '尼希米记', 16, 10, 37, '并且把我们最好的面粉和举祭，各样树上的果子、新酒、新油，都带给祭司，交到我们神殿的仓库；又要把我们田地出产的十分之一给利未人，利未人可以在我们所有城镇的耕地收取十分之一的出产。'),
('CNV', '尼希米记', 16, 10, 38, '利未人收取十分之一出产的时候，要有一个作祭司的亚伦的子孙与他们在一起；利未人要从这十分之一中，抽取十分之一奉到我们神的殿，交到库房的贮藏室。'),
('CNV', '尼希米记', 16, 10, 39, '以色列人和利未人要把五谷、新酒、新油作举祭，带到贮存圣所器皿的贮藏室，就是供职的祭司、守门的和歌唱的居住的地方。我们决不会疏忽供应我们神的殿。'),
('CNV', '尼希米记', 16, 11, 1, '那时，民众的领袖住在耶路撒冷；其余的民众都抽签，抽出十分之一，住在圣城耶路撒冷，余下的十分之九就住在别的城镇。'),
('CNV', '尼希米记', 16, 11, 2, '众人为所有自愿住在耶路撒冷的人祝福。'),
('CNV', '尼希米记', 16, 11, 3, '以色列人、祭司、利未人、作殿役的和所罗门仆人的子孙，各住在犹大众城自己的地业中；犹大省的首领住在耶路撒冷的，有以下这些人：'),
('CNV', '尼希米记', 16, 11, 4, '有些犹大的子孙和便雅悯的子孙，住在耶路撒冷。犹大的子孙有：法勒斯的子孙乌西雅的儿子亚他雅；乌西雅是撒迦利雅的儿子，撒迦利雅是亚玛利雅的儿子，亚玛利雅是示法提雅的儿子，示法提雅是玛勒列的儿子。'),
('CNV', '尼希米记', 16, 11, 5, '又有巴录的儿子玛西雅；巴录是谷何西的儿子，谷何西是哈赛雅的儿子，哈赛雅是亚大雅的儿子，亚大雅是约雅立的儿子，约雅立是撒迦利雅的儿子，撒迦利雅是示罗尼的儿子。'),
('CNV', '尼希米记', 16, 11, 6, '所有住在耶路撒冷的法勒斯子孙，共四百六十八人，他们都是勇士。'),
('CNV', '尼希米记', 16, 11, 7, '便雅悯的子孙有：米书兰的儿子撒路；米书兰是约叶的儿子，约叶是毗大雅的儿子，毗大雅是哥赖雅的儿子，哥赖雅是玛西雅的儿子，玛西雅是以铁的儿子，以铁是耶筛亚的儿子。'),
('CNV', '尼希米记', 16, 11, 8, '他的众兄弟都是勇士（本句《马索拉文本》作“在他以后是迦拜和撒来”，明显是残缺；今照《七十士译本》翻译），共九百二十八人。'),
('CNV', '尼希米记', 16, 11, 9, '细基利的儿子约珥是管理他们的官长；哈西努亚的儿子犹大是那城的副市长。'),
('CNV', '尼希米记', 16, 11, 10, '祭司有：约雅立的儿子耶大雅，又有雅斤，'),
('CNV', '尼希米记', 16, 11, 11, '以及神殿的总管西莱雅；西莱雅是希勒家的儿子，希勒家是米书兰的儿子，米书兰是撒督的儿子，撒督是米拉约的儿子，米拉约是亚希突的儿子；'),
('CNV', '尼希米记', 16, 11, 12, '还有他们的亲族，在殿里工作事奉的，共八百二十二人；又有耶罗罕的儿子亚大雅；耶罗罕是毗拉利的儿子，毗拉利是暗洗的儿子，暗洗是撒迦利亚的儿子，撒迦利亚是巴施户珥的儿子，巴施户珥是玛基雅的儿子；'),
('CNV', '尼希米记', 16, 11, 13, '还有他的亲族作族长的共二百四十二人；又有亚萨列的儿子亚玛帅；亚萨列是亚哈赛的儿子，亚哈赛是米实利末的儿子，米实利末是音麦的儿子；'),
('CNV', '尼希米记', 16, 11, 14, '又有他们的亲族，英勇的战士共一百二十八人；哈基多琳的儿子撒巴第业是管理他们的官长。'),
('CNV', '尼希米记', 16, 11, 15, '利未人有：哈述的儿子示玛雅；哈述是押利甘的儿子，押利甘是哈沙比雅的儿子，哈沙比雅是布尼的儿子；'),
('CNV', '尼希米记', 16, 11, 16, '又有利未人的族长沙比太和约撒拔，管理神殿的外务。'),
('CNV', '尼希米记', 16, 11, 17, '米迦的儿子玛他尼，领导赞美，献上感谢的祷告；米迦是撒底的儿子，撒底是亚萨的儿子；八布迦在他的兄弟中作副手；还有沙母亚的儿子押大，沙母亚是加拉的儿子，加拉是耶杜顿的儿子。'),
('CNV', '尼希米记', 16, 11, 18, '所有在圣城的利未人，共二百八十四人。'),
('CNV', '尼希米记', 16, 11, 19, '守门的有：亚谷和达们，以及他们的亲族，看守各门，共一百七十二人。'),
('CNV', '尼希米记', 16, 11, 20, '其余的以色列人、祭司、利未人各住在犹大众城自己的地业中。'),
('CNV', '尼希米记', 16, 11, 21, '作殿役的住在俄斐勒；西哈和基斯帕管理作殿役的人。'),
('CNV', '尼希米记', 16, 11, 22, '在耶路撒冷管理利未人的，是巴尼的儿子乌西，巴尼是哈沙比雅的儿子，哈沙比雅是玛他尼的儿子，玛他尼是米迦的儿子，他是亚萨的子孙，就是那些管理神殿事务的歌唱者。'),
('CNV', '尼希米记', 16, 11, 23, '王命令他们，规定歌唱者每天当尽的责任。'),
('CNV', '尼希米记', 16, 11, 24, '犹大的儿子谢拉的子孙中，米示萨别的儿子毗他希雅是王的助手，统管一切民事。'),
('CNV', '尼希米记', 16, 11, 25, '至于村庄和所属的田地，有些犹大人住在基列．亚巴和属于基列．亚巴的乡村，有些住在底本和属于底本的乡村，有些住在叶甲薛和属于叶甲薛的村庄，'),
('CNV', '尼希米记', 16, 11, 26, '有些住在耶书亚、摩拉大、伯．帕列、'),
('CNV', '尼希米记', 16, 11, 27, '哈萨．书亚、别是巴和属于别是巴的乡村，'),
('CNV', '尼希米记', 16, 11, 28, '有些住在洗革拉、米哥拿和属于米哥拿的乡村，'),
('CNV', '尼希米记', 16, 11, 29, '有些住在音．临门、琐拉、耶末、'),
('CNV', '尼希米记', 16, 11, 30, '撒挪亚、亚杜兰和属于这两地的村庄，拉吉和属于拉吉的田地，亚西加和属于亚西加的乡村；他们安营居住的地方，从别是巴直到欣嫩谷。'),
('CNV', '尼希米记', 16, 11, 31, '有些便雅悯人住在迦巴、密抹、亚雅、伯特利和属于伯特利的乡村，'),
('CNV', '尼希米记', 16, 11, 32, '有些住在亚拿突、挪伯、亚难雅、'),
('CNV', '尼希米记', 16, 11, 33, '夏琐、拉玛、基他音、'),
('CNV', '尼希米记', 16, 11, 34, '哈叠、洗编、尼八拉、'),
('CNV', '尼希米记', 16, 11, 35, '罗德、阿挪和匠人谷；'),
('CNV', '尼希米记', 16, 11, 36, '有些利未人曾经住在犹大地，却归到便雅悯地。'),
('CNV', '尼希米记', 16, 12, 1, '与撒拉铁的儿子所罗巴伯和耶书亚一起上来的祭司和利未人有以下这些人：祭司有西莱雅、耶利米、以斯拉、'),
('CNV', '尼希米记', 16, 12, 2, '亚玛利雅、玛鹿、哈突、'),
('CNV', '尼希米记', 16, 12, 3, '示迦尼、利宏、米利末、'),
('CNV', '尼希米记', 16, 12, 4, '易多、近顿、亚比雅、'),
('CNV', '尼希米记', 16, 12, 5, '米雅民、玛底雅、璧迦、'),
('CNV', '尼希米记', 16, 12, 6, '示玛雅、约雅立、耶大雅、'),
('CNV', '尼希米记', 16, 12, 7, '撒路、亚木、希勒家和耶大雅。这些人在耶书亚的日子作祭司和他们亲族的首领。'),
('CNV', '尼希米记', 16, 12, 8, '利未人有耶书亚、宾内、甲篾、示利比、犹大、玛他尼和他的兄弟们，负责颂赞的事。'),
('CNV', '尼希米记', 16, 12, 9, '他们的兄弟八布迦和乌尼按着班次，与他们相对站立。'),
('CNV', '尼希米记', 16, 12, 10, '耶书亚生约雅金，约雅金生以利亚实，以利亚实生耶何耶大，'),
('CNV', '尼希米记', 16, 12, 11, '耶何耶大生约拿单，约拿单生押杜亚。'),
('CNV', '尼希米记', 16, 12, 12, '在约雅金的日子，祭司作族长的，属西莱雅族的，有米拉雅；属耶利米族的，有哈拿尼雅；'),
('CNV', '尼希米记', 16, 12, 13, '属以斯拉族的，有米书兰；属亚玛利雅族的，有约哈难；'),
('CNV', '尼希米记', 16, 12, 14, '属米利古族的，有约拿单；属示巴尼族的，有约瑟；'),
('CNV', '尼希米记', 16, 12, 15, '属哈琳族的，有押拿；属米拉约族的，有希勒恺；'),
('CNV', '尼希米记', 16, 12, 16, '属易多族的，有撒迦利亚；属近顿族的，有米书兰；'),
('CNV', '尼希米记', 16, 12, 17, '属亚比雅族的，有细基利；属米拿民族的，有某一位；属摩亚底族的，有毗勒太；'),
('CNV', '尼希米记', 16, 12, 18, '属璧迦族的，有沙母亚；属示玛雅族的，有约拿单；'),
('CNV', '尼希米记', 16, 12, 19, '属约雅立族的，有玛特乃；属耶大雅族的，有乌西；'),
('CNV', '尼希米记', 16, 12, 20, '属撒来族的，有加莱；属亚木族的，有希伯；'),
('CNV', '尼希米记', 16, 12, 21, '属希勒家族的，有哈沙比雅；属耶大雅族的，有拿坦业。'),
('CNV', '尼希米记', 16, 12, 22, '在以利亚实、耶何耶大、约哈难和押杜亚的日子，利未人的族长都登记了，同样，波斯王大利乌在位时的祭司也都登记了。'),
('CNV', '尼希米记', 16, 12, 23, '作族长的利未人登记在编年录上，直到以利亚实的孙子约哈难的时候。'),
('CNV', '尼希米记', 16, 12, 24, '利未人的族长是哈沙比雅、示利比、甲篾的儿子耶书亚与他们的兄弟相对站立，照着神人大卫的命令，按着班次赞美称颂。'),
('CNV', '尼希米记', 16, 12, 25, '玛他尼、八布迦、俄巴底亚、米书兰、达们和亚谷都是守门的，守卫城门的库房。'),
('CNV', '尼希米记', 16, 12, 26, '这些人是在约撒达的孙子、耶书亚的儿子约雅金的日子，以及在省长尼希米和祭司兼经学家以斯拉的日子任职。'),
('CNV', '尼希米记', 16, 12, 27, '耶路撒冷城墙举行奉献典礼的时候，众民在各地寻找利未人，带他们到耶路撒冷来，要他们称谢、歌唱、敲钹、弹琴鼓瑟，欢欢喜喜地举行奉献典礼。'),
('CNV', '尼希米记', 16, 12, 28, '歌唱者从耶路撒冷四围的平原，从尼陀法的村庄，'),
('CNV', '尼希米记', 16, 12, 29, '从伯．吉甲，从迦巴和押玛弗的田庄聚集前来；因为歌唱者在耶路撒冷四围为自己建造村庄。'),
('CNV', '尼希米记', 16, 12, 30, '祭司和利未人洁净了自己，然后洁净民众，以及城门和城墙。'),
('CNV', '尼希米记', 16, 12, 31, '我带领犹大的领袖上了城墙，组织了两大队颂赞的人，一队在城墙右边，向着粪门前进，'),
('CNV', '尼希米记', 16, 12, 32, '跟随他们后面的是何沙雅和犹大的一半领袖；'),
('CNV', '尼希米记', 16, 12, 33, '还有亚撒利雅、以斯拉、米书兰、'),
('CNV', '尼希米记', 16, 12, 34, '犹大、便雅悯、示玛雅、耶利米；'),
('CNV', '尼希米记', 16, 12, 35, '还有拿着号筒的祭司：约拿单的儿子撒迦利亚；约拿单是示玛雅的儿子，示玛雅是玛他尼的儿子，玛他尼是米该亚的儿子，米该亚是撒刻的儿子，撒刻是亚萨的儿子；'),
('CNV', '尼希米记', 16, 12, 36, '他的兄弟示玛雅、亚撒利、米拉莱、基拉莱、玛艾、拿坦业、犹大、哈拿尼拿着神人大卫的乐器。经学家以斯拉走在他们前面。'),
('CNV', '尼希米记', 16, 12, 37, '他们到了泉门，就登上大卫城的台阶，随着城墙的升势，经过大卫的宫殿，走到东边的水门。'),
('CNV', '尼希米记', 16, 12, 38, '第二队颂赞的人往左边行，我和一半的人民跟着他们，在城墙上过了炉楼，直走到宽墙，'),
('CNV', '尼希米记', 16, 12, 39, '过了以法莲门、古门、鱼门、哈楠业楼、哈米亚楼，直到羊门，就在护卫院的门前站住。'),
('CNV', '尼希米记', 16, 12, 40, '于是这两队颂赞的人就站在神的殿里，我和一半的官长也站在那里；'),
('CNV', '尼希米记', 16, 12, 41, '祭司以利亚金、玛西雅、米拿尼、米该雅、以利约乃、撒迦利亚和哈楠尼亚，拿着号筒；'),
('CNV', '尼希米记', 16, 12, 42, '又有玛西雅、示玛雅、以利亚撒、乌西、约哈难、玛基雅、以拦和以谢；歌唱者在伊斯拉希雅领导下，高声歌唱。'),
('CNV', '尼希米记', 16, 12, 43, '那一天，众人献上极大的祭祀，而且非常欢乐，因为神使他们大大欢乐；连妇女和孩童也都欢乐；耶路撒冷欢乐的声音在老远的地方都可以听见。'),
('CNV', '尼希米记', 16, 12, 44, '那时，有一些人被委派管理存放举祭、初熟之物和十分之一供物的库房，把各城的田地，照着律法所规定归给祭司和利未人的部分收集到那里。犹大人为侍立供职的祭司和利未人欢乐。'),
('CNV', '尼希米记', 16, 12, 45, '祭司和利未人谨守他们的神所吩咐的，谨守洁净的礼；歌唱者和守门的也照着大卫和他的儿子所罗门的命令去行，'),
('CNV', '尼希米记', 16, 12, 46, '因为远在大卫和亚萨的时代，已有诗班长，并且有赞美称颂神的诗歌。'),
('CNV', '尼希米记', 16, 12, 47, '在所罗巴伯和尼希米的日子，以色列众人把歌唱的和守门的每日应得的分供给他们；又把分别为圣的分给利未人；而利未人也把分别为圣的分给亚伦的子孙。'),
('CNV', '尼希米记', 16, 13, 1, '那时，他们宣读摩西的书给众民听，见书上写着说：亚扪人和摩押人永远不可进入神的会，'),
('CNV', '尼希米记', 16, 13, 2, '因为他们没有拿食物和水来迎接以色列人，反而雇用了巴兰来与他们作对，咒诅他们；但是我的神使咒诅变为祝福。'),
('CNV', '尼希米记', 16, 13, 3, '众民听见了这律法，就跟一切闲杂人分离。'),
('CNV', '尼希米记', 16, 13, 4, '这事以前，受委派管理我们神殿的库房的以利亚实祭司，与多比雅的关系很密切。'),
('CNV', '尼希米记', 16, 13, 5, '他为多比雅预备了一间大房间，那里以前是用来收存素祭、乳香和器皿，还有祭司的举祭，以及按照命令供给利未人、歌唱者和守门的那些五谷、新酒和新油的十分之一。'),
('CNV', '尼希米记', 16, 13, 6, '这事发生的时候，我不在耶路撒冷；因为在巴比伦王亚达薛西三十二年，我回到王那里去；过了一段时期，我又向王告了假，'),
('CNV', '尼希米记', 16, 13, 7, '回到耶路撒冷，那时我才知道以利亚实在神殿的院子里，为多比雅预备一间房间那件恶事。'),
('CNV', '尼希米记', 16, 13, 8, '我十分恼怒，就把多比雅的一切家具，都从房间里抛出去。'),
('CNV', '尼希米记', 16, 13, 9, '又吩咐人洁净那几间房间，然后把神殿的器皿，与素祭和乳香搬回那里。'),
('CNV', '尼希米记', 16, 13, 10, '我发觉利未人应得的分，没有人供给他们，甚至供职的利未人和歌唱者，各人都跑回自己的田地去。'),
('CNV', '尼希米记', 16, 13, 11, '于是我责备众官长说：“为什么疏忽供应神的殿呢？”我就再召集利未人，使他们重站原来的岗位。'),
('CNV', '尼希米记', 16, 13, 12, '犹大众人就把五谷、新酒和新油的十分之一，奉到库房。'),
('CNV', '尼希米记', 16, 13, 13, '我委派示利米雅祭司、经学家撒督和利未人毗大雅作库官，管理库房；他们的助手是玛他尼的孙子、撒刻的儿子哈难；这些人都是忠信可靠的；他们的责任是把人奉献的各物分给他们的兄弟。'),
('CNV', '尼希米记', 16, 13, 14, '“我的神啊，求你因这事记念我，不要涂抹我为我神的殿和一切敬拜的礼仪所行的忠诚的事。”'),
('CNV', '尼希米记', 16, 13, 15, '那时，我在犹大看见有人在安息日踹压酒池，搬运禾捆，驮在驴上，又把酒、葡萄、无花果和各样的担子，在安息日运到耶路撒冷；我就在他们卖粮食的那天警戒他们。'),
('CNV', '尼希米记', 16, 13, 16, '又有推罗人住在耶路撒冷城中，他们把鱼和各样的货物运进来，在安息日卖给犹大人，而且在耶路撒冷贩卖。'),
('CNV', '尼希米记', 16, 13, 17, '于是我责备犹大的贵族，对他们说：“你们怎么行这恶事，亵渎安息日呢？'),
('CNV', '尼希米记', 16, 13, 18, '从前你们的列祖不是这样行，以致我们的神使这一切灾祸临到我们和这城吗？现在你们亵渎安息日，使神的忿怒越发临到以色列。”'),
('CNV', '尼希米记', 16, 13, 19, '所以在安息日的前一天，黄昏的阴影临到耶路撒冷城门的时候，我就吩咐人把城门关闭；我又下令不许开门，直到安息日过了，我又派我的仆人在城门站岗，免得有人在安息日挑担子进来。'),
('CNV', '尼希米记', 16, 13, 20, '于是商人和贩卖各样货物的，一次两次在耶路撒冷城外过夜。'),
('CNV', '尼希米记', 16, 13, 21, '我警告他们，对他们说：“你们为什么要在城墙前面过夜呢？如果你们再这样，我就要动手对付你们。”从那时起，他们在安息日就不敢再来了。'),
('CNV', '尼希米记', 16, 13, 22, '我吩咐利未人洁净自己，然后来看守城门，使安息日分别为圣。“我的神啊，求你也因这事记念我，照着你丰盛的慈爱怜恤我！”'),
('CNV', '尼希米记', 16, 13, 23, '那些日子，我也发现有些犹大人娶了亚实突、亚扪和摩押的女子为妻。'),
('CNV', '尼希米记', 16, 13, 24, '他们的儿女有一半说亚实突话，其他就说他们民族的语言，他们却不会说犹大话。'),
('CNV', '尼希米记', 16, 13, 25, '我就责备他们，咒诅他们，击打他们中间的几个人，拔下他们的头发，叫他们指着神起誓，说：“你们决不可把自己的女儿嫁给他们的儿子，也决不可为儿子或为自己娶他们的女儿。'),
('CNV', '尼希米记', 16, 13, 26, '以色列王所罗门不是在这些事上犯了罪吗？在许多国中并没有一个王能比得上他的；他蒙他的神所爱，神立他作全以色列的王，可是连他也被外族的女子引诱犯罪。'),
('CNV', '尼希米记', 16, 13, 27, '难道我们要听从你们，行这大恶，娶外族的女子为妻，对我们神不忠吗？”'),
('CNV', '尼希米记', 16, 13, 28, '大祭司以利亚实的孙子耶何耶大的一个儿子，是和伦人参巴拉的女婿，我就驱逐他离开我。'),
('CNV', '尼希米记', 16, 13, 29, '“我的神啊，求你记住他们，因为他们玷污了祭司的职分，也污辱了祭司职分和利未人的约。”'),
('CNV', '尼希米记', 16, 13, 30, '这样，我就洁净了他们，使他们脱离一切外族人的污秽，又重新指派祭司和利未人的职责，各人有自己的工作。'),
('CNV', '尼希米记', 16, 13, 31, '我又指派人按时供应木柴和奉献初熟之物。“我的神啊，求你记念我，施恩给我。”'),
('CNV', '以斯帖记', 17, 1, 1, '亚哈随鲁在位的时候，他统治从印度到古实共一百二十七省。'),
('CNV', '以斯帖记', 17, 1, 2, '他在书珊城登了国位。'),
('CNV', '以斯帖记', 17, 1, 3, '他执政第三年，曾为众领袖和臣仆摆设筵席；波斯和玛代的权贵，以及各省的贵族和领袖都在他面前。'),
('CNV', '以斯帖记', 17, 1, 4, '他把自己尊荣之国的财富和伟大威风的荣华，向他们展现很多日子，共有一百八十天。'),
('CNV', '以斯帖记', 17, 1, 5, '这些日子过了，王又为所有在书珊城的人民，无论尊卑大小，在御园的院子里摆设筵席七天。'),
('CNV', '以斯帖记', 17, 1, 6, '御园中有白色绵织的帷幕、蓝色的幔子，细麻绳、紫色绳悬在银环里和大理石柱上；有金银的床榻摆在红色、白色、黄色和黑色的大理石所铺的地上。'),
('CNV', '以斯帖记', 17, 1, 7, '赐饮都用金器皿；器皿与器皿各有不同；御酒很多，足显王的厚赐。'),
('CNV', '以斯帖记', 17, 1, 8, '饮酒都照着定例，不准勉强；因为王对他宫里的所有臣仆立下规矩，要照着各人的意愿而行。'),
('CNV', '以斯帖记', 17, 1, 9, '王后瓦实提也在亚哈随鲁王的王宫中，为妇女们摆设筵席。'),
('CNV', '以斯帖记', 17, 1, 10, '第七日，亚哈随鲁王因饮酒心里高兴，就吩咐侍候在他面前的七个太监：米户幔、比斯他、哈波拿、比革他、亚拔他、西达、甲迦，'),
('CNV', '以斯帖记', 17, 1, 11, '去请王后瓦实提，戴着后冕到王面前，使众人和大臣欣赏她的美丽；因为她的容貌很美。'),
('CNV', '以斯帖记', 17, 1, 12, '王后瓦实提却不肯遵照王藉着太监所传的命令，所以王非常生气，怒火中烧。'),
('CNV', '以斯帖记', 17, 1, 13, '王就咨询通达时务的哲士；因为当时按照王的常规，王要处理一事，必先问问面前所有精通法令和审断的朝臣。'),
('CNV', '以斯帖记', 17, 1, 14, '那时在王身边的有甲示拿、示达、押玛他、他施斯、米力、玛西拿、米母干等七位波斯、玛代的大臣；他们都是常见王面，在国中居首位的。'),
('CNV', '以斯帖记', 17, 1, 15, '王问他们说：“王后瓦实提不遵行亚哈随鲁王藉着太监所传的命令，按照法令应怎样办理呢？”'),
('CNV', '以斯帖记', 17, 1, 16, '米母干在王和众领袖面前回答：“王后瓦实提不但得罪了皇上，而且还得罪了亚哈随鲁王各省的臣民。'),
('CNV', '以斯帖记', 17, 1, 17, '因为王后这事必传到所有妇女的耳中，会使她们眼中轻视自己的丈夫，因为她们说：‘亚哈随鲁王吩咐人带王后瓦实提到王面前，她却没有来。’'),
('CNV', '以斯帖记', 17, 1, 18, '现在波斯和玛代的公主贵妇听见王后这件事，就必照样告诉王的大臣，这样轻视和忿怒的事就常有了。'),
('CNV', '以斯帖记', 17, 1, 19, '王若是赞成，可以下一道谕旨，并且写在波斯和玛代的法令中，永不废除。不准瓦实提再到亚哈随鲁王面前来，又请王把她王后的位分赐给另一位比她好的人。'),
('CNV', '以斯帖记', 17, 1, 20, '王颁布的谕旨传遍全国的时候，所有的妇女都必敬重她们的丈夫，不论丈夫尊卑贵贱。”'),
('CNV', '以斯帖记', 17, 1, 21, '王和众领袖都赞成米母干的话；王就照着他的话去行，'),
('CNV', '以斯帖记', 17, 1, 22, '把诏书送到王的各省，每一省都用各省的文字，每一族都用各族的方言，使作丈夫的都在家中作主，说话有权威。'),
('CNV', '以斯帖记', 17, 2, 1, '这些事以后，亚哈随鲁王的怒气消减了，就想念瓦实提和她所行的，以及怎样降旨办她的事。'),
('CNV', '以斯帖记', 17, 2, 2, '于是有些侍臣对王说：“要差人为王寻找一些美貌的少女。'),
('CNV', '以斯帖记', 17, 2, 3, '王可以委派官员在国中各省，把所有美貌的少女都召到书珊城的女院那里，交在掌理女子的王家太监希该手下，可以供给她们洁身用的香品。'),
('CNV', '以斯帖记', 17, 2, 4, '王喜悦的女子，就可以作王后，代替瓦实提。”王喜悦这话，就这样行了。'),
('CNV', '以斯帖记', 17, 2, 5, '在书珊城里，有一个犹大人，名叫末底改，是便雅悯人基士的曾孙、示每的孙子、睚珥的儿子。'),
('CNV', '以斯帖记', 17, 2, 6, '末底改在巴比伦王尼布甲尼撒掳走犹大王耶哥尼雅和别的俘虏的时候，也同时从耶路撒冷被掳走。'),
('CNV', '以斯帖记', 17, 2, 7, '末底改抚养自己叔叔的女儿哈大沙（哈大沙就是以斯帖），因为她没有父母。这女子体态美丽，容貌娟秀；她父母死了，末底改就收养她作自己的女儿。'),
('CNV', '以斯帖记', 17, 2, 8, '王的命令和谕旨传开了，许多少女都被召到书珊城，交在希该的手下；以斯帖也被带到王宫里去，交在管理女子的希该手下。'),
('CNV', '以斯帖记', 17, 2, 9, '希该喜悦以斯帖，就恩待她，急忙供给她洁身用的香品和她应得的食物，又给她七个美丽的侍女，都是从王宫里选出来给她的，再把她和她的侍女搬进女院上好的房子里。'),
('CNV', '以斯帖记', 17, 2, 10, '以斯帖没有把自己的种族和身世告诉人，因为末底改吩咐她不可告诉人。'),
('CNV', '以斯帖记', 17, 2, 11, '末底改天天都在女院的院子前面徘徊，要知道以斯帖平安不平安，她的情形怎样。'),
('CNV', '以斯帖记', 17, 2, 12, '每个少女轮流进宫见亚哈随鲁王之前，都要照着女子的规例洁净身体十二个月，因为女子洁身的规例是这样：六个月用没药油，六个月用香品和妇女洁身用的其他物品。'),
('CNV', '以斯帖记', 17, 2, 13, '那时，少女进去见王是这样的：从女院到王宫的时候，她所要的都要给她。'),
('CNV', '以斯帖记', 17, 2, 14, '她晚上进去，次日早晨回到第二女院去，交给管理妃嫔的沙甲，就是王的太监；除非王喜悦她，题名召她，她就不再进去见王。'),
('CNV', '以斯帖记', 17, 2, 15, '末底改的叔叔亚比孩的女儿以斯帖，就是末底改收养作自己女儿的，轮到她进去见王的时候，除了王的太监，掌理女子的希该所预备的以外，以斯帖别无所求；看见以斯帖的，都喜爱她。'),
('CNV', '以斯帖记', 17, 2, 16, '亚哈随鲁王执政第七年十月，就是提别月，以斯帖被带进王宫去见亚哈随鲁王。'),
('CNV', '以斯帖记', 17, 2, 17, '王爱以斯帖超过所有其他的女子；在所有的处女中，她在王的面前，最得王的恩宠与喜爱；王把王后的冠冕戴在她头上，立她为王后，代替瓦实提。'),
('CNV', '以斯帖记', 17, 2, 18, '王为他的文武百官大摆筵席，就是以斯帖的婚筵，又向各省颁布休假一天，并且照着王的厚意，颁赐礼物。'),
('CNV', '以斯帖记', 17, 2, 19, '第二次召集处女的时候，末底改坐在朝门那里。'),
('CNV', '以斯帖记', 17, 2, 20, '以斯帖照着末底改吩咐她的，没有把自己的身世和种族告诉人；末底改所说的话，以斯帖都遵行，就像昔日养育她的时候一样。'),
('CNV', '以斯帖记', 17, 2, 21, '那时，末底改坐在朝门那里，王有两个守门的太监：辟探和提列，一时因为恼怒，正想下手害亚哈随鲁王。'),
('CNV', '以斯帖记', 17, 2, 22, '这阴谋给末底改知道了，他就告诉王后以斯帖；以斯帖就以末底改的名义对王说起这事。'),
('CNV', '以斯帖记', 17, 2, 23, '那阴谋查究起来，就发现真相；于是把二人悬挂在木架上。这事在王面前曾写于史记。'),
('CNV', '以斯帖记', 17, 3, 1, '这事以后，亚哈随鲁王使亚甲族哈米大他的儿子哈曼晋陞；王提拔他，使他的地位高过所有与他在一起的大臣。'),
('CNV', '以斯帖记', 17, 3, 2, '在朝门那里，王的所有臣仆，都向哈曼屈身下拜，因为王曾经这样吩咐；只有末底改不跪，也不拜。'),
('CNV', '以斯帖记', 17, 3, 3, '于是在朝门的臣仆问末底改：“你为什么违背王的命令呢？”'),
('CNV', '以斯帖记', 17, 3, 4, '他们天天劝他，他还是不听，他们就告诉哈曼，要看看末底改的话是不是坚持到底，因为他已经告诉他们，他自己是犹大人。'),
('CNV', '以斯帖记', 17, 3, 5, '哈曼见末底改不向他屈身下拜，就非常忿怒。'),
('CNV', '以斯帖记', 17, 3, 6, '他以为只下手对付末底改一人还是小事，因为有人把末底改的本族告诉了哈曼；所以哈曼设法要把亚哈随鲁王全国所有的犹大人，与末底改一起消灭。'),
('CNV', '以斯帖记', 17, 3, 7, '亚哈随鲁王十二年正月，就是尼散月，有人在哈曼面前弄卜“普珥”，就是抽签，逐日逐月地抽，结果抽出了十二月，就是亚达月。'),
('CNV', '以斯帖记', 17, 3, 8, '哈曼对亚哈随鲁王说：“有一个种族，散居在王国各省各民族之中；他们的法例与各族的法例不同，他们也不遵守王的法规；所以留下他们，对王实在无益。'),
('CNV', '以斯帖记', 17, 3, 9, '王若是赞成，请王降旨消灭他们；我愿捐出三十四万公斤银子，交在管理国务的人手中，纳入王库。”'),
('CNV', '以斯帖记', 17, 3, 10, '于是王从自己的手中取下戒指，交给犹大人的敌人，亚甲族哈米大他的儿子哈曼。'),
('CNV', '以斯帖记', 17, 3, 11, '王对哈曼说：“这银子仍赐给你，这民也交给你，你看怎样好，就怎样待他们吧。”'),
('CNV', '以斯帖记', 17, 3, 12, '正月十三日，王的书记都召了来，照着哈曼的一切吩咐，用各省的文字，各族的方言，奉亚哈随鲁王的名下旨，又用王的戒指盖上印，颁给总督、各省的省长和各族的领袖。'),
('CNV', '以斯帖记', 17, 3, 13, '王旨交给众驿使传到王的各省，吩咐要在一日之内，在十二月，就是亚达月十三日，把所有的犹大人，无论老少妇孺，都全部毁灭、杀绝、除尽，并且抢夺他们的财产。'),
('CNV', '以斯帖记', 17, 3, 14, '谕文抄本颁行各省，通告各族，使他们准备好这一天。'),
('CNV', '以斯帖记', 17, 3, 15, '驿使奉王命急忙出发，御旨从书珊城颁布出去。那时王与哈曼又同坐共饮，书珊城的居民却非常慌乱。'),
('CNV', '以斯帖记', 17, 4, 1, '末底改知道了发生的一切事，就撕裂自己的衣服，披上麻衣，撒上灰尘，出到城中，大声痛哭地呼叫。'),
('CNV', '以斯帖记', 17, 4, 2, '他到了御门前，就停住，因为身穿麻衣的，不可以进御门。'),
('CNV', '以斯帖记', 17, 4, 3, '王的谕旨和命令传到的各省各地，犹大人都大大悲哀，禁食、哭泣、悲伤；许多人披上麻衣，躺在灰尘中。'),
('CNV', '以斯帖记', 17, 4, 4, '以斯帖的婢女和太监把这事告诉以斯帖，王后就非常惊慌，就派人送衣服给末底改穿着，要他脱下麻衣，他却不接受。'),
('CNV', '以斯帖记', 17, 4, 5, '以斯帖就把王派来侍候她的一个太监哈他革召了来，吩咐他到末底改那里去，探听这是什么一回事，又是为了什么缘故。'),
('CNV', '以斯帖记', 17, 4, 6, '于是哈他革出到御门前的广场去见末底改。'),
('CNV', '以斯帖记', 17, 4, 7, '末底改把他遭遇的一切事，以及哈曼为灭尽犹大人答应捐银给王库的数目，都告诉了他。'),
('CNV', '以斯帖记', 17, 4, 8, '末底改又把在书珊城颁布要毁灭犹大人的谕旨抄本，交给了哈他革，要他给以斯帖看，并且要给她说明，吩咐她进宫见王，向王求情，为自己的族人在王面前恳求。'),
('CNV', '以斯帖记', 17, 4, 9, '哈他革回来，把末底改的话都告诉了以斯帖。'),
('CNV', '以斯帖记', 17, 4, 10, '以斯帖把以下的话告诉哈他革，又吩咐他回覆末底改说：'),
('CNV', '以斯帖记', 17, 4, 11, '“王所有的臣仆和各省的人民，都知道有一条法令：无论男女，没有奉召就擅入内院去见王的，除非王向他伸出金杖，赐他免死，一律要处以死刑。现在我没有奉召进去见王已经三十天了。”'),
('CNV', '以斯帖记', 17, 4, 12, '哈他革把以斯帖的话都告诉末底改。'),
('CNV', '以斯帖记', 17, 4, 13, '末底改叫人回覆以斯帖说：“你不要心里想，你在王宫里比所有的犹大人都安全。'),
('CNV', '以斯帖记', 17, 4, 14, '这时你若是缄默不言，犹大人必会从别的地方得着解救，那时你和你的父家就必灭亡。谁知你得了王后的位分，不是为了挽救现今的危机吗？”'),
('CNV', '以斯帖记', 17, 4, 15, '以斯帖吩咐人回覆末底改说：'),
('CNV', '以斯帖记', 17, 4, 16, '“你要去，把书珊城所有的犹大人都召集起来，为我禁食三天，就是三日三夜不吃不喝；我和我的婢女也要这样禁食。然后我就违例进去见王；我若是死，就死吧。”'),
('CNV', '以斯帖记', 17, 4, 17, '于是末底改离开了，照着以斯帖吩咐的一切去行。'),
('CNV', '以斯帖记', 17, 5, 1, '第三天，以斯帖穿上朝服，站在王宫的内院，对着王殿；王在殿里坐在王位上，对着殿门。'),
('CNV', '以斯帖记', 17, 5, 2, '王见王后以斯帖站在院内，就对她施恩，向她伸出手中的金杖，以斯帖就上前摸杖头。'),
('CNV', '以斯帖记', 17, 5, 3, '王问她：“王后以斯帖啊，你有什么事吗？你求什么？就是一半江山，也必赐给你。”'),
('CNV', '以斯帖记', 17, 5, 4, '以斯帖回答：“王若是欢喜，就请王今天带着哈曼来赴我为王预备的筵席。”'),
('CNV', '以斯帖记', 17, 5, 5, '王说：“快把哈曼召来，好照着以斯帖的话去行。”于是王带着哈曼去赴以斯帖预备的筵席。'),
('CNV', '以斯帖记', 17, 5, 6, '在酒席中，王问以斯帖：“你要什么？我必赐给你；你求什么？就是一半江山，也必为你成全。”'),
('CNV', '以斯帖记', 17, 5, 7, '以斯帖回答说：“我所要我所求的就是：'),
('CNV', '以斯帖记', 17, 5, 8, '我若是在王眼前蒙恩，王若是愿意赐给我所要的，成全我所求的，就请王带着哈曼明天再来赴我为你们预备的筵席；明天我必照着王的命令行。”'),
('CNV', '以斯帖记', 17, 5, 9, '那天哈曼心里快乐，高高兴兴地出来；但是哈曼见了末底改在御门那里不站起来，也不因哈曼的缘故而退避，哈曼心里就对末底改充满忿怒。'),
('CNV', '以斯帖记', 17, 5, 10, '哈曼忍住怒气，回家去了，就派人去请他的朋友和妻子细利斯来。'),
('CNV', '以斯帖记', 17, 5, 11, '哈曼把他的富贵荣华、儿女的众多，以及王怎样使他尊大，怎样抬举他在王的众领袖和众臣仆之上的一切事，都数说给他们听。'),
('CNV', '以斯帖记', 17, 5, 12, '哈曼又说：“王后以斯帖除我以外，没有邀请别人与王一同去赴她预备的筵席；明天又邀请我与王一同到她那里去赴席。'),
('CNV', '以斯帖记', 17, 5, 13, '只是每逢我看见坐在朝门那里的犹大人末底改的时候，这一切对我都没有多大的意思。”'),
('CNV', '以斯帖记', 17, 5, 14, '他的妻子细利斯和他所有的朋友都对他说：“叫人立一个二十二公尺高的木架，明早求王，把末底改挂在上面，然后你可以欢欢喜喜地与王一同赴筵席了。”这话使哈曼很满意，就叫人做了木架。'),
('CNV', '以斯帖记', 17, 6, 1, '那一夜，王睡不着觉，就吩咐人把史记，就是年鉴拿来，在王面前诵读。'),
('CNV', '以斯帖记', 17, 6, 2, '有一处记着说：王有两个守门的太监：辟探和提列，企图要谋害亚哈随鲁王；这事给末底改告发了。'),
('CNV', '以斯帖记', 17, 6, 3, '王问：“为了这事，末底改得了什么尊荣和封赐没有？”侍候王的众臣仆回答：“他什么也没有得到。”'),
('CNV', '以斯帖记', 17, 6, 4, '王问：“谁在院子里？”那时哈曼正进了王宫的外院，要求王把末底改挂在哈曼为他预备的木架上。'),
('CNV', '以斯帖记', 17, 6, 5, '王的臣仆对他说：“是哈曼站在院子里。”王说：“叫他进来。”'),
('CNV', '以斯帖记', 17, 6, 6, '哈曼就进去，王问他：“王喜欢赐尊荣给他的人，要怎样待他呢？”哈曼心里想：“王喜欢赐尊荣的人，除我以外，还有谁呢？”'),
('CNV', '以斯帖记', 17, 6, 7, '于是哈曼回答王：“王喜欢赐尊荣的人，'),
('CNV', '以斯帖记', 17, 6, 8, '要把王常穿的朝服和王常骑的骏马，就是头戴王冠的骏马带来，'),
('CNV', '以斯帖记', 17, 6, 9, '把朝服和骏马交给王最尊贵的一个大臣手里，把衣服给王喜欢赐尊荣的人穿上，使他骑在马上，走过城中的街上，又要有人在他前面宣告：‘王喜欢赐尊荣的人，要这样待他。’”'),
('CNV', '以斯帖记', 17, 6, 10, '王对哈曼说：“赶快拿朝服和骏马来，照着你所说的，去行在那坐在朝门那里的犹大人末底改身上；你所说的，一样也不可缺少。”'),
('CNV', '以斯帖记', 17, 6, 11, '于是哈曼把朝服和骏马拿来，先给末底改穿上朝服，然后使他骑在马上，走过城中的街上，又在他前面宣告：“王喜欢赐尊荣的人，要这样待他。”')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以斯帖记', 17, 6, 12, '末底改仍回到御门那里；哈曼却急急忙忙回了家，带着悲哀的心蒙着头。'),
('CNV', '以斯帖记', 17, 6, 13, '哈曼把遭遇的一切事，都述说给他的妻子细利斯和他所有的朋友听；他的谋士和妻子细利斯对他说：“在末底改面前，你开始失败了；他若是犹大人，你就不能胜过他：你终必在他面前失败。”'),
('CNV', '以斯帖记', 17, 6, 14, '他们还与哈曼说话的时候，王的太监来了，催哈曼快走，赴以斯帖预备的筵席。'),
('CNV', '以斯帖记', 17, 7, 1, '王带着哈曼去赴王后以斯帖的筵席。'),
('CNV', '以斯帖记', 17, 7, 2, '在这第二次的酒席中，王又问以斯帖：“王后以斯帖啊，你要什么？我必赐给你；你求什么？就是一半江山，也必给你成全。”'),
('CNV', '以斯帖记', 17, 7, 3, '王后以斯帖回答，说：“我若是在你眼前蒙恩，王若是喜欢，我所要的，是要王把我的性命赐给我；我所求的，是求王把我的族人赐给我。'),
('CNV', '以斯帖记', 17, 7, 4, '因为我和我的族人被人出卖，快要毁灭，被杀尽、灭绝了。我们若是只被卖为奴婢，我也必闭口不言，但王的损失是敌人不能补偿的。”'),
('CNV', '以斯帖记', 17, 7, 5, '亚哈随鲁王问王后以斯帖，说：“存心这样行的人是谁？他在哪里？”'),
('CNV', '以斯帖记', 17, 7, 6, '以斯帖回答：“这敌人和仇人，就是这恶人哈曼！”哈曼在王和王后面前立刻惊惶万分。'),
('CNV', '以斯帖记', 17, 7, 7, '于是王带着盛怒，从酒席间起来，到御园里去；哈曼却留下来求王后以斯帖救他一命，因为哈曼看出王已经决意要加罪与他。'),
('CNV', '以斯帖记', 17, 7, 8, '王从御园回到酒席那里；那时哈曼正伏在以斯帖所靠的榻上；于是王说：“他竟敢在宫里，当着我的面污辱王后吗？”这话一出王口，人就把哈曼的脸蒙住了。'),
('CNV', '以斯帖记', 17, 7, 9, '在王面前有一个太监哈波拿说：“还有，哈曼为那曾经说好话救王有功的末底改，立了一个二十二公尺高的木架，现在正立在哈曼的家里呢。”王说：“把哈曼挂在上面吧！”'),
('CNV', '以斯帖记', 17, 7, 10, '于是他们把哈曼挂在他为末底改预备的木架上；王的忿怒才渐渐止息。'),
('CNV', '以斯帖记', 17, 8, 1, '当日，亚哈随鲁把犹大人的敌人哈曼的家产，赐给王后以斯帖；末底改也来到王的面前，因为以斯帖已经把末底改和她的关系告诉王。'),
('CNV', '以斯帖记', 17, 8, 2, '王就摘下自己的戒指，就是从哈曼那里取回的，给了末底改，以斯帖也委派末底改管理哈曼的家产。'),
('CNV', '以斯帖记', 17, 8, 3, '以斯帖又在王面前说话，俯伏在王的脚前，含泪恳求王免除亚甲族人哈曼所加的灾害，以及他设计要害犹大人的阴谋。'),
('CNV', '以斯帖记', 17, 8, 4, '王向以斯帖伸出了金杖，以斯帖就起来，站在王的面前；'),
('CNV', '以斯帖记', 17, 8, 5, '她说：“王若是同意，我若是在王面前蒙恩，王若以为这事是对的，王若喜爱我，就请下旨，废除亚甲族哈米大他的儿子哈曼设计的谕文，就是他写下要消灭在王各省的犹大人的谕文。'),
('CNV', '以斯帖记', 17, 8, 6, '因为我怎忍看见我的同胞受害呢？我怎忍看见我的族人消灭呢？”'),
('CNV', '以斯帖记', 17, 8, 7, '亚哈随鲁王对王后以斯帖和犹大人末底改说：“因为哈曼要下手害犹大人，我已经把哈曼的家产赐给了以斯帖，人也把哈曼挂在木架了。'),
('CNV', '以斯帖记', 17, 8, 8, '现在你们可以照着你们的意思，奉王的名为犹大人写谕旨，用王的印戒盖上；因为奉王的名所写，用王的戒指盖上印的谕旨，是没有人可以废除的。”'),
('CNV', '以斯帖记', 17, 8, 9, '那时是三月，就是西弯月，二十三日，王的文士都召了来，照着末底改所吩咐一切有关犹大人的事，用各省的文字、各族的方言写了谕旨，从印度到古实的一百二十七省，给各省的总督、省长和领袖，也用犹大人的文字和方言写给犹大人。'),
('CNV', '以斯帖记', 17, 8, 10, '末底改奉亚哈随鲁王的名写了谕旨，又用王的戒指盖上印；文书由驿使骑上御养的、为国事而用的快马，传送到各处去。'),
('CNV', '以斯帖记', 17, 8, 11, '文书上写着：王准许在各城的犹大人，可以聚集起来，保护自己的性命；也可以毁灭、杀尽和灭绝那些敌对犹大人的各族和各省的势力，包括妇孺，并且可以掠夺他们的财产；'),
('CNV', '以斯帖记', 17, 8, 12, '一日之间，在十二月，就是亚达月，十三日，在亚哈随鲁王的各省，开始实行。'),
('CNV', '以斯帖记', 17, 8, 13, '谕旨的抄本作为御令，颁发到各省，宣告各族，使犹大人准备那日，好在仇敌身上施行报复。'),
('CNV', '以斯帖记', 17, 8, 14, '于是，骑上为国事而用的快马的驿使，迫于王命，就急急忙忙出发，谕旨传遍书珊城。'),
('CNV', '以斯帖记', 17, 8, 15, '末底改穿着紫蓝色和白色的朝服，戴着硕大的金冠冕，又披上紫色细麻布的外袍，从王面前出来；书珊城的人都欢呼快乐。'),
('CNV', '以斯帖记', 17, 8, 16, '犹大人得到了光彩、欢喜、快乐和尊荣。'),
('CNV', '以斯帖记', 17, 8, 17, '在各省各城中，王的命令和谕旨所到之处，犹大人都欢喜快乐，饮宴放假；那地的人民，有许多因为惧怕犹大人，就都自认是犹大人。'),
('CNV', '以斯帖记', 17, 9, 1, '十二月，就是亚达月，十三日，王的命令和谕旨快要执行的时候，就是犹大人的仇敌盼望辖制犹大人的日子，反成了犹大人辖制恨他们的人的日子。'),
('CNV', '以斯帖记', 17, 9, 2, '犹大人在亚哈随鲁王各省的城里聚集起来，要下手攻击那些想谋害他们的人；没有人能抵挡他们，因为各族的人都惧怕他们。'),
('CNV', '以斯帖记', 17, 9, 3, '各省的官长、总督、省长和办理王事务的人，因为惧怕末底改，就都支持犹大人。'),
('CNV', '以斯帖记', 17, 9, 4, '末底改在朝中的确非常尊大，他的声誉传遍各省；末底改这人的权力越来越大。'),
('CNV', '以斯帖记', 17, 9, 5, '这样，犹大人击杀他们所有的仇敌，他们用刀尽量击杀，随意对待他们的仇人。'),
('CNV', '以斯帖记', 17, 9, 6, '在书珊城里，犹大人就杀灭了五百人。'),
('CNV', '以斯帖记', 17, 9, 7, '他们又杀了巴珊大他、达分、亚斯帕他、'),
('CNV', '以斯帖记', 17, 9, 8, '破拉他、亚大利雅、亚利大他、'),
('CNV', '以斯帖记', 17, 9, 9, '帕玛斯他、亚利赛、亚利代和瓦耶撒他，'),
('CNV', '以斯帖记', 17, 9, 10, '这十个人就是哈米大他的孙子、哈曼的儿子，犹大人的敌人；至于财物，犹大人却没有下手掠夺。'),
('CNV', '以斯帖记', 17, 9, 11, '当日在书珊城被杀的人的数目，呈到王面前。'),
('CNV', '以斯帖记', 17, 9, 12, '王问王后以斯帖：“犹大人在书珊城杀灭了五百人，又杀了哈曼的十个儿子；在王其他省内，他们怎样行呢！现在你要什么，我必赐给你，你还求什么，也必给你成全。”'),
('CNV', '以斯帖记', 17, 9, 13, '以斯帖回答：“王若是同意，求你恩准书珊的犹大人，明日也照着今日的谕旨行事，把哈曼的十个儿子挂在木架上。”'),
('CNV', '以斯帖记', 17, 9, 14, '王就下令这样行；谕旨传遍书珊，人就把哈曼的十个儿子挂在木架上。'),
('CNV', '以斯帖记', 17, 9, 15, '亚达月十四日，在书珊的犹大人又聚集起来，在书珊杀了三百人，却没有下手掠夺他们的财物。'),
('CNV', '以斯帖记', 17, 9, 16, '在王各省其余的犹大人，也都聚集起来，保护自己的性命，向他们的仇敌报复，杀了恨他们的人共七万五千；至于财物，他们却没有下手掠夺。'),
('CNV', '以斯帖记', 17, 9, 17, '这是在亚达月十三日的事，十四日他们得享安宁，以这日为设宴欢乐的日子。'),
('CNV', '以斯帖记', 17, 9, 18, '但在书珊的犹大人在十三、十四日聚集起来杀敌，他们就在十五日休息，以这日为设宴欢乐的日子。'),
('CNV', '以斯帖记', 17, 9, 19, '因此乡村的犹大人，就是住在没有城墙的村镇的，都以亚达月十四日为欢乐饮宴的吉日，互送礼物。'),
('CNV', '以斯帖记', 17, 9, 20, '末底改把这些事记录下来，并且送文书给亚哈随鲁各省远近所有的犹大人，'),
('CNV', '以斯帖记', 17, 9, 21, '嘱咐他们每年都要守亚达月十四、十五两日。'),
('CNV', '以斯帖记', 17, 9, 22, '以这月的两日，为犹大人脱离仇敌，得享安宁的日子，是转忧为喜，转哀为乐的吉日，叫他们在这两日饮宴欢乐，大家互赠礼物，也周济穷人。'),
('CNV', '以斯帖记', 17, 9, 23, '于是，犹大人承诺要守他们起初所守的，也承诺要遵守末底改写给他们的。'),
('CNV', '以斯帖记', 17, 9, 24, '原本犹大人的敌人，亚甲族哈米大他的儿子哈曼曾经设谋陷害犹大人，要消灭他们；他弄卜“普珥”，就是抽签，为要打击和消灭犹大人。'),
('CNV', '以斯帖记', 17, 9, 25, '但这事呈到王面前以后，王使用文书降旨吩咐，使哈曼计谋的恶事，就是他设谋陷害犹大人的事归到他自己的头上，又使人把他和他的众子挂在木架上。'),
('CNV', '以斯帖记', 17, 9, 26, '因此，犹大人照着“普珥”的名字，称这两日为普珥节；所以他们因这信上的话，又因他们所看见和所遭遇的事，'),
('CNV', '以斯帖记', 17, 9, 27, '犹大人就立了定例，承诺他们自己和他们的后裔，以及所有与他们联合的人，每年都要按着所写的和指定的两日守这节日，永不可废止。'),
('CNV', '以斯帖记', 17, 9, 28, '使人在各省各城，家家户户，世世代代，都记念、遵守这两日，使这普珥节的日子在犹大人中，永不废止，在他们的后裔中也不断被记念。'),
('CNV', '以斯帖记', 17, 9, 29, '亚比孩的女儿王后以斯帖和犹大人末底改以全权写了这第二封信，嘱咐犹大人守这普珥节。'),
('CNV', '以斯帖记', 17, 9, 30, '他用和平和诚实的话，把文书送给亚哈随鲁国中一百二十七省所有的犹大人，'),
('CNV', '以斯帖记', 17, 9, 31, '劝他们按着规定的时期，照着犹大人末底改和王后以斯帖所嘱咐的，也照着他们在禁食和哀求的时候为自己与后裔所承诺的，守这普珥节。'),
('CNV', '以斯帖记', 17, 9, 32, '以斯帖的命令确定了普珥节；这命令也记录在史记上。'),
('CNV', '以斯帖记', 17, 10, 1, '亚哈随鲁王使陆地和众海岛的居民都向他进贡。'),
('CNV', '以斯帖记', 17, 10, 2, '他所行有权能的事迹，以及末底改被尊为大的详细经过，不是都写在玛代和波斯王的史记上吗？'),
('CNV', '以斯帖记', 17, 10, 3, '犹大人末底改的地位仅次于亚哈随鲁王，在犹大人中被尊为大，得民众同胞的爱戴；他为自己的族人求福祉，向他们说平安的话。'),
('CNV', '约伯记', 18, 1, 1, '乌斯地有一个人，名叫约伯。这人完全、正直，敬畏神，远离罪恶。'),
('CNV', '约伯记', 18, 1, 2, '他生了七男三女。'),
('CNV', '约伯记', 18, 1, 3, '他的家产有七千只羊、三千匹骆驼、五百对牛、五百头母驴，并且有许多仆婢。这人在全东方的人中至为尊贵。'),
('CNV', '约伯记', 18, 1, 4, '他的儿子素常轮流各按自己的日子在家摆设筵席，并且打发人去邀请他们的三个姊妹来一同吃喝。'),
('CNV', '约伯记', 18, 1, 5, '轮流设宴的日子一过，约伯就差人去叫他们自洁。他清早起来，按他们的数目献上燔祭。因为他心里想：“说不定孩子犯了罪，心中亵渎了神。”约伯经常这样作。'),
('CNV', '约伯记', 18, 1, 6, '有一天，神的众子都来侍立在耶和华面前，撒但也来到他们中间。'),
('CNV', '约伯记', 18, 1, 7, '耶和华问撒但：“你从哪里来？”撒但回答耶和华说：“我在地上徘徊，走来走去。”'),
('CNV', '约伯记', 18, 1, 8, '耶和华问撒但：“你有没有注意到我的仆人约伯？世上再也没有一个人像他那样完全、正直，敬畏神，远离罪恶。”'),
('CNV', '约伯记', 18, 1, 9, '撒但回答耶和华说：“约伯敬畏神，难道是无缘无故的吗？'),
('CNV', '约伯记', 18, 1, 10, '你不是在他四周围上篱笆保护他吗？他的家和他所有的一切，以及他手所作的，你都赐福，他的家产也在地上增添。'),
('CNV', '约伯记', 18, 1, 11, '只要你伸手打击他所有的一切，他一定当面亵渎你。”'),
('CNV', '约伯记', 18, 1, 12, '耶和华对撒但说：“好吧，他所有的一切都交在你手中，只是不可以伸手害他。”于是撒但从耶和华面前退去。'),
('CNV', '约伯记', 18, 1, 13, '有一天，约伯的儿女正在他们长兄的家里吃饭喝酒的时候，'),
('CNV', '约伯记', 18, 1, 14, '有报信的来见约伯，说：“牛正在耕田，母驴在附近吃草的时候，'),
('CNV', '约伯记', 18, 1, 15, '示巴人忽然来侵袭，把牛驴掳去，又用刀杀了仆人，只有我一个人逃脱，来向你报告。”'),
('CNV', '约伯记', 18, 1, 16, '这个人还在说话的时候，又有人来说：“神的火从天上降下来，把群羊和仆人都烧光了，只有我一个人逃脱，来向你报告。”'),
('CNV', '约伯记', 18, 1, 17, '他还在说话的时候，又有人来说：“迦勒底人分成三队突袭骆驼，把它们掳去，又用刀杀了仆人，只有我一个人逃脱，来向你报告。”'),
('CNV', '约伯记', 18, 1, 18, '他还在说话的时候，又有人来说：“你的儿女正在他们长兄的家里吃饭喝酒的时候，'),
('CNV', '约伯记', 18, 1, 19, '没想到有一阵狂风，从旷野那边刮来，吹袭房屋的四角，房屋倒塌在年轻人身上，他们就都死了，只有我一个人逃脱，来向你报告。”'),
('CNV', '约伯记', 18, 1, 20, '于是约伯起来，撕裂外袍，剃了头，俯伏在地上敬拜，'),
('CNV', '约伯记', 18, 1, 21, '说：“我赤身出于母胎，也必赤身归去。赏赐的是耶和华，收回的也是耶和华；耶和华的名是应当称颂的。”'),
('CNV', '约伯记', 18, 1, 22, '在这一切事上，约伯并没有犯罪，也没有归咎于神。'),
('CNV', '约伯记', 18, 2, 1, '又有一天，神的众子都来侍立在耶和华面前，撒但也来到他们中间，侍立在耶和华面前。'),
('CNV', '约伯记', 18, 2, 2, '耶和华问撒但：“你从哪里来？”撒但回答说：“我在地上徘徊，走来走去。”'),
('CNV', '约伯记', 18, 2, 3, '耶和华问撒但：“你有没有注意到我的仆人约伯？世上再也没有一个人像他那样完全、正直，敬畏神，远离罪恶。虽然你挑拨我与他作对，无缘无故使他倾家荡产，他还是坚守自己的纯全。”'),
('CNV', '约伯记', 18, 2, 4, '撒但回答耶和华说：“人以皮换皮，宁可付出他所有的一切去保命。'),
('CNV', '约伯记', 18, 2, 5, '只要你伸手伤害他的骨和肉，他一定当面亵渎你。”'),
('CNV', '约伯记', 18, 2, 6, '耶和华对撒但说：“好吧，他在你手中，不过，要留存他的命。”'),
('CNV', '约伯记', 18, 2, 7, '于是撒但从耶和华面前退去，击打约伯，使他从脚掌到头顶都生了毒疮。'),
('CNV', '约伯记', 18, 2, 8, '约伯坐在灰烬中，拿瓦片刮自己。'),
('CNV', '约伯记', 18, 2, 9, '他妻子对他说：“难道你还要坚守自己的纯全吗？你不如放弃神，死掉算了。”'),
('CNV', '约伯记', 18, 2, 10, '可是约伯对她说：“你说话像个愚妄的女人。难道我们从神得福，也不应当受祸吗？”在这一切事上，约伯并没有用口犯罪。'),
('CNV', '约伯记', 18, 2, 11, '约伯的三个朋友，提幔人以利法、书亚人比勒达、拿玛人琐法，听到这一切降在他身上的灾祸，就各从自己的地方出发，相约而来对他表同情，安慰他。'),
('CNV', '约伯记', 18, 2, 12, '他们从远处举目观望，竟认不出他来，就放声大哭，各自撕裂外袍，向天扬起尘土，落在自己头上。'),
('CNV', '约伯记', 18, 2, 13, '他们就七天七夜与他一起坐在地上，没有人向他说一句话，因为他们看出他极其痛苦。'),
('CNV', '约伯记', 18, 3, 1, '后来，约伯开口咒诅自己的生日。'),
('CNV', '约伯记', 18, 3, 2, '约伯说：'),
('CNV', '约伯记', 18, 3, 3, '“愿我生的那日泯灭，人说怀男胎的那夜灭没。'),
('CNV', '约伯记', 18, 3, 4, '愿那日变成黑暗，愿神不从上面眷顾，愿光明不照耀在其上。'),
('CNV', '约伯记', 18, 3, 5, '愿黑暗与死荫索讨那日，愿密云停留在上面，愿白天的昏黑惊吓它。'),
('CNV', '约伯记', 18, 3, 6, '愿那夜被幽暗夺去，不让它连在平日之中，列入月数之内。'),
('CNV', '约伯记', 18, 3, 7, '愿那夜没有生育，也没有欢乐的声音。'),
('CNV', '约伯记', 18, 3, 8, '那些咒诅日子、善于惹动海怪的，愿他们咒诅那夜。'),
('CNV', '约伯记', 18, 3, 9, '愿那夜黎明的星星变成黑暗，愿那夜等候发光却不亮，见不到清晨的曙光。'),
('CNV', '约伯记', 18, 3, 10, '因为那夜没有把我母胎的门关闭，也没有把苦难隐藏，使我看不见。'),
('CNV', '约伯记', 18, 3, 11, '我为什么不一离母胎就死去？我为什么不一出母腹就断气？'),
('CNV', '约伯记', 18, 3, 12, '为什么有膝承接我？为什么有乳哺养我？'),
('CNV', '约伯记', 18, 3, 13, '不然，我早已躺下安息，'),
('CNV', '约伯记', 18, 3, 14, '与世上那些为自己建造陵墓的君王和谋士同睡，'),
('CNV', '约伯记', 18, 3, 15, '或与那些拥有黄金，房屋装满银子的王侯同眠。'),
('CNV', '约伯记', 18, 3, 16, '我为什么不像暗中流产的胎，未见天日的婴孩，归于无有呢？'),
('CNV', '约伯记', 18, 3, 17, '在那里，恶人止息搅扰，筋疲力尽的得安息；'),
('CNV', '约伯记', 18, 3, 18, '被囚的同享安宁；听不见督工的声音；'),
('CNV', '约伯记', 18, 3, 19, '老少尊卑都在那里，奴仆脱离主人的辖制。'),
('CNV', '约伯记', 18, 3, 20, '为什么有光明赐给劳碌的人，有生命赐给苦命的人呢？'),
('CNV', '约伯记', 18, 3, 21, '他们想死却死不了，找死胜于找宝藏；'),
('CNV', '约伯记', 18, 3, 22, '他们找到坟墓就高兴，非常欢喜快乐。'),
('CNV', '约伯记', 18, 3, 23, '为什么有生命赐给前途茫茫，又被神四面围困的人呢？'),
('CNV', '约伯记', 18, 3, 24, '我以叹息代替食物，我唉哼的声音如水涌出。'),
('CNV', '约伯记', 18, 3, 25, '我所惧怕的临到我，我所惊恐的向我而来。'),
('CNV', '约伯记', 18, 3, 26, '我不得安逸，不得安静，也不得安息，却有搅扰来到。”'),
('CNV', '约伯记', 18, 4, 1, '提幔人以利法回答说：'),
('CNV', '约伯记', 18, 4, 2, '“人若对你说一句话，你就厌烦吗？但谁又忍得住不说话呢？'),
('CNV', '约伯记', 18, 4, 3, '你曾经教过许多人，又坚固了无力的手；'),
('CNV', '约伯记', 18, 4, 4, '你的话扶起了绊倒的人，你使弯曲乏力的膝坚挺。'),
('CNV', '约伯记', 18, 4, 5, '但现在祸患临到你，你就灰心，灾祸遇上你，你就惊惶沮丧。'),
('CNV', '约伯记', 18, 4, 6, '你所自恃的，不是敬畏神吗？你所盼望的，不是行为完全吗？'),
('CNV', '约伯记', 18, 4, 7, '请想一想，无辜的人有谁灭亡？哪有正直的人被剪除呢？'),
('CNV', '约伯记', 18, 4, 8, '据我所见，耕耘罪孽的，必收割罪孽；种植毒害的，必收割毒害。'),
('CNV', '约伯记', 18, 4, 9, '他们因神的气息而灭亡，因他的怒气而消灭。'),
('CNV', '约伯记', 18, 4, 10, '狮子的咆哮，猛狮的吼声，尽都止息，壮狮的牙齿也都断掉。'),
('CNV', '约伯记', 18, 4, 11, '公狮因缺乏猎物而死亡，母狮之子也被分散。'),
('CNV', '约伯记', 18, 4, 12, '有话偷偷传给我，我的耳朵听到细语；'),
('CNV', '约伯记', 18, 4, 13, '在夜间因异象而烦扰的心思中，世人都在沉睡的时候，'),
('CNV', '约伯记', 18, 4, 14, '恐惧战栗临到我，以致我全身发抖。'),
('CNV', '约伯记', 18, 4, 15, '有灵拂过我面前，使我毛骨悚然。'),
('CNV', '约伯记', 18, 4, 16, '那灵站住，我辨不出他的形状，只见有一形象在我眼前，然后我听见低微的声音，说：'),
('CNV', '约伯记', 18, 4, 17, '‘人能在神面前算为公义吗？人能在他的创造主面前算为洁净吗？'),
('CNV', '约伯记', 18, 4, 18, '他的仆役他还不信任，他的天使他也指责过错，'),
('CNV', '约伯记', 18, 4, 19, '何况那些住在土屋里，根基在尘土中，比蠹虫还容易被压碎的人呢？'),
('CNV', '约伯记', 18, 4, 20, '在早晚之间他们就被毁灭，永归沉沦，无人怀念。'),
('CNV', '约伯记', 18, 4, 21, '他们帐棚的绳索不是从他们中间抽出来吗？他们死去，不是无智慧而死吗？’”'),
('CNV', '约伯记', 18, 5, 1, '“你只管呼吁吧，有谁回答你？在众圣者之中你转向哪一位？'),
('CNV', '约伯记', 18, 5, 2, '烦恼杀死愚昧人，激情害死愚蒙人。'),
('CNV', '约伯记', 18, 5, 3, '我看见愚昧人扎下了根，但咒诅忽然临到他的居所。'),
('CNV', '约伯记', 18, 5, 4, '他的儿女远离安稳之处，在城门口被欺压却没有人援救。'),
('CNV', '约伯记', 18, 5, 5, '饥饿的人吃尽他的庄稼，连在荆棘里的也抢去；口渴的人（按照《马索拉文本》，“口渴的人”作“网罗”；现参照其他抄本及古译本翻译）吞尽他的财富。'),
('CNV', '约伯记', 18, 5, 6, '患难不从土中生出来，劳碌不由地里长出来；'),
('CNV', '约伯记', 18, 5, 7, '原来人为劳碌而生，如同火花向上飞扬。'),
('CNV', '约伯记', 18, 5, 8, '至于我，我必寻求神，向他陈明我的案件。'),
('CNV', '约伯记', 18, 5, 9, '他所作的大事无法测度，所行的奇事不可胜数。'),
('CNV', '约伯记', 18, 5, 10, '降雨在地上，遣水到田里，'),
('CNV', '约伯记', 18, 5, 11, '把低微的安置在高位，把哀恸的高举于安稳之处；'),
('CNV', '约伯记', 18, 5, 12, '又挫败狡猾人的计谋，使他们的手所作的无法成全；'),
('CNV', '约伯记', 18, 5, 13, '他使有智慧的人中了自己的诡计，使奸诈人的谋算快快失败。'),
('CNV', '约伯记', 18, 5, 14, '他们白天遇见黑暗，中午摸索如在夜间。'),
('CNV', '约伯记', 18, 5, 15, '他拯救穷乏人脱离他们口中的刀剑，脱离强暴人的手；'),
('CNV', '约伯记', 18, 5, 16, '这样，贫穷人有指望，不义的人却闭口无言。'),
('CNV', '约伯记', 18, 5, 17, '神所责备的人是有福的，所以你不要轻看全能者的管教。'),
('CNV', '约伯记', 18, 5, 18, '因为他打伤，又缠裹；他击伤，又亲手医治。'),
('CNV', '约伯记', 18, 5, 19, '你六次遭遇患难，他都救拔你，就算第七次，灾祸也伤不了你。'),
('CNV', '约伯记', 18, 5, 20, '在饥荒中，他必救你脱离死亡；在战争中，他必救你脱离刀剑的权势。'),
('CNV', '约伯记', 18, 5, 21, '你必不受人口舌之害，灾殃临到，也不害怕。'),
('CNV', '约伯记', 18, 5, 22, '对灾殃和饥馑，一笑置之，地上的野兽你也不害怕。'),
('CNV', '约伯记', 18, 5, 23, '你必与田间的石头立约，田间的野兽必与你和平相处。'),
('CNV', '约伯记', 18, 5, 24, '你必晓得你的帐棚平安无事；你查看庄舍，也一无缺失。'),
('CNV', '约伯记', 18, 5, 25, '你必晓得你的后裔众多，子孙像地上的青草那样茂盛。'),
('CNV', '约伯记', 18, 5, 26, '你必全寿才归到坟墓去，如同禾捆到时就收起来。'),
('CNV', '约伯记', 18, 5, 27, '这道理我们已经查明实在是这样，你当聆听，也当明白。”'),
('CNV', '约伯记', 18, 6, 1, '于是约伯回答说：'),
('CNV', '约伯记', 18, 6, 2, '“但愿称称我的烦恼，把我的灾害一起放在天平上。'),
('CNV', '约伯记', 18, 6, 3, '现在这些都比海沙更重，所以我冒失发言。'),
('CNV', '约伯记', 18, 6, 4, '因为全能者的箭射中我，我的灵喝尽了箭的毒液，神的惊吓排阵攻击我。'),
('CNV', '约伯记', 18, 6, 5, '野驴有草料还会哀鸣吗？牛有饲料还会穷叫吗？'),
('CNV', '约伯记', 18, 6, 6, '淡而无盐的食物有什么好吃呢？蛋白有什么味道呢？'),
('CNV', '约伯记', 18, 6, 7, '这些使我恶心的食物，我必不肯尝。'),
('CNV', '约伯记', 18, 6, 8, '但愿我得着我所祈求的，愿神赐我所盼望的。'),
('CNV', '约伯记', 18, 6, 9, '愿他乐意把我压碎，愿他放手把我剪除。'),
('CNV', '约伯记', 18, 6, 10, '这样，我们得安慰，在无情的痛苦之中我还可以欢跃，因为我没有否认那圣者的言语。'),
('CNV', '约伯记', 18, 6, 11, '我有什么力量使我能等候呢？我的结局是什么好叫我忍耐呢？'),
('CNV', '约伯记', 18, 6, 12, '我的气力是石头一样吗？我的肉身是铜的吗？'),
('CNV', '约伯记', 18, 6, 13, '我里面不是无能自助吗？见识不是离我而去吗？'),
('CNV', '约伯记', 18, 6, 14, '朋友应该怜悯灰心的人，因为他舍弃了对全能者的敬畏。'),
('CNV', '约伯记', 18, 6, 15, '我的兄弟诡诈像干涸的溪流，又像流干的溪水；'),
('CNV', '约伯记', 18, 6, 16, '水流因冰块融化而混浊，有雪隐藏在其中。'),
('CNV', '约伯记', 18, 6, 17, '天气一暖溪水就消失，气候一热就干涸。'),
('CNV', '约伯记', 18, 6, 18, '商队顺溪而行，结果偏离原道，走到荒野之地而死亡。'),
('CNV', '约伯记', 18, 6, 19, '提玛的商队瞻望溪水，示巴的客旅等候水流。'),
('CNV', '约伯记', 18, 6, 20, '他们失望，因为所盼望的落了空；他们到达那里就灰心。'),
('CNV', '约伯记', 18, 6, 21, '现在你们就是这样，看见我的灾难就害怕。'),
('CNV', '约伯记', 18, 6, 22, '难道我说过‘请供给我’，或说‘取你们的财物馈赠我’吗？'),
('CNV', '约伯记', 18, 6, 23, '或我说过‘救我脱离敌人的手’，或说‘赎我脱离强暴人的手’吗？'),
('CNV', '约伯记', 18, 6, 24, '请指教，我就默不作声；请指示，我有什么过错。'),
('CNV', '约伯记', 18, 6, 25, '正直的言语多么有力！但你们的责备究竟责备什么呢？'),
('CNV', '约伯记', 18, 6, 26, '绝望人的话不过是风，你们还想批判吗？'),
('CNV', '约伯记', 18, 6, 27, '你们竟抽签得孤儿，拿朋友当货物。'),
('CNV', '约伯记', 18, 6, 28, '现在请你们看看我，我绝不当你们的面撒谎。'),
('CNV', '约伯记', 18, 6, 29, '请转意，不要不公道；请再转意，我还有道理在。'),
('CNV', '约伯记', 18, 6, 30, '我的舌上有不义吗？我的口不能辨别灾害吗？”'),
('CNV', '约伯记', 18, 7, 1, '“人在世上怎能没有劳役呢？他的日子不像雇工的日子吗？'),
('CNV', '约伯记', 18, 7, 2, '正如仆人切慕暮影，又像雇工盼望工价。'),
('CNV', '约伯记', 18, 7, 3, '照样，我有空虚的岁月，也有劳苦的黑夜为我派定。'),
('CNV', '约伯记', 18, 7, 4, '我躺下的时候，就说：‘我什么时候起来？’然而，长夜漫漫，我辗转反侧，直到黎明。'),
('CNV', '约伯记', 18, 7, 5, '我的肉体以虫子和土块为衣裳，我的皮肤裂开又流脓。'),
('CNV', '约伯记', 18, 7, 6, '我过的日子比梭还要快，在毫无盼望之中而结束。'),
('CNV', '约伯记', 18, 7, 7, '求你记念我的性命不过是一口气，我的眼必不再看见福乐。'),
('CNV', '约伯记', 18, 7, 8, '看我的，他的眼再也看不到我，你的眼要看我，我已经不在了。'),
('CNV', '约伯记', 18, 7, 9, '云彩怎样消散逝去，照样，人下阴间也不再上来。'),
('CNV', '约伯记', 18, 7, 10, '他不再回自己的家，故乡再也不认识他。'),
('CNV', '约伯记', 18, 7, 11, '因此，我不再禁止我的口，我要说出灵里的忧愁，倾诉心中的痛苦。'),
('CNV', '约伯记', 18, 7, 12, '我岂是海洋或是海怪，你竟然设守卫防备我？'),
('CNV', '约伯记', 18, 7, 13, '我若说：‘我的床必安慰我，我的榻必减轻我的苦情’，'),
('CNV', '约伯记', 18, 7, 14, '你就用梦惊扰我，又用异象惊吓我，'),
('CNV', '约伯记', 18, 7, 15, '以致我宁可窒息而死，也不肯保留我这一身的骨头。'),
('CNV', '约伯记', 18, 7, 16, '我厌恶自己，不愿永远活下去。任凭我吧，因为我的日子都是空虚的。'),
('CNV', '约伯记', 18, 7, 17, '人算什么，你竟看他为大，又把他放在心上；'),
('CNV', '约伯记', 18, 7, 18, '每天早晨你都鉴察他，每时每刻你也试验他。'),
('CNV', '约伯记', 18, 7, 19, '你到什么时候才转眼不看我，任凭我咽下唾沫呢？'),
('CNV', '约伯记', 18, 7, 20, '鉴察世人的主啊！我若犯了罪，跟你有什么关系呢？你为什么把我当作箭靶，使我以自己为重担呢？'),
('CNV', '约伯记', 18, 7, 21, '你为什么不赦免我的过犯，除去我的罪孽呢？现在我快要躺卧在尘土中，那时你寻找我，我却不在了。”'),
('CNV', '约伯记', 18, 8, 1, '书亚人比勒达回答说：'),
('CNV', '约伯记', 18, 8, 2, '“这些话你要说到几时，你口中的言语像狂风到几时呢？'),
('CNV', '约伯记', 18, 8, 3, '神怎会歪曲公平？全能者怎会屈枉公义？'),
('CNV', '约伯记', 18, 8, 4, '你的儿女若得罪了他，他就因他们的过犯撇弃他们。'),
('CNV', '约伯记', 18, 8, 5, '你若殷勤寻求神，向全能者恳求；'),
('CNV', '约伯记', 18, 8, 6, '你若又洁净又正直，他就必为你奋起，复兴你公义的居所。'),
('CNV', '约伯记', 18, 8, 7, '你起初虽然微小，到后来必定非常兴旺。'),
('CNV', '约伯记', 18, 8, 8, '请你查问前几代，留意他们列祖所查究的。'),
('CNV', '约伯记', 18, 8, 9, '我们只是昨天才有的，所以一无所知；我们在世的日子不过是影儿。'),
('CNV', '约伯记', 18, 8, 10, '难道他们不指教你，告诉你，从心里发出言语来吗？'),
('CNV', '约伯记', 18, 8, 11, '蒲草没有泥，怎能生长？芦苇没有水，怎能长大呢？'),
('CNV', '约伯记', 18, 8, 12, '尚青还没有割下来的时候，就比百草先枯槁。'),
('CNV', '约伯记', 18, 8, 13, '忘记神的，他们的末路也是这样；不敬虔的人，他的指望必成泡影。'),
('CNV', '约伯记', 18, 8, 14, '他所自恃的，必被折断；他所靠赖的，不过是蜘蛛网。'),
('CNV', '约伯记', 18, 8, 15, '他倚靠自己的家，家却立不住，他抓紧自己的家，家却存不久。'),
('CNV', '约伯记', 18, 8, 16, '他在阳光之下，枝润叶青，它的嫩枝长满园子，'),
('CNV', '约伯记', 18, 8, 17, '它的根缠绕石堆，扎入石地之中。'),
('CNV', '约伯记', 18, 8, 18, '他若从本处被拔除，那处就否认他，说：‘我没有见过你。’'),
('CNV', '约伯记', 18, 8, 19, '看哪，这就是他人生的乐趣，往后必有别的人从尘土中生出来。'),
('CNV', '约伯记', 18, 8, 20, '看哪，神必不离弃完全人，也不扶助行恶的人之手；'),
('CNV', '约伯记', 18, 8, 21, '他还要以欢笑充满你的口，以欢呼充满你的嘴。'),
('CNV', '约伯记', 18, 8, 22, '恨你的都必以羞耻为衣，恶人的帐棚必归于无有。”'),
('CNV', '约伯记', 18, 9, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 9, 2, '“我实在知道是这样，但是，人在神面前怎能算为公义呢？'),
('CNV', '约伯记', 18, 9, 3, '人若愿意与他辩论，连千分之一也答不出来。'),
('CNV', '约伯记', 18, 9, 4, '他心里有智慧，而且有极大的能力，有谁对他刚硬而平安无事呢？'),
('CNV', '约伯记', 18, 9, 5, '他在怒中移山翻冈；山冈却不知道；'),
('CNV', '约伯记', 18, 9, 6, '他使大地震动离开本处，大地的柱子就摇撼；'),
('CNV', '约伯记', 18, 9, 7, '他吩咐太阳，太阳就不上升，又封闭众星；'),
('CNV', '约伯记', 18, 9, 8, '他独自铺开苍天，步行在海浪之上；'),
('CNV', '约伯记', 18, 9, 9, '他造北斗与参星，昴星和南方的星座；'),
('CNV', '约伯记', 18, 9, 10, '他所行的大事无法测度，所行的奇事不可胜数。'),
('CNV', '约伯记', 18, 9, 11, '他行过我身边，我却看不见；他掠过去，我竟不觉察。'),
('CNV', '约伯记', 18, 9, 12, '他夺取，谁能拦阻他？谁敢问他：‘你干什么？’'),
('CNV', '约伯记', 18, 9, 13, '神必不抑制他的怒气，海怪拉哈伯的助手都俯伏在他以下。'),
('CNV', '约伯记', 18, 9, 14, '何况我呢？我怎敢回答他，措辞与他辩论呢？'),
('CNV', '约伯记', 18, 9, 15, '即使我有理，也不敢回答，只向那审判我的求怜悯；'),
('CNV', '约伯记', 18, 9, 16, '即使我呼求，他也回答我，我还是不信他会垂听我的声音。'),
('CNV', '约伯记', 18, 9, 17, '他用暴风伤害我，无缘无故加添我的创伤。'),
('CNV', '约伯记', 18, 9, 18, '他不让我喘一口气，却使我饱尝苦楚。'),
('CNV', '约伯记', 18, 9, 19, '若论力量，他多么强大，若论诉讼，他说：‘谁能把我传来？’'),
('CNV', '约伯记', 18, 9, 20, '即使我有理，我的口还是定我有罪；即使我完全，我的口还是判我乖谬。'),
('CNV', '约伯记', 18, 9, 21, '我虽然完全，却不顾我自己，倒厌恶我的生命。'),
('CNV', '约伯记', 18, 9, 22, '所以我说，善恶都是一样，完全人和恶人，他都灭尽。'),
('CNV', '约伯记', 18, 9, 23, '灾祸忽然把人杀害的时候，他就必嘲笑无辜人的遭遇。'),
('CNV', '约伯记', 18, 9, 24, '全世界交在恶人的手中，他蒙蔽世上审判官的脸，如果不是他，那么是谁呢？'),
('CNV', '约伯记', 18, 9, 25, '我的日子过得比信差还快，飞快逝去，不见福乐。'),
('CNV', '约伯记', 18, 9, 26, '我的日子消逝有如快船，好像俯冲猛扑食物的鹰。'),
('CNV', '约伯记', 18, 9, 27, '我若说：‘我要忘记我的苦情，要除去愁容，面露喜乐。’'),
('CNV', '约伯记', 18, 9, 28, '我就惧怕我的一切痛苦，因为我知道你必不以我为无辜。'),
('CNV', '约伯记', 18, 9, 29, '我既然被定为有罪，又何必徒然劳苦呢？'),
('CNV', '约伯记', 18, 9, 30, '我若用雪水洗净我的身，又用碱水洁净我的手，'),
('CNV', '约伯记', 18, 9, 31, '你还是把我扔入坑中，连我的衣服也憎恶我。'),
('CNV', '约伯记', 18, 9, 32, '他不像我是个人，使我可以答他，让我们一起对簿公堂。'),
('CNV', '约伯记', 18, 9, 33, '我俩之间并没有仲裁者，能够按手在我们双方身上。'),
('CNV', '约伯记', 18, 9, 34, '愿他使他的刑杖离开我，愿他可畏的威严不惊吓我，'),
('CNV', '约伯记', 18, 9, 35, '我就说话，也不怕他，因为我本身并不是这种人。”'),
('CNV', '约伯记', 18, 10, 1, '“我厌恶我的性命，我要尽情吐苦水，倾诉心中的痛苦。'),
('CNV', '约伯记', 18, 10, 2, '我要对神说：不要定我有罪，请告诉我你为什么与我相争。'),
('CNV', '约伯记', 18, 10, 3, '压迫无辜，又弃绝你手所作的，却喜悦恶人的计谋，你都以为美吗？'),
('CNV', '约伯记', 18, 10, 4, '你的眼不是肉眼，你观看不像人观看，'),
('CNV', '约伯记', 18, 10, 5, '你的日子不如人的日子，你的年岁不像人的年岁，'),
('CNV', '约伯记', 18, 10, 6, '以致你追究我的罪孽，细察我的罪过吗？'),
('CNV', '约伯记', 18, 10, 7, '你知道我并没有罪，但没有人能救我脱离你的手。'),
('CNV', '约伯记', 18, 10, 8, '你的手塑我造我，但一转过来你就要毁灭我。'),
('CNV', '约伯记', 18, 10, 9, '求你记念你造我如抟泥，你还要使我归于尘土吗？'),
('CNV', '约伯记', 18, 10, 10, '你不是把我倒出来像倒奶，又使我凝结像奶酪凝固吗？'),
('CNV', '约伯记', 18, 10, 11, '你以皮肉为衣给我穿上，以筋骨接络我；'),
('CNV', '约伯记', 18, 10, 12, '你赐我生命，又向我施慈爱，你的眷顾保守我的心灵。'),
('CNV', '约伯记', 18, 10, 13, '这些事你都藏在你的心里，我知道这是你的旨意。'),
('CNV', '约伯记', 18, 10, 14, '我若犯罪，你就鉴察，绝不赦免我的罪孽；'),
('CNV', '约伯记', 18, 10, 15, '我若有罪，就有祸了；我若有理，也不敢抬头，饱尝羞辱，看看自己的苦难。'),
('CNV', '约伯记', 18, 10, 16, '我若昂首自得，你便如狮子猎我（“如狮子猎我”或译：“猎我如猎狮子”），又在我身上彰显你惊人的大能。'),
('CNV', '约伯记', 18, 10, 17, '你重新设立见证攻击我，对我加增你的忿怒，派兵轮流攻击我。'),
('CNV', '约伯记', 18, 10, 18, '你为什么使我出母胎呢？我不如死去，无人得见我，'),
('CNV', '约伯记', 18, 10, 19, '这样，就像从来没有我一样，一出母腹就被送入坟墓。'),
('CNV', '约伯记', 18, 10, 20, '我的日子不是很少吗？请住手，转离我，使我在往黑暗死荫之地以先，'),
('CNV', '约伯记', 18, 10, 21, '在去而不返之前，可以喜乐片刻；'),
('CNV', '约伯记', 18, 10, 22, '那地黑暗，如死荫的幽暗，毫无秩序，即使有光也像幽暗。”'),
('CNV', '约伯记', 18, 11, 1, '拿玛人琐法回答说：'),
('CNV', '约伯记', 18, 11, 2, '“这许多的话怎可不回答，多嘴多舌的人怎能算为义呢？'),
('CNV', '约伯记', 18, 11, 3, '你胡言乱语可使人不作声吗？你嘲笑的时候，无人责备吗？'),
('CNV', '约伯记', 18, 11, 4, '你说：‘我的道理纯全，我在你眼前洁净。’'),
('CNV', '约伯记', 18, 11, 5, '但愿神说话，愿他开口跟你说话，'),
('CNV', '约伯记', 18, 11, 6, '把智慧的奥秘向你显明，因为真的智慧有两面。你当知道神已忘记了你一部分的罪孽。'),
('CNV', '约伯记', 18, 11, 7, '神高深莫测之事你怎能查出呢？全能者的终极你怎能洞悉呢？'),
('CNV', '约伯记', 18, 11, 8, '他的智慧高于诸天，你能作什么呢？比阴间还深，你怎能识透？'),
('CNV', '约伯记', 18, 11, 9, '他的智慧比地长，比海宽。'),
('CNV', '约伯记', 18, 11, 10, '他若过来把人囚禁，召人受审，谁能阻止他呢？'),
('CNV', '约伯记', 18, 11, 11, '因为他认识虚谎的人，他看见欺诈，怎能不鉴察？'),
('CNV', '约伯记', 18, 11, 12, '虚妄的人悟出慧心，就像野驴生子为人。'),
('CNV', '约伯记', 18, 11, 13, '你若心里归向他，又向他伸手祷告；'),
('CNV', '约伯记', 18, 11, 14, '你若远远地除掉你手里的欺诈，不让不义居在你的帐棚里；'),
('CNV', '约伯记', 18, 11, 15, '那么你必仰面，毫无愧色；你也必坚定稳妥，无所惧怕。'),
('CNV', '约伯记', 18, 11, 16, '你必忘记你的苦楚，回忆好像逝去的流水，'),
('CNV', '约伯记', 18, 11, 17, '你们的人生必明亮如正午，虽然黑暗仍像早晨。'),
('CNV', '约伯记', 18, 11, 18, '因为有指望，你必安稳，你必四处巡查，安然睡觉。'),
('CNV', '约伯记', 18, 11, 19, '你躺卧，不受惊吓，必有很多人求你的情面。'),
('CNV', '约伯记', 18, 11, 20, '但恶人的眼目必昏花，逃亡之路也必断绝，他们的指望就是最后的一口气。”'),
('CNV', '约伯记', 18, 12, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 12, 2, '“你们真的是有知识的民，你们死了，智慧也跟你们一同灭亡。'),
('CNV', '约伯记', 18, 12, 3, '但我也有聪明像你们一样，我并非不及你们，像你们所说的这些事，有谁不晓得呢？'),
('CNV', '约伯记', 18, 12, 4, '我这求告神，又蒙他应允的，竟成为朋友的笑柄，公义完全的人竟成为笑柄，'),
('CNV', '约伯记', 18, 12, 5, '平静的人心中藐视灾祸，作将滑跌者的分。'),
('CNV', '约伯记', 18, 12, 6, '强盗的帐幕兴旺，惹神发怒的安稳，神的手赏赐他们。'),
('CNV', '约伯记', 18, 12, 7, '你且问走兽，走兽必指教你，又问空中的飞鸟，飞鸟必告诉你；'),
('CNV', '约伯记', 18, 12, 8, '或向地说话，地必指教你，海中的鱼也必向你说明。'),
('CNV', '约伯记', 18, 12, 9, '从这一切看来，谁不知道，是耶和华的手作成这事的呢？'),
('CNV', '约伯记', 18, 12, 10, '活物的生命与全人类的气息，都在耶和华的手中。'),
('CNV', '约伯记', 18, 12, 11, '耳朵不是试验说话，好像上膛尝试食物吗？'),
('CNV', '约伯记', 18, 12, 12, '你们说：老年的有智慧，长寿的有聪明。'),
('CNV', '约伯记', 18, 12, 13, '他有智慧与能力，又有谋略与聪明。'),
('CNV', '约伯记', 18, 12, 14, '他所拆毁的，就不能重建，他所囚禁的，就不能释放。'),
('CNV', '约伯记', 18, 12, 15, '他若把水阻截，水就干涸，他再把水放出，水就使地翻倒。'),
('CNV', '约伯记', 18, 12, 16, '他有大能与智谋，受骗的与骗人的，都是属他的。'),
('CNV', '约伯记', 18, 12, 17, '他把谋士剥衣掳去，并且愚弄审判官。'),
('CNV', '约伯记', 18, 12, 18, '他解开了君王绑人的绳索，又用腰布捆绑君王的腰。'),
('CNV', '约伯记', 18, 12, 19, '他把祭司剥衣掳去，倾覆有权有势的人。'),
('CNV', '约伯记', 18, 12, 20, '他除掉忠信人的言论，又除去老年人的辨别力。'),
('CNV', '约伯记', 18, 12, 21, '他把羞辱倾倒在王子上，又松开壮士的腰带。'),
('CNV', '约伯记', 18, 12, 22, '他从黑暗中彰显奥秘，把死荫领进光中。'),
('CNV', '约伯记', 18, 12, 23, '他使邦国兴盛，又毁灭他们，扩张邦国，又把他们掳去。'),
('CNV', '约伯记', 18, 12, 24, '他除掉地上人民中首领的悟性，使他们在无路的荒野之地飘流。'),
('CNV', '约伯记', 18, 12, 25, '他们在黑暗无光中摸索，他使他们飘泊无定像醉汉一样。”'),
('CNV', '约伯记', 18, 13, 1, '“这一切我的眼睛都见过，我的耳朵都听过，而且明白。'),
('CNV', '约伯记', 18, 13, 2, '你们所知道的我也知道，我并非不及你们。'),
('CNV', '约伯记', 18, 13, 3, '但我要对全能者说话，我愿与神辩论。'),
('CNV', '约伯记', 18, 13, 4, '你们都是捏造谎言的，都是无用的医生。'),
('CNV', '约伯记', 18, 13, 5, '但愿你们完全不作声，这样才算为你们的智慧。'),
('CNV', '约伯记', 18, 13, 6, '请你们听我的辩论，留心听我嘴唇的申诉。'),
('CNV', '约伯记', 18, 13, 7, '你们要为神说不义的言语吗？你们要为他说诡诈的话吗？'),
('CNV', '约伯记', 18, 13, 8, '你们要徇神的情面吗？要为神争辩吗？'),
('CNV', '约伯记', 18, 13, 9, '他把你们查出来，这是好吗？人怎样哄骗人，你们也怎样哄骗神吗？'),
('CNV', '约伯记', 18, 13, 10, '你们若暗中徇情面，他必然责备你们。'),
('CNV', '约伯记', 18, 13, 11, '他的尊严不是叫你们惧怕吗？他的惊吓不是临到你们吗？'),
('CNV', '约伯记', 18, 13, 12, '你们背诵的格言都是炉灰的格言，你们的辩护都是泥土的辩护。'),
('CNV', '约伯记', 18, 13, 13, '你们要静默，离开我，好让我说话，然后不论什么事也好，让它临到我吧。'),
('CNV', '约伯记', 18, 13, 14, '我已把我的肉挂在自己的牙上，把我的命放在自己的手中。'),
('CNV', '约伯记', 18, 13, 15, '他必杀我，我没有指望了，我必在他面前辩明我所行的；'),
('CNV', '约伯记', 18, 13, 16, '这要成为我的拯救，因为不敬虔的人不能到他面前来。'),
('CNV', '约伯记', 18, 13, 17, '你们当细听我的言语，让我的宣言进入你们的耳中。'),
('CNV', '约伯记', 18, 13, 18, '现在我已呈上我的案件，我知道我自己得算为义，'),
('CNV', '约伯记', 18, 13, 19, '有谁与我相争呢？若有，我就默然不言，气绝而亡。'),
('CNV', '约伯记', 18, 13, 20, '只要不对我行两件事，我就不躲开你的面，'),
('CNV', '约伯记', 18, 13, 21, '就是把你的手缩回，远离我身，又不使你的惊惧威吓我。'),
('CNV', '约伯记', 18, 13, 22, '这样，你一呼叫，我就回答，或是让我说话，你回答我。'),
('CNV', '约伯记', 18, 13, 23, '我的罪孽与罪过有多少呢？求你让我知道我的过犯与罪过。'),
('CNV', '约伯记', 18, 13, 24, '你为什么掩面，把我当作你的仇敌呢？'),
('CNV', '约伯记', 18, 13, 25, '你要使被风吹动的树叶战抖吗？你要追赶枯干了的碎秸吗？'),
('CNV', '约伯记', 18, 13, 26, '你记录判词攻击我，又使我承当我幼年的罪孽；'),
('CNV', '约伯记', 18, 13, 27, '你把我的两脚上了木狗，又鉴察我一切所行的，为我的脚掌定界限。'),
('CNV', '约伯记', 18, 13, 28, '我的生命像破灭腐朽之物，又像虫蛀的衣服。”'),
('CNV', '约伯记', 18, 14, 1, '“妇人所生的日子短少，满有搅扰；'),
('CNV', '约伯记', 18, 14, 2, '他生长如花，又遭割下；他飞去如影，并不停留。'),
('CNV', '约伯记', 18, 14, 3, '这样的人你还睁眼看他，又把他带到你跟前受审吗？'),
('CNV', '约伯记', 18, 14, 4, '谁能使洁净出于污秽呢？无人有此本事。'),
('CNV', '约伯记', 18, 14, 5, '人的日子既然被限定，他的月数亦在乎你，你也定下他的界限，使他不能越过。'),
('CNV', '约伯记', 18, 14, 6, '就求你转眼不看他，使他得歇息（“使他得歇息”或译：“不去管他”），直等到他像雇工一样享受他的日子。'),
('CNV', '约伯记', 18, 14, 7, '树木常有希望，树木若被砍下，也会再发芽，嫩枝仍生长不息。'),
('CNV', '约伯记', 18, 14, 8, '虽然树根衰老在地里，树干也枯死在土中，'),
('CNV', '约伯记', 18, 14, 9, '一有水气，就会萌芽，又生长枝条如新栽的树一样。'),
('CNV', '约伯记', 18, 14, 10, '人死了，就化为乌有；人一气绝就不在了。'),
('CNV', '约伯记', 18, 14, 11, '海洋中的水消失，江河枯竭干涸，'),
('CNV', '约伯记', 18, 14, 12, '人也是这样一躺下去，就不再起来，直到天都没有了还不醒过来，也不能从睡眠中被唤醒。'),
('CNV', '约伯记', 18, 14, 13, '但愿你把我藏在阴间，把我隐藏，直到你的怒气过去；愿你为我定一个期限，好记念我。'),
('CNV', '约伯记', 18, 14, 14, '人若死了，怎能再活呢？我要在我一切劳苦的日子等待，等到我得释放的时候来到。'),
('CNV', '约伯记', 18, 14, 15, '你一呼叫，我就回答你，你必渴慕你手所作的。'),
('CNV', '约伯记', 18, 14, 16, '但现在你数点我的脚步，必不再鉴察我的罪过，'),
('CNV', '约伯记', 18, 14, 17, '我的过犯被你封在囊中，我的罪孽你以灰泥遮盖了。'),
('CNV', '约伯记', 18, 14, 18, '山崩下坠，岩石挪开原处；'),
('CNV', '约伯记', 18, 14, 19, '流水磨蚀石头，水的泛溢冲去地上的尘土，你也这样灭绝人的指望。'),
('CNV', '约伯记', 18, 14, 20, '你永远胜过人，人就去世，你改变他的容貌，把他遣走。'),
('CNV', '约伯记', 18, 14, 21, '他的儿女得尊荣，他并不晓得，他们降为卑，他也不觉得，'),
('CNV', '约伯记', 18, 14, 22, '只觉自己身上的痛苦，为自己悲哀。”'),
('CNV', '约伯记', 18, 15, 1, '提幔人以利法回答说：'),
('CNV', '约伯记', 18, 15, 2, '“智慧人怎可用虚空的知识来回答呢？怎可用东风充满自己的肚腹呢？'),
('CNV', '约伯记', 18, 15, 3, '他怎可用无益的话，或无用的言词辩论呢？'),
('CNV', '约伯记', 18, 15, 4, '你还废弃了敬畏神的心，拦阻了在神面前的默祷。'),
('CNV', '约伯记', 18, 15, 5, '你的罪孽教导你的口，你采用诡诈人的舌头，'),
('CNV', '约伯记', 18, 15, 6, '是你的口定你的罪，不是我，你嘴唇作见证控告你。'),
('CNV', '约伯记', 18, 15, 7, '你是头一个生下来的人吗？你在诸山未有之前诞生的吗？'),
('CNV', '约伯记', 18, 15, 8, '你曾聆听过神的密旨吗？你可以独占智慧吗？'),
('CNV', '约伯记', 18, 15, 9, '有什么是你知道，我们不知道的呢？你明白，我们不明白的呢？'),
('CNV', '约伯记', 18, 15, 10, '我们中间有白头发的，又有年纪老的，年岁比你的父亲还大。'),
('CNV', '约伯记', 18, 15, 11, '神的安慰对你是否太少？温柔的言语对你是否不足？'),
('CNV', '约伯记', 18, 15, 12, '你的心为什么迷惑你，你的眼为什么闪出怒光，'),
('CNV', '约伯记', 18, 15, 13, '以致你的心灵转过来抗拒神，从你的口中竟发出这样的话？'),
('CNV', '约伯记', 18, 15, 14, '人是什么，能算为洁净吗？妇人所生的，能算为公义吗？'),
('CNV', '约伯记', 18, 15, 15, '神不信任他的众天使，在他看来，诸天也不洁净，'),
('CNV', '约伯记', 18, 15, 16, '何况那可憎又腐败，喝罪孽如同喝水的世人呢？'),
('CNV', '约伯记', 18, 15, 17, '我要告诉你，你要听我说。我所看见的，我要述说，'),
('CNV', '约伯记', 18, 15, 18, '就是智慧人所传讲的，并没有隐瞒从他们列祖所领受的。'),
('CNV', '约伯记', 18, 15, 19, '这地唯独赐给列祖，并没有外族人从他们中间经过。'),
('CNV', '约伯记', 18, 15, 20, '恶人一生饱受痛苦，一生的年数都为强暴留存。'),
('CNV', '约伯记', 18, 15, 21, '恐怖之声常在他的耳中，太平的时候，强盗就来袭击他。'),
('CNV', '约伯记', 18, 15, 22, '他不信他能从黑暗中转回，自己留给刀剑杀害。'),
('CNV', '约伯记', 18, 15, 23, '他飘流觅食说：‘哪里有呢？’他知道黑暗的日子已经临近了。'),
('CNV', '约伯记', 18, 15, 24, '患难与困苦使他惊惶，又胜过他，像君王预备上阵攻击一样。'),
('CNV', '约伯记', 18, 15, 25, '因为他向神挥拳，向全能者逞强，'),
('CNV', '约伯记', 18, 15, 26, '用盾牌的厚凸面，硬着颈项向他直闯。'),
('CNV', '约伯记', 18, 15, 27, '因为他以自己的脂肪蒙脸，腰上积满肥油。'),
('CNV', '约伯记', 18, 15, 28, '他住在被毁的城邑里，住在没有人居住，注定快要成为乱堆的房屋里。'),
('CNV', '约伯记', 18, 15, 29, '他不再富足，他的财富不能持久，他的产业也不得在地上扩张，'),
('CNV', '约伯记', 18, 15, 30, '他不能离开黑暗，火焰必烧干他的嫩枝，他必因神口中的气而离去。'),
('CNV', '约伯记', 18, 15, 31, '他不信靠虚假，自己欺骗自己，因为虚假必成为他的报应。'),
('CNV', '约伯记', 18, 15, 32, '他的日期未到以先，这事必成全，他的枝子，也不青绿。'),
('CNV', '约伯记', 18, 15, 33, '他必像葡萄树未熟的葡萄掉落一样，又如橄榄树的花朵一开就谢一般。'),
('CNV', '约伯记', 18, 15, 34, '因为不敬虔的人必不能生育，火必吞灭收受贿赂者的帐幕。'),
('CNV', '约伯记', 18, 15, 35, '他们所怀的是罪恶，所生的是罪孽，他们腹中所预备的是诡诈。”'),
('CNV', '约伯记', 18, 16, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 16, 2, '“像这样的话，我听了很多；你们都是叫人愁烦的安慰者。'),
('CNV', '约伯记', 18, 16, 3, '虚空的言语，有穷尽吗？或有什么惹你答个不休的呢？'),
('CNV', '约伯记', 18, 16, 4, '你们若处在我的景况，我也能像你们那样说话，我也能砌辞攻击你们，并且能向你们摇头。'),
('CNV', '约伯记', 18, 16, 5, '我能用口鼓励你们，我嘴唇的安慰，能缓和你们的痛苦。'),
('CNV', '约伯记', 18, 16, 6, '我若说话，痛苦仍不消解，我若闭口不说，痛苦也不离开我。'),
('CNV', '约伯记', 18, 16, 7, '现在神使我困倦，‘你蹂躏了我的全家，'),
('CNV', '约伯记', 18, 16, 8, '又把我捆绑起来。’这就作为证据；我身体的枯瘦也当面作证反对我。'),
('CNV', '约伯记', 18, 16, 9, '他的怒气撕裂我，攻击我；他向我咬牙切齿，我的敌人以锐利的眼光看着我。'),
('CNV', '约伯记', 18, 16, 10, '他们向我大大张嘴，以蔑视的态度打我的脸颊，联合一起攻击我。'),
('CNV', '约伯记', 18, 16, 11, '神把我交给不义的人，把我丢在恶人的手中。'),
('CNV', '约伯记', 18, 16, 12, '我本来安逸，他却把我压碎；掐着我的颈项，把我摔碎；又把我当作他的箭靶。'),
('CNV', '约伯记', 18, 16, 13, '他的弓箭手四面包围我，他剖开我的腰子，全不顾惜，把我的胆倾倒在地上。'),
('CNV', '约伯记', 18, 16, 14, '他把我破伤，在破口上又加破伤，如勇士一般向我直冲。'),
('CNV', '约伯记', 18, 16, 15, '我把麻布缝在我的皮肤上，把我的角插入尘土中。'),
('CNV', '约伯记', 18, 16, 16, '我的脸因哭泣而发红，在我的眼皮上满是黑影。'),
('CNV', '约伯记', 18, 16, 17, '然而在我的手中没有强暴，我的祷告也是清洁的。'),
('CNV', '约伯记', 18, 16, 18, '地啊，不要遮盖我的血；不要让我的哀求有停留的地方。'),
('CNV', '约伯记', 18, 16, 19, '现今，在天上有我的见证，在高天之上，有我的证人。'),
('CNV', '约伯记', 18, 16, 20, '讥笑我的，就是我的朋友，我的眼向神流泪。'),
('CNV', '约伯记', 18, 16, 21, '但愿人可以为人与神分辩，正如世人为朋友辩白一样。'),
('CNV', '约伯记', 18, 16, 22, '因为我的年数将尽，我快要走上那条一去不返的路。”'),
('CNV', '约伯记', 18, 17, 1, '“我的气息将断，我的日子快尽，坟墓已为我预备好了。'),
('CNV', '约伯记', 18, 17, 2, '真有嘲笑人的在我这里，我的眼看着他们的悖逆。'),
('CNV', '约伯记', 18, 17, 3, '愿你给我保证，亲自为我作保；除你以外有谁肯与我击掌作保呢？'),
('CNV', '约伯记', 18, 17, 4, '你蒙蔽了他们的心，不让他们明白；因此你必不高举他们。'),
('CNV', '约伯记', 18, 17, 5, '为分产业而控告朋友的，他子孙的眼睛也要昏花。'),
('CNV', '约伯记', 18, 17, 6, '他使我成为民众的笑柄，人人都吐唾沫在我的脸上。'),
('CNV', '约伯记', 18, 17, 7, '我的眼睛因忧愁而昏花，我的身体瘦骨如柴。'),
('CNV', '约伯记', 18, 17, 8, '正直人必因此惊讶，要被激发起来，攻击不敬虔的人。'),
('CNV', '约伯记', 18, 17, 9, '义人必坚守自己的道路，手洁的人要力上加力。'),
('CNV', '约伯记', 18, 17, 10, '然而你们众人，可以再来，在你们中间我找不到一个有智慧的人。'),
('CNV', '约伯记', 18, 17, 11, '我的日子已过，我的谋算和我心中所想的都已粉碎。'),
('CNV', '约伯记', 18, 17, 12, '他们把黑夜变为白昼，因为黑暗的缘故，他们就说：‘光明临近了。’'),
('CNV', '约伯记', 18, 17, 13, '我若等待阴间作我的家，在黑暗中铺张我的床榻；'),
('CNV', '约伯记', 18, 17, 14, '我若对深坑说：‘你是我的父亲’，对虫说：‘你是我的母亲，我的姊妹’，'),
('CNV', '约伯记', 18, 17, 15, '那么，我的指望在哪里呢？我的指望谁能看得见呢？'),
('CNV', '约伯记', 18, 17, 16, '等到安息在尘土中的时候，那些指望必下到阴间的门闩那里。”'),
('CNV', '约伯记', 18, 18, 1, '书亚人比勒达回答说：'),
('CNV', '约伯记', 18, 18, 2, '“你寻索言语要到几时呢？先想清楚，然后我们再说吧。'),
('CNV', '约伯记', 18, 18, 3, '我们为什么算为牲畜？为什么在你的眼中看为污秽呢？'),
('CNV', '约伯记', 18, 18, 4, '你这因怒气而撕裂自己的，难道大地要为你的缘故被丢弃，磐石要挪移离开原处吗？'),
('CNV', '约伯记', 18, 18, 5, '恶人的灯必要熄灭，他的火焰必不照耀；'),
('CNV', '约伯记', 18, 18, 6, '他帐棚中的光要变为黑暗，上面的灯也必熄灭。'),
('CNV', '约伯记', 18, 18, 7, '他的脚步必然狭窄，自己的计谋必把他绊倒；'),
('CNV', '约伯记', 18, 18, 8, '他的脚送自己进入网罗，他走在陷阱之上。'),
('CNV', '约伯记', 18, 18, 9, '圈套要缠住他的脚跟，网罗要罩在他身上。'),
('CNV', '约伯记', 18, 18, 10, '活扣为他藏在地里，羁绊为他埋在路上。'),
('CNV', '约伯记', 18, 18, 11, '惊骇四面恐吓他，并且追赶他的脚踪。'),
('CNV', '约伯记', 18, 18, 12, '他的气力因饥饿衰败，祸患预备使他跌倒。'),
('CNV', '约伯记', 18, 18, 13, '灾祸侵蚀了他大部分的皮肤，死亡的长子吃掉了他的肢体。'),
('CNV', '约伯记', 18, 18, 14, '他要从他倚靠的帐棚中被拔出来，被带到惊骇的王那里，'),
('CNV', '约伯记', 18, 18, 15, '不属他的住在他的帐棚里，硫磺撒在他的居所之上。'),
('CNV', '约伯记', 18, 18, 16, '他下面的根枯干，上面的枝子凋谢。'),
('CNV', '约伯记', 18, 18, 17, '他令人怀念的都从地上灭没，他的名字不再留存在田上。'),
('CNV', '约伯记', 18, 18, 18, '他们把他从光明中赶到黑暗里，又把他从世界中赶出去。'),
('CNV', '约伯记', 18, 18, 19, '在本族中他无子无孙，在他寄居之地，也没有生存的人。'),
('CNV', '约伯记', 18, 18, 20, '西方的人因他的日子惊讶，东方的人也战栗不已。'),
('CNV', '约伯记', 18, 18, 21, '不义的人之住所实在是这样，这就是不认识神的人的收场。”'),
('CNV', '约伯记', 18, 19, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 19, 2, '“你们叫我受苦要到几时呢？用话压碎我要到几时呢？'),
('CNV', '约伯记', 18, 19, 3, '你们已经十次侮辱我，你们苛刻地对我，也不觉得羞耻。'),
('CNV', '约伯记', 18, 19, 4, '即使我真的有过错，由我承担好了。'),
('CNV', '约伯记', 18, 19, 5, '你们若真的妄自尊大攻击我，用我的羞辱来证明我的不是，'),
('CNV', '约伯记', 18, 19, 6, '那么，就知道是神颠倒我的案件，用他的网圈住我。'),
('CNV', '约伯记', 18, 19, 7, '我呼叫‘强暴！’却没有回答；我呼求，却得不到公断。'),
('CNV', '约伯记', 18, 19, 8, '神用篱笆拦阻我的道路，使我不能经过；他又使黑暗笼罩我的路。'),
('CNV', '约伯记', 18, 19, 9, '他从我身上剥去我的荣耀，又挪去我头上的冠冕。'),
('CNV', '约伯记', 18, 19, 10, '他四面拆毁我，我就离世，他又把我这指望如树枝一样拔出来。'),
('CNV', '约伯记', 18, 19, 11, '他的怒气向我发作，把我看作他的敌人；'),
('CNV', '约伯记', 18, 19, 12, '他的军队一起上来，他们建筑高的斜道（“高的斜道”直译是“他们的道路”）攻击我，在我的帐棚周围安营。'),
('CNV', '约伯记', 18, 19, 13, '他使我的族人远离我，使我熟悉的人完全与我疏远。'),
('CNV', '约伯记', 18, 19, 14, '我的亲戚离弃我，我的朋友忘记我；'),
('CNV', '约伯记', 18, 19, 15, '在我家中寄居的和我的婢女，都把我当作外人，我在他们的眼中是个外族人。'),
('CNV', '约伯记', 18, 19, 16, '我呼唤仆人，他不回答，我得用口哀求他。'),
('CNV', '约伯记', 18, 19, 17, '妻子厌恶我的气息，同胞兄弟也厌弃我，'),
('CNV', '约伯记', 18, 19, 18, '连小孩子也藐视我，我一起来，他们就讥笑我；'),
('CNV', '约伯记', 18, 19, 19, '我所有的密友都憎恶我，我所爱的人也向我反脸。'),
('CNV', '约伯记', 18, 19, 20, '我的骨头紧贴着皮肉，我只剩牙皮逃过大难。'),
('CNV', '约伯记', 18, 19, 21, '我的朋友啊！求你们怜悯我，怜悯我吧！因为神的手击打了我。'),
('CNV', '约伯记', 18, 19, 22, '你们为什么有如神那样逼迫我？还不因吃我的肉感到满足吗？'),
('CNV', '约伯记', 18, 19, 23, '但愿我的话现在都写下，都刻在书简上，'),
('CNV', '约伯记', 18, 19, 24, '用铁笔又用铅，永远刻在磐石上。'),
('CNV', '约伯记', 18, 19, 25, '我知道我的救赎主活着，最后他必在地上兴起（“最后他必在地上兴起”或译：“最后他必站立在地上”）。'),
('CNV', '约伯记', 18, 19, 26, '我的皮肉遭受毁坏以后，这事就要发生，我必在肉体以外得见神。'),
('CNV', '约伯记', 18, 19, 27, '我必见他在我身边，我要亲眼见他，并非外人，我的心肠在我里面渴想极了。'),
('CNV', '约伯记', 18, 19, 28, '你们若说：‘惹事的根既然在他，我们要怎样逼迫他呢？’'),
('CNV', '约伯记', 18, 19, 29, '你们就当惧怕刀剑，因为这些罪孽带来刀剑的惩罚，好使你们知道有审判。”'),
('CNV', '约伯记', 18, 20, 1, '拿玛人琐法回答说：'),
('CNV', '约伯记', 18, 20, 2, '“我的心思烦扰叫我回话，因为我内心急躁。'),
('CNV', '约伯记', 18, 20, 3, '我听见了那羞辱我的责备，心灵因着我的悟性回答我。'),
('CNV', '约伯记', 18, 20, 4, '你不知亘古以来，自从地上有人以来，'),
('CNV', '约伯记', 18, 20, 5, '恶人的欢呼并不长久，不敬虔者的快乐，不过是暂时的吗？'),
('CNV', '约伯记', 18, 20, 6, '虽然他的高贵上达于天，他的头直插云霄，'),
('CNV', '约伯记', 18, 20, 7, '他必永远灭亡像自己的粪一般，素来看见他的，都要说：‘他在哪里呢？’'),
('CNV', '约伯记', 18, 20, 8, '他必如梦一般飞逝，人再也找不着他，他必被赶去如夜间的异象，'),
('CNV', '约伯记', 18, 20, 9, '亲眼见过他的，必不再见他，他的本处也必看不见他。'),
('CNV', '约伯记', 18, 20, 10, '他的儿女必向穷人求恩，他们的手要退还他不义之财，'),
('CNV', '约伯记', 18, 20, 11, '他的骨头虽然充满青春活力，却必与他一同躺卧在尘土中。'),
('CNV', '约伯记', 18, 20, 12, '邪恶在他的口中虽然甘甜，他把邪恶藏在自己的舌下。'),
('CNV', '约伯记', 18, 20, 13, '他虽然爱惜不舍，含在口中，'),
('CNV', '约伯记', 18, 20, 14, '然而他的食物在他腹中却要变坏，在他里面成为眼镜蛇的毒汁。'),
('CNV', '约伯记', 18, 20, 15, '他吞下了财宝，还要把它吐出来，神要从他的腹中把它掏出来，'),
('CNV', '约伯记', 18, 20, 16, '他必吸吮眼镜蛇的毒液，腹蛇的舌头必把他杀死。'),
('CNV', '约伯记', 18, 20, 17, '他必不得看见江河，就是流蜜与奶的江河。'),
('CNV', '约伯记', 18, 20, 18, '他劳苦所得的必归别人，自己却不得吃用；他交易得来的财利，自己却不得享用。'),
('CNV', '约伯记', 18, 20, 19, '因为他欺压穷人，不顾他们，强抢不是自己建造的房屋。'),
('CNV', '约伯记', 18, 20, 20, '因为他内心没有安宁，他不能保存他喜爱的东西。'),
('CNV', '约伯记', 18, 20, 21, '他吃得一无所剩，所以他的福乐不能持久；'),
('CNV', '约伯记', 18, 20, 22, '他在满足有余的时候，陷入困境，受过苦的人的手都临到他身上。'),
('CNV', '约伯记', 18, 20, 23, '他正在填饱肚腹的时候，神就把猛烈的怒气降在他身上，他正在吃饭的时候，神要把这怒气如雨降在他身上。'),
('CNV', '约伯记', 18, 20, 24, '他要逃避铁制的兵器，但铜弓的箭必把他射穿；'),
('CNV', '约伯记', 18, 20, 25, '他把箭一抽，箭就从背后出来，发亮的箭头从他的胆中出来，死亡的惊恐临到他身上。'),
('CNV', '约伯记', 18, 20, 26, '万般黑暗为他的财宝留存，不是由人吹着的火要吞灭他，要毁掉他帐棚中所剩下的。'),
('CNV', '约伯记', 18, 20, 27, '天必显露他的罪孽，地要兴起来攻击他，'),
('CNV', '约伯记', 18, 20, 28, '他的家产必被掠去，在神忿怒的日子被冲走。'),
('CNV', '约伯记', 18, 20, 29, '这是恶人从神所得的分，是神给他指定的产业。”'),
('CNV', '约伯记', 18, 21, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 21, 2, '“你们要细听我的言语，这就算是你们给我的安慰。'),
('CNV', '约伯记', 18, 21, 3, '请原谅我，我又要说话了，说完以后，就任凭你们嘲笑吧！'),
('CNV', '约伯记', 18, 21, 4, '我岂是抱怨的人呢？我的心为什么不能忍耐呢？'),
('CNV', '约伯记', 18, 21, 5, '你们注视我，惊讶吧，用手掩口吧。'),
('CNV', '约伯记', 18, 21, 6, '我每逢想起，就惊惶，浑身战抖。'),
('CNV', '约伯记', 18, 21, 7, '恶人为什么总可以存活，活到老，而且财势强大？'),
('CNV', '约伯记', 18, 21, 8, '他们的后裔在他们面前坚定，他们眼见自己的子孙在他们周围立定。'),
('CNV', '约伯记', 18, 21, 9, '他们的家宅平安无惧，神的刑杖也不加在他们身上。'),
('CNV', '约伯记', 18, 21, 10, '他们的公牛交配而不落种，他们的母牛下犊而不掉胎，'),
('CNV', '约伯记', 18, 21, 11, '他们叫小孩子出去多如羊群，他们的年轻人四处跳跃；'),
('CNV', '约伯记', 18, 21, 12, '他们跟着琴鼓高歌，又因着箫的声音欢乐。'),
('CNV', '约伯记', 18, 21, 13, '他们幸福度过他们的日子，一剎那间下阴间，毫无病痛。'),
('CNV', '约伯记', 18, 21, 14, '然而他们对神说：‘离开我们吧，我们不愿意晓得你的道路。'),
('CNV', '约伯记', 18, 21, 15, '全能者是谁，竟要我们服事他呢？我们若向他恳求，有什么益处呢？’'),
('CNV', '约伯记', 18, 21, 16, '他们的福乐岂不是掌握在他们的手中？恶人的谋算离我很远。'),
('CNV', '约伯记', 18, 21, 17, '恶人的灯何尝熄灭？灾难何尝临到他们身上？神何尝在忿怒中把痛苦分给他们！'),
('CNV', '约伯记', 18, 21, 18, '他们何尝像风前的干草，何尝像暴风刮去的糠秕？'),
('CNV', '约伯记', 18, 21, 19, '你们说：‘神为恶人的儿女积蓄罪孽’，我却说：‘神报应他本人，好叫他自己明白。’'),
('CNV', '约伯记', 18, 21, 20, '愿他亲眼看见自己败落，愿他喝全能者的烈怒。'),
('CNV', '约伯记', 18, 21, 21, '他的岁月既然断绝，他还会看顾自己身后的家吗？'),
('CNV', '约伯记', 18, 21, 22, '神既然审判那些在高位的，谁能把什么知识教给他呢？'),
('CNV', '约伯记', 18, 21, 23, '有人到死的时候仍然气力充足，享尽平静与安逸；'),
('CNV', '约伯记', 18, 21, 24, '他的奶桶充满鲜奶，他的骨髓滋润。'),
('CNV', '约伯记', 18, 21, 25, '有人到死的时候心里痛苦，一生未尝美食；'),
('CNV', '约伯记', 18, 21, 26, '他们都一起躺在尘土中，虫子爬满他们身上。'),
('CNV', '约伯记', 18, 21, 27, '我知道你们的心思，与你们恶待我的计谋。'),
('CNV', '约伯记', 18, 21, 28, '你们问：‘霸王的房屋在哪里？恶人住过的帐棚在哪里？’'),
('CNV', '约伯记', 18, 21, 29, '你们没有问问过路的人吗？不承认他们所提的证据吗？'),
('CNV', '约伯记', 18, 21, 30, '就是恶人在灾难的日子得存留，在神发怒的时候得逃脱。'),
('CNV', '约伯记', 18, 21, 31, '他所行的，有谁敢当面指责他呢？他所作的，有谁能报应他呢？'),
('CNV', '约伯记', 18, 21, 32, '然而他被人抬到坟墓里，并且有人看守他的墓地。'),
('CNV', '约伯记', 18, 21, 33, '他以谷中的土块为甘甜，所有的人跟在他后面，走在他前面的不计其数。'),
('CNV', '约伯记', 18, 21, 34, '你们的回话既然只存虚假，怎样徒然安慰我呢？”'),
('CNV', '约伯记', 18, 22, 1, '提幔人以利法回答说：'),
('CNV', '约伯记', 18, 22, 2, '“人对神能有什么益处呢？明智的人只能益己。'),
('CNV', '约伯记', 18, 22, 3, '你为人公义可讨全能者喜悦吗？你行为完全可有利于他呢？'),
('CNV', '约伯记', 18, 22, 4, '他是因你敬畏他而责备你，对你施行审判吗？'),
('CNV', '约伯记', 18, 22, 5, '你的罪恶不是很大吗？你的罪孽不是没有穷尽吗？'),
('CNV', '约伯记', 18, 22, 6, '你无缘无故强取兄弟的东西作当头，剥去衣不蔽体的人的衣服。'),
('CNV', '约伯记', 18, 22, 7, '疲乏的人你没有给他水喝，饥饿的人你没有给他饭吃。'),
('CNV', '约伯记', 18, 22, 8, '有势力的人就有土地，尊贵的人住在其中。'),
('CNV', '约伯记', 18, 22, 9, '你叫寡妇空手而去，你折断孤儿的膀臂。'),
('CNV', '约伯记', 18, 22, 10, '因此有网罗环绕着你，恐惧也忽然使你惊慌。'),
('CNV', '约伯记', 18, 22, 11, '光明变成黑暗，以致你看不见，并且洪水淹没你。'),
('CNV', '约伯记', 18, 22, 12, '神不是高于诸天吗？你看看最高的星星，多么的高啊！'),
('CNV', '约伯记', 18, 22, 13, '你说：‘神知道什么？他能透过幽暗施行审判吗？'),
('CNV', '约伯记', 18, 22, 14, '密云把他遮盖，使他不能看见我们；他在天上的圆圈上面走来走去。’'),
('CNV', '约伯记', 18, 22, 15, '你要谨守古往的道，就是恶人所行走的吗？'),
('CNV', '约伯记', 18, 22, 16, '他们未到时候，就被抓去，他们的根基被洪水冲去。'),
('CNV', '约伯记', 18, 22, 17, '他们对神说：‘离开我们吧！全能者能把我们怎么样呢？’'),
('CNV', '约伯记', 18, 22, 18, '他用美物充满他们的房屋，恶人的谋算远离我。'),
('CNV', '约伯记', 18, 22, 19, '义人看见了，就欢喜；无辜的人嘲笑他们，说：'),
('CNV', '约伯记', 18, 22, 20, '‘我们的对头必被剪除，他们剥下来的有火吞灭了。’'),
('CNV', '约伯记', 18, 22, 21, '你与神和好，就可以得平安，这样，福乐就必临到你。'),
('CNV', '约伯记', 18, 22, 22, '你该从他口中领受训诲，把他的话放在心里。'),
('CNV', '约伯记', 18, 22, 23, '你若归向全能者，就必得建立；你若使不义远离你的帐棚，'),
('CNV', '约伯记', 18, 22, 24, '把你的金块丢在尘土中，把俄斐的金块丢在河流的石头间，'),
('CNV', '约伯记', 18, 22, 25, '全能者就必作你的金块，作你的银堆，'),
('CNV', '约伯记', 18, 22, 26, '你就必以全能者为乐，向神仰起脸来。'),
('CNV', '约伯记', 18, 22, 27, '你向他祈求，他就垂听你，你也要还你的愿。'),
('CNV', '约伯记', 18, 22, 28, '你决定的计划，他必为你成全，光明必照在你的路上。'),
('CNV', '约伯记', 18, 22, 29, '人谦卑的时候，你就说：‘升高吧！’眼中谦卑的他必拯救，'),
('CNV', '约伯记', 18, 22, 30, '并非无辜的人，神尚且搭救他；他要因你手中的洁净得救拔。”'),
('CNV', '约伯记', 18, 23, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 23, 2, '“直到今日我还有苦情要申诉，我虽然叹息，他的手仍然沉重。'),
('CNV', '约伯记', 18, 23, 3, '但愿我知道怎样能寻见神，能到他的台前来。'),
('CNV', '约伯记', 18, 23, 4, '好让我在他面前呈上我的案件，满口辩论向他申诉；'),
('CNV', '约伯记', 18, 23, 5, '知道他要回答我的话，明白他对我说什么。'),
('CNV', '约伯记', 18, 23, 6, '他会以大能与我相争吗？必不会这样，他必关怀我。'),
('CNV', '约伯记', 18, 23, 7, '在他那里正直人可以与他彼此辩论，这样，我就必永远摆脱那审判我的。'),
('CNV', '约伯记', 18, 23, 8, '可是我往前走，他不在那里；我若往后退，我也不能见他。'),
('CNV', '约伯记', 18, 23, 9, '他在左边行事，我却见不到；他在右边隐藏，我却看不见。'),
('CNV', '约伯记', 18, 23, 10, '可是他知道我所行的道路，他试炼我以后，我必像精金出现。'),
('CNV', '约伯记', 18, 23, 11, '我的脚紧随他的脚步，我谨守他的道，并不偏离。'),
('CNV', '约伯记', 18, 23, 12, '他嘴唇的命令我没有离弃，我珍藏他口中的言语在我的心胸，胜过我需用的饮食（“胜过我需用的饮食”或可参照《七十士译本》等古译本翻译为“在我的心胸”）。'),
('CNV', '约伯记', 18, 23, 13, '但是他既已定意，谁能使他转意呢？他心里所愿的，就行出来。'),
('CNV', '约伯记', 18, 23, 14, '他为我所定的，他必成全，这类的事情，他还有许多。'),
('CNV', '约伯记', 18, 23, 15, '因此我在他面前惊惶，一想到这事，我就惧怕他。'),
('CNV', '约伯记', 18, 23, 16, '神使我心里胆怯，全能者使我惊惶，'),
('CNV', '约伯记', 18, 23, 17, '因为我在黑暗面前并没有被消灭，也不怕幽暗遮盖着我的脸。”'),
('CNV', '约伯记', 18, 24, 1, '“为什么全能者不保留赏善罚恶的时间？为什么认识他的人不能看见他的日子？'),
('CNV', '约伯记', 18, 24, 2, '恶人挪移地界，抢夺群畜去牧养。'),
('CNV', '约伯记', 18, 24, 3, '他们赶走孤儿的驴，强取寡妇的牛作抵押。'),
('CNV', '约伯记', 18, 24, 4, '他们使穷人离开大道，世上的贫民都一起躲藏起来。'),
('CNV', '约伯记', 18, 24, 5, '这些贫穷人像旷野的野驴，出外劳碌，殷勤寻觅食物，野地为他们和他们的孩子供应食物。'),
('CNV', '约伯记', 18, 24, 6, '他们在田里收割草料，在恶人的葡萄园中摘取剩余的葡萄。'),
('CNV', '约伯记', 18, 24, 7, '他们赤身露体无衣过夜，在寒冷中毫无遮盖。'),
('CNV', '约伯记', 18, 24, 8, '他被山上的大雨淋湿，因为没有躲避之处就紧抱磐石。'),
('CNV', '约伯记', 18, 24, 9, '有人从母亲的怀中抢走孤儿，又强取穷人的衣物作抵押，'),
('CNV', '约伯记', 18, 24, 10, '因此穷人赤身露体流浪，他们因饥饿就抬走禾捆；'),
('CNV', '约伯记', 18, 24, 11, '他们在那些人的橄榄树行列（“那些人的橄榄树行列”直译是“他们的行列”）内榨油，又在葡萄园里踹酒（“又在葡萄园里踹酒”直译是“又踹酒池”），但自己仍然口渴。'),
('CNV', '约伯记', 18, 24, 12, '有人从城里唉哼，受伤的人呼求，神却不理会恶人的愚妄。'),
('CNV', '约伯记', 18, 24, 13, '又有人与光为敌，不认识光明的道，不留在光明的路中。'),
('CNV', '约伯记', 18, 24, 14, '杀人的黎明起来，杀戮困苦人与穷人，夜间又去作盗贼。'),
('CNV', '约伯记', 18, 24, 15, '奸夫的眼睛等待黄昏，说：‘没有眼可以看见我’，就把自己的脸蒙起来。'),
('CNV', '约伯记', 18, 24, 16, '盗贼黑夜挖穿屋子，白天却躲藏起来，他们不想认识光明。'),
('CNV', '约伯记', 18, 24, 17, '他们看晨光如死荫，因为他们认识死荫的惊骇。'),
('CNV', '约伯记', 18, 24, 18, '这些恶人如水面上飘浮的东西迅速流逝，他们在世上所得的分被咒诅，他们不能再走葡萄园的路。'),
('CNV', '约伯记', 18, 24, 19, '干旱与炎热怎样消除雪水，阴间也这样除去犯罪的人。'),
('CNV', '约伯记', 18, 24, 20, '怀他的母胎忘记他，虫子要以他为甘甜，他不再被人记念，不义的人必如树折断。'),
('CNV', '约伯记', 18, 24, 21, '他恶待不能生育，没有孩子的妇人，也不善待寡妇。'),
('CNV', '约伯记', 18, 24, 22, '神却用自己的能力延长强暴的人的性命，生命难保的仍然兴起。'),
('CNV', '约伯记', 18, 24, 23, '神使他们安稳，他们就有所倚靠，他的眼也看顾他们的道路。'),
('CNV', '约伯记', 18, 24, 24, '他们被高举不过片时，就没有了，他们降为卑，如众人一样被收拾起来，他们又如谷穗枯干。'),
('CNV', '约伯记', 18, 24, 25, '如果不是这样，谁能证明我是撒谎的，指出我的言语为空虚的呢？”'),
('CNV', '约伯记', 18, 25, 1, '书亚人比勒达回答说：'),
('CNV', '约伯记', 18, 25, 2, '“神有治理之权，威严可畏，他在高天之处施行和平。'),
('CNV', '约伯记', 18, 25, 3, '他的天军怎能数算？他的光一发谁不被照耀呢？'),
('CNV', '约伯记', 18, 25, 4, '这样在神面前，人怎能称为义呢？妇人所生的，怎能算为洁净呢？'),
('CNV', '约伯记', 18, 25, 5, '在神的眼中，月亮都不明亮，星星也不皎洁，'),
('CNV', '约伯记', 18, 25, 6, '更何况如虫的人，像蛆的世人呢！”'),
('CNV', '约伯记', 18, 26, 1, '约伯回答说：'),
('CNV', '约伯记', 18, 26, 2, '“无能力的，你怎样帮助他，膀臂无力的，你怎样拯救他！'),
('CNV', '约伯记', 18, 26, 3, '无智慧的，你怎样教导他，显明你丰盛的智慧！'),
('CNV', '约伯记', 18, 26, 4, '你靠谁发言呢？谁的灵从你而出呢？'),
('CNV', '约伯记', 18, 26, 5, '阴魂和在水中居住的，都在水下痛苦不堪。'),
('CNV', '约伯记', 18, 26, 6, '阴间在神面前赤露敞开，灭亡之处也没有遮盖。'),
('CNV', '约伯记', 18, 26, 7, '他把北极铺在空间，把地球挂在太空。'),
('CNV', '约伯记', 18, 26, 8, '他把水包在密云中，水下面的云却不破裂。'),
('CNV', '约伯记', 18, 26, 9, '他遮蔽自己宝座的正面，把云铺在上面。'),
('CNV', '约伯记', 18, 26, 10, '在水面划出界限，直到光与暗的交界。'),
('CNV', '约伯记', 18, 26, 11, '天的柱子都因他的斥责震动惊奇；'),
('CNV', '约伯记', 18, 26, 12, '他以能力搅动大海，以聪明击伤拉哈伯。'),
('CNV', '约伯记', 18, 26, 13, '他以自己的气使天晴朗，他的手刺穿逃跑的蛇。'),
('CNV', '约伯记', 18, 26, 14, '这些不过是他的作为的一点点，我们从他那里所听到的，是多么的微小！他大能的雷声谁能够明白呢？”'),
('CNV', '约伯记', 18, 27, 1, '约伯继续他的讲论，说：'),
('CNV', '约伯记', 18, 27, 2, '“永活的神夺去我的公理，全能者使我心中痛苦。'),
('CNV', '约伯记', 18, 27, 3, '只要我的生命还在我里面，神赐我的气息还在我鼻孔里，'),
('CNV', '约伯记', 18, 27, 4, '我的嘴唇决不说不义之言，我的舌头也不讲诡诈之语。'),
('CNV', '约伯记', 18, 27, 5, '我绝对不以你们为是，我到死也不放弃我的纯全；'),
('CNV', '约伯记', 18, 27, 6, '我坚守我的义决不放松，我一生的日子我的心必不责备我。'),
('CNV', '约伯记', 18, 27, 7, '愿我的敌人如恶人一般，愿那起来攻击我的像不义的人一样。'),
('CNV', '约伯记', 18, 27, 8, '不敬虔的人被剪除，神夺去他性命的时候还有什么指望呢？'),
('CNV', '约伯记', 18, 27, 9, '患难临到他身上的时候，神会垂听他的哀求吗？'),
('CNV', '约伯记', 18, 27, 10, '他以全能者为乐，时时求告神吗？'),
('CNV', '约伯记', 18, 27, 11, '我藉神的能力教导你们，我不向你们隐瞒全能者的事。'),
('CNV', '约伯记', 18, 27, 12, '你们都亲自见过，你们为什么成了这么虚妄呢？'),
('CNV', '约伯记', 18, 27, 13, '这是恶人从神所得的分，强暴的人从全能者所得的业。'),
('CNV', '约伯记', 18, 27, 14, '即使他的儿女增多，还是被刀剑所杀，他的子孙也必永不得饱食；'),
('CNV', '约伯记', 18, 27, 15, '他的遗族在死人中埋葬，他的寡妇也都不哀哭。'),
('CNV', '约伯记', 18, 27, 16, '他虽然堆积银子如尘沙，预备衣服如泥土，'),
('CNV', '约伯记', 18, 27, 17, '他尽管预备，义人却要穿上；他的银子，无辜的人也要瓜分。'),
('CNV', '约伯记', 18, 27, 18, '他建造房屋如蜘蛛结网，又如守望者所搭的棚。'),
('CNV', '约伯记', 18, 27, 19, '他虽然躺下的时候富有，却不再这样；他一张开双眼，财富就不在了。'),
('CNV', '约伯记', 18, 27, 20, '惊恐必如众水追上他，暴风在夜间把他刮去。'),
('CNV', '约伯记', 18, 27, 21, '东风把他吹起，他就消逝；又把他卷起，离开原来的地方。'),
('CNV', '约伯记', 18, 27, 22, '神射击他，毫不留情，他甚愿快快逃脱神的手。'),
('CNV', '约伯记', 18, 27, 23, '有人向他拍掌，发咝声赶他离开原来的地方。”'),
('CNV', '约伯记', 18, 28, 1, '“银子有矿，金子有冶炼的地方。'),
('CNV', '约伯记', 18, 28, 2, '铁从土中取出，熔化石头而得铜。'),
('CNV', '约伯记', 18, 28, 3, '人探求黑暗的尽头，查明在阴暗中的石矿，直到极处。'),
('CNV', '约伯记', 18, 28, 4, '在无人居住之处，足迹罕至之地开坑探矿，他们与人远离，悬在坑中摇来摇去。'),
('CNV', '约伯记', 18, 28, 5, '至于地，粮食从它而出，地底下却好像被火翻转过来一样。'),
('CNV', '约伯记', 18, 28, 6, '石中有蓝宝石，也有金沙。'),
('CNV', '约伯记', 18, 28, 7, '矿坑中的路，鸷鸟不知道，连鹰的眼也未曾见过；'),
('CNV', '约伯记', 18, 28, 8, '狂傲的野兽未曾行过，猛狮也未曾经过。'),
('CNV', '约伯记', 18, 28, 9, '人伸手击凿坚石，使山脚翻倒过来。'),
('CNV', '约伯记', 18, 28, 10, '在磐石中凿出坑道，亲眼看见各样宝物。'),
('CNV', '约伯记', 18, 28, 11, '他堵住水源，不让滴漏，又使隐藏之物显露在光中。'),
('CNV', '约伯记', 18, 28, 12, '然而，智慧在何处可寻？聪明之地在哪里呢？'),
('CNV', '约伯记', 18, 28, 13, '智慧的价值人不知道，在活人之地也寻不到。'),
('CNV', '约伯记', 18, 28, 14, '深渊说：‘不在我里面’，沧海说：‘不在我这里’。'),
('CNV', '约伯记', 18, 28, 15, '智慧不能用纯金购买，也不能称银子作它的代价。'),
('CNV', '约伯记', 18, 28, 16, '俄斐金，贵重的玛瑙、蓝宝石，都不能与它比较。'),
('CNV', '约伯记', 18, 28, 17, '黄金和玻璃不能与它比较，纯金的器皿不能与它交换。'),
('CNV', '约伯记', 18, 28, 18, '珊瑚和水晶都不值一提，取得智慧胜过取得红宝石。'),
('CNV', '约伯记', 18, 28, 19, '古实的黄玉不能与它比较，纯金也不能与它较量。'),
('CNV', '约伯记', 18, 28, 20, '然而，智慧从哪里来，聪明之地在哪里呢？'),
('CNV', '约伯记', 18, 28, 21, '众生的眼睛都看不到，空中的飞鸟也不能发现。'),
('CNV', '约伯记', 18, 28, 22, '灭亡和死亡都说：‘我们只风闻它的事罢了。’'),
('CNV', '约伯记', 18, 28, 23, '神明白智慧的道路，也晓得智慧的所在，'),
('CNV', '约伯记', 18, 28, 24, '因为他察看全世界，遍观全地。'),
('CNV', '约伯记', 18, 28, 25, '他为风定轻重，又度量众水；'),
('CNV', '约伯记', 18, 28, 26, '为雨露立定律，为雷电定道路。'),
('CNV', '约伯记', 18, 28, 27, '那时他看见智慧，描述智慧，他坚立智慧，并且查探智慧。'),
('CNV', '约伯记', 18, 28, 28, '他对人说：‘敬畏主就是智慧，远离邪恶就是聪明。’”'),
('CNV', '约伯记', 18, 29, 1, '约伯继续他的讲论，说：'),
('CNV', '约伯记', 18, 29, 2, '“但愿我的景况像以前的岁月，像神保守我的日子。'),
('CNV', '约伯记', 18, 29, 3, '那时他的灯照在我的头上，我靠着他的光行过黑暗。'),
('CNV', '约伯记', 18, 29, 4, '但愿我仍然活在年轻力壮的日子，那时神在我的帐棚里与我亲密。'),
('CNV', '约伯记', 18, 29, 5, '全能者仍然与我同在，我的孩子都环绕我。'),
('CNV', '约伯记', 18, 29, 6, '我用油洗脚，磐石为我出油成河。'),
('CNV', '约伯记', 18, 29, 7, '我出到城门那里去，在广场上预备我的座位。'),
('CNV', '约伯记', 18, 29, 8, '年轻人看见我，就回避，年老的也起身站立。'),
('CNV', '约伯记', 18, 29, 9, '王子都停止说话，并且用手掩口。'),
('CNV', '约伯记', 18, 29, 10, '众领袖都不敢作声，他们的舌头紧贴上颚。'),
('CNV', '约伯记', 18, 29, 11, '耳朵听见我的，就称我有福。眼睛看见我的，就作证称赞我。'),
('CNV', '约伯记', 18, 29, 12, '因为我救了呼救的穷人，和无人帮助的孤儿。'),
('CNV', '约伯记', 18, 29, 13, '将要灭亡的，为我祝福；我使寡妇的心欢呼。'),
('CNV', '约伯记', 18, 29, 14, '我以公义作衣服穿上；我的公平好像外袍和冠冕。'),
('CNV', '约伯记', 18, 29, 15, '我作了瞎子的眼，瘸子的腿。'),
('CNV', '约伯记', 18, 29, 16, '我作过贫穷人的父亲，我查究过我素来不认识的人的案件。'),
('CNV', '约伯记', 18, 29, 17, '我打碎了不义的人的牙齿，使捕食的掉下来。'),
('CNV', '约伯记', 18, 29, 18, '那时我心里想：‘我必在家中安然去世，我必增添我的日子像沙尘那么多。'),
('CNV', '约伯记', 18, 29, 19, '我的根蔓延到水边，露水整夜沾在我的枝上。'),
('CNV', '约伯记', 18, 29, 20, '我的荣耀在身上常新，我的弓在我手上重新得力。'),
('CNV', '约伯记', 18, 29, 21, '大家都聆听我，等候我；静默无声地领受我的指导。'),
('CNV', '约伯记', 18, 29, 22, '我说了话以后，他们就不再说，我的言语像雨露一般滴在他们身上。'),
('CNV', '约伯记', 18, 29, 23, '他们等候我像等候雨水，又大大张嘴如切慕春雨。'),
('CNV', '约伯记', 18, 29, 24, '我向他们微笑，他们也不敢相信；他们珍惜我脸上的光。'),
('CNV', '约伯记', 18, 29, 25, '我为他们选择道路，又坐首位；我像君王住在军队中，又像个安慰悲伤的人。’”'),
('CNV', '约伯记', 18, 30, 1, '“但现在年纪比我小的人都笑我；我不容许他们的父亲与我羊群的犬只为伴。'),
('CNV', '约伯记', 18, 30, 2, '他们的气力已经衰退了，他们两手的力量对我有什么益处呢？'),
('CNV', '约伯记', 18, 30, 3, '他们因穷乏与饥饿而消瘦，在黑夜荒废与荒凉之地咀嚼旷野的干草；'),
('CNV', '约伯记', 18, 30, 4, '他们在草丛中采摘咸草，以罗腾树根作食物。'),
('CNV', '约伯记', 18, 30, 5, '他们从人群中被赶出去，人追喊他们如追喊贼一样，'),
('CNV', '约伯记', 18, 30, 6, '以致他们住在惊吓谷之中，在地洞和岩穴之间；'),
('CNV', '约伯记', 18, 30, 7, '他们在草丛中间喊叫，在杂草之下集合起来。'),
('CNV', '约伯记', 18, 30, 8, '他们都是愚顽人、下流人的子孙，被人鞭打逐出境外。'),
('CNV', '约伯记', 18, 30, 9, '现在他们以我为歌曲，我竟成了他们的笑柄。'),
('CNV', '约伯记', 18, 30, 10, '他们厌恶我，远远地离开我，又不住吐唾沫在我脸上，'),
('CNV', '约伯记', 18, 30, 11, '因为神把我的弓弦松开，叫我受苦，他们就在我面前任意妄为（“任意妄为”直译是“解开辔头”）。'),
('CNV', '约伯记', 18, 30, 12, '一窝暴民在我右边兴起，推开我的脚，筑起灾难的路攻击我。'),
('CNV', '约伯记', 18, 30, 13, '他们拆毁了我的路，没有别人的帮助也能毁灭我；'),
('CNV', '约伯记', 18, 30, 14, '他们闯进来如闯大破口，在废墟之中辊过来，'),
('CNV', '约伯记', 18, 30, 15, '惊骇临到我的身上，驱逐我的尊严如风吹一般，我的好景像云一样过去。'),
('CNV', '约伯记', 18, 30, 16, '现在我的心伤恸有如倒了出来，苦难的日子把我抓住。'),
('CNV', '约伯记', 18, 30, 17, '夜间痛苦刺透我的骨头，疼痛不止，不住地咀嚼我。'),
('CNV', '约伯记', 18, 30, 18, '我的衣服因神的大力变了形，他的大力如外衣的领口把我束紧。'),
('CNV', '约伯记', 18, 30, 19, '神把我扔在泥中，我就像尘土和炉灰一般。'),
('CNV', '约伯记', 18, 30, 20, '神啊！我向你呼求，你却不应允我，我站起来，你也不理我。'),
('CNV', '约伯记', 18, 30, 21, '你变成待我残忍，用你大能的手迫害我，'),
('CNV', '约伯记', 18, 30, 22, '你把我提到风中，使我被风刮去，使我在暴风中消散。'),
('CNV', '约伯记', 18, 30, 23, '我知道你必使我归回死地，归到那为众生所定的阴宅。'),
('CNV', '约伯记', 18, 30, 24, '然而人跌倒，怎会不伸手？人遇灾祸，怎会不呼救呢？'),
('CNV', '约伯记', 18, 30, 25, '艰难过日的，我不是为他哀哭；贫穷的，我不是为他忧愁吗？'),
('CNV', '约伯记', 18, 30, 26, '我希望得福乐，灾祸就来了；我等候光明，幽暗就到了。'),
('CNV', '约伯记', 18, 30, 27, '我的心肠沸腾、不安，痛苦的日子临到我。'),
('CNV', '约伯记', 18, 30, 28, '我四处行走，全身发黑，并不是因为日晒；我在会中站着呼求。'),
('CNV', '约伯记', 18, 30, 29, '我与野狗为兄弟，又与鸵鸟作同伴。'),
('CNV', '约伯记', 18, 30, 30, '我的皮肤发黑脱落，我的骨头因热发烧，'),
('CNV', '约伯记', 18, 30, 31, '所以我的琴音变为哀音，我的箫声变为哭声。”'),
('CNV', '约伯记', 18, 31, 1, '“我与自己的眼睛立了约，决不注视处女。'),
('CNV', '约伯记', 18, 31, 2, '从至上的神所得的分，从至高的全能者所得的业是什么呢？'),
('CNV', '约伯记', 18, 31, 3, '灾难不是临到不义的人吗？灾祸不是临到作孽的人吗？'),
('CNV', '约伯记', 18, 31, 4, '神不是察看我的道路，数算我的一切脚步吗？'),
('CNV', '约伯记', 18, 31, 5, '我若与虚谎同行，我的脚若急于追随诡诈，'),
('CNV', '约伯记', 18, 31, 6, '就愿我被公平的天平称度，使神可以知道我的完全。'),
('CNV', '约伯记', 18, 31, 7, '我的脚步若偏离正道，我的心若随从眼目而行，我的手掌若黏有任何污点，'),
('CNV', '约伯记', 18, 31, 8, '就愿我所种的，让别人来吃，愿我田中出产的，都连根拔起来。'),
('CNV', '约伯记', 18, 31, 9, '我的心若被女人迷惑，在别人的门口埋伏，'),
('CNV', '约伯记', 18, 31, 10, '就愿我的妻子作别人的奴仆，也愿别人屈身与她行淫，'),
('CNV', '约伯记', 18, 31, 11, '因为这是大恶，是该受审判的罪孽；'),
('CNV', '约伯记', 18, 31, 12, '这是焚烧直至毁灭的火，必把我所有的收获都拔出来。'),
('CNV', '约伯记', 18, 31, 13, '我的仆婢与我争论的时候，我若轻视他们的案件，'),
('CNV', '约伯记', 18, 31, 14, '神若起来，我怎么办呢？他若鉴察，我怎样回答呢？'),
('CNV', '约伯记', 18, 31, 15, '那造我在母腹中的，不也造他吗？造我们在母胎里的，不是同一位吗？'),
('CNV', '约伯记', 18, 31, 16, '我若不给穷人所要的，或使寡妇的眼所期待的落空；')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '约伯记', 18, 31, 17, '我若独吃我的一点食物，孤儿却没有与我同吃；'),
('CNV', '约伯记', 18, 31, 18, '自我幼年时，孤儿与我一同长大，以我为父，从我出母腹以来，我就善待寡妇。'),
('CNV', '约伯记', 18, 31, 19, '我若见人因无衣服死亡，或贫穷人毫无遮盖；'),
('CNV', '约伯记', 18, 31, 20, '他若不因我的羊毛得温暖，他的心若不向我道谢；'),
('CNV', '约伯记', 18, 31, 21, '我若在城门见有支持我的，就挥手攻击孤儿，'),
('CNV', '约伯记', 18, 31, 22, '就愿我的肩头从肩胛脱落，愿我的前臂从上臂折断；'),
('CNV', '约伯记', 18, 31, 23, '因为神所降的灾难使我恐惧，因他的崇高我不敢妄为。'),
('CNV', '约伯记', 18, 31, 24, '我若以黄金为我所信靠的，又对精金说：‘你是我所靠赖的’；'),
('CNV', '约伯记', 18, 31, 25, '我若因为财物丰裕，或因为我多获财利而欢喜；'),
('CNV', '约伯记', 18, 31, 26, '我若见太阳（“太阳”直译是“光”）照耀，或明月行在空中，'),
('CNV', '约伯记', 18, 31, 27, '以致心中暗暗地受到迷惑，用自己的嘴亲手；'),
('CNV', '约伯记', 18, 31, 28, '那么这也就是该受审判的罪孽，因为我欺哄了高高在上的神。'),
('CNV', '约伯记', 18, 31, 29, '我若因恨我的人遭灾祸而欢喜，或因他遇患难而高兴；'),
('CNV', '约伯记', 18, 31, 30, '我并没有容许我的口犯罪，咒诅他的性命。'),
('CNV', '约伯记', 18, 31, 31, '我家里的人若没有说：‘谁能找出哪一个没有饱吃他的肉食的呢？’'),
('CNV', '约伯记', 18, 31, 32, '旅客没有在街上过夜，我的门向过路的人是敞开的。'),
('CNV', '约伯记', 18, 31, 33, '我若像亚当遮掩我的过犯，把我的罪孽藏在怀中，'),
('CNV', '约伯记', 18, 31, 34, '因为我惧怕群众，宗族的藐视又使我惊恐，以致我静默不言，足不出门。'),
('CNV', '约伯记', 18, 31, 35, '但愿有一位肯听我的，看哪！这是我所划的押，愿全能者回答我，愿那与我争讼的写好状词。'),
('CNV', '约伯记', 18, 31, 36, '我定要把它带到我的肩上，绑在我的头上为冠冕。'),
('CNV', '约伯记', 18, 31, 37, '我要向他述说全部的行为，又像王子一般进到他面前。'),
('CNV', '约伯记', 18, 31, 38, '我的田地若呼冤控告我，地的犁沟若都一同哀哭；'),
('CNV', '约伯记', 18, 31, 39, '我若吃地里的出产而不给价银，或使地主气绝身亡，'),
('CNV', '约伯记', 18, 31, 40, '就愿蒺藜长出来代替小麦，臭草代替大麦。”约伯的话说完了。'),
('CNV', '约伯记', 18, 32, 1, '因为约伯自以为义，于是这三个人就不再回答他。'),
('CNV', '约伯记', 18, 32, 2, '那时，布西人兰族巴拉迦的儿子以利户发怒了；他向约伯发怒，因为他在神面前自以为义。'),
('CNV', '约伯记', 18, 32, 3, '他又向约伯的三个朋友发怒，因为他们虽然仍以约伯为有罪，却找不到回答的话来。'),
('CNV', '约伯记', 18, 32, 4, '以利户等待着要向约伯说话，因为他们的年纪都比以利户大。'),
('CNV', '约伯记', 18, 32, 5, '以利户一见这三个人的口里无话回答，他就发怒了。'),
('CNV', '约伯记', 18, 32, 6, '布西人巴拉迦的儿子以利户回答说：“我年纪轻，你们年纪大，因此我拘束畏惧，不敢向你们表达我的意见。'),
('CNV', '约伯记', 18, 32, 7, '我心里想：‘年长的当先说话，寿高的当以智慧教训人。’'),
('CNV', '约伯记', 18, 32, 8, '但是在人心里面有灵，全能者的气息使人有聪明。'),
('CNV', '约伯记', 18, 32, 9, '年纪大的不都有智慧，年老的不都能明白是非，'),
('CNV', '约伯记', 18, 32, 10, '因此我说：‘你们要听我说话，我也要说出我的意见。’'),
('CNV', '约伯记', 18, 32, 11, '你们砌词说话的时候，我等待着你们的话，留心听你们的理论。'),
('CNV', '约伯记', 18, 32, 12, '我留意听你们，不料，你们中间没有人能驳倒约伯，驳回他所说的话。'),
('CNV', '约伯记', 18, 32, 13, '你们不要说：‘我们寻得了智慧；能胜过他的，是神，不是人。’'),
('CNV', '约伯记', 18, 32, 14, '约伯没有用他的话攻击我，我也不用你们的话回答他。'),
('CNV', '约伯记', 18, 32, 15, '他们惊惶失措，不再回应，他们没有什么可说的话了。'),
('CNV', '约伯记', 18, 32, 16, '因为他们不说话，因为他们站着不再回应，我就等待吗？'),
('CNV', '约伯记', 18, 32, 17, '我也要回答我的一份话，我也要表达我的意见，'),
('CNV', '约伯记', 18, 32, 18, '因为我充满了要说的话，我里面的灵催逼我说出来。'),
('CNV', '约伯记', 18, 32, 19, '我里面如盛酒的囊，没有出气的地方，又如新酒袋，快要破裂。'),
('CNV', '约伯记', 18, 32, 20, '我要说话，使我可以舒畅，我要开口回答。'),
('CNV', '约伯记', 18, 32, 21, '我必不徇人的情面，也不奉承人，'),
('CNV', '约伯记', 18, 32, 22, '因为我不晓得怎样奉承。不然，我的创造主很快就把我除去。”'),
('CNV', '约伯记', 18, 33, 1, '“可是，约伯啊，请听我的言语，留心听我的一切话。'),
('CNV', '约伯记', 18, 33, 2, '我现在开口，用舌头发言；'),
('CNV', '约伯记', 18, 33, 3, '我的话表明我心中的正直，我所知道的，我的嘴唇就诚诚实实地说出来。'),
('CNV', '约伯记', 18, 33, 4, '神的灵创造了我，全能者的气使我存活。'),
('CNV', '约伯记', 18, 33, 5, '你若能够办得到，就回答我，用话语攻击我，表明立场，当面攻击我。'),
('CNV', '约伯记', 18, 33, 6, '在神面前我与你一样，也是用土捏造的。'),
('CNV', '约伯记', 18, 33, 7, '我的威严必不惊吓你，我的压力也不加重在你身上。'),
('CNV', '约伯记', 18, 33, 8, '你所说的，我已经听见了，也听到你言语的声音，说：'),
('CNV', '约伯记', 18, 33, 9, '‘我是洁净的，毫无过犯；我是清白的，没有罪孽。'),
('CNV', '约伯记', 18, 33, 10, '神找机会攻击我，把我当作仇敌；'),
('CNV', '约伯记', 18, 33, 11, '他把我的两脚上了木狗，又鉴察我一切所行的。’'),
('CNV', '约伯记', 18, 33, 12, '我要告诉你，你这话错了，因为神比世人大。'),
('CNV', '约伯记', 18, 33, 13, '你为什么对神争辩，说：‘无论世人的什么话，他都不回答’呢？'),
('CNV', '约伯记', 18, 33, 14, '原来神用这个方法或那个方法说了，只是，世人没有留意。'),
('CNV', '约伯记', 18, 33, 15, '世人都在床上打盹，沉睡临到他们的时候，神用异梦与夜间的异象，'),
('CNV', '约伯记', 18, 33, 16, '告诉他们，他坚定他们所得的训诲，'),
('CNV', '约伯记', 18, 33, 17, '好叫人离开自己的恶行，又叫人与骄傲隔绝，'),
('CNV', '约伯记', 18, 33, 18, '拦阻人的性命不下在坑里，又阻止他的生命不死在刀下。'),
('CNV', '约伯记', 18, 33, 19, '人在床上被痛苦惩治，他的骨头不住地痛苦挣扎，'),
('CNV', '约伯记', 18, 33, 20, '以致他的生命厌恶食物，他的胃口也厌恶美食，'),
('CNV', '约伯记', 18, 33, 21, '他的肌肉消瘦以致看不见，以前看不见的骨头，现在都凸出来。'),
('CNV', '约伯记', 18, 33, 22, '他的性命接近深坑，他的生命靠近灭命的天使。'),
('CNV', '约伯记', 18, 33, 23, '在一千位天使之中，若有一位作人的中保，指示人当行的事，'),
('CNV', '约伯记', 18, 33, 24, '恩待他，说：‘救赎他免下深坑；我已经得到了赎价。’'),
('CNV', '约伯记', 18, 33, 25, '他的肌肉就比孩童的更嫩，他更恢复满有青春活力的日子。'),
('CNV', '约伯记', 18, 33, 26, '他向神祈求，神就喜悦他，他也欢呼着朝见神的面，人又恢复自己的义。'),
('CNV', '约伯记', 18, 33, 27, '他在人面前歌唱，说：‘我犯了罪，颠倒是非，但我没有受到应得的报应。'),
('CNV', '约伯记', 18, 33, 28, '他救赎我的性命免入深坑，我的生命必得见光明。’'),
('CNV', '约伯记', 18, 33, 29, '神总是三番四次，向人行这一切事，'),
('CNV', '约伯记', 18, 33, 30, '要把人的性命从深坑里救回来，好使活人之光光照他。'),
('CNV', '约伯记', 18, 33, 31, '约伯啊，你当留心听我，当默不作声，我要说话。'),
('CNV', '约伯记', 18, 33, 32, '你若有话说，就请回答我；你只管说吧，因为我愿意以你为义。'),
('CNV', '约伯记', 18, 33, 33, '你若没有话说，就要听我说，你当默不作声，我就把智慧教导你。”'),
('CNV', '约伯记', 18, 34, 1, '以利户回答，说：'),
('CNV', '约伯记', 18, 34, 2, '“智慧人哪！你们要听我的话；有知识的人哪！你们要侧耳听我。'),
('CNV', '约伯记', 18, 34, 3, '因为耳朵试验言语，好像上膛尝试食物。'),
('CNV', '约伯记', 18, 34, 4, '我们要选择何为是，让我们彼此知道何为善。'),
('CNV', '约伯记', 18, 34, 5, '约伯说：‘我是有理的，神却夺去我的公理；'),
('CNV', '约伯记', 18, 34, 6, '我虽然有公理，却被认为是说谎的；我虽然毫无过犯，我所受的箭伤却无法医治。’'),
('CNV', '约伯记', 18, 34, 7, '有哪一个人像约伯呢？他喝亵慢如同喝水，'),
('CNV', '约伯记', 18, 34, 8, '他与作孽的同伙，他与恶人同行。'),
('CNV', '约伯记', 18, 34, 9, '因为他说过：‘人讨神的喜悦，对他并无益处。’'),
('CNV', '约伯记', 18, 34, 10, '所以，明理的人哪！你们要听我的话，神决不至作恶，全能者断不至行不义，'),
('CNV', '约伯记', 18, 34, 11, '因为神必照着人所作的报应他，使各人按照所行的得报应。'),
('CNV', '约伯记', 18, 34, 12, '真的，神必不作恶，全能者也必不颠倒是非。'),
('CNV', '约伯记', 18, 34, 13, '谁派他管理大地？谁设立全世界呢？'),
('CNV', '约伯记', 18, 34, 14, '他若对人决心这样作，他若把灵与气收归自己，'),
('CNV', '约伯记', 18, 34, 15, '有血肉生命的就都一同气绝身亡，世人都归回尘土。'),
('CNV', '约伯记', 18, 34, 16, '你若明理，就请听这话，留心听我说话的声音。'),
('CNV', '约伯记', 18, 34, 17, '恨恶公平的真的可以掌权吗？那有公义与大能的，你定他为有罪吗？'),
('CNV', '约伯记', 18, 34, 18, '他不是对君王说：‘你是匪徒’，又对贵族说：‘你们是恶人’吗？'),
('CNV', '约伯记', 18, 34, 19, '他不徇王子的情面，也不看重富人过于穷人，因为他们都是他手所造的。'),
('CNV', '约伯记', 18, 34, 20, '他们在半夜之中剎那之间死亡，平民因遭受震动而去世，有权势的被除灭非借人手。'),
('CNV', '约伯记', 18, 34, 21, '神的眼看顾人的道路，察看他每一步，'),
('CNV', '约伯记', 18, 34, 22, '没有黑暗，又没有死荫的地方，可以给作孽的在那里藏身。'),
('CNV', '约伯记', 18, 34, 23, '神不必进一步鉴察人，使人到他面前去受审判。'),
('CNV', '约伯记', 18, 34, 24, '他不必查究就可以打碎有权势的人，并且设立别人代替他们。'),
('CNV', '约伯记', 18, 34, 25, '他原来留心他们所行的，在夜间倾覆他们，他们就被压碎；'),
('CNV', '约伯记', 18, 34, 26, '他在观众面前击打他们，有如击打恶人一样；'),
('CNV', '约伯记', 18, 34, 27, '因为他们偏离正道不跟从他，也不留心他的一切道路，'),
('CNV', '约伯记', 18, 34, 28, '以致穷人的哀求达到他那里，他也垂听了困苦人的哀求。'),
('CNV', '约伯记', 18, 34, 29, '他若安静不动，谁能定他有罪呢？他若掩面，谁能看见他呢？无论对待一国或一人，都是这样。'),
('CNV', '约伯记', 18, 34, 30, '别让不敬虔的人作王，免得他危害人民。'),
('CNV', '约伯记', 18, 34, 31, '有人对神说：‘我忍受了管教，不再有败坏的行为了，'),
('CNV', '约伯记', 18, 34, 32, '我所看不到的求你指教我，我若行了罪孽，必不再行’。'),
('CNV', '约伯记', 18, 34, 33, '神会因你拒绝悔改，就遵照你的心意吗？要作抉择的是你，不是我，你所知道的，只管说出来吧。'),
('CNV', '约伯记', 18, 34, 34, '明理的人必对我说，智慧的人要听我的话。'),
('CNV', '约伯记', 18, 34, 35, '约伯说话毫无知识，他的言语没有智慧。'),
('CNV', '约伯记', 18, 34, 36, '但愿约伯被试验到底，因为他的回答像恶人一样。'),
('CNV', '约伯记', 18, 34, 37, '他在自己的罪上又加过犯，在我们中间鼓掌嘲笑神，用许多话敌对神。”'),
('CNV', '约伯记', 18, 35, 1, '以利户回答说：'),
('CNV', '约伯记', 18, 35, 2, '“你说：‘我在神面前更显为义’，你自以为这话有理吗？'),
('CNV', '约伯记', 18, 35, 3, '你还说：‘你有什么益处呢？我不犯罪有什么好处？’'),
('CNV', '约伯记', 18, 35, 4, '我要用言语回答你，和与你在一起的朋友。'),
('CNV', '约伯记', 18, 35, 5, '你要往天仰望观看，细看高过你的云天。'),
('CNV', '约伯记', 18, 35, 6, '你若犯罪，你能使神受害吗？你的过犯若增多，你又能使他受损吗？'),
('CNV', '约伯记', 18, 35, 7, '你若为人正义，你能给他什么呢？他从你手里能领受什么呢？'),
('CNV', '约伯记', 18, 35, 8, '你的邪恶只能害像你的人，你的公义也只能叫世人得益。'),
('CNV', '约伯记', 18, 35, 9, '他们因多受欺压而呼叫，因受强权者的压制而呼求。'),
('CNV', '约伯记', 18, 35, 10, '却没有说：‘神我的创造主在哪里呢？他使人在夜间歌唱。'),
('CNV', '约伯记', 18, 35, 11, '他教导我们过于教导地上的走兽，使我们有智慧胜于空中的飞鸟。’'),
('CNV', '约伯记', 18, 35, 12, '因为恶人骄傲的缘故，他们在那里呼求，神却不回答。'),
('CNV', '约伯记', 18, 35, 13, '真的，神必不垂听虚妄的呼求，全能者也必不留意，'),
('CNV', '约伯记', 18, 35, 14, '更何况你说你不得见他。你的案件在他面前，你忍耐地等候他吧！'),
('CNV', '约伯记', 18, 35, 15, '但现在因为他还没有在忿怒中降罚，也不大理会人的过犯；'),
('CNV', '约伯记', 18, 35, 16, '所以约伯开口说空话，多说无知识的话。”'),
('CNV', '约伯记', 18, 36, 1, '以利户又接着说：'),
('CNV', '约伯记', 18, 36, 2, '“你再等我片刻我就指示你，因为我还有话要为神说。'),
('CNV', '约伯记', 18, 36, 3, '我要从远处引来我的意见，把公义归给我的创造主。'),
('CNV', '约伯记', 18, 36, 4, '我的话真的不是谎言，有一位知识全备的与你同在。'),
('CNV', '约伯记', 18, 36, 5, '神大有能力，并且不藐视人，他的智慧大有能力。'),
('CNV', '约伯记', 18, 36, 6, '他不容恶人生存，却为困苦人主持公道。'),
('CNV', '约伯记', 18, 36, 7, '他的眼目时常看顾义人，他使他们与君王同坐宝座，他们永远被高举。'),
('CNV', '约伯记', 18, 36, 8, '他们若被锁链捆住，被苦难的绳索缠住，'),
('CNV', '约伯记', 18, 36, 9, '他就把他们的作为和过犯都显示，使他们知道他们骄傲自大。'),
('CNV', '约伯记', 18, 36, 10, '他开启他们的耳朵可以领受教训，吩咐他们离开罪孽而悔改。'),
('CNV', '约伯记', 18, 36, 11, '他们若听从他、事奉他，就必幸福地度尽他们的日子，也必快乐地度过他们的岁月。'),
('CNV', '约伯记', 18, 36, 12, '他们若不听从，就必死在刀下，毫无知识地气绝身亡。'),
('CNV', '约伯记', 18, 36, 13, '那些心里不敬虔的人积存怒气，神捆绑他们，他们竟不呼求。'),
('CNV', '约伯记', 18, 36, 14, '他必早年丧命，丧命如庙妓一样。'),
('CNV', '约伯记', 18, 36, 15, '神藉着苦难救拔困苦人，以他们所受的压迫开启他们的耳朵。'),
('CNV', '约伯记', 18, 36, 16, '他也诱导你脱离患难的虎口，到宽阔不狭窄之地，到你摆满肥甘的席上。'),
('CNV', '约伯记', 18, 36, 17, '你却满有恶人所当受的审判，审断和刑罚把你抓住。'),
('CNV', '约伯记', 18, 36, 18, '你要小心不可让忿怒激动你，以致侮慢神，也不要因赎价大而偏离正道。'),
('CNV', '约伯记', 18, 36, 19, '你的呼求、或一切势力，能使你不受患难吗？'),
('CNV', '约伯记', 18, 36, 20, '你不可切慕黑夜来临，就是众人在他们的住处被除灭的时候。'),
('CNV', '约伯记', 18, 36, 21, '你要小心，不可转向罪孽，因为你选择罪孽而不选择患难。'),
('CNV', '约伯记', 18, 36, 22, '神靠自己的能力高高在上，有谁像神指教人呢？'),
('CNV', '约伯记', 18, 36, 23, '谁把他所行的道路派给他？谁能说：‘你所行的不义’呢？'),
('CNV', '约伯记', 18, 36, 24, '你要记得称赞他所行的为大，就是众人所歌颂的。'),
('CNV', '约伯记', 18, 36, 25, '他所行的，万人都看见，世人都从远处观看。'),
('CNV', '约伯记', 18, 36, 26, '神为至大，我们不能了解，他的年数，无法测度。'),
('CNV', '约伯记', 18, 36, 27, '他吸收滴滴水点，使水滴在云雾中化成雨，'),
('CNV', '约伯记', 18, 36, 28, '云层倾下雨水，沛然降在世人身上。'),
('CNV', '约伯记', 18, 36, 29, '谁能明白云彩的展开，和神行宫的雷声呢？'),
('CNV', '约伯记', 18, 36, 30, '他在自己的周围展开电光，又用水遮盖海底；'),
('CNV', '约伯记', 18, 36, 31, '他用这些审断万人，又赐予丰盛的粮食；'),
('CNV', '约伯记', 18, 36, 32, '他以电光遮盖双手，然后吩咐电光去攻击目标，'),
('CNV', '约伯记', 18, 36, 33, '他以雷声宣扬自己，甚至牲畜也注意将有什么临近。”'),
('CNV', '约伯记', 18, 37, 1, '“我的心因此战兢，跳离原处。'),
('CNV', '约伯记', 18, 37, 2, '你们当细听他轰轰的声音，他口中发出隆隆的雷声。'),
('CNV', '约伯记', 18, 37, 3, '他发雷声响遍天下，也发电光闪到地极。'),
('CNV', '约伯记', 18, 37, 4, '接着雷声霹雳，神以自己威严之声打雷，人听到雷声的时候，神并没有留住风霜雨云（“风霜雨云”直译是“它们”）。'),
('CNV', '约伯记', 18, 37, 5, '神以奇妙的方法打雷，他行大事，我们不能了解。'),
('CNV', '约伯记', 18, 37, 6, '他对雪说：‘降在地上’，对大雨暴雨也是这样。'),
('CNV', '约伯记', 18, 37, 7, '他封住各人的手，叫万人知道他的作为。'),
('CNV', '约伯记', 18, 37, 8, '野兽进入洞中，留在穴里。'),
('CNV', '约伯记', 18, 37, 9, '风暴来自南宫，寒冷出于北方。'),
('CNV', '约伯记', 18, 37, 10, '神所呼的气息结成冰，广阔无边的水也凝结；'),
('CNV', '约伯记', 18, 37, 11, '他使密云满载水气，云彩布散他的电光。'),
('CNV', '约伯记', 18, 37, 12, '电光照着神的指引来往旋转，在地球上行他一切所吩咐的。'),
('CNV', '约伯记', 18, 37, 13, '他使电光来临，是为施行责罚，或为滋润大地，或为赐予慈爱。'),
('CNV', '约伯记', 18, 37, 14, '约伯啊！你当留心听这话，要站立思想神奇妙的事。'),
('CNV', '约伯记', 18, 37, 15, '神怎样吩咐这些，又怎样使云中的电光照耀，你知道吗？'),
('CNV', '约伯记', 18, 37, 16, '密云怎样浮于空中，那知识全备者奇妙的作为，你知道吗？'),
('CNV', '约伯记', 18, 37, 17, '地因南风而寂静的时候，你的衣服怎样热起来，你知道吗？'),
('CNV', '约伯记', 18, 37, 18, '你能与神同铺云天吗？这云天坚硬如铸成的镜子。'),
('CNV', '约伯记', 18, 37, 19, '我们因愚昧无知的缘故，不能陈明我们的案件，请你告诉我们应该对他说什么话。'),
('CNV', '约伯记', 18, 37, 20, '人怎能对他说：‘我要说话’？哪有人自愿灭亡呢？'),
('CNV', '约伯记', 18, 37, 21, '人不能看见云后的强光，唯有经风一吹，天才晴朗。'),
('CNV', '约伯记', 18, 37, 22, '金光来自北方，在神的周围有可怕的威严。'),
('CNV', '约伯记', 18, 37, 23, '论到全能者，我们无法把他查出；他大有能力与公平，又满有公义，他必不苦待人。'),
('CNV', '约伯记', 18, 37, 24, '因此人人都应该敬畏他；心中自以为有智慧的，他都不看顾。”'),
('CNV', '约伯记', 18, 38, 1, '那时，耶和华在旋风中回答约伯，说：'),
('CNV', '约伯记', 18, 38, 2, '“这以无知无识的言语，使我的旨意暗晦不明的是谁呢？'),
('CNV', '约伯记', 18, 38, 3, '现在你要如勇士束腰，我要问你，你要告诉我。'),
('CNV', '约伯记', 18, 38, 4, '我奠定大地根基的时候，你在哪里呢？你若有聪明，就只管说吧。'),
('CNV', '约伯记', 18, 38, 5, '你一定晓得是谁定大地的尺度，是谁把准绳拉在大地之上？'),
('CNV', '约伯记', 18, 38, 6, '地的基础奠在哪里，地的角石是谁安放的？'),
('CNV', '约伯记', 18, 38, 7, '那时晨星一起歌唱，神的众子也都欢呼。'),
('CNV', '约伯记', 18, 38, 8, '海水冲出如婴孩出母胎，那时谁用门把海水关闭呢？'),
('CNV', '约伯记', 18, 38, 9, '是我以云彩当作海的衣服，以幽暗当作包裹海的布；'),
('CNV', '约伯记', 18, 38, 10, '我为海定界限，又安置门闩和门户，'),
('CNV', '约伯记', 18, 38, 11, '说：‘你只可到这里，不可越过，你狂傲的波浪要在这里止住。’'),
('CNV', '约伯记', 18, 38, 12, '自你有生以来，你何曾吩咐过晨光照耀，使黎明的曙光知道自己的本位，'),
('CNV', '约伯记', 18, 38, 13, '叫这光照遍大地的四极，把恶人从那里抖掉呢？'),
('CNV', '约伯记', 18, 38, 14, '因着这光，地面改变如在泥上盖上印，万象显出如衣服一样。'),
('CNV', '约伯记', 18, 38, 15, '恶人必得不到亮光，高举的膀臂必被折断。'),
('CNV', '约伯记', 18, 38, 16, '你曾到过海的泉源，在深渊的底处行走过吗？'),
('CNV', '约伯记', 18, 38, 17, '死亡的门曾向你显露吗？死荫的门你曾见过吗？'),
('CNV', '约伯记', 18, 38, 18, '地的广阔，你明白吗？你若完全知道，就只管说吧。'),
('CNV', '约伯记', 18, 38, 19, '哪条是到光明居所的道路？黑暗的本位在哪里？'),
('CNV', '约伯记', 18, 38, 20, '你能把光与暗带到它们的境地吗？你晓得通到它们居所的路吗？'),
('CNV', '约伯记', 18, 38, 21, '你是知道的，因为那时你已经出生了，你一生的日数也很多。'),
('CNV', '约伯记', 18, 38, 22, '你曾入过雪库，或见过雹仓吗？'),
('CNV', '约伯记', 18, 38, 23, '这些雪雹是我为降患难的时候，为打仗和争战的日子所存留的。'),
('CNV', '约伯记', 18, 38, 24, '光从哪条路散开，东风从哪里分散在地上？'),
('CNV', '约伯记', 18, 38, 25, '谁为大雨分水道，谁为雷电定道路？'),
('CNV', '约伯记', 18, 38, 26, '使雨降在无人之地，落在无人居住的旷野，'),
('CNV', '约伯记', 18, 38, 27, '使荒废之地得着滋润，使青草在干旱之地得以长起来呢？'),
('CNV', '约伯记', 18, 38, 28, '雨有父亲吗？露珠是谁生的呢？'),
('CNV', '约伯记', 18, 38, 29, '冰出自谁的胎？天上的霜是谁所生的呢？'),
('CNV', '约伯记', 18, 38, 30, '众水坚硬如石头，深渊的表面冻结成冰。'),
('CNV', '约伯记', 18, 38, 31, '你能系住昴星的结吗？你能解开参星的带吗？'),
('CNV', '约伯记', 18, 38, 32, '你能按时领出玛查鲁夫星系吗？你能引导北斗和随从它的众星吗？'),
('CNV', '约伯记', 18, 38, 33, '你晓得天的定例吗？你能在地上建立天的权威吗？'),
('CNV', '约伯记', 18, 38, 34, '你能向密云扬声吗？你能使洪水淹没你吗？'),
('CNV', '约伯记', 18, 38, 35, '你能差派闪电，闪电就发出，并且对你说：‘我们在这里’吗？'),
('CNV', '约伯记', 18, 38, 36, '谁把智慧放在怀里，或把聪明赐于人的心中？'),
('CNV', '约伯记', 18, 38, 37, '尘土融合成团，土块黏结在一起的时候，'),
('CNV', '约伯记', 18, 38, 38, '谁能凭智慧数算云天呢？谁能把天上的水袋倾倒呢？'),
('CNV', '约伯记', 18, 38, 39, '狮子在洞中蹲伏，在藏身之处躺卧埋伏的时候，'),
('CNV', '约伯记', 18, 38, 40, '你能为母狮猎取食物吗？你能使食欲饱足吗？'),
('CNV', '约伯记', 18, 38, 41, '乌鸦雏鸟因缺乏食物飞来飞去，向神哀求的时候，谁为乌鸦预备食物呢？”'),
('CNV', '约伯记', 18, 39, 1, '“山岩间的野山羊的产期你能晓得吗？母鹿下犊之期你能察出吗？'),
('CNV', '约伯记', 18, 39, 2, '它们怀胎的月数你能计算吗？它们生产的日期你能晓得吗？'),
('CNV', '约伯记', 18, 39, 3, '它们屈身，把子产下，就除掉生产的疼痛。'),
('CNV', '约伯记', 18, 39, 4, '幼雏渐渐健壮，在荒野长大，它们一离群出去，就不再返回。'),
('CNV', '约伯记', 18, 39, 5, '谁放野驴自由出去呢？谁解开快驴的绳索呢？'),
('CNV', '约伯记', 18, 39, 6, '我使原野作它的家，使咸地作它的居所。'),
('CNV', '约伯记', 18, 39, 7, '它嗤笑城里的喧哗，不听赶野驴的呼喝声；'),
('CNV', '约伯记', 18, 39, 8, '它探索群山作它的草场，寻觅各样青绿的东西。'),
('CNV', '约伯记', 18, 39, 9, '野牛怎肯作你的仆人，或在你的槽旁过夜呢？'),
('CNV', '约伯记', 18, 39, 10, '你怎能用套绳把野牛系在犁沟呢？它怎肯跟着你耙山谷之地呢？'),
('CNV', '约伯记', 18, 39, 11, '你怎能因它的力大就倚赖它？怎能把你所作的交给它作呢？'),
('CNV', '约伯记', 18, 39, 12, '怎能信任它能把你的粮食运回来；又收聚你禾场上的谷粒呢？'),
('CNV', '约伯记', 18, 39, 13, '鸵鸟的翅膀欣然鼓动，但它的翎毛和羽毛哪有慈爱呢？'),
('CNV', '约伯记', 18, 39, 14, '它把蛋都留在地上，使它们在土里得温暖，'),
('CNV', '约伯记', 18, 39, 15, '它却忘记了人的脚可以把蛋踩碎，野地的走兽会把蛋践踏。'),
('CNV', '约伯记', 18, 39, 16, '它苛待幼雏，看它们好像不是自己生的，就算它的劳苦白费了，也漠不关心，'),
('CNV', '约伯记', 18, 39, 17, '因为神使它忘记了智慧，也没有把聪明分给它。'),
('CNV', '约伯记', 18, 39, 18, '它挺身鼓翼奔跑的时候，就讥笑马和骑马的人。'),
('CNV', '约伯记', 18, 39, 19, '马的大力是你所赐的吗？它颈上的鬃毛是你披上的吗？'),
('CNV', '约伯记', 18, 39, 20, '是你使它跳跃像蝗虫吗？它喷气之威使人惊惶。'),
('CNV', '约伯记', 18, 39, 21, '它在谷中扒地，以己力为乐，它出去迎战手持武器的人。'),
('CNV', '约伯记', 18, 39, 22, '它讥笑可怕的事，并不惊慌，也不在刀剑的面前退缩。'),
('CNV', '约伯记', 18, 39, 23, '箭袋、闪烁的矛与枪，都在它的身上铮铮有声。'),
('CNV', '约伯记', 18, 39, 24, '它震抖激动，驰骋大地，一听见角声，就不能站定。'),
('CNV', '约伯记', 18, 39, 25, '角声一响，它就说‘呵哈’，它从远处闻到战争的气味，又听见军长的雷声和战争的吶喊。'),
('CNV', '约伯记', 18, 39, 26, '鹰鸟飞翔，展翅南飞，是因着你的聪明吗？'),
('CNV', '约伯记', 18, 39, 27, '大鹰上腾，在高处筑巢，是听你的吩咐吗？'),
('CNV', '约伯记', 18, 39, 28, '它住在山岩之上，栖息在岩崖与坚固所在之上，'),
('CNV', '约伯记', 18, 39, 29, '从那里窥看猎物，它们的眼睛可以从远处观望。'),
('CNV', '约伯记', 18, 39, 30, '它的幼雏也都吮血；被杀的人在哪里，鹰也在哪里。”'),
('CNV', '约伯记', 18, 40, 1, '耶和华又对约伯说：'),
('CNV', '约伯记', 18, 40, 2, '“挑剔是非的，怎能与全能者争辩呢？责备神的，回答这个问题吧。”'),
('CNV', '约伯记', 18, 40, 3, '于是约伯回答耶和华说：'),
('CNV', '约伯记', 18, 40, 4, '“我是微小的，可以回答你什么呢？我只好用手掩口。'),
('CNV', '约伯记', 18, 40, 5, '这说了一次，不再回答；说了二次就不再说。”'),
('CNV', '约伯记', 18, 40, 6, '于是耶和华从旋风中回答约伯说：'),
('CNV', '约伯记', 18, 40, 7, '“你要如勇士束腰，我要问你，你要告诉我。'),
('CNV', '约伯记', 18, 40, 8, '你怎能废弃我所审断的？怎能定我为有罪，好显出你自己为义呢？'),
('CNV', '约伯记', 18, 40, 9, '你有神那样的膀臂吗？你能用他那样的声音打雷吗？'),
('CNV', '约伯记', 18, 40, 10, '你当以庄严与尊贵为装饰，以尊荣与威严为衣服。'),
('CNV', '约伯记', 18, 40, 11, '要倒尽你忿激的怒气，观看所有骄傲的人，使他们降卑。'),
('CNV', '约伯记', 18, 40, 12, '观看所有骄傲的人，把他制伏，把恶人践踏在他们的地方，'),
('CNV', '约伯记', 18, 40, 13, '把他们一起掩藏在尘土里，把他们本人捆绑在隐密处。'),
('CNV', '约伯记', 18, 40, 14, '这样，我就要向你承认，你的右手能拯救你。'),
('CNV', '约伯记', 18, 40, 15, '你看看河马吧，我造它像造你一样，它吃草如牛一般。'),
('CNV', '约伯记', 18, 40, 16, '你看，它的力量在腰间，它的能力在肚腹的肌肉上，'),
('CNV', '约伯记', 18, 40, 17, '它挺直尾巴硬如香柏树，它大腿的筋虬结在一起，'),
('CNV', '约伯记', 18, 40, 18, '它的骨头仿佛铜管，它的骨干好像铁棍。'),
('CNV', '约伯记', 18, 40, 19, '它在神所造的事工中居首（“它在神所造的事工中居首”直译作“它在神的工作中居首”），只有创造它的能使刀剑临到它身上。'),
('CNV', '约伯记', 18, 40, 20, '群山为它生出食物，田野的百兽都在那里玩耍。'),
('CNV', '约伯记', 18, 40, 21, '它躺在莲叶之下，躺在芦苇丛中与泥泽之间；'),
('CNV', '约伯记', 18, 40, 22, '莲叶的阴影遮蔽它，溪旁的白杨树环绕它。'),
('CNV', '约伯记', 18, 40, 23, '江河泛滥，它毫不慌张，约旦河的水涨到它的口边，它还是安然。'),
('CNV', '约伯记', 18, 40, 24, '它警觉的时候谁能捉拿它？谁能用铁圈穿它的鼻子呢？”'),
('CNV', '约伯记', 18, 41, 1, '“你能用鱼钩钓上鳄鱼吗？能用绳子把它的舌头压下吗？'),
('CNV', '约伯记', 18, 41, 2, '能把草绳穿进它的鼻子吗？能用刺钩穿透它的腮骨吗？'),
('CNV', '约伯记', 18, 41, 3, '它会向你再三恳求，对你说温柔的话吗？'),
('CNV', '约伯记', 18, 41, 4, '它肯与你立约，好使你永远奴役它吗？'),
('CNV', '约伯记', 18, 41, 5, '你怎能玩弄它，像玩弄雀鸟一样呢？怎能把它拴住，给你的幼女取乐呢？'),
('CNV', '约伯记', 18, 41, 6, '结伙的渔夫怎能拿它当货物买卖呢？怎能把它分给商人呢？'),
('CNV', '约伯记', 18, 41, 7, '你能用倒钩扎满它的皮吗？能用鱼叉扎满它的头吗？'),
('CNV', '约伯记', 18, 41, 8, '你把手按在它身上，想到与它的战斗，你就不再是这样作了。（本章第1~8节在《马索拉文本》为40:25~32）'),
('CNV', '约伯记', 18, 41, 9, '人希望捉住它是徒然的，人一见它，就心惊胆战。（本节在《马索拉文本》为41:1）'),
('CNV', '约伯记', 18, 41, 10, '人惹它的时候，它不是很凶猛吗？这样，有谁人在我面前能站立得住呢？'),
('CNV', '约伯记', 18, 41, 11, '谁先给了我，以致我要偿还呢？天下万物，都是我的。'),
('CNV', '约伯记', 18, 41, 12, '论到鳄鱼的四肢和它的力气，以及美好的体态，我不能缄默不言。'),
('CNV', '约伯记', 18, 41, 13, '谁能揭开它的外皮呢？谁能进入它上下两颚之间呢？'),
('CNV', '约伯记', 18, 41, 14, '谁能打开它的口呢？它的牙齿令人战栗。'),
('CNV', '约伯记', 18, 41, 15, '它的背有一行一行的鳞甲，紧紧合闭着，像印得很紧的印章一样。'),
('CNV', '约伯记', 18, 41, 16, '这鳞甲一一相连接，连气也透不入其间，'),
('CNV', '约伯记', 18, 41, 17, '鳞甲一一互相连合，互相紧贴，不能分离。'),
('CNV', '约伯记', 18, 41, 18, '它打的喷嚏闪出光来，它的眼睛如同清晨的阳光；'),
('CNV', '约伯记', 18, 41, 19, '有火从它的口中发出，火星四射；'),
('CNV', '约伯记', 18, 41, 20, '有烟从它的鼻孔里冒出来，像从沸腾的锅中和烧着的芦苇里冒出来一样；'),
('CNV', '约伯记', 18, 41, 21, '它的气可以点着煤炭，有火焰从它的口里喷出来，'),
('CNV', '约伯记', 18, 41, 22, '它的颈项上存着能力，惊恐在它面前跳跃。'),
('CNV', '约伯记', 18, 41, 23, '它下垂的肌肉紧贴在一起，牢牢地贴在身上，不能摇动。'),
('CNV', '约伯记', 18, 41, 24, '它的心坚实如石头，如下磨石那样坚实。'),
('CNV', '约伯记', 18, 41, 25, '它一起来，勇士都惊慌，因惊惶过度举止失措。'),
('CNV', '约伯记', 18, 41, 26, '追上它的刀剑都没用，矛枪、标枪、短枪也是这样。'),
('CNV', '约伯记', 18, 41, 27, '它把铁当作干草，把铜当作朽木。'),
('CNV', '约伯记', 18, 41, 28, '弓箭不能使它逃跑，甩石机弦在它看来不过是碎秸。'),
('CNV', '约伯记', 18, 41, 29, '棍棒被它当作碎秸，短枪飕飕之声它也讥笑。'),
('CNV', '约伯记', 18, 41, 30, '它的腹下像锐利的瓦片，它在泥上碾过如同有利钉的耙犁田一样。'),
('CNV', '约伯记', 18, 41, 31, '它使深渊沸腾，它搅动海洋如在鼎中调制膏油。'),
('CNV', '约伯记', 18, 41, 32, '它使自己行过的路发出白光，令人把深渊当作白发老人。'),
('CNV', '约伯记', 18, 41, 33, '在世上没有一样像它的，它是无所惧怕的动物；'),
('CNV', '约伯记', 18, 41, 34, '所有高大的动物，它都藐视，它在一切狂傲的野兽之上作王。”'),
('CNV', '约伯记', 18, 42, 1, '约伯回答耶和华说：'),
('CNV', '约伯记', 18, 42, 2, '“我知道你万事都能作，你的旨意是不能拦阻的。'),
('CNV', '约伯记', 18, 42, 3, '这以无知无识的言语使神的旨意模糊不清的是谁呢？所以我说了我所不明白的；这些事太奇妙，是我不晓得的。'),
('CNV', '约伯记', 18, 42, 4, '求你听我，我要说话；我要问你，你要告诉我。'),
('CNV', '约伯记', 18, 42, 5, '我从前只是风闻有你，但现在亲眼看见你。'),
('CNV', '约伯记', 18, 42, 6, '因此我厌恶自己，在尘土和灰烬中懊悔。”'),
('CNV', '约伯记', 18, 42, 7, '耶和华对约伯说了这些话以后，就对提幔人以利法说：“我要向你和你的两个朋友生气，因为你们讲论我，不如我的仆人约伯说的对。'),
('CNV', '约伯记', 18, 42, 8, '现在你们要为自己取七头公牛、七只公羊，到我的仆人约伯那里去，为你们献上燔祭，我的仆人约伯就替你们祷告；我悦纳他的祷告，就不按照你们的愚昧待你们。你们讲论我，不如我的仆人约伯说的对。”'),
('CNV', '约伯记', 18, 42, 9, '于是提幔人以利法、书亚人比勒达、拿玛人琐法，照着耶和华吩咐他们的去行，耶和华就悦纳约伯的祷告。'),
('CNV', '约伯记', 18, 42, 10, '约伯替他的朋友祷告，耶和华就恢复约伯原来的景况，还照约伯以前所有的一切加倍赐给他。'),
('CNV', '约伯记', 18, 42, 11, '约伯的众兄弟姊妹和以前认识的人都来见他，在他家里与他一同吃饭，又因耶和华降予他的一切灾祸都对他表同情，安慰他，每人送他一块银子和一个金环。'),
('CNV', '约伯记', 18, 42, 12, '这样，耶和华后来赐给约伯的福比先前更多：他有一万四千只羊、六千匹骆驼、一千对牛、一千头母驴。'),
('CNV', '约伯记', 18, 42, 13, '他也有七个儿子和三个女儿。'),
('CNV', '约伯记', 18, 42, 14, '他给长女起名叫耶米玛，次女名叫基洗亚，三女名叫基连．哈朴。'),
('CNV', '约伯记', 18, 42, 15, '在那全地中，找不到像约伯女儿那么美貌的妇女。她们的父亲在她们兄弟中间把产业分给她们。'),
('CNV', '约伯记', 18, 42, 16, '此后，约伯又活了一百四十年，得见他的儿孙到四代。'),
('CNV', '约伯记', 18, 42, 17, '这样，约伯年纪老迈，寿终而死。'),
('CNV', '诗篇', 19, 1, 1, '有福的人：不从恶人的计谋，不站罪人的道路，不坐好讥笑的人的座位。'),
('CNV', '诗篇', 19, 1, 2, '他喜爱的是耶和华的律法，他昼夜默诵的也是耶和华的律法。'),
('CNV', '诗篇', 19, 1, 3, '他像一棵树，栽在溪水旁，按时结果子，叶子总不枯干；他所作的一切，尽都顺利。'),
('CNV', '诗篇', 19, 1, 4, '恶人却不是这样，他们好像糠秕，被风吹散。'),
('CNV', '诗篇', 19, 1, 5, '因此，在审判的时候，恶人必站立不住；在义人的团体中，罪人也必这样。'),
('CNV', '诗篇', 19, 1, 6, '因为耶和华看顾义人的道路，恶人的道路却必灭亡。'),
('CNV', '诗篇', 19, 2, 1, '列国为什么骚动？万民为什么空谋妄想？'),
('CNV', '诗篇', 19, 2, 2, '世上的君王起来，首领聚在一起，敌对耶和华和他所膏立的，说：'),
('CNV', '诗篇', 19, 2, 3, '“我们来挣断他们给我们的束缚，摆脱他们的绳索！”'),
('CNV', '诗篇', 19, 2, 4, '那坐在天上的必发笑，主必讥笑他们。'),
('CNV', '诗篇', 19, 2, 5, '那时，他必在烈怒中对他们讲话，在震怒中使他们惊慌，说：'),
('CNV', '诗篇', 19, 2, 6, '“我已经在锡安我的圣山上，立了我的君王。”'),
('CNV', '诗篇', 19, 2, 7, '受膏者说：“我要宣告耶和华的谕旨：耶和华对我说：‘你是我的儿子，我今日生了你。'),
('CNV', '诗篇', 19, 2, 8, '你求我，我就把列国赐给你作产业，把全地都归属于你。'),
('CNV', '诗篇', 19, 2, 9, '你必用铁杖击打他们，好像打碎陶器一样粉碎他们。’”'),
('CNV', '诗篇', 19, 2, 10, '现在，君王啊！你们要谨慎。地上的审判官啊！你们应当听劝告。'),
('CNV', '诗篇', 19, 2, 11, '你们要以敬畏的态度事奉耶和华，又应当存战兢的心而欢呼。'),
('CNV', '诗篇', 19, 2, 12, '你们要用嘴亲吻子，否则他一发怒，你们就在路上灭亡，因为他的怒气快要发作。凡是投靠他的，都是有福的。'),
('CNV', '诗篇', 19, 3, 1, '耶和华啊！我的仇敌竟然这么多。起来攻击我的竟然那么多。'),
('CNV', '诗篇', 19, 3, 2, '有很多人议论我说：“他从神那里得不到救助。”（细拉）'),
('CNV', '诗篇', 19, 3, 3, '耶和华啊！你却是我周围的盾牌，是我的荣耀，是使我抬起头来的。'),
('CNV', '诗篇', 19, 3, 4, '我发声向耶和华呼求的时候，他就从他的圣山上回答我。（细拉）'),
('CNV', '诗篇', 19, 3, 5, '我躺下，我睡觉，我醒来，都因耶和华在扶持着我。'),
('CNV', '诗篇', 19, 3, 6, '虽有千万人包围攻击我，我也不怕。'),
('CNV', '诗篇', 19, 3, 7, '耶和华啊！求你起来；我的神啊！求你拯救我，你击打了我所有仇敌的脸颊，打碎了恶人的牙齿。'),
('CNV', '诗篇', 19, 3, 8, '救恩属于耶和华，愿你赐福给你的子民。（细拉）'),
('CNV', '诗篇', 19, 4, 1, '我公义的神啊（“我公义的神啊”或译：“使我为义的神啊”）！我呼求的时候，求你答应我。我在困苦中，你曾使我舒畅。求你恩待我，听我的祷告。'),
('CNV', '诗篇', 19, 4, 2, '尊贵的人啊！你们把我的荣耀变为羞辱，要到几时呢？你们喜爱虚妄，追求虚谎，要到几时呢？（细拉）'),
('CNV', '诗篇', 19, 4, 3, '你们要知道耶和华已经把虔诚人分别出来，归他自己；我向耶和华呼求的时候，他就垂听。'),
('CNV', '诗篇', 19, 4, 4, '你们生气，却不可犯罪；在床上的时候，你们要在心里思想，并且要安静。（细拉）'),
('CNV', '诗篇', 19, 4, 5, '你们应当献公义的祭，也要投靠耶和华。'),
('CNV', '诗篇', 19, 4, 6, '有许多人说：“谁能指示我们得什么好处呢？”耶和华啊！求你仰起你的脸，光照我们。'),
('CNV', '诗篇', 19, 4, 7, '你使我心里喜乐，胜过人在丰收五谷新酒时的喜乐。'),
('CNV', '诗篇', 19, 4, 8, '我必平平安安躺下睡觉，因为只有你耶和华能使我安然居住。'),
('CNV', '诗篇', 19, 5, 1, '耶和华啊！求你留心听我的话，顾念我的叹息。'),
('CNV', '诗篇', 19, 5, 2, '我的王，我的神啊！求你倾听我呼求的声音，因为我向你祷告。'),
('CNV', '诗篇', 19, 5, 3, '耶和华啊！求你在清晨听我的声音；我要一早向你陈明，并且迫切等候。'),
('CNV', '诗篇', 19, 5, 4, '因为你是不喜爱邪恶的神，恶人不能与你同住。'),
('CNV', '诗篇', 19, 5, 5, '狂傲的人不能在你眼前站立，你恨恶所有作恶的人。'),
('CNV', '诗篇', 19, 5, 6, '你必灭绝说谎话的；好流人血和弄诡诈的，都是耶和华所憎恶的。'),
('CNV', '诗篇', 19, 5, 7, '至于我，我必凭着你丰盛的慈爱，进入你的殿；我要存着敬畏你的心，向你的圣所敬拜。'),
('CNV', '诗篇', 19, 5, 8, '耶和华啊！求你因我仇敌的缘故，按着你的公义引导我，在我面前铺平你的道路。'),
('CNV', '诗篇', 19, 5, 9, '因为他们的口里没有真话，他们的内心充满毁灭人的意图，他们的喉咙是敞开的坟墓，他们用舌头弄诡诈。'),
('CNV', '诗篇', 19, 5, 10, '神啊！求你定他们的罪；愿他们因自己的诡计跌倒，愿你因他们许多的过犯，把他们赶出去，因为他们背叛了你。'),
('CNV', '诗篇', 19, 5, 11, '愿所有投靠你的人都喜乐，常常欢呼；愿你保护他们，又愿爱你名的人，因你欢乐。'),
('CNV', '诗篇', 19, 5, 12, '耶和华啊！因为你必赐福给义人，你要以恩惠像盾牌四面护卫他。'),
('CNV', '诗篇', 19, 6, 1, '耶和华啊！求你不要在烈怒中责备我，也不要在气忿中管教我。'),
('CNV', '诗篇', 19, 6, 2, '耶和华啊！求你恩待我，因为我软弱；耶和华啊！求你医治我，因为我的骨头发抖。'),
('CNV', '诗篇', 19, 6, 3, '我的心也大大战栗，耶和华啊！要等到几时呢？'),
('CNV', '诗篇', 19, 6, 4, '耶和华啊！求你回转搭救我，因你慈爱的缘故拯救我。'),
('CNV', '诗篇', 19, 6, 5, '因为在死亡之地无人记念你，在阴间有谁称谢你呢？'),
('CNV', '诗篇', 19, 6, 6, '我因悲叹而疲惫，我夜夜流泪，把床漂起，把床榻浸透。'),
('CNV', '诗篇', 19, 6, 7, '我因愁烦眼目昏花，因众多的仇敌视力衰退。'),
('CNV', '诗篇', 19, 6, 8, '你们所有作恶的人，离开我去吧，因为耶和华听了我哀哭的声音。'),
('CNV', '诗篇', 19, 6, 9, '耶和华听了我的恳求，耶和华必接纳我的祷告。'),
('CNV', '诗篇', 19, 6, 10, '我所有的仇敌都必蒙羞，大大惊惶；眨眼之间，他们必蒙羞后退。'),
('CNV', '诗篇', 19, 7, 1, '耶和华我的神啊！我已经投靠了你，求你拯救我脱离所有追赶我的人。求你搭救我，'),
('CNV', '诗篇', 19, 7, 2, '免得他们像狮子一般把我撕裂，把我撕碎的时候，也没有人搭救。'),
('CNV', '诗篇', 19, 7, 3, '耶和华我的神啊！如果我作了这事，如果我手中有罪孽，'),
('CNV', '诗篇', 19, 7, 4, '如果我以恶回报那与我为友的人，或是无故掠夺与我为敌的人，'),
('CNV', '诗篇', 19, 7, 5, '就任凭仇敌追赶我，直到追上，把我的性命践踏在地上，使我的光荣归于尘土。（细拉）'),
('CNV', '诗篇', 19, 7, 6, '耶和华啊！求你在怒中起来，求你挺身而起，抵挡我敌人的暴怒，求你为我兴起；你已经出令施行审判。'),
('CNV', '诗篇', 19, 7, 7, '愿万民聚集环绕你，愿你归回高处，统管他们。'),
('CNV', '诗篇', 19, 7, 8, '愿耶和华审判万民。耶和华啊！求你按着我的公义，照着我心中的正直判断我。'),
('CNV', '诗篇', 19, 7, 9, '愿恶人的恶行止息，愿你使义人坚立。公义的神啊！你是察验人心肠肺腑的。'),
('CNV', '诗篇', 19, 7, 10, '神是我的盾牌，他拯救心里正直的人。'),
('CNV', '诗篇', 19, 7, 11, '神是公义的审判者，他是天天向恶人发怒的神。'),
('CNV', '诗篇', 19, 7, 12, '如果人不悔改，神必把他的刀磨快。神已经把弓拉开，准备妥当。'),
('CNV', '诗篇', 19, 7, 13, '他亲自预备了致命的武器，他使所射的箭成为燃烧的箭。'),
('CNV', '诗篇', 19, 7, 14, '看哪！恶人为了罪孽经历产痛，他怀的是恶毒，生下的是虚谎。'),
('CNV', '诗篇', 19, 7, 15, '他挖掘坑穴，挖得深深的，自己却掉进所挖的陷阱里。'),
('CNV', '诗篇', 19, 7, 16, '他的恶毒必回到自己的头上，他的强暴必落在自己的头顶上。'),
('CNV', '诗篇', 19, 7, 17, '我要照着耶和华的公义称谢他，歌颂至高者耶和华的名。'),
('CNV', '诗篇', 19, 8, 1, '耶和华我们的主啊！你的名在全地是多么威严，你把你的荣美彰显在天上。'),
('CNV', '诗篇', 19, 8, 2, '因你仇敌的缘故，你从小孩和婴儿的口中，得着了赞美（“得着了赞美”或译：“建立了能力”），使仇敌和报仇的无话可说。'),
('CNV', '诗篇', 19, 8, 3, '我观看你手所造的天，和你所安放的月亮和星星。'),
('CNV', '诗篇', 19, 8, 4, '啊！人算什么，你竟记念他？世人算什么，你竟眷顾他？'),
('CNV', '诗篇', 19, 8, 5, '你使他比天使（“天使”或译：“神”）低微一点，却赐给他荣耀尊贵作冠冕。'),
('CNV', '诗篇', 19, 8, 6, '你叫他管理你手所造的，把万物都放在他的脚下，'),
('CNV', '诗篇', 19, 8, 7, '就是所有的牛羊、田间的走兽、'),
('CNV', '诗篇', 19, 8, 8, '空中的飞鸟、海里的鱼，和海里游行的水族。'),
('CNV', '诗篇', 19, 8, 9, '耶和华我们的主啊！你的名在全地是多么威严。'),
('CNV', '诗篇', 19, 9, 1, '耶和华啊！我要全心称谢你，我要述说你一切奇妙的作为。'),
('CNV', '诗篇', 19, 9, 2, '我要因你快乐欢欣；至高者啊！我要歌颂你的名。'),
('CNV', '诗篇', 19, 9, 3, '我的仇敌转身退后的时候，就在你的面前绊倒、灭亡。'),
('CNV', '诗篇', 19, 9, 4, '因为你为我伸了冤，辨了屈；你坐在宝座上，施行公义的审判。'),
('CNV', '诗篇', 19, 9, 5, '你斥责了列国，灭绝了恶人；你涂抹了他们的名，直到永永远远。'),
('CNV', '诗篇', 19, 9, 6, '仇敌的结局到了，他们遭毁灭，直到永远；你拆毁他们的城镇，使它们湮没无闻。'),
('CNV', '诗篇', 19, 9, 7, '耶和华却永远坐着为王，为了施行审判，他已经设立宝座。'),
('CNV', '诗篇', 19, 9, 8, '他必以公义审判世界，按正直判断万民。'),
('CNV', '诗篇', 19, 9, 9, '耶和华要给受欺压的人作保障，作患难时的避难所。'),
('CNV', '诗篇', 19, 9, 10, '认识你名的人必倚靠你；耶和华啊！你从未撇弃寻求你的人。'),
('CNV', '诗篇', 19, 9, 11, '你们要歌颂住在锡安的耶和华，要在万民中传扬他的作为。'),
('CNV', '诗篇', 19, 9, 12, '因为那追讨流人血的罪的，他记念受苦的人，他没有忘记他们的哀求。'),
('CNV', '诗篇', 19, 9, 13, '耶和华啊！求你恩待我，看看那些恨我的人加给我的苦难；求你把我从死门拉上来，'),
('CNV', '诗篇', 19, 9, 14, '好叫我述说你一切可称颂的事，并在锡安的城门（“的城门”原文作“女子的门”）因你的救恩欢乐。'),
('CNV', '诗篇', 19, 9, 15, '列国陷入自己挖掘的坑中，他们的脚在自己暗设的网里缠住了。'),
('CNV', '诗篇', 19, 9, 16, '耶和华已经把自己显明，又施行了审判；恶人被自己手所作的缠住了。（希迦庸、细拉）'),
('CNV', '诗篇', 19, 9, 17, '恶人都必归到阴间，忘记神的列国都必灭亡。'),
('CNV', '诗篇', 19, 9, 18, '但贫穷的人必不会被永远遗忘，困苦人的希望也必不会永久落空。'),
('CNV', '诗篇', 19, 9, 19, '耶和华啊！求你起来，不要让世人得胜；愿列国都在你面前受审判。'),
('CNV', '诗篇', 19, 9, 20, '耶和华啊！求你使他们惊惧，愿列国都知道自己不过是人。（细拉）'),
('CNV', '诗篇', 19, 10, 1, '耶和华啊！你为什么远远地站着？在患难的时候，你为什么隐藏起来呢？'),
('CNV', '诗篇', 19, 10, 2, '恶人骄横地追逼困苦人，愿恶人陷入自己所设的阴谋中。'),
('CNV', '诗篇', 19, 10, 3, '恶人夸耀心中的欲望，他称赞贪财的人，却藐视耶和华（“他称赞贪财的人，却藐视耶和华”或译：“贪财的人谤渎耶和华，并藐视他”）。'),
('CNV', '诗篇', 19, 10, 4, '恶人面带骄傲，说：“耶和华必不追究！”在他的一切思想中，都没有神。'),
('CNV', '诗篇', 19, 10, 5, '他的道路时常稳妥，你的判断高超，他却不放在眼内；他对所有的仇敌都嗤之以鼻。'),
('CNV', '诗篇', 19, 10, 6, '他心里说：“我必永不摇动，我决不会遭遇灾难。”'),
('CNV', '诗篇', 19, 10, 7, '他口里充满咒诅、诡诈和欺压的话，舌头底下尽是毒害与奸恶。'),
('CNV', '诗篇', 19, 10, 8, '他在村庄里埋伏等候，在隐密处杀害无辜的人，他的眼睛暗地里窥探不幸的人。'),
('CNV', '诗篇', 19, 10, 9, '他在隐密处埋伏，像狮子埋伏在丛林中；他埋伏要掳走困苦人，他把困苦人拉入自己的网中，掳走了他们。'),
('CNV', '诗篇', 19, 10, 10, '他击打，他屈身蹲伏，不幸的人就倒在他的爪下。'),
('CNV', '诗篇', 19, 10, 11, '他心里说：“神已经忘记了，他已经掩面，永远不看。”'),
('CNV', '诗篇', 19, 10, 12, '耶和华啊！求你起来；神啊！求你举起手来，不要忘记困苦的人。'),
('CNV', '诗篇', 19, 10, 13, '恶人为什么藐视神，心里说：“你必不追究”呢？'),
('CNV', '诗篇', 19, 10, 14, '其实你已经看见了，忧患与愁苦你都已经看到，并且放在自己的手中；不幸的人把自己交托你；你是帮助孤儿的。'),
('CNV', '诗篇', 19, 10, 15, '愿你打断恶人和坏人的膀臂，愿你追究他们的恶行，直到清清楚楚。'),
('CNV', '诗篇', 19, 10, 16, '耶和华作王直到永永远远，列国都从他的地上灭亡。'),
('CNV', '诗篇', 19, 10, 17, '耶和华啊！困苦人的心愿你已经听见，你必坚固他们的心，也必留心听他们的呼求；'),
('CNV', '诗篇', 19, 10, 18, '好为孤儿和受欺压的人伸冤，使地上的人不再施行恐吓。'),
('CNV', '诗篇', 19, 11, 1, '我投靠耶和华，你们怎么对我说：“你要像飞鸟逃到你的山上去。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 11, 2, '看哪！恶人的弓已经拉开，箭已经上弦，要从暗处射那心里正直的人。'),
('CNV', '诗篇', 19, 11, 3, '根基既然毁坏，义人还能作什么呢？”'),
('CNV', '诗篇', 19, 11, 4, '耶和华在他的圣殿里，耶和华的宝座在天上，他的眼睛观看，他的目光察验世人。'),
('CNV', '诗篇', 19, 11, 5, '耶和华试验义人和恶人，他的心恨恶喜爱强暴的人。'),
('CNV', '诗篇', 19, 11, 6, '耶和华必使火炭落在恶人身上，烈火、硫磺和旱风是他们杯中的分。'),
('CNV', '诗篇', 19, 11, 7, '因为耶和华是公义的，他喜爱公义的行为，正直的人必得见他的面。'),
('CNV', '诗篇', 19, 12, 1, '耶和华啊！求你施行拯救，因为虔诚人没有了，在世人中的信实人也不见了。'),
('CNV', '诗篇', 19, 12, 2, '他们彼此说谎，用谄媚的嘴唇说话，口是心非。'),
('CNV', '诗篇', 19, 12, 3, '愿耶和华剪除一切说谄媚话的嘴唇，和说夸大话的舌头。'),
('CNV', '诗篇', 19, 12, 4, '他们曾说：“我们必能以舌头取胜；我们的嘴唇是自己的，谁能作我们的主呢？”'),
('CNV', '诗篇', 19, 12, 5, '耶和华说：“因为困苦人的冤屈和贫穷人的叹息，我现在要起来，把他们安置在他们渴望的稳妥之中。”'),
('CNV', '诗篇', 19, 12, 6, '耶和华的言语是纯净的言语，好像银子在泥炉中炼过，精炼过七次一样。'),
('CNV', '诗篇', 19, 12, 7, '耶和华啊！求你保守我们，保护我们永远脱离这世代的人（按照《马索拉文本》，“我们……我们”作“他们……他”;现参照其他抄本及《七十士译本》翻译）。'),
('CNV', '诗篇', 19, 12, 8, '恶人到处横行，邪恶在世人中被高举。'),
('CNV', '诗篇', 19, 13, 1, '耶和华啊！你忘记我要到几时呢？要到永远吗？你掩面不顾我，要到几时呢？'),
('CNV', '诗篇', 19, 13, 2, '我心里筹算不安，内心终日愁苦，要到几时呢？我的仇敌胜过我，要到几时呢？'),
('CNV', '诗篇', 19, 13, 3, '耶和华我的神啊！求你看顾我，应允我；求你使我的眼睛明亮，免得我沉睡至死；'),
('CNV', '诗篇', 19, 13, 4, '免得我的仇敌说：“我胜过了他”；免得我跌倒的时候我的敌人就欢呼。'),
('CNV', '诗篇', 19, 13, 5, '至于我，我倚靠你的慈爱，我的心必因你的救恩欢呼。'),
('CNV', '诗篇', 19, 13, 6, '我要歌颂耶和华，因他以厚恩待我。（本章第5~6节在《马索拉文本》为13:6）'),
('CNV', '诗篇', 19, 14, 1, '愚顽人心里说：“没有神。”他们都是败坏，行了可憎的事，没有一个行善的。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 14, 2, '耶和华从天上察看世人，要看看有明慧的没有，有寻求神的没有。'),
('CNV', '诗篇', 19, 14, 3, '人人都偏离了正道，一同变成污秽；没有行善的，连一个也没有。'),
('CNV', '诗篇', 19, 14, 4, '所有作恶的都是无知的吗？他们吞吃我的子民好像吃饭一样，并不求告耶和华。'),
('CNV', '诗篇', 19, 14, 5, '他们必大大震惊，因为神在义人的群体中。'),
('CNV', '诗篇', 19, 14, 6, '你们要使困苦人的计划失败，但耶和华是他的避难所。'),
('CNV', '诗篇', 19, 14, 7, '但愿以色列的救恩从锡安而出；耶和华给他子民带来复兴的时候（“耶和华给他子民带来复兴的时候”或译：“耶和华把他被掳的子民带回来的时候”），雅各要快乐，以色列要欢喜。'),
('CNV', '诗篇', 19, 15, 1, '耶和华啊！谁能在你的帐幕里寄居？谁能在你的圣山上居住呢？（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 15, 2, '就是行为完全，作事公义，心里说诚实话的人。'),
('CNV', '诗篇', 19, 15, 3, '他不以舌头诋毁人，不恶待朋友，也不毁谤他的邻居。'),
('CNV', '诗篇', 19, 15, 4, '他眼中藐视卑鄙的人，却尊重敬畏耶和华的人。他起了誓，纵然自己吃亏，也不更改。'),
('CNV', '诗篇', 19, 15, 5, '他不拿自己的银子放债取利，也不收受贿赂陷害无辜；行这些事的人，必永不动摇。'),
('CNV', '诗篇', 19, 16, 1, '神啊！求你保守我，因为我投靠你。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 16, 2, '我（“我”有古抄本作“你”）曾对耶和华说：“你是我的主，我的好处不在你以外。”'),
('CNV', '诗篇', 19, 16, 3, '至于世上的圣民，他们都是尊贵荣美的人，全是我所喜爱的。'),
('CNV', '诗篇', 19, 16, 4, '追求别神的，他们的愁苦必定加多。他们所奠的血祭，我不祭奠；我的嘴唇也不提别神的名。'),
('CNV', '诗篇', 19, 16, 5, '耶和华是我的产业，是我杯中的分；我所得的业分，你亲自为我持守。'),
('CNV', '诗篇', 19, 16, 6, '准绳量给我的是佳美之地，我的产业实在令我喜悦。'),
('CNV', '诗篇', 19, 16, 7, '我要称颂那指导我的耶和华，我的心在夜间也劝戒我。'),
('CNV', '诗篇', 19, 16, 8, '我常常把耶和华摆在我面前，因他在我右边，我必不会动摇。'),
('CNV', '诗篇', 19, 16, 9, '为此我的心快乐，我的灵（“灵”或译：“荣耀”或“肝”；与30:12，57:8，108:1同）欢欣，我的肉身也必安然居住。'),
('CNV', '诗篇', 19, 16, 10, '因为你必不把我的灵魂撇在阴间，也必不容你的圣者见朽坏（“朽坏”或译：“深渊”）。'),
('CNV', '诗篇', 19, 16, 11, '你必把生命的路指示我，在你面前有满足的喜乐，在你的右手中有永远的福乐。'),
('CNV', '诗篇', 19, 17, 1, '耶和华啊！求你垂听我公义的案件，倾听我的申诉；求你留心听我的祷告，这不是出于诡诈嘴唇的祷告。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 17, 2, '愿我的判词从你面前发出，愿你的眼睛察看正直的事。'),
('CNV', '诗篇', 19, 17, 3, '你试验了我的心，在夜间鉴察了我；你熬炼了我，还是找不到什么，因为我立志使我的口没有过犯。'),
('CNV', '诗篇', 19, 17, 4, '至于世人的行为，我藉着你嘴唇所出的话，保护了自己，不行强暴人的道路。'),
('CNV', '诗篇', 19, 17, 5, '我的脚步稳踏在你的路径上，我的两脚没有动摇。'),
('CNV', '诗篇', 19, 17, 6, '神啊！我向你呼求，因为你必应允我；求你侧耳听我，垂听我的祷告。'),
('CNV', '诗篇', 19, 17, 7, '求你把你的慈爱奇妙地彰显，用右手拯救那些投靠你的，脱离那些起来攻击他们的。'),
('CNV', '诗篇', 19, 17, 8, '求你保护我，像保护眼中的瞳人，把我隐藏在你的翅膀荫下；'),
('CNV', '诗篇', 19, 17, 9, '使我脱离那些欺压我的恶人，脱离那些围绕我的死敌。'),
('CNV', '诗篇', 19, 17, 10, '他们闭塞了怜悯的心（“怜悯的心”原文作“他们的脂油”），口里说出骄傲的话。'),
('CNV', '诗篇', 19, 17, 11, '他们追踪我，现在把我围困了（“他们追踪我，现在把我围困了”原文作“他们围困了我们的脚步”）；他们瞪着眼，要把我推倒在地上。'),
('CNV', '诗篇', 19, 17, 12, '他们像急于撕碎猎物的狮子，又像蹲伏在隐密处的幼狮。'),
('CNV', '诗篇', 19, 17, 13, '耶和华啊！求你起来，迎面攻击他们，把他们打倒；用你的刀救我的命脱离恶人。'),
('CNV', '诗篇', 19, 17, 14, '耶和华啊！求你用手救我脱离世人，脱离那些只在今生有分的世人。求你用你为他们储存的充满他们的肚腹，使他们的儿女都可以饱尝，他们还有剩余的留给他们的子孙。'),
('CNV', '诗篇', 19, 17, 15, '至于我，我必在义中得见你的面；我醒来的时候，得见你的形象就心满意足。'),
('CNV', '诗篇', 19, 18, 1, '耶和华我的力量啊！我爱你。'),
('CNV', '诗篇', 19, 18, 2, '耶和华是我的岩石、我的山寨、我的救主、我的神、我的磐石、我所投靠的、我的盾牌、我救恩的角、我的高台。'),
('CNV', '诗篇', 19, 18, 3, '我向那当受赞美的耶和华呼求，就得到拯救，脱离我的仇敌。'),
('CNV', '诗篇', 19, 18, 4, '死亡的绳索环绕我，毁灭的急流淹没了我。'),
('CNV', '诗篇', 19, 18, 5, '阴间的绳索围绕着我，死亡的网罗迎面而来。'),
('CNV', '诗篇', 19, 18, 6, '急难临到我的时候，我求告耶和华，我向我的神呼求；他从殿中听了我的声音，我在他面前的呼求进了他的耳中。'),
('CNV', '诗篇', 19, 18, 7, '那时大地摇撼震动，群山的根基也都动摇，它们摇撼，是因为耶和华发怒。'),
('CNV', '诗篇', 19, 18, 8, '浓烟从他的鼻孔往上冒，烈火从他的口中喷出来，连炭也烧着了。'),
('CNV', '诗篇', 19, 18, 9, '他使天下垂，亲自降临；在他的脚下黑云密布。'),
('CNV', '诗篇', 19, 18, 10, '他乘着基路伯飞行，藉着风的翅膀急飞。'),
('CNV', '诗篇', 19, 18, 11, '他以黑暗作他的隐密处，他以浓黑的水气，就是天空的密云，作他四周的帷帐。'),
('CNV', '诗篇', 19, 18, 12, '密云、冰雹与火炭，从他面前的光辉经过。'),
('CNV', '诗篇', 19, 18, 13, '耶和华在天上打雷，至高者发出声音，发出冰雹和火炭。'),
('CNV', '诗篇', 19, 18, 14, '他射出箭来，使它们四散；他连连发出闪电，使它们混乱。'),
('CNV', '诗篇', 19, 18, 15, '耶和华斥责一发，你鼻孔的气一出，海底就出现，大地的根基也显露。'),
('CNV', '诗篇', 19, 18, 16, '他从高处伸手抓住我，把我从大水中拉上来。'),
('CNV', '诗篇', 19, 18, 17, '他救我脱离我的强敌，脱离那些恨我的人，因为他们比我强盛。'),
('CNV', '诗篇', 19, 18, 18, '在我遭难的日子，他们来攻击我，但耶和华是我的支持。'),
('CNV', '诗篇', 19, 18, 19, '他又领我出去，到那宽阔之地；他搭救我，因为他喜悦我。'),
('CNV', '诗篇', 19, 18, 20, '耶和华按着我的公义报答我，照着我手中的清洁回报我。'),
('CNV', '诗篇', 19, 18, 21, '因为我谨守了耶和华的道，未曾作恶离开我的神。'),
('CNV', '诗篇', 19, 18, 22, '因为他的一切典章常摆在我面前，他的律例，我未曾丢弃。'),
('CNV', '诗篇', 19, 18, 23, '我在他面前作完全的人，我也谨慎自己，脱离我的罪孽。'),
('CNV', '诗篇', 19, 18, 24, '所以耶和华按着我的公义，照着我在他眼前手中的清洁回报我。'),
('CNV', '诗篇', 19, 18, 25, '对慈爱的人，你显出你的慈爱；对完全的人，你显出你的完全；'),
('CNV', '诗篇', 19, 18, 26, '对清洁的人，你显出你的清洁；对狡诈的人，你显出你的机巧。'),
('CNV', '诗篇', 19, 18, 27, '谦卑的人，你要拯救；高傲的眼睛，你要贬低。'),
('CNV', '诗篇', 19, 18, 28, '耶和华啊！你点亮了我的灯；我的神照明了我的黑暗。'),
('CNV', '诗篇', 19, 18, 29, '藉着你，我攻破敌军；靠着我的神，我跳过墙垣。'),
('CNV', '诗篇', 19, 18, 30, '这位神，他的道路是完全的；耶和华的话是炼净的；凡是投靠他的，他都作他们的盾牌。'),
('CNV', '诗篇', 19, 18, 31, '除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？'),
('CNV', '诗篇', 19, 18, 32, '他是那位以能力给我束腰的神，他使我的道路完全。'),
('CNV', '诗篇', 19, 18, 33, '他使我的脚像母鹿的蹄，又使我站稳在高处。'),
('CNV', '诗篇', 19, 18, 34, '他教导我的手怎样作战，又使我的手臂可以拉开铜弓。'),
('CNV', '诗篇', 19, 18, 35, '你把你救恩的盾牌赐给我，你的右手扶持我，你的温柔使我昌大。'),
('CNV', '诗篇', 19, 18, 36, '你使我脚底下的路径宽阔，我的两膝没有动摇。'),
('CNV', '诗篇', 19, 18, 37, '我追赶仇敌，把他们追上；不消灭他们，我必不归回。'),
('CNV', '诗篇', 19, 18, 38, '我重创他们，使他们不能起来；他们都倒在我的脚下。'),
('CNV', '诗篇', 19, 18, 39, '你以能力给我束腰，使我能够作战；你又使那些起来攻击我的人都屈服在我的脚下。'),
('CNV', '诗篇', 19, 18, 40, '你使我的仇敌在我面前转背逃跑，使我可以歼灭恨我的人。'),
('CNV', '诗篇', 19, 18, 41, '他们呼叫，却没有人拯救；就算向耶和华呼求，他也不答应他们。'),
('CNV', '诗篇', 19, 18, 42, '我捣碎他们，像风前的尘土，我倾倒他们，像街上的烂泥。'),
('CNV', '诗篇', 19, 18, 43, '你救我脱离了人民的争竞，你立我作列国的元首；我不认识的人民要服事我。'),
('CNV', '诗篇', 19, 18, 44, '他们一听见，就服从我；外族人都向我假意归顺。'),
('CNV', '诗篇', 19, 18, 45, '外族人大势已去，战战兢兢地从他们的要塞走出来。'),
('CNV', '诗篇', 19, 18, 46, '耶和华是永活的，我的磐石是应当称颂的，拯救我的神是应当被尊为至高的。'),
('CNV', '诗篇', 19, 18, 47, '他是那位为我伸冤的神，他使万民服在我的脚下。'),
('CNV', '诗篇', 19, 18, 48, '他救我脱离我的仇敌。你还把我高举起来，高过那些起来攻击我的人，又救我脱离了强暴的人。'),
('CNV', '诗篇', 19, 18, 49, '因此，耶和华啊！我要在列国中称赞你，歌颂你的名。'),
('CNV', '诗篇', 19, 18, 50, '耶和华赐极大的救恩给他所立的王，又向他的受膏者施慈爱，就是向大卫和他的后裔施慈爱，直到永远。'),
('CNV', '诗篇', 19, 19, 1, '诸天述说神的荣耀，穹苍传扬他的作为。'),
('CNV', '诗篇', 19, 19, 2, '天天发出言语，夜夜传出知识。'),
('CNV', '诗篇', 19, 19, 3, '没有话语，没有言词，人也听不到它们的声音。'),
('CNV', '诗篇', 19, 19, 4, '它们的声音（按照《马索拉文本》，“声音”作“准绳”；现参照《七十士译本》等古译本翻译）传遍全地，它们的言语传到地极，神在它们中间为太阳安设帐幕。'),
('CNV', '诗篇', 19, 19, 5, '太阳如同新郎出洞房，又像勇士欢欢喜喜地跑路。'),
('CNV', '诗篇', 19, 19, 6, '它从天的这边出来，绕行到天的那边；没有什么可以隐藏，得不到它的温暖。'),
('CNV', '诗篇', 19, 19, 7, '耶和华的律法是完全的，能使人心苏醒；耶和华的法度是坚定的，能使愚人有智慧。'),
('CNV', '诗篇', 19, 19, 8, '耶和华的训词是正直的，能使人心快乐；耶和华的命令是清洁的，能使人的眼睛明亮。'),
('CNV', '诗篇', 19, 19, 9, '耶和华的话语（“耶和华的话语”原文作“耶和华的敬畏”）是洁净的，能坚立到永远；耶和华的典章是真实的，完全公义；'),
('CNV', '诗篇', 19, 19, 10, '都比金子宝贵，比大量的精金更宝贵；比蜜甘甜，比蜂房滴下来的蜜更甘甜；'),
('CNV', '诗篇', 19, 19, 11, '并且你的仆人也藉着这些得到警戒，谨守这些就得着大赏赐。'),
('CNV', '诗篇', 19, 19, 12, '谁能知道自己的错误呢？求你赦免我隐而未现的过失。'),
('CNV', '诗篇', 19, 19, 13, '求你拦阻你仆人，不犯任意妄为的罪，不许它们辖制我；我才可以完全，不犯大过。'),
('CNV', '诗篇', 19, 19, 14, '耶和华我的磐石、我的救赎主啊！愿我口中的言语、心里的意念，都在你面前蒙悦纳。'),
('CNV', '诗篇', 19, 20, 1, '愿耶和华在你遭难的日子应允你，愿雅各的神的名保护你。'),
('CNV', '诗篇', 19, 20, 2, '愿他从圣所帮助你，从锡安扶持你。'),
('CNV', '诗篇', 19, 20, 3, '愿他记念你的一切素祭，悦纳你的燔祭。（细拉）'),
('CNV', '诗篇', 19, 20, 4, '愿他照着你的心愿赏赐你，实现你的一切计划。'),
('CNV', '诗篇', 19, 20, 5, '我们要因你的胜利欢呼，因我们神的名高举旗帜；愿耶和华实现你所求的一切。'),
('CNV', '诗篇', 19, 20, 6, '现在我确知，耶和华拯救自己的受膏者；他必从他的圣天上应允他，用自己右手的能力拯救他。'),
('CNV', '诗篇', 19, 20, 7, '有人靠车，有人靠马。我们却靠耶和华我们神的名。'),
('CNV', '诗篇', 19, 20, 8, '他们都屈身跌倒，我们却起来，挺身而立。'),
('CNV', '诗篇', 19, 20, 9, '耶和华啊！求你拯救君王！我们呼求的时候，愿你应允我们（按照《马索拉文本》，“愿你应允我们”应作“愿他应允我们”；现参照《七十士译本》翻译）。'),
('CNV', '诗篇', 19, 21, 1, '耶和华啊！王因你的力量快乐，因你的救恩大大欢呼。'),
('CNV', '诗篇', 19, 21, 2, '他心里所愿的，你赐给了他；他嘴唇所求的，你没有拒绝。（细拉）'),
('CNV', '诗篇', 19, 21, 3, '你以美福迎接他，把精金的冠冕戴在他头上。'),
('CNV', '诗篇', 19, 21, 4, '他向你求寿，你就赐给他，就是长久的日子，直到永远。'),
('CNV', '诗篇', 19, 21, 5, '他因你的救恩大有荣耀，你又把尊荣和威严加给他。'),
('CNV', '诗篇', 19, 21, 6, '你把永远的福分赐给他，又使他因与你同在的喜乐欢欣。'),
('CNV', '诗篇', 19, 21, 7, '王倚靠耶和华，靠着至高者的慈爱，他必不至动摇。'),
('CNV', '诗篇', 19, 21, 8, '你的手要搜出你所有的仇敌，你的右手必搜出那些恨你的人。'),
('CNV', '诗篇', 19, 21, 9, '你出现的时候，就要使他们像炽热的火炉；耶和华必在他的震怒中吞灭他们，火必烧灭他们。'),
('CNV', '诗篇', 19, 21, 10, '你必从地上除灭他们的子孙，从人间除灭他们的后裔。'),
('CNV', '诗篇', 19, 21, 11, '虽然他们定下恶计害你，他们所设的阴谋却不能成功。'),
('CNV', '诗篇', 19, 21, 12, '你的箭扣上弦，对准他们的脸的时候，他们必转身而逃。'),
('CNV', '诗篇', 19, 21, 13, '耶和华啊！愿你因自己的能力被尊崇，好让我们歌唱，颂赞你的大能。'),
('CNV', '诗篇', 19, 22, 1, '我的神！我的神！你为什么离弃我？为什么远离不救我，不听我呻吟的话呢？'),
('CNV', '诗篇', 19, 22, 2, '我的神啊！我日间呼求，你不应允；在晚上我还是不停止。'),
('CNV', '诗篇', 19, 22, 3, '但你是圣洁的，是用以色列的赞美为宝座的。'),
('CNV', '诗篇', 19, 22, 4, '我们的列祖倚靠你，他们倚靠你，你就救他们。'),
('CNV', '诗篇', 19, 22, 5, '他们向你哀求，就得拯救；他们倚靠你，就不失望。'),
('CNV', '诗篇', 19, 22, 6, '但我是虫，不是人，是世上所羞辱的，也是众人所藐视的。'),
('CNV', '诗篇', 19, 22, 7, '看见我的，都嘲笑我；他们撇着嘴，摇着头，说：'),
('CNV', '诗篇', 19, 22, 8, '“他既然把自己交托耶和华，就让耶和华搭救他吧！耶和华既然喜悦他，就让耶和华拯救他吧！”'),
('CNV', '诗篇', 19, 22, 9, '然而，是你使我从母腹中出来的；我在母亲的怀里，你就使我有倚靠的心。'),
('CNV', '诗篇', 19, 22, 10, '我自出母胎，就被交托给你；我一出母腹，你就是我的神。'),
('CNV', '诗篇', 19, 22, 11, '求你不要远离我，因为灾难临近了，却没有人帮助我。'),
('CNV', '诗篇', 19, 22, 12, '有许多公牛围着我，巴珊强壮的公牛困住了我。'),
('CNV', '诗篇', 19, 22, 13, '他们向我大大地张嘴，像抓撕吼叫的狮子。'),
('CNV', '诗篇', 19, 22, 14, '我好像水被倾倒出去，我全身的骨头都散脱了，我的心在我里面像蜡融化。'),
('CNV', '诗篇', 19, 22, 15, '我的精力像瓦片一样枯干，我的舌头紧黏着上颚，你把我放在死亡的尘土中。'),
('CNV', '诗篇', 19, 22, 16, '犬类围着我，恶党环绕我，他们扎了（按照《马索拉文本》，“他们扎了”作“像狮子”；现参照《七十士译本》等古译本翻译）我的手我的脚。'),
('CNV', '诗篇', 19, 22, 17, '我能数算我全身的骨头，他们却瞪着眼看我。'),
('CNV', '诗篇', 19, 22, 18, '他们彼此分了我的外衣，又为我的内衣抽签。'),
('CNV', '诗篇', 19, 22, 19, '至于你，耶和华啊！求你不要远离我；我的力量啊！求你快来帮助我。'),
('CNV', '诗篇', 19, 22, 20, '求你搭救我的性命脱离刀剑，搭救我的生命脱离恶狗的爪。'),
('CNV', '诗篇', 19, 22, 21, '求你拯救我脱离狮子的口，拯救我脱离野牛的角。你已经应允了我。'),
('CNV', '诗篇', 19, 22, 22, '我要向我的兄弟宣扬你的名，我要在聚会中赞美你。'),
('CNV', '诗篇', 19, 22, 23, '敬畏耶和华的人哪！你们要赞美他；雅各所有的后裔啊！你们都要尊敬他；以色列所有的后裔啊！你们都要惧怕他。'),
('CNV', '诗篇', 19, 22, 24, '因为他不轻看，不厌恶受苦的人的痛苦，也没有掩面不顾他；受苦的人呼求的时候，他就垂听。'),
('CNV', '诗篇', 19, 22, 25, '在大会中，我赞美你的话是从你而来的；在敬畏耶和华的人面前，我要还我的愿。'),
('CNV', '诗篇', 19, 22, 26, '受苦的人必吃得饱足，寻求耶和华的人必赞美他，愿你们的心永远活着！'),
('CNV', '诗篇', 19, 22, 27, '地的四极，都要记念耶和华，并且归向他。列国的万族，都要在他（“他”有古抄本作“你”）面前敬拜。'),
('CNV', '诗篇', 19, 22, 28, '因为国度是属于耶和华的，他是掌管万国的。'),
('CNV', '诗篇', 19, 22, 29, '地上所有富足的人，都必吃喝、敬拜；所有下到尘土中，不再存活的人，都在他面前屈身下拜。'),
('CNV', '诗篇', 19, 22, 30, '必有后裔服事他，必有人把主的事向后代述说。'),
('CNV', '诗篇', 19, 22, 31, '他们要把他的公义传给以后出生的民，说明这是他所作的。'),
('CNV', '诗篇', 19, 23, 1, '耶和华是我的牧人，我必不会缺乏。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 23, 2, '他使我躺卧在青草地上，领我到安静的水边。'),
('CNV', '诗篇', 19, 23, 3, '他使我的灵魂苏醒；为了自己的名，他引导我走义路。'),
('CNV', '诗篇', 19, 23, 4, '我虽然行过死荫的山谷，也不怕遭受伤害，因为你与我同在；你的杖你的竿都安慰我。'),
('CNV', '诗篇', 19, 23, 5, '在我敌人面前，你为我摆设筵席；你用油膏了我的头，使我的杯满溢。'),
('CNV', '诗篇', 19, 23, 6, '我一生的日子，必有恩惠慈爱紧随着我；我也要住在耶和华的殿中，直到永远。'),
('CNV', '诗篇', 19, 24, 1, '地和地上所充满的，世界和住在世上的，都是属于耶和华的。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 24, 2, '因为他把地奠定在海上，使世界安定在众水之上。'),
('CNV', '诗篇', 19, 24, 3, '谁能登上耶和华的山？谁能站在他的圣所中呢？'),
('CNV', '诗篇', 19, 24, 4, '就是手洁心清的人，他不倾向虚妄，起誓不怀诡诈。'),
('CNV', '诗篇', 19, 24, 5, '他必领受从耶和华来的福分，也必蒙拯救他的神称他为义。'),
('CNV', '诗篇', 19, 24, 6, '这就是求问耶和华的那一类人，就是寻求你面的雅各。（细拉）'),
('CNV', '诗篇', 19, 24, 7, '众城门哪！抬起你们的头来；古老的门户啊！你们要被举起，好让荣耀的王进来。'),
('CNV', '诗篇', 19, 24, 8, '那荣耀的王是谁呢？就是强而有力的耶和华，在战场上大有能力的耶和华。'),
('CNV', '诗篇', 19, 24, 9, '众城门哪！抬起你们的头来；古老的门户啊！你们要被举起，好让荣耀的王进来。'),
('CNV', '诗篇', 19, 24, 10, '那荣耀的王是谁呢？万军之耶和华，他就是那荣耀的王。（细拉）'),
('CNV', '诗篇', 19, 25, 1, '耶和华啊！我的心仰望你。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 25, 2, '我的神啊！我倚靠你，求你不要使我羞愧，也不要使我的仇敌胜过我。'),
('CNV', '诗篇', 19, 25, 3, '等候你的必不羞愧，但那些无故以诡诈待人的必要羞愧。'),
('CNV', '诗篇', 19, 25, 4, '耶和华啊！求你把你的道路指示我，求你把你的路径教导我，'),
('CNV', '诗篇', 19, 25, 5, '求你以你的真理引导我，教训我，因为你是拯救我的神；我整天等候的就是你。'),
('CNV', '诗篇', 19, 25, 6, '耶和华啊！求你记念你的怜悯和慈爱，因为它们自古以来就存在。'),
('CNV', '诗篇', 19, 25, 7, '求你不要记念我幼年的罪恶和我的过犯；耶和华啊！求你因你的恩惠，按着你的慈爱记念我。'),
('CNV', '诗篇', 19, 25, 8, '耶和华是良善和正直的，因此他必指示罪人走正路。'),
('CNV', '诗篇', 19, 25, 9, '他必引导谦卑的人行正义，把他的道路教导谦卑的人。'),
('CNV', '诗篇', 19, 25, 10, '遵守耶和华的约和法度的人，耶和华都以慈爱和信实待他们。'),
('CNV', '诗篇', 19, 25, 11, '耶和华啊！因你名的缘故，求你赦免我的罪孽，因为我的罪孽重大。'),
('CNV', '诗篇', 19, 25, 12, '谁是那敬畏耶和华的人？耶和华必指示他应选择的道路。'),
('CNV', '诗篇', 19, 25, 13, '他必安享福乐，他的后裔要承受地土。'),
('CNV', '诗篇', 19, 25, 14, '耶和华把心意向敬畏他的人显示，又使他们认识他的约。'),
('CNV', '诗篇', 19, 25, 15, '我的眼睛时常仰望耶和华，因为他必使我的脚脱离网罗。'),
('CNV', '诗篇', 19, 25, 16, '求你转向我，恩待我，因为我孤独困苦。'),
('CNV', '诗篇', 19, 25, 17, '我心中的愁苦增多，求你使我从痛苦中得释放。'),
('CNV', '诗篇', 19, 25, 18, '求你看看我的困苦和艰难，赦免我的一切罪恶。'),
('CNV', '诗篇', 19, 25, 19, '求你看看我的仇敌，因为他们人数众多，他们深深痛恨我。'),
('CNV', '诗篇', 19, 25, 20, '求你护卫我的性命，搭救我；不要叫我羞愧，因为我投靠你。'),
('CNV', '诗篇', 19, 25, 21, '愿纯全和正直保护我，因为我等候你。'),
('CNV', '诗篇', 19, 25, 22, '神啊！求你救赎以色列，救他脱离一切困苦。'),
('CNV', '诗篇', 19, 26, 1, '耶和华啊！求你为我伸冤，因为我向来行事正直；我倚靠耶和华，并不动摇。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 26, 2, '耶和华啊！求你试验我，鉴察我，熬炼我的肺腑心肠。'),
('CNV', '诗篇', 19, 26, 3, '因为你的慈爱常在我的眼前，我行事为人都按着你的真理。'),
('CNV', '诗篇', 19, 26, 4, '我决不与奸诈的人同坐，也不和虚伪的人来往。'),
('CNV', '诗篇', 19, 26, 5, '我恨恶恶人的聚会，也不与作恶的同坐。'),
('CNV', '诗篇', 19, 26, 6, '耶和华啊！我要洗手表明无辜，才来绕着你的祭坛行走；'),
('CNV', '诗篇', 19, 26, 7, '好使我发出称谢的声音，述说你一切奇妙的作为。'),
('CNV', '诗篇', 19, 26, 8, '耶和华啊！我喜爱你住宿的殿，你荣耀居住的地方。'),
('CNV', '诗篇', 19, 26, 9, '求你不要把我的性命和罪人一同除掉，也不要把我的生命和流人血的人一起消灭。'),
('CNV', '诗篇', 19, 26, 10, '他们的手中有恶计，他们的右手充满贿赂。'),
('CNV', '诗篇', 19, 26, 11, '至于我，我要按正直行事为人，求你救赎我，恩待我。'),
('CNV', '诗篇', 19, 26, 12, '我的脚站在平坦的地方，我要在众会中称颂耶和华。'),
('CNV', '诗篇', 19, 27, 1, '耶和华是我的亮光，是我的救恩，我还怕谁呢？耶和华是我性命的避难所，我还惧谁呢？（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 27, 2, '那些作恶的，就是我的敌人、我的仇敌，他们逼近我，要吃我肉的时候，就绊跌仆倒。'),
('CNV', '诗篇', 19, 27, 3, '虽有军兵扎营攻击我，我的心也不害怕；虽然发动战争攻击我，我仍旧安稳。'),
('CNV', '诗篇', 19, 27, 4, '有一件事我求过耶和华，我还要寻求；我要一生一世住在耶和华的殿里，瞻仰他的荣美，在他的殿中求问。'),
('CNV', '诗篇', 19, 27, 5, '因为在我遭难的日子，他必把我藏在他的帐棚里，把我隐藏在他帐幕的隐密处，又把我高举在磐石上。'),
('CNV', '诗篇', 19, 27, 6, '现在，我可以抬起头来，高过我四周的仇敌；我要在他的帐幕里，献上欢呼的祭；我要歌唱，颂赞耶和华。'),
('CNV', '诗篇', 19, 27, 7, '耶和华啊！我发声呼求的时候，求你垂听；求你恩待我，应允我。'),
('CNV', '诗篇', 19, 27, 8, '你说：“你们要寻求我的面！”那时我的心对你说：“耶和华啊！你的面我正要寻求。”'),
('CNV', '诗篇', 19, 27, 9, '求你不要向我掩面，不要发怒赶逐你的仆人，你一向是帮助我的。拯救我的神啊！求你不要撇下我，也不要离弃我。'),
('CNV', '诗篇', 19, 27, 10, '虽然我的父母离弃我，耶和华却收留我。'),
('CNV', '诗篇', 19, 27, 11, '耶和华啊！求你指示我你的道路；为我仇敌的缘故引导我走平坦的路。'),
('CNV', '诗篇', 19, 27, 12, '求你不要照着我敌人的心愿，把我交给他们，因为有作假见证的人起来攻击我，并且口出凶暴的话。'),
('CNV', '诗篇', 19, 27, 13, '我还是相信，在活人之地，我可以看见耶和华的恩惠。'),
('CNV', '诗篇', 19, 27, 14, '你要等候耶和华，要刚强，要坚定你的心，要等候耶和华。'),
('CNV', '诗篇', 19, 28, 1, '耶和华啊！我向你呼求；我的磐石啊！不要不听我；如果你缄默不理我，我就跟那些下坑的人一样。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 28, 2, '我向你呼求，向你的至圣所举手祷告的时候，求你垂听我恳求的声音。'),
('CNV', '诗篇', 19, 28, 3, '求你不要把我和坏人，跟作恶的人一同除掉；他们与邻居说平安的话，心里却存着奸恶。'),
('CNV', '诗篇', 19, 28, 4, '愿你按着他们所作的，照着他们所行的恶报应他们；愿你照着他们手所作的报应他们，把他们应得的报应加给他们。'),
('CNV', '诗篇', 19, 28, 5, '他们既然不关心耶和华的作为，和他手所作的，耶和华就必拆毁他们，不建立他们。'),
('CNV', '诗篇', 19, 28, 6, '耶和华是应当称颂的，因为他听了我恳求的声音。'),
('CNV', '诗篇', 19, 28, 7, '耶和华是我的力量，是我的盾牌；我的心倚靠他，我就得到帮助；所以我的心欢乐。我要用诗歌颂赞他。'),
('CNV', '诗篇', 19, 28, 8, '耶和华是他子民的力量，又是他受膏者得救的保障。'),
('CNV', '诗篇', 19, 28, 9, '求你拯救你的子民，赐福给你的产业，牧养他们，怀抱他们，直到永远。'),
('CNV', '诗篇', 19, 29, 1, '神的众子啊！要归给耶和华，你们要把荣耀和能力归给耶和华。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 29, 2, '要把耶和华的名的荣耀归给他，要以圣洁的装束敬拜耶和华（“要以圣洁的装束敬拜耶和华”或译：“在耶和华显现的时候，要敬拜他”，或“要在耶和华圣洁的光辉中敬拜他”）。'),
('CNV', '诗篇', 19, 29, 3, '耶和华的声音在众水之上，荣耀的神打雷，耶和华打雷在大水之上。'),
('CNV', '诗篇', 19, 29, 4, '耶和华的声音大有能力，耶和华的声音充满威严。'),
('CNV', '诗篇', 19, 29, 5, '耶和华的声音震断了香柏树，耶和华震断了黎巴嫩的香柏树。'),
('CNV', '诗篇', 19, 29, 6, '他使黎巴嫩山跳跃像牛犊，使西连山跳跃像野牛犊。'),
('CNV', '诗篇', 19, 29, 7, '耶和华的声音带着火焰劈下。'),
('CNV', '诗篇', 19, 29, 8, '耶和华的声音震撼旷野，耶和华震撼加低斯的旷野。'),
('CNV', '诗篇', 19, 29, 9, '耶和华的声音惊动母鹿生产，使林中的树木光秃凋零；凡是在他殿中的都说：“荣耀啊！”'),
('CNV', '诗篇', 19, 29, 10, '耶和华坐在洪水之上，耶和华坐着为王直到永远。'),
('CNV', '诗篇', 19, 29, 11, '愿耶和华赐力量给他的子民，愿耶和华赐平安的福给他的子民。'),
('CNV', '诗篇', 19, 30, 1, '耶和华啊！我要尊崇你，因为你曾救拔我，不容我的仇敌向我夸耀。'),
('CNV', '诗篇', 19, 30, 2, '耶和华我的神啊！我曾向你呼求，你也医治了我。'),
('CNV', '诗篇', 19, 30, 3, '耶和华啊！你曾把我从阴间救上来，使我存活，不至于下坑。'),
('CNV', '诗篇', 19, 30, 4, '耶和华的圣民哪！你们要歌颂耶和华，赞美他的圣名。'),
('CNV', '诗篇', 19, 30, 5, '因为他的怒气只是短暂的，他的恩惠却是一生一世的；夜间虽然不断有哭泣，早晨却必欢呼。'),
('CNV', '诗篇', 19, 30, 6, '至于我，我在安稳的时候曾说：“我必永不动摇。”'),
('CNV', '诗篇', 19, 30, 7, '耶和华啊！你的恩宠，使我坚立，如同大山；你一掩面，我就惊惶。'),
('CNV', '诗篇', 19, 30, 8, '耶和华啊！我曾向你呼求；我曾向我主恳求，说：'),
('CNV', '诗篇', 19, 30, 9, '“我被害流血，下到深坑，有什么益处呢？尘土还能称赞你，还能传扬你的信实吗？'),
('CNV', '诗篇', 19, 30, 10, '耶和华啊！求你垂听，恩待我；耶和华啊！求你帮助我。”'),
('CNV', '诗篇', 19, 30, 11, '你已经把我的悲哀变为舞蹈，把我的麻衣脱去，又给我穿上欢乐；'),
('CNV', '诗篇', 19, 30, 12, '好让我的灵（“灵”或译：“荣耀”或“肝”；与16:9，57:8，108:1同）歌颂你，永不停止。耶和华我的神啊！我要永远称赞你。'),
('CNV', '诗篇', 19, 31, 1, '耶和华啊！我投靠你；求你使我永不羞愧，求你按着你的公义搭救我。'),
('CNV', '诗篇', 19, 31, 2, '求你留心听我，赶快拯救我；求你作我坚固的磐石，作拯救我的坚垒。'),
('CNV', '诗篇', 19, 31, 3, '因为你是我的岩石、我的坚垒；为你名的缘故，求你带领我，引导我。'),
('CNV', '诗篇', 19, 31, 4, '求你救我脱离人为我暗设的网罗，因为你是我的避难所。'),
('CNV', '诗篇', 19, 31, 5, '我把我的灵魂交在你手里，耶和华信实的神啊！你救赎了我。'),
('CNV', '诗篇', 19, 31, 6, '我恨恶那些信奉虚无偶像的人；至于我，我却倚靠耶和华。'),
('CNV', '诗篇', 19, 31, 7, '我要因你的慈爱欢喜快乐，因为你看见了我的困苦，知道我心中的痛苦；'),
('CNV', '诗篇', 19, 31, 8, '你没有把我交在仇敌的手里，你使我的脚站稳在宽阔之地。'),
('CNV', '诗篇', 19, 31, 9, '耶和华啊！求你恩待我，因为我在患难之中；我的眼睛因愁烦昏花，我的身、我的心也都衰残。'),
('CNV', '诗篇', 19, 31, 10, '我的生命因愁苦耗尽，我的岁月在叹息中消逝，我的力量因罪孽衰退，我的骨头也枯干。'),
('CNV', '诗篇', 19, 31, 11, '我因众仇敌的缘故，成了众人羞辱的对象，在我的邻居面前更是这样；认识我的人都惧怕我；在街上看见我的，都避开我。'),
('CNV', '诗篇', 19, 31, 12, '我被人完全忘记，如同死了的人，我好像破碎的器皿，'),
('CNV', '诗篇', 19, 31, 13, '我听见许多人的毁谤，四周都有惊吓；他们一同商议攻击我，图谋要取我的性命。'),
('CNV', '诗篇', 19, 31, 14, '但是，耶和华啊！我还是倚靠你；我说：“你是我的神。”'),
('CNV', '诗篇', 19, 31, 15, '我的一生都在你的手中；求你救我脱离我仇敌的手，和那些迫害我的人。'),
('CNV', '诗篇', 19, 31, 16, '求你用你的脸光照你的仆人，以你的慈爱拯救我。'),
('CNV', '诗篇', 19, 31, 17, '耶和华啊！求你不要使我羞愧，因为我向你呼求；求你使恶人羞愧，使他们在阴间静寂无声。'),
('CNV', '诗篇', 19, 31, 18, '那些逞骄傲，态度轻慢，说话狂傲攻击义人的，愿他们说谎的嘴唇哑而无声。'),
('CNV', '诗篇', 19, 31, 19, '耶和华啊！你为敬畏你的人所珍藏的好处，为投靠你的人在世人面前所施行的恩惠，是多么丰盛。'),
('CNV', '诗篇', 19, 31, 20, '你把他们藏在你面前的隐密处，免得他们陷在世人的阴谋里；又把他们保护在帐棚内，以免落在口舌的争竞中。'),
('CNV', '诗篇', 19, 31, 21, '耶和华是应当称颂的，因为我在被围困的城里，他就向我显出他奇妙的慈爱。'),
('CNV', '诗篇', 19, 31, 22, '至于我，我曾在惊恐中说：“我从你眼前被隔绝”；可是我向你呼求的时候，你还是垂听了我恳求的声音。'),
('CNV', '诗篇', 19, 31, 23, '耶和华的众圣民哪！你们都要爱耶和华；耶和华保护诚实的人，却严厉地报应行事骄傲的人。'),
('CNV', '诗篇', 19, 31, 24, '所有仰望耶和华的人，你们都要刚强，坚固你们的心。'),
('CNV', '诗篇', 19, 32, 1, '过犯得蒙赦免，罪恶得到遮盖的人，是有福的。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 32, 2, '心里没有诡诈，耶和华不算为有罪的，这人是有福的。'),
('CNV', '诗篇', 19, 32, 3, '我闭口不认罪的时候，就整天唉哼，以致骨头衰残。'),
('CNV', '诗篇', 19, 32, 4, '因为你的手昼夜重压在我身上，我的精力耗尽，好像盛暑的干旱。（细拉）'),
('CNV', '诗篇', 19, 32, 5, '我向你承认我的罪，没有隐藏我的罪孽；我说：“我要向耶和华承认我的过犯”；你就赦免我的罪孽。（细拉）'),
('CNV', '诗篇', 19, 32, 6, '因此，凡是敬虔的人，都当趁你可寻找的时候，向你祷告；大水泛滥的时候，必不能达到他那里。'),
('CNV', '诗篇', 19, 32, 7, '你是我藏身之处，你必保护我脱离患难，以得救的欢呼四面环绕我。（细拉）'),
('CNV', '诗篇', 19, 32, 8, '我要教导你，指示你应走的路；我要劝戒你，我的眼睛看顾你。'),
('CNV', '诗篇', 19, 32, 9, '你不可像无知的骡马，如果不用嚼环辔头勒住它们，它们就不肯走近。'),
('CNV', '诗篇', 19, 32, 10, '恶人必受许多痛苦；但倚靠耶和华的，必有慈爱四面环绕他。'),
('CNV', '诗篇', 19, 32, 11, '义人哪！你们要靠着耶和华欢喜快乐；所有心里正直的人哪！你们都要欢呼。'),
('CNV', '诗篇', 19, 33, 1, '义人哪！你们要靠着耶和华欢呼；正直人赞美主是合宜的。'),
('CNV', '诗篇', 19, 33, 2, '你们要弹琴称谢耶和华，用十弦瑟歌颂他。'),
('CNV', '诗篇', 19, 33, 3, '你们要向他唱新歌，在欢呼声中巧妙地弹奏。'),
('CNV', '诗篇', 19, 33, 4, '因为耶和华的话是正直的，他的一切作为都是诚实的。'),
('CNV', '诗篇', 19, 33, 5, '耶和华喜爱公义和公正，全地充满耶和华的慈爱。'),
('CNV', '诗篇', 19, 33, 6, '诸天藉着耶和华的话而造，天上的万象藉着他口中的气而成。'),
('CNV', '诗篇', 19, 33, 7, '他把海水聚集成垒（“成垒”或译：“在皮袋里”），把深海安放在库房中。'),
('CNV', '诗篇', 19, 33, 8, '愿全地都敬畏耶和华，愿世上的居民都惧怕他。'),
('CNV', '诗篇', 19, 33, 9, '因为他说有，就有；命立，就立。'),
('CNV', '诗篇', 19, 33, 10, '耶和华破坏列国的谋略，使万民的计划挫败。'),
('CNV', '诗篇', 19, 33, 11, '耶和华的谋略永远立定，他心中的计划万代长存。'),
('CNV', '诗篇', 19, 33, 12, '以耶和华为神的，那国是有福的；耶和华拣选作自己产业的，那民是有福的。'),
('CNV', '诗篇', 19, 33, 13, '耶和华从天上观看，他看见全人类。'),
('CNV', '诗篇', 19, 33, 14, '从自己的住处，他察看地上所有的居民。'),
('CNV', '诗篇', 19, 33, 15, '他是那创造众人的心，了解他们一切作为的。'),
('CNV', '诗篇', 19, 33, 16, '君王不是因兵多得胜，勇士不是因力大得救。'),
('CNV', '诗篇', 19, 33, 17, '想靠马得胜是枉然的；马虽然力大，也不能救人。'),
('CNV', '诗篇', 19, 33, 18, '耶和华的眼睛看顾敬畏他的人，和那些仰望他慈爱的人；'),
('CNV', '诗篇', 19, 33, 19, '要搭救他们的性命脱离死亡，使他们在饥荒中可以存活。'),
('CNV', '诗篇', 19, 33, 20, '我们的心等候耶和华，他是我们的帮助、我们的盾牌。'),
('CNV', '诗篇', 19, 33, 21, '我们的心因他欢乐，因为我们倚靠他的圣名。'),
('CNV', '诗篇', 19, 33, 22, '耶和华啊！求你照着我们所仰望你的，向我们施慈爱。'),
('CNV', '诗篇', 19, 34, 1, '我要时常称颂耶和华，赞美他的话必常在我口中。'),
('CNV', '诗篇', 19, 34, 2, '我的心要因耶和华夸耀，困苦的人听见了就喜乐。'),
('CNV', '诗篇', 19, 34, 3, '你们要跟我一起尊耶和华为大，我们来一同高举他的名。'),
('CNV', '诗篇', 19, 34, 4, '我曾求问耶和华，他应允了我，救我脱离一切恐惧。'),
('CNV', '诗篇', 19, 34, 5, '人仰望他，就有光彩，他们的脸必不蒙羞。'),
('CNV', '诗篇', 19, 34, 6, '我这困苦人呼求，耶和华就垂听，拯救我脱离一切患难。'),
('CNV', '诗篇', 19, 34, 7, '耶和华的使者，在敬畏他的人周围扎营，搭救他们。'),
('CNV', '诗篇', 19, 34, 8, '你们要亲自体验，就知道耶和华是美善的；投靠他的人，都是有福的。'),
('CNV', '诗篇', 19, 34, 9, '耶和华的圣民哪！你们要敬畏他，因为敬畏他的一无所缺。'),
('CNV', '诗篇', 19, 34, 10, '少壮狮子有时还缺食挨饿，但寻求耶和华的，什么好处都不缺。'),
('CNV', '诗篇', 19, 34, 11, '孩子们！你们要来听我；我要教导你们敬畏耶和华。'),
('CNV', '诗篇', 19, 34, 12, '谁喜爱生命，爱慕长寿，享受美福，'),
('CNV', '诗篇', 19, 34, 13, '就应谨守舌头，不出恶言，嘴唇不说欺诈的话。'),
('CNV', '诗篇', 19, 34, 14, '也要离恶行善，寻找并追求和睦。'),
('CNV', '诗篇', 19, 34, 15, '耶和华的眼睛看顾义人，他的耳朵垂听他们的呼求。'),
('CNV', '诗篇', 19, 34, 16, '耶和华的脸敌对作恶的人，要把他们的名从世上除掉。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '诗篇', 19, 34, 17, '义人哀求，耶和华就垂听，搭救他们脱离一切患难，'),
('CNV', '诗篇', 19, 34, 18, '耶和华亲近心中破碎的人，拯救灵里痛悔的人，'),
('CNV', '诗篇', 19, 34, 19, '义人虽有许多苦难，但耶和华搭救他脱离这一切。'),
('CNV', '诗篇', 19, 34, 20, '耶和华保全他一身的骨头，连一根也不容折断。'),
('CNV', '诗篇', 19, 34, 21, '恶人必被恶害死；憎恨义人的，必被定罪。'),
('CNV', '诗篇', 19, 34, 22, '耶和华救赎他仆人的性命；凡是投靠他的，必不被定罪。'),
('CNV', '诗篇', 19, 35, 1, '耶和华啊！与我相争的，求你与他们相争；与我作战的，求你与他们作战。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 35, 2, '求你紧握大小的盾牌，起来帮助我。'),
('CNV', '诗篇', 19, 35, 3, '拔出矛枪战斧，迎击那些追赶我的；求你对我说：“我是你的拯救。”'),
('CNV', '诗篇', 19, 35, 4, '愿那些寻索我命的，蒙羞受辱；愿设计陷害我的，退后羞愧。'),
('CNV', '诗篇', 19, 35, 5, '愿他们像风前的糠秕，有耶和华的使者驱逐他们。'),
('CNV', '诗篇', 19, 35, 6, '愿他们的路又暗又滑，有耶和华的使者追赶他们。'),
('CNV', '诗篇', 19, 35, 7, '因为他们无故为我暗设网罗，无故挖坑要陷害我的性命。'),
('CNV', '诗篇', 19, 35, 8, '愿毁灭在不知不觉间临到他身上，愿他暗设的网罗缠住自己，愿他落在其中遭毁灭。'),
('CNV', '诗篇', 19, 35, 9, '我的心必因耶和华快乐，因他的救恩高兴。'),
('CNV', '诗篇', 19, 35, 10, '我全身的骨头都要说：“耶和华啊！有谁像你呢？你搭救困苦的人，脱离那些比他强盛的；搭救困苦和穷乏的人，脱离那些抢夺他的。”'),
('CNV', '诗篇', 19, 35, 11, '强暴的见证人起来，盘问我所不知道的事。'),
('CNV', '诗篇', 19, 35, 12, '他们对我以恶报善，使我孤苦无依。'),
('CNV', '诗篇', 19, 35, 13, '至于我，他们有病的时候，我就穿上麻衣，禁食刻苦己心；我心里也不住地祷告（“我心里也不住地祷告”原文作“我的祷告都回到自己的怀中”）。'),
('CNV', '诗篇', 19, 35, 14, '我往来奔走，看他们像自己的朋友兄弟；我哀痛屈身，如同哀悼母亲。'),
('CNV', '诗篇', 19, 35, 15, '但我跌倒的时候，他们竟聚集一起欢庆；我素不相识的聚集一起攻击我，他们不住地欺凌我。'),
('CNV', '诗篇', 19, 35, 16, '他们以最粗鄙的话讥笑我（按照《马索拉文本》，本句应作“他们好像筵席上狂妄的讥笑者”；现参照《七十士译本》翻译），向我咬牙切齿。'),
('CNV', '诗篇', 19, 35, 17, '主啊！你还要看多久？求你救我的性命脱离他们的残害，救我的生命脱离少壮狮子。'),
('CNV', '诗篇', 19, 35, 18, '我要在大会中称谢你，我要在众民中赞美你。'),
('CNV', '诗篇', 19, 35, 19, '求你不容那些无理与我为敌的，向我夸耀；不让那些无故恨我的，向我挤眼。'),
('CNV', '诗篇', 19, 35, 20, '因为他们不说和睦的话，却计划诡诈的事，陷害世上的安静人。'),
('CNV', '诗篇', 19, 35, 21, '他们张大嘴巴攻击我，说：“啊哈！啊哈！我们亲眼看见了。”'),
('CNV', '诗篇', 19, 35, 22, '耶和华啊！你已经看见了，求你不要缄默；主啊！求你不要远离我。'),
('CNV', '诗篇', 19, 35, 23, '我的神，我的主啊！求你激动醒起，为我伸冤辩护。'),
('CNV', '诗篇', 19, 35, 24, '耶和华我的神啊！求你按着你的公义判断我，不容他们向我夸耀。'),
('CNV', '诗篇', 19, 35, 25, '不要让他们心里说：“啊哈！这正是我们的心愿！”不要让他们说：“我们把他吞下去了！”'),
('CNV', '诗篇', 19, 35, 26, '愿那些喜欢我遭难的，一同蒙羞抱愧；愿那些对我妄自尊大的，都披上惭愧和耻辱。'),
('CNV', '诗篇', 19, 35, 27, '愿那些喜悦我冤屈昭雪的，都欢呼快乐；愿他们不住地说：“要尊耶和华为大，他喜悦他的仆人平安。”'),
('CNV', '诗篇', 19, 35, 28, '我的舌头要述说你的公义，终日赞美你。'),
('CNV', '诗篇', 19, 36, 1, '恶人的罪过在他心中深处说话，他眼中也不怕神。（本节或译：“我心中深处有话说，是关于恶人的罪过，他眼中不怕神”）'),
('CNV', '诗篇', 19, 36, 2, '罪过媚惑他，因此在他眼中看来，自己的罪孽不会揭发，也不会被恨恶。'),
('CNV', '诗篇', 19, 36, 3, '他口中的话语都是罪恶和诡诈，他不再是明慧的，也不再行善。'),
('CNV', '诗篇', 19, 36, 4, '他在床上密谋作恶，定意行在不善的道路上，并不弃绝恶事。'),
('CNV', '诗篇', 19, 36, 5, '耶和华啊！你的慈爱上及诸天，你的信实高达云霄。'),
('CNV', '诗篇', 19, 36, 6, '你的公义好像大山，你的公正如同深渊；耶和华啊！人和牲畜，你都庇佑。'),
('CNV', '诗篇', 19, 36, 7, '神啊！你的慈爱多么宝贵；世人都投靠在你的翅膀荫下。'),
('CNV', '诗篇', 19, 36, 8, '他们必饱尝你殿里的盛筵，你必使他们喝你乐河的水。'),
('CNV', '诗篇', 19, 36, 9, '因为生命的泉源在你那里；在你的光中，我们才能看见光。'),
('CNV', '诗篇', 19, 36, 10, '求你常施慈爱给认识你的人，常施公义给心里正直的人。'),
('CNV', '诗篇', 19, 36, 11, '求你不容骄傲人的脚践踏（“践踏”原文作“临到”）我，不让恶人的手使我流离飘荡。'),
('CNV', '诗篇', 19, 36, 12, '作恶的人必跌倒；他们被推倒，不能再起来。'),
('CNV', '诗篇', 19, 37, 1, '不要因作恶的人心怀不平，不要因犯罪的人产生嫉妒。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 37, 2, '因为他们好像草快要枯干，像即将凋萎的青草。'),
('CNV', '诗篇', 19, 37, 3, '你要倚靠耶和华，并要行善；你要住在地上，以信实为粮食。'),
('CNV', '诗篇', 19, 37, 4, '你要以耶和华为乐，他就把你心里所求的赐给你。'),
('CNV', '诗篇', 19, 37, 5, '你要把你的道路交托耶和华，并倚靠他，他就必成全。'),
('CNV', '诗篇', 19, 37, 6, '他必使你的公义好像光发出，使你的公正如日中天。'),
('CNV', '诗篇', 19, 37, 7, '你要在耶和华面前静默无声，耐心地等候他；不要因那凡事顺利的，和那恶谋得逞的，心怀不平。'),
('CNV', '诗篇', 19, 37, 8, '你要抑制怒气，消除烈怒；不要心怀不平，那只会导致你作恶。'),
('CNV', '诗篇', 19, 37, 9, '因为作恶的必被剪除，但等候耶和华的必承受地土。'),
('CNV', '诗篇', 19, 37, 10, '再过不久，恶人就不存在了；你到他的地方寻找，也找不到。'),
('CNV', '诗篇', 19, 37, 11, '但谦卑的人必承受地土，可以享受丰盛的平安。'),
('CNV', '诗篇', 19, 37, 12, '恶人谋害义人，向他咬牙切齿；'),
('CNV', '诗篇', 19, 37, 13, '但主必笑他，因为知道他遭报的日子快要来到。'),
('CNV', '诗篇', 19, 37, 14, '恶人已经拔出刀来，拉开了弓，要打倒困苦和贫穷的人，杀害行为正直的人。'),
('CNV', '诗篇', 19, 37, 15, '他们的刀必刺入自己的心，他们的弓必被折断。'),
('CNV', '诗篇', 19, 37, 16, '一个义人拥有的虽少，胜过许多恶人的财富。'),
('CNV', '诗篇', 19, 37, 17, '因为恶人的膀臂必被折断，耶和华却扶持义人。'),
('CNV', '诗篇', 19, 37, 18, '耶和华眷顾完全人在世的日子，他们的产业必存到永远。'),
('CNV', '诗篇', 19, 37, 19, '在患难的时候，他们必不蒙羞；在饥荒的日子，他们必得饱足。'),
('CNV', '诗篇', 19, 37, 20, '恶人却必灭亡；耶和华的仇敌好像草场的华美，他们必要消失，像烟一般消失。'),
('CNV', '诗篇', 19, 37, 21, '恶人借贷总不偿还，义人却慷慨施舍。'),
('CNV', '诗篇', 19, 37, 22, '蒙耶和华赐福的，必承受地土；受他咒诅的，必被剪除。'),
('CNV', '诗篇', 19, 37, 23, '人的脚步是耶和华立定的，他的道路也是耶和华喜悦的。'),
('CNV', '诗篇', 19, 37, 24, '他虽然跌跤，却不至仆倒；因为耶和华用手扶持他。'),
('CNV', '诗篇', 19, 37, 25, '我从前年幼，现在年老，从未见过义人被弃，也从未见过他的后裔讨饭。'),
('CNV', '诗篇', 19, 37, 26, '他常常慷慨借给人；他的后裔必定蒙福。'),
('CNV', '诗篇', 19, 37, 27, '应当离恶行善，你就可以永远安居。'),
('CNV', '诗篇', 19, 37, 28, '因为耶和华喜爱公正，也不撇弃他的圣民；他们必永远蒙庇佑，恶人的后裔却必被剪除。'),
('CNV', '诗篇', 19, 37, 29, '义人必承受地土，永远居住在自己的地上。'),
('CNV', '诗篇', 19, 37, 30, '义人的口说出智慧，他的舌头讲论正义。'),
('CNV', '诗篇', 19, 37, 31, '神的律法在他心里，他的脚步必不滑跌。'),
('CNV', '诗篇', 19, 37, 32, '恶人窥伺义人，想要杀死他。'),
('CNV', '诗篇', 19, 37, 33, '耶和华必不把他撇弃在恶人的手中，在审判的时候，也不定他的罪。'),
('CNV', '诗篇', 19, 37, 34, '你要等候耶和华，谨守他的道；他必高举你，使你承受地土；恶人被剪除的时候，你必看见。'),
('CNV', '诗篇', 19, 37, 35, '我曾看见强暴的恶人兴旺，像树木在本土茂盛。'),
('CNV', '诗篇', 19, 37, 36, '但他很快就消逝，不再存在了；我寻找他，却找不到。'),
('CNV', '诗篇', 19, 37, 37, '你要细察完全人，观看正直人；因为爱和平的必有后代。'),
('CNV', '诗篇', 19, 37, 38, '犯罪的人必一同灭绝，恶人的后代必被剪除。'),
('CNV', '诗篇', 19, 37, 39, '义人的拯救是由耶和华而来；在患难的时候，他作他们的避难所。'),
('CNV', '诗篇', 19, 37, 40, '耶和华帮助他们，搭救他们；他搭救他们脱离恶人，拯救他们，因为他们投靠他。'),
('CNV', '诗篇', 19, 38, 1, '耶和华啊！求你不要在忿怒中责备我，也不要在烈怒中管教我。'),
('CNV', '诗篇', 19, 38, 2, '因为你的箭射入我身，你的手压住我。'),
('CNV', '诗篇', 19, 38, 3, '因你的忿怒，我体无完肤；因我的罪恶，我的骨头都不安妥。'),
('CNV', '诗篇', 19, 38, 4, '我的罪孽高过我的头，如同重担，使我担当不起。'),
('CNV', '诗篇', 19, 38, 5, '因为我的愚昧，我的伤口发臭流脓。'),
('CNV', '诗篇', 19, 38, 6, '我屈身弯腰，弯到极低，整天哀痛，到处行走。'),
('CNV', '诗篇', 19, 38, 7, '我的两腰灼痛，我体无完肤。'),
('CNV', '诗篇', 19, 38, 8, '我已经疲乏无力，被压得粉碎了；我因心里痛苦而唉哼。'),
('CNV', '诗篇', 19, 38, 9, '主啊！我的心愿都在你面前，我不向你隐瞒我的叹息。'),
('CNV', '诗篇', 19, 38, 10, '我的心剧烈跳动，我的力量衰退；连我眼中的光彩也消逝了。'),
('CNV', '诗篇', 19, 38, 11, '我的良朋密友因我的灾祸，都站到一旁去；我的亲人也都站得远远的。'),
('CNV', '诗篇', 19, 38, 12, '那些寻索我命的，设下网罗；那些想要害我的，口说威吓的话，他们整天思想诡计。'),
('CNV', '诗篇', 19, 38, 13, '至于我，像个聋子，不能听见；像个哑巴，不能开口。'),
('CNV', '诗篇', 19, 38, 14, '我竟变成了一个象是不能听见的人，变成了一个口中不能反驳的人。'),
('CNV', '诗篇', 19, 38, 15, '耶和华啊！我等候你；主我的神啊！你必应允我。'),
('CNV', '诗篇', 19, 38, 16, '因为我曾说：“恐怕他们向我夸耀；我的脚滑跌的时候，不要让他们向我夸口。”'),
('CNV', '诗篇', 19, 38, 17, '我随时会跌倒，我的痛苦常在我面前。'),
('CNV', '诗篇', 19, 38, 18, '我要承认我的罪孽，我要因我的罪忧伤。'),
('CNV', '诗篇', 19, 38, 19, '但我强悍的仇敌众多，无理憎恨我的不断增加。'),
('CNV', '诗篇', 19, 38, 20, '那些以恶报善的都与我作对，因为我追求良善。'),
('CNV', '诗篇', 19, 38, 21, '耶和华啊！求你不要离弃我；我的神啊，求你不要远离我。'),
('CNV', '诗篇', 19, 38, 22, '拯救我的主啊！求你快来帮助我。'),
('CNV', '诗篇', 19, 39, 1, '我曾说：“我要谨慎我的行为，不让我的舌头犯罪；恶人在我面前的时候，我总要用罩子约束我的嘴。”'),
('CNV', '诗篇', 19, 39, 2, '我静默不出声，甚至连好话也不说（“甚至连好话也不说”或译：“我安静也得不到安慰”），我的痛苦就更加剧烈。'),
('CNV', '诗篇', 19, 39, 3, '我的心在我里面发热；我默想的时候，心里火烧；我就用舌头说话：'),
('CNV', '诗篇', 19, 39, 4, '“耶和华啊！求你使我知道我的结局，我的寿数有多少，使我知道我的生命多么短促。'),
('CNV', '诗篇', 19, 39, 5, '你使我的日子窄如手掌，我的一生在你面前如同无有；各人站得最稳的时候，也只不过是一口气。（细拉）'),
('CNV', '诗篇', 19, 39, 6, '世人来来往往只是幻影，他们忙乱也是虚空；积聚财物，却不知道谁要来收取。'),
('CNV', '诗篇', 19, 39, 7, '主啊！现在我还等候什么呢？我的指望在乎你。'),
('CNV', '诗篇', 19, 39, 8, '求你救我脱离我的一切过犯，不要使我遭受愚顽人的羞辱。'),
('CNV', '诗篇', 19, 39, 9, '因为是你作了这事，我就静默不开口。'),
('CNV', '诗篇', 19, 39, 10, '求你除掉你降在我身上的灾祸；因你手的责打，我就消灭。'),
('CNV', '诗篇', 19, 39, 11, '你因人的罪孽，藉着责罚管教他们，叫他们所宝贵的消失，像被虫蛀蚀；世人都不过是一口气。（细拉）'),
('CNV', '诗篇', 19, 39, 12, '耶和华啊！求你垂听我的祷告，留心听我的呼求；我流泪，求你不要缄默；因为我在你面前是客旅，是寄居的，像我所有的祖先一样。'),
('CNV', '诗篇', 19, 39, 13, '求你不要怒视我，使我在去而不返之先，可以喜乐。”'),
('CNV', '诗篇', 19, 40, 1, '我曾切切等候耶和华；他转向我，听了我的呼求。'),
('CNV', '诗篇', 19, 40, 2, '他把我从荒芜的坑里，从泥沼中拉上来；他使我的脚站在磐石上，又使我的脚步稳定。'),
('CNV', '诗篇', 19, 40, 3, '他使我口唱新歌，赞美我们的神；许多人看见了，就必惧怕，并且要倚靠耶和华。'),
('CNV', '诗篇', 19, 40, 4, '那倚靠耶和华，不转向高傲和偏向虚谎的人的，这人是有福的。'),
('CNV', '诗篇', 19, 40, 5, '耶和华我的神啊！你所行的奇事，并你向我们所怀的意念很多，没有人可以和你相比；如果我要述说陈明，也多到不能胜数。'),
('CNV', '诗篇', 19, 40, 6, '祭品和礼物不是你喜悦的。你开通了我的耳朵；燔祭和赎罪祭，不是你要求的。'),
('CNV', '诗篇', 19, 40, 7, '那时我说：“看哪！我来了，经卷上已经记载我的事；'),
('CNV', '诗篇', 19, 40, 8, '我的神啊！我乐意遵行你的旨意；你的律法常在我的心里。”'),
('CNV', '诗篇', 19, 40, 9, '我要在大会中传扬公义的福音；我必不禁止我的嘴唇；耶和华啊！这是你知道的。'),
('CNV', '诗篇', 19, 40, 10, '我没有把你的公义隐藏在心里；我已经述说了你的信实和救恩；在大会中，我没有隐瞒你的慈爱和诚实。'),
('CNV', '诗篇', 19, 40, 11, '耶和华啊！求你的怜悯不要向我止息；愿你的慈爱和诚实常常保护我。'),
('CNV', '诗篇', 19, 40, 12, '因有无数的祸患围绕着我；我的罪孽追上了我，使我不能看见；它们比我的头发还多，以致我心惊胆战。'),
('CNV', '诗篇', 19, 40, 13, '耶和华啊！求你开恩搭救我；耶和华啊！求你快来帮助我。'),
('CNV', '诗篇', 19, 40, 14, '愿那些寻找我，要毁灭我命的，一同抱愧蒙羞；愿那些喜悦我遭害的，退后受辱。'),
('CNV', '诗篇', 19, 40, 15, '愿那些对我说：“啊哈！啊哈！”的，都因羞愧而惊惶。'),
('CNV', '诗篇', 19, 40, 16, '愿所有寻求你的，都因你欢喜快乐；愿那些喜爱你救恩的，常说：“要尊耶和华为大。”'),
('CNV', '诗篇', 19, 40, 17, '至于我，我是困苦贫穷的；主仍顾念我。你是我的帮助，我的拯救；我的神啊！求你不要耽延。'),
('CNV', '诗篇', 19, 41, 1, '关怀穷乏人的有福了；在遭难的日子，耶和华必救他。'),
('CNV', '诗篇', 19, 41, 2, '耶和华要保护他，使他生存；他在地上要称为有福的；求你不要照着他敌人的心愿把他交给他们。'),
('CNV', '诗篇', 19, 41, 3, '他患病在床，耶和华必扶持他；在病榻中你使他恢复健康。'),
('CNV', '诗篇', 19, 41, 4, '至于我，我曾说：“耶和华啊！求你恩待我；求你医治我，因为我得罪了你。”'),
('CNV', '诗篇', 19, 41, 5, '我的仇敌用恶毒的话中伤我，说：“他什么时候死呢？他的名字什么时候消灭呢？”'),
('CNV', '诗篇', 19, 41, 6, '即使他来看我，说的也是假话；他把奸诈积存在心里，走到外面才说出来。'),
('CNV', '诗篇', 19, 41, 7, '所有憎恨我的人，都交头接耳地议论我；他们设恶计要害我，说：'),
('CNV', '诗篇', 19, 41, 8, '“有恶疾临到他身上；他既然躺下了，就必一病不起。”'),
('CNV', '诗篇', 19, 41, 9, '连我信任的密友，就是那吃我饭的，也用脚踢我。'),
('CNV', '诗篇', 19, 41, 10, '至于你，耶和华啊！求你恩待我，使我康复起来，好报复他们。'),
('CNV', '诗篇', 19, 41, 11, '因此我就知道你喜爱我，因为我的仇敌不能向我欢呼夸胜。'),
('CNV', '诗篇', 19, 41, 12, '至于我，你因为我正直，就扶持我；你使我永远站在你面前。'),
('CNV', '诗篇', 19, 41, 13, '耶和华以色列的神是应当称颂的，从永远直到永远。阿们，阿们。'),
('CNV', '诗篇', 19, 42, 1, '神啊！我的心渴慕你，好像鹿渴慕溪水。'),
('CNV', '诗篇', 19, 42, 2, '我的心渴想神，就是永活的神；我什么时候可以来朝见神的面呢？'),
('CNV', '诗篇', 19, 42, 3, '人整天对我说：“你的神在哪里呢？”我就昼夜以眼泪当饭吃。'),
('CNV', '诗篇', 19, 42, 4, '我从前常常和群众同去，与他们进到神的殿里，在欢呼和称谢声中，大家守节。每逢想起这些事，我的心就感到难过。'),
('CNV', '诗篇', 19, 42, 5, '我的心哪！你为什么沮丧呢？为什么在我里面不安呢？应当等候神；因为我还要称赞他，他是我面前的救助、我的神。'),
('CNV', '诗篇', 19, 42, 6, '我的心在我里面沮丧；因此我从约旦地，从黑门岭，从米萨山，记念你。'),
('CNV', '诗篇', 19, 42, 7, '你的瀑布一发声，深渊就和深渊响应；你的洪涛和波浪都掩盖了我。'),
('CNV', '诗篇', 19, 42, 8, '白天耶和华赐下他的慈爱；夜间我要向他歌颂，向赐我生命的神祷告。'),
('CNV', '诗篇', 19, 42, 9, '我要对神我的磐石说：“你为什么忘记我呢？我为什么因仇敌的压迫徘徊悲哀呢？”'),
('CNV', '诗篇', 19, 42, 10, '我的敌人整天对我说：“你的神在哪里呢？”他们这样辱骂我的时候，就像在击碎我的骨头。'),
('CNV', '诗篇', 19, 42, 11, '我的心哪！你为什么沮丧呢？为什么在我里面不安呢？应当等候神；因为我还要称赞他，他是我面前的救助、我的神。'),
('CNV', '诗篇', 19, 43, 1, '神啊！求你为我伸冤，为我的案件向不敬虔的国申辩；求你救我脱离诡诈和不义的人；'),
('CNV', '诗篇', 19, 43, 2, '因为你是赐我力量的神。你为什么弃绝我呢？我为什么因仇敌的压迫徘徊悲哀呢？'),
('CNV', '诗篇', 19, 43, 3, '求你发出你的亮光和真理，好引导我，带我到你的圣山，到你的居所。'),
('CNV', '诗篇', 19, 43, 4, '我就走到神的祭坛前，到神、我极大的喜乐那里。神啊！我的神啊！我要弹琴称赞你。'),
('CNV', '诗篇', 19, 43, 5, '我的心哪！你为什么沮丧呢？为什么在我里面不安呢？应当等候神；因为我还要称赞他，他是我面前的救助、我的神。'),
('CNV', '诗篇', 19, 44, 1, '神啊！你在古时，在我们列祖的日子所作的事，我们亲耳听见了，我们的列祖也给我们述说过。'),
('CNV', '诗篇', 19, 44, 2, '你曾亲手把列国赶出去，却栽培了我们的列祖；你曾苦待众民，却使我们的列祖昌盛。'),
('CNV', '诗篇', 19, 44, 3, '因为他们取得那地，不是靠自己的刀剑；他们得胜，也不是靠自己的膀臂；而是靠你的右手、你的膀臂和你脸上的光，因为你喜悦他们。'),
('CNV', '诗篇', 19, 44, 4, '神啊！你是我的王；求你出令，使雅各得胜。'),
('CNV', '诗篇', 19, 44, 5, '我们靠着你，必打倒我们的敌人；靠着你的名，必践踏那些起来攻击我们的。'),
('CNV', '诗篇', 19, 44, 6, '因为我不是倚靠我的弓，我的刀剑也不能使我得胜。'),
('CNV', '诗篇', 19, 44, 7, '但你使我们胜过了我们的敌人，使憎恨我们的人都羞愧。'),
('CNV', '诗篇', 19, 44, 8, '我们整天因神夸耀，我们要永远称赞你的名。（细拉）'),
('CNV', '诗篇', 19, 44, 9, '现在，你却弃绝我们，使我们受辱，不再和我们的军队一同出征。'),
('CNV', '诗篇', 19, 44, 10, '你使我们在敌人面前转身后退；憎恨我们的人都任意抢掠。'),
('CNV', '诗篇', 19, 44, 11, '你使我们像给人宰吃的羊，把我们分散在列国中。'),
('CNV', '诗篇', 19, 44, 12, '你把你的子民廉价出售；他们的售价并没有使你得到利益。'),
('CNV', '诗篇', 19, 44, 13, '你使我们成为邻居的羞辱，成为我们四周的人讥笑和讽刺的对象。'),
('CNV', '诗篇', 19, 44, 14, '你使我们在列国中成为话柄，在万民中使人摇头。'),
('CNV', '诗篇', 19, 44, 15, '我的羞辱整天在我面前，我脸上的羞愧把我遮盖了；'),
('CNV', '诗篇', 19, 44, 16, '都因那辱骂和毁谤的人的声音，并因仇敌和报仇者的缘故。'),
('CNV', '诗篇', 19, 44, 17, '这一切临到我们身上，我们却没有忘记你，也没有违背你的约。'),
('CNV', '诗篇', 19, 44, 18, '我们的心没有退后，我们的脚步也没有偏离你的路。'),
('CNV', '诗篇', 19, 44, 19, '但你竟在野狗之地把我们压伤了，又以死亡的阴影笼罩我们。'),
('CNV', '诗篇', 19, 44, 20, '如果我们忘记了我们神的名，或是向别神伸手祷告；'),
('CNV', '诗篇', 19, 44, 21, '神不会查究这事吗？因为他知道人心的隐秘。'),
('CNV', '诗篇', 19, 44, 22, '为你的缘故，我们终日被置于死地；人看我们如同将宰的羊。'),
('CNV', '诗篇', 19, 44, 23, '主啊！求你醒来，为什么还睡着呢？求你起来，不要永远弃绝我们。'),
('CNV', '诗篇', 19, 44, 24, '你为什么掩面，忘记了我们的苦难和压迫呢？'),
('CNV', '诗篇', 19, 44, 25, '我们俯伏在尘土之上；我们的身体紧贴地面。'),
('CNV', '诗篇', 19, 44, 26, '求你起来帮助我们，为了你慈爱的缘故救赎我们。'),
('CNV', '诗篇', 19, 45, 1, '我心里涌出优美的言辞；我要为王朗诵我的作品；我的舌头像经验丰富的作家的笔。'),
('CNV', '诗篇', 19, 45, 2, '你比世人都美好；你的嘴唇吐出恩言；因此，神赐福给你，直到永远。'),
('CNV', '诗篇', 19, 45, 3, '大能者啊！愿你腰间佩上刀，彰显你的尊荣和威严。'),
('CNV', '诗篇', 19, 45, 4, '在你的威严中，为了真理、谦卑和公义的缘故，你胜利地乘车前进；愿你的右手施行可畏的事。'),
('CNV', '诗篇', 19, 45, 5, '你的箭锐利，射中了王的仇敌的心；万民都仆倒在你脚下。'),
('CNV', '诗篇', 19, 45, 6, '神啊！你的宝座是永永远远的，你国的权杖是公平的权杖。'),
('CNV', '诗篇', 19, 45, 7, '你喜爱公义，恨恶邪恶，所以，神，就是你的神，用喜乐的油膏抹你，胜过膏抹你的同伴。'),
('CNV', '诗篇', 19, 45, 8, '你的衣服都有没药、沉香和肉桂的香气；从象牙宫里有丝弦的乐声，使你欢喜。'),
('CNV', '诗篇', 19, 45, 9, '你的贵妃中有众君王的女儿；王后佩戴着俄斐的金饰，站在你的右边。'),
('CNV', '诗篇', 19, 45, 10, '王所爱的女子啊！你要听，要看，要留心地听；你要忘记你的本族和你的父家；'),
('CNV', '诗篇', 19, 45, 11, '王就爱慕你的美丽；因为他是你的主，你要向他俯伏。'),
('CNV', '诗篇', 19, 45, 12, '推罗的居民（“居民”原文作“女子”）必带着礼物而来；民间富有的人要向你求恩。'),
('CNV', '诗篇', 19, 45, 13, '王所爱的女子在宫里，极其荣华；她的衣服全是用金线绣成的。'),
('CNV', '诗篇', 19, 45, 14, '她身穿刺绣的衣服，被引到王的面前；她后面伴随的童女，也都被带到你的面前。'),
('CNV', '诗篇', 19, 45, 15, '她们欢喜快乐被引到王那里；她们要进入王宫。'),
('CNV', '诗篇', 19, 45, 16, '你的子孙必接续你的列祖；你要立他们作全地的王。'),
('CNV', '诗篇', 19, 45, 17, '我必使你的名被万代记念；因此万民都必称赞你，直到永永远远。'),
('CNV', '诗篇', 19, 46, 1, '神是我们的避难所，是我们的力量，是我们在患难中随时都可得到的帮助。'),
('CNV', '诗篇', 19, 46, 2, '因此，地虽然震动，群山虽然崩塌入海洋的深处，我们也不害怕。'),
('CNV', '诗篇', 19, 46, 3, '虽然海浪翻腾澎湃，虽然山岳因波涛汹涌摇动，我们也不害怕。（细拉）'),
('CNV', '诗篇', 19, 46, 4, '有一条河，它众多的支流使神的城充满快乐；这城就是至高者居住的圣所。'),
('CNV', '诗篇', 19, 46, 5, '神在城中，城必不动摇；天一亮，神必帮助它。'),
('CNV', '诗篇', 19, 46, 6, '列邦喧嚷，万国动摇；神一发声，地就融化。'),
('CNV', '诗篇', 19, 46, 7, '万军之耶和华与我们同在；雅各的神是我们的保障。（细拉）'),
('CNV', '诗篇', 19, 46, 8, '你们都来，看耶和华的作为，看他怎样使地荒凉。'),
('CNV', '诗篇', 19, 46, 9, '他使战争止息，直到地极；他把弓折毁，把矛砍断，把战车用火焚烧。'),
('CNV', '诗篇', 19, 46, 10, '你们要住手，要知道我是神；我要在列国中被尊崇，我要在全地上被尊崇。'),
('CNV', '诗篇', 19, 46, 11, '万军之耶和华与我们同在；雅各的神是我们的保障。（细拉）'),
('CNV', '诗篇', 19, 47, 1, '万民哪！你们都要鼓掌，要向神欢声呼喊；'),
('CNV', '诗篇', 19, 47, 2, '因为耶和华至高者是可敬畏的，他是统治全地的大君王。'),
('CNV', '诗篇', 19, 47, 3, '他要使万民臣服在我们之下，使列国臣服在我们的脚下。'),
('CNV', '诗篇', 19, 47, 4, '他为我们选择了我们的产业，就是他所爱的雅各的荣耀。（细拉）'),
('CNV', '诗篇', 19, 47, 5, '神在欢呼声中上升，耶和华在号角声中上升。'),
('CNV', '诗篇', 19, 47, 6, '你们要歌颂，歌颂神；你们要歌颂，歌颂我们的王。'),
('CNV', '诗篇', 19, 47, 7, '因为神是全地的王，你们要用诗歌歌颂他。'),
('CNV', '诗篇', 19, 47, 8, '神作王统治列国，神坐在他的圣宝座上。'),
('CNV', '诗篇', 19, 47, 9, '万民中的显贵都聚集起来，要作亚伯拉罕的神的子民；因为地上的君王（“君王”原文作“盾牌”）都归顺神；他被尊为至高。'),
('CNV', '诗篇', 19, 48, 1, '在我们神的城中，在他的圣山上，耶和华是至大的，应该大受赞美。'),
('CNV', '诗篇', 19, 48, 2, '在北面的锡安山、大君王的城，美丽高耸，是全地所喜欢的。'),
('CNV', '诗篇', 19, 48, 3, '神在城的堡垒中，显明自己是避难所。'),
('CNV', '诗篇', 19, 48, 4, '看哪！列王会合，一同前进。'),
('CNV', '诗篇', 19, 48, 5, '他们一见这城，就惊惶，慌忙逃跑。'),
('CNV', '诗篇', 19, 48, 6, '他们在那里战栗恐惧；他们痛苦好像妇人分娩时一样。'),
('CNV', '诗篇', 19, 48, 7, '你用东风摧毁他施的船队。'),
('CNV', '诗篇', 19, 48, 8, '在万军之耶和华的城中，就是在我们神的城中，我们所看见的，正如我们所听见的：神必坚立这城，直到永远。（细拉）'),
('CNV', '诗篇', 19, 48, 9, '神啊！我们在你的殿中，想念你的慈爱。'),
('CNV', '诗篇', 19, 48, 10, '神啊！你受的赞美，就像你的名一样，达到地极；你的右手满了公义。'),
('CNV', '诗篇', 19, 48, 11, '因你的审判，锡安山应当欢喜，犹大的居民（“居民”原文作“女子”）应当快乐。'),
('CNV', '诗篇', 19, 48, 12, '你们要在锡安四处巡行，绕城一周，数点城楼，'),
('CNV', '诗篇', 19, 48, 13, '细察它的外墙，巡视它的堡垒，使你们可以述说给后代的人听。'),
('CNV', '诗篇', 19, 48, 14, '因为这位神就是我们的神，直到永永远远；他必引导我们，直到我们死的时候。'),
('CNV', '诗篇', 19, 49, 1, '万民哪！你们要听这话；世上的居民哪！你们要留心听。'),
('CNV', '诗篇', 19, 49, 2, '不论地位高低，或贫或富，都要一同留心听。'),
('CNV', '诗篇', 19, 49, 3, '我的口要说出智慧的话；我的心要默想明智的事。'),
('CNV', '诗篇', 19, 49, 4, '我要留心聆听箴言；我要弹琴解开谜语。'),
('CNV', '诗篇', 19, 49, 5, '在患难的日子，暗中迫害我的恶人围绕我的时候，我何须惧怕呢？'),
('CNV', '诗篇', 19, 49, 6, '他们倚靠财富，自夸多财。'),
('CNV', '诗篇', 19, 49, 7, '但他们没有一个能把他的兄弟赎回，或把他的赎价交给神，'),
('CNV', '诗篇', 19, 49, 8, '（因为他生命的赎价非常昂贵，只好永远放弃，）'),
('CNV', '诗篇', 19, 49, 9, '使他永远活着，不见朽坏。'),
('CNV', '诗篇', 19, 49, 10, '他看见智慧人死去，愚昧人和愚顽人一同灭亡，把他们的财产留给别人。'),
('CNV', '诗篇', 19, 49, 11, '他们心里想，他们的家必永存，他们的住处必留到万代；他们以自己的名，称自己的地方。'),
('CNV', '诗篇', 19, 49, 12, '但是人不能长享富贵；他们就像要灭亡的牲畜一样。'),
('CNV', '诗篇', 19, 49, 13, '这就是愚昧人的道路；但在他们以后的人，还欣赏他们的话。（细拉）'),
('CNV', '诗篇', 19, 49, 14, '他们好像羊群被派定下阴间；死亡必作他们的牧人。到了早晨，正直人要管辖他们；他们的形体必被阴间消灭，他们再没有住处。'),
('CNV', '诗篇', 19, 49, 15, '但神必救赎我的灵魂脱离阴间的权势，因为他必把我接去。（细拉）'),
('CNV', '诗篇', 19, 49, 16, '别人发财，家室增荣的时候，你不要惧怕。'),
('CNV', '诗篇', 19, 49, 17, '因为他死的时候，什么也不能带走；他的荣华也不能随他下去。'),
('CNV', '诗篇', 19, 49, 18, '他在世的时候，虽然自称是有福的，并且说：“只要你丰足，人就称赞你。”'),
('CNV', '诗篇', 19, 49, 19, '他还要归到他历代的祖宗那里去，永不再见光明。'),
('CNV', '诗篇', 19, 49, 20, '人享富贵而不聪明，就像要灭亡的牲畜一样。'),
('CNV', '诗篇', 19, 50, 1, '大能者神耶和华已经说话，从日出之地到日落之处呼唤大地。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 50, 2, '神从全美的锡安，已经彰显荣光。'),
('CNV', '诗篇', 19, 50, 3, '我们的神来临，决不缄默无声；在他面前有火燃烧，在他四周有暴风刮起。'),
('CNV', '诗篇', 19, 50, 4, '他向天上、向地下呼唤，为要审判自己的子民，说：'),
('CNV', '诗篇', 19, 50, 5, '“你们把我的圣民聚集到我这里来，就是那些用祭物与我立约的人。”'),
('CNV', '诗篇', 19, 50, 6, '诸天宣扬他的公义，因为神自己就是审判者。（细拉）'),
('CNV', '诗篇', 19, 50, 7, '“我的子民哪！你们要听，我要说话；以色列啊！我要控诉你；我是神，是你的神。'),
('CNV', '诗篇', 19, 50, 8, '我不是因你的祭物责备你，你的燔祭常在我面前。'),
('CNV', '诗篇', 19, 50, 9, '我不从你家里取公牛，也不从你羊圈中取公山羊。'),
('CNV', '诗篇', 19, 50, 10, '因为树林中的百兽是我的，千山上的牲畜也是我的。'),
('CNV', '诗篇', 19, 50, 11, '山中的雀鸟我都认识，田野的走兽也都属我。'),
('CNV', '诗篇', 19, 50, 12, '如果我饿了，我也不用对你说；因为世界和其中所充满的，都是我的。'),
('CNV', '诗篇', 19, 50, 13, '难道我要吃公牛的肉吗？要喝公山羊的血吗？'),
('CNV', '诗篇', 19, 50, 14, '你要以感谢为祭献给神，又要向至高者还你的愿。'),
('CNV', '诗篇', 19, 50, 15, '在患难的日子，你呼求我。我必搭救你，你也必尊敬我。”'),
('CNV', '诗篇', 19, 50, 16, '但神对恶人说：“你怎么敢述说我的律例，你的口怎么敢提到我的约呢？'),
('CNV', '诗篇', 19, 50, 17, '至于你，你憎恨管教，并且把我的话丢在背后。'),
('CNV', '诗篇', 19, 50, 18, '你看见盗贼的时候，就乐于和他在一起；你又与行淫的人有分。'),
('CNV', '诗篇', 19, 50, 19, '你使你的口乱说坏话，使你的舌头编造谎言。'),
('CNV', '诗篇', 19, 50, 20, '你经常毁谤你的兄弟，诬蔑你母亲的儿子。'),
('CNV', '诗篇', 19, 50, 21, '你作了这些事，我默不作声；你以为我和你一样？其实我要责备你，要当面指控你。'),
('CNV', '诗篇', 19, 50, 22, '忘记神的人哪！你们要思想这事，免得我把你们撕碎，没有人能搭救。'),
('CNV', '诗篇', 19, 50, 23, '凡是以感谢为祭献上的，就是尊敬我；那预备道路的，我必使他得见神的救恩。”'),
('CNV', '诗篇', 19, 51, 1, '神啊！求你按着你的慈爱恩待我，照着你丰盛的怜悯涂抹我的过犯。'),
('CNV', '诗篇', 19, 51, 2, '求你彻底洗净我的罪孽，洁除我的罪。'),
('CNV', '诗篇', 19, 51, 3, '因为我知道我的过犯；我的罪常在我面前。'),
('CNV', '诗篇', 19, 51, 4, '我得罪了你，唯独得罪你；我行了你眼中看为恶的事，因此，你宣判的时候，显为公义；你审判的时候，显为清正。'),
('CNV', '诗篇', 19, 51, 5, '看哪，我是在罪孽里生的；我母亲在罪中怀了我。'),
('CNV', '诗篇', 19, 51, 6, '看哪！你喜爱的是内心的诚实；在我内心的隐密处，你使我得智慧。'),
('CNV', '诗篇', 19, 51, 7, '求你用牛膝草洁净我，我就干净；求你洗净我，我就比雪更白。'),
('CNV', '诗篇', 19, 51, 8, '求你使我听见欢喜和快乐的声音，使你所压伤的骨头可以欢呼。'),
('CNV', '诗篇', 19, 51, 9, '求你掩面不看我的罪恶，求你涂抹我的一切罪孽。'),
('CNV', '诗篇', 19, 51, 10, '神啊！求你为我造一颗清洁的心，求你使我里面重新有坚定的灵。'),
('CNV', '诗篇', 19, 51, 11, '不要把我从你面前丢弃，不要从我身上收回你的圣灵。'),
('CNV', '诗篇', 19, 51, 12, '求你使我重得你救恩的喜乐，重新有乐意的灵支持我。'),
('CNV', '诗篇', 19, 51, 13, '我就必把你的道指教有过犯的人，罪人必回转归向你。'),
('CNV', '诗篇', 19, 51, 14, '神啊！你是拯救我的神，求你救我脱离流人血的罪；我的舌头就必颂扬你的公义。'),
('CNV', '诗篇', 19, 51, 15, '主啊！求你开我的嘴，使我的口宣扬赞美你的话。'),
('CNV', '诗篇', 19, 51, 16, '因为你不喜爱祭物；我就是献上燔祭，你也不喜悦。'),
('CNV', '诗篇', 19, 51, 17, '神所要的祭，就是破碎的灵；神啊！破碎痛悔的心，你必不轻看。'),
('CNV', '诗篇', 19, 51, 18, '求你按着你的美意善待锡安；求你修筑耶路撒冷的城墙。'),
('CNV', '诗篇', 19, 51, 19, '那时，你必悦纳公义的祭、燔祭和全牲的燔祭；那时，人必把公牛献在你的祭坛上。'),
('CNV', '诗篇', 19, 52, 1, '勇士啊！你为什么以作恶自夸呢？神的慈爱是常存的。'),
('CNV', '诗篇', 19, 52, 2, '你图谋毁灭，你的舌头锋利像剃刀，常弄诡诈。'),
('CNV', '诗篇', 19, 52, 3, '你喜爱作恶过于行善，喜爱撒谎过于说实话。（细拉）'),
('CNV', '诗篇', 19, 52, 4, '你喜爱你诡诈的舌头，所说一切毁灭人的话。'),
('CNV', '诗篇', 19, 52, 5, '神必把你永远拆毁；他必把你挪去，把你从帐棚中揪出来，把你从活人之地连根拔起。（细拉）'),
('CNV', '诗篇', 19, 52, 6, '义人必看见而惧怕；他们必讥笑他，说：'),
('CNV', '诗篇', 19, 52, 7, '“看哪！这就是那不以神为自己保障的人，他只倚靠自己丰盛的财富，以毁灭别人来加强自己的力量。”'),
('CNV', '诗篇', 19, 52, 8, '至于我，我就像神殿中茂盛的橄榄树一样；我倚靠神的慈爱，直到永永远远。'),
('CNV', '诗篇', 19, 52, 9, '我要永远称谢你，因为你行了这事；我必在你圣民的面前，宣扬（“宣扬”原文作“仰望”）你的名，因你的名是美好的。'),
('CNV', '诗篇', 19, 53, 1, '愚顽人心里说：“没有神。”他们都是败坏，行了可憎的不义；没有一个行善的。'),
('CNV', '诗篇', 19, 53, 2, '神从天上察看世人，要看看有明慧的没有，有寻求神的没有，'),
('CNV', '诗篇', 19, 53, 3, '他们各人都偏离了正道，一同变成污秽；没有行善的，连一个也没有。'),
('CNV', '诗篇', 19, 53, 4, '作恶的都是无知的吗？他们吞吃我的子民好像吃饭一样，并不求告神。'),
('CNV', '诗篇', 19, 53, 5, '他们在无可惊惧的时候，必大大震惊；因为神把那些扎营攻击你的人的骨头击散了；他们蒙羞受辱，因为神弃绝了他们。'),
('CNV', '诗篇', 19, 53, 6, '但愿以色列的救恩从锡安而出；神给他子民带来复兴的时候（“神给他子民带来复兴的时候”或译：“神把他被掳的子民带回来的时候”），雅各要快乐，以色列要欢喜。'),
('CNV', '诗篇', 19, 54, 1, '神啊！求你因你的名拯救我，求你以你的大能为我伸冤。'),
('CNV', '诗篇', 19, 54, 2, '神啊！求你垂听我的祷告，留心听我口中的言语。'),
('CNV', '诗篇', 19, 54, 3, '因为傲慢的人（“傲慢的人”有古抄本作“外族人”）起来攻击我，强横的人寻索我的性命；他们不把神放在眼里。（细拉）'),
('CNV', '诗篇', 19, 54, 4, '看哪！神是我的帮助；主是扶持我性命的。'),
('CNV', '诗篇', 19, 54, 5, '愿灾祸报应在我仇敌的身上；愿你因你的信实消灭他们。'),
('CNV', '诗篇', 19, 54, 6, '我要甘心情愿献祭给你；耶和华啊！我必称赞你的名，因你的名是美好的。'),
('CNV', '诗篇', 19, 54, 7, '他救我脱离了一切患难；我亲眼看见了我的仇敌灭亡。'),
('CNV', '诗篇', 19, 55, 1, '神啊！求你倾听我的祷告，不要隐藏起来不听我的恳求。'),
('CNV', '诗篇', 19, 55, 2, '求你留心听我，应允我；我在苦恼中必不安宁，唉哼难过；'),
('CNV', '诗篇', 19, 55, 3, '这都是由于仇敌的声音，和恶人的欺压；因为他们使祸患临到我的身上，怒气冲冲地迫害我。'),
('CNV', '诗篇', 19, 55, 4, '我的心在我里面绞痛，死亡的恐怖落在我身上。'),
('CNV', '诗篇', 19, 55, 5, '惧怕和战兢临到我，惊恐笼罩着我。'),
('CNV', '诗篇', 19, 55, 6, '我说：“但愿我有鸽子一般的翅膀，我就飞走，得以安居。'),
('CNV', '诗篇', 19, 55, 7, '看哪！我必逃往远处，在旷野里住宿。（细拉）'),
('CNV', '诗篇', 19, 55, 8, '我要赶快到我避难的地方去，逃避狂风暴雨。”'),
('CNV', '诗篇', 19, 55, 9, '主啊！扰乱恶人的计谋，使他们的意见（“意见”原文作“舌头”）分歧，因为我在城中看见了强暴和争竞的事。'),
('CNV', '诗篇', 19, 55, 10, '恶人日夜在城墙上绕行，在城里尽是邪恶与祸害；'),
('CNV', '诗篇', 19, 55, 11, '城中也有毁灭人的事，欺压和诡诈不离城里的街道。'),
('CNV', '诗篇', 19, 55, 12, '原来不是仇敌辱骂我，如果是仇敌，我还可以忍受；也不是恨我的人向我狂妄自大，如果是恨我的人，我还可以躲避他。'),
('CNV', '诗篇', 19, 55, 13, '但你是和我同等地位的人，是我的良友，我的知己。'),
('CNV', '诗篇', 19, 55, 14, '我们常在一起密谈，我们在神的殿中与群众同行。'),
('CNV', '诗篇', 19, 55, 15, '愿死亡忽然临到他们身上，愿他们活活下到阴间去，因为在他们中间，就是在他们的住所里，尽是邪恶。'),
('CNV', '诗篇', 19, 55, 16, '至于我，我却要求告神，耶和华就必拯救我。'),
('CNV', '诗篇', 19, 55, 17, '无论在晚上、早晨或中午，我都哀诉唉哼；他必听我的声音。'),
('CNV', '诗篇', 19, 55, 18, '他救赎我的性命脱离攻击我的人，使我得着平安，尽管攻击我的人的确很多。'),
('CNV', '诗篇', 19, 55, 19, '神必听见，那从亘古坐着为王的必使他们受苦，（细拉）因他们不肯改变，也不敬畏神。'),
('CNV', '诗篇', 19, 55, 20, '他违背了自己的约，伸手攻击那些与他和好的人。'),
('CNV', '诗篇', 19, 55, 21, '他的口比奶油光滑，他的心却怀着争战的意图；他的话比油还柔和，其实却是拔了出来的刀。'),
('CNV', '诗篇', 19, 55, 22, '你要把你的重担卸给耶和华，他必扶持你；他永远不会让义人动摇。'),
('CNV', '诗篇', 19, 55, 23, '神啊！你必使恶人堕入灭亡的深坑里；流人血和行诡诈的人必活不到半世；至于我，我必倚靠你。'),
('CNV', '诗篇', 19, 56, 1, '神啊！求你恩待我，因为人要践踏我；他们终日攻击我，迫害我。'),
('CNV', '诗篇', 19, 56, 2, '我的仇敌终日践踏我，攻击我的人很多。'),
('CNV', '诗篇', 19, 56, 3, '至高者（“至高者”原文放在第2节末，在那里或译：“因逞骄傲攻击我的人很多”）啊！我惧怕的时候，就要倚靠你。'),
('CNV', '诗篇', 19, 56, 4, '靠着神，我要赞美他的话；我倚靠神，就必不惧怕，人能把我怎么样呢？'),
('CNV', '诗篇', 19, 56, 5, '他们终日歪曲我的话，常常设计谋陷害我。'),
('CNV', '诗篇', 19, 56, 6, '他们聚集在一起，埋伏着，窥探我的脚踪，等候要害我的性命。'),
('CNV', '诗篇', 19, 56, 7, '愿他们因罪孽的缘故不能逃脱；神啊！愿你在怒中使这些人败落。'),
('CNV', '诗篇', 19, 56, 8, '我多次流离，你都数算；你把我的眼泪装在你的皮袋里。这不都记在你的册子上吗？'),
('CNV', '诗篇', 19, 56, 9, '我呼求你的时候，我的仇敌就都转身退后；因此我知道神是帮助我的。'),
('CNV', '诗篇', 19, 56, 10, '靠着神，我要赞美他的话；靠着耶和华，我要赞美他的话。'),
('CNV', '诗篇', 19, 56, 11, '我倚靠神，就必不惧怕，人能把我怎么样呢？'),
('CNV', '诗篇', 19, 56, 12, '神啊！我要偿还我向你所许的愿，我要把感谢祭献给你。'),
('CNV', '诗篇', 19, 56, 13, '因为你救了我的性命脱离死亡；你不是救了我的脚不跌倒，使我在生命的光中，行在神你的面前吗？'),
('CNV', '诗篇', 19, 57, 1, '神啊，求你恩待我！求你恩待我！因为我投靠你；我要投靠在你翅膀的荫下，直到灾害过去。'),
('CNV', '诗篇', 19, 57, 2, '我要向至高的神呼求，就是向为我成就他旨意的神呼求。'),
('CNV', '诗篇', 19, 57, 3, '神从天上施恩拯救我，斥责那践踏我的人；（细拉）神必向我发出他的慈爱和信实。'),
('CNV', '诗篇', 19, 57, 4, '我躺卧在狮子中间，就是在那些想吞灭人的世人中间；他们的牙齿是枪和箭，他们的舌头是快刀。'),
('CNV', '诗篇', 19, 57, 5, '神啊！愿你被尊崇，过于诸天；愿你的荣耀遍及全地。'),
('CNV', '诗篇', 19, 57, 6, '他们为我的脚设下了网罗，使我低头屈服；他们在我面前挖了坑，自己反掉进坑中。（细拉）'),
('CNV', '诗篇', 19, 57, 7, '神啊！我的心坚定，我的心坚定；我要歌唱，我要颂赞。'),
('CNV', '诗篇', 19, 57, 8, '我的灵（“灵”或译：“荣耀”或“肝”；与16:9，30:12，108:1同）啊！你要醒过来。琴和瑟啊！你们都要醒过来。我也要唤醒黎明。'),
('CNV', '诗篇', 19, 57, 9, '主啊！我要在万民中称谢你，在万族中歌颂你。'),
('CNV', '诗篇', 19, 57, 10, '因为你的慈爱伟大，高及诸天，你的信实上达云霄。'),
('CNV', '诗篇', 19, 57, 11, '神啊！愿你被尊崇，过于诸天；愿你的荣耀遍及全地。'),
('CNV', '诗篇', 19, 58, 1, '掌权者啊！你们真的讲公义吗（本句或译：“你们默然不语，真的讲公义吗”）？你们真的按照正直审判世人吗？'),
('CNV', '诗篇', 19, 58, 2, '不是的，你们心中策划奸恶；你们的手在地上施行强暴（本句原文作“你们在地上称出你们手中的强暴”）。'),
('CNV', '诗篇', 19, 58, 3, '恶人一出母胎，就走上歧路；他们一离母腹，就走偏了路，常说谎话。'),
('CNV', '诗篇', 19, 58, 4, '他们的毒气好像蛇的毒气，又像耳朵塞住的聋虺，'),
('CNV', '诗篇', 19, 58, 5, '不听行法术者的声音，就是极灵的咒语，也是无效。'),
('CNV', '诗篇', 19, 58, 6, '神啊！求你敲掉他们口中的牙齿；耶和华啊！求你打断少壮狮子的颚骨。'),
('CNV', '诗篇', 19, 58, 7, '愿他们像流水般消逝；愿他们射箭的时候，箭头折断（本句原文意义不甚明确）。'),
('CNV', '诗篇', 19, 58, 8, '愿他们像蜗牛般蠕行消融，如同妇人流产未见天日的胎儿。'),
('CNV', '诗篇', 19, 58, 9, '你们用荆棘烧火，锅还未热，他要用旋风把烧着的和未烧着的一起刮去。'),
('CNV', '诗篇', 19, 58, 10, '义人看见仇敌遭报就欢喜；他要在恶人的血中洗自己的脚。'),
('CNV', '诗篇', 19, 58, 11, '因此，人必说：“义人果然有善报；在世上确有一位施行审判的神。”'),
('CNV', '诗篇', 19, 59, 1, '我的神啊！求你救我脱离我的仇敌，求你把我安放在高处，脱离那些起来攻击我的人。'),
('CNV', '诗篇', 19, 59, 2, '求你救我脱离作孽的人，救我脱离流人血的人。'),
('CNV', '诗篇', 19, 59, 3, '看哪！他们埋伏要害我的性命；强盛的人聚集起来攻击我；耶和华啊！这不是因我的过犯，也不是因我的罪恶。'),
('CNV', '诗篇', 19, 59, 4, '我虽然没有过错，他们还是跑来，预备好攻击我。求你醒来，帮助我，鉴察我。'),
('CNV', '诗篇', 19, 59, 5, '万军的神耶和华啊！你是以色列的神，求你醒来，惩罚万国；求你不要恩待那些背信弃义的恶人。（细拉）'),
('CNV', '诗篇', 19, 59, 6, '他们每晚都回来，好像狗一样狂吠，环绕着城行走。'),
('CNV', '诗篇', 19, 59, 7, '看哪！他们口中吐出恶言，他们嘴里吐出利刀，他们心里说：“有谁听见呢？”'),
('CNV', '诗篇', 19, 59, 8, '但你耶和华必讥笑他们，你必嗤笑万国。'),
('CNV', '诗篇', 19, 59, 9, '我的力量啊！我要仰望你，神啊！因为你是我的高台。'),
('CNV', '诗篇', 19, 59, 10, '我的神必以慈爱迎接我；神必叫我看见我的仇敌遭报。'),
('CNV', '诗篇', 19, 59, 11, '不要杀害他们，免得我的人民忘记了；主啊！你是我们的盾牌，求你用你的能力，使他们飘流无定，并且降为卑微。'),
('CNV', '诗篇', 19, 59, 12, '因他们口中的罪，因他们嘴里所说的话，愿他们在自己的骄傲中被缠住。因他们所说的是咒骂和欺骗的话，'),
('CNV', '诗篇', 19, 59, 13, '求你在怒中消灭他们，消灭他们，以致无一幸免，好使他们知道神在雅各中间掌权，直到地极。（细拉）'),
('CNV', '诗篇', 19, 59, 14, '他们每晚都回来，好像狗一样狂吠，环绕着城行走。'),
('CNV', '诗篇', 19, 59, 15, '他们四处飘流，寻找食物；如果得不到饱足，就不断咆哮。'),
('CNV', '诗篇', 19, 59, 16, '至于我，我要歌颂你的能力，每天早晨我要向你的慈爱欢呼，因为你作了我的高台，在患难的日子，作了我的避难所。'),
('CNV', '诗篇', 19, 59, 17, '我的力量啊！我要向你歌唱；神啊！你是我的高台，是向我施慈爱的神。'),
('CNV', '诗篇', 19, 60, 1, '神啊！你丢弃了我们，击碎了我们；你曾向我们发怒，现在求你复兴我们。'),
('CNV', '诗篇', 19, 60, 2, '你使地震动、崩裂，求你修补裂缝，因为地正在摇动。'),
('CNV', '诗篇', 19, 60, 3, '你使你的子民遇见艰苦；你使我们喝那令人东倒西歪的酒。'),
('CNV', '诗篇', 19, 60, 4, '你为敬畏你的人，竖起旗帜，使他们可以逃到那里，躲避敌人的弓箭（“使他们可以逃到那里，躲避敌人的弓箭”或译：“可以为真理扬起来”）。（细拉）'),
('CNV', '诗篇', 19, 60, 5, '求你用右手拯救我们，应允我们，好使你所喜爱的人得拯救。'),
('CNV', '诗篇', 19, 60, 6, '神在自己的圣所（“神在自己的圣所”或译：“神指着自己的圣洁”）说：“我必夸胜，我必分开示剑，我必量度疏割谷。'),
('CNV', '诗篇', 19, 60, 7, '基列是我的，玛拿西是我的；以法莲是我的头盔；犹大是我的权杖。'),
('CNV', '诗篇', 19, 60, 8, '摩押是我的洗脚盆；我要向以东抛鞋；我要因战胜非利士欢呼（按照《马索拉文本》，本句应作“非利士啊，你要因我的缘故欢呼”；现参照叙利亚抄本翻译）。”'),
('CNV', '诗篇', 19, 60, 9, '谁能带我进坚固城？谁能领我到以东地去呢？'),
('CNV', '诗篇', 19, 60, 10, '神啊！你不是把我们丢弃了吗？神啊！你不和我们的军队一同出战吗？'),
('CNV', '诗篇', 19, 60, 11, '求你帮助我们抵挡敌人，因为人的援助是没有用的。'),
('CNV', '诗篇', 19, 60, 12, '我们靠着神奋勇作战，因为他必践踏我们的敌人。'),
('CNV', '诗篇', 19, 61, 1, '神啊！求你听我的呼求，留心听我的祷告。'),
('CNV', '诗篇', 19, 61, 2, '我内心沮丧的时候，我从地极向你呼求；求你领我到那比我更高的磐石上面去。'),
('CNV', '诗篇', 19, 61, 3, '因为你作过我的避难所，作过我逃避仇敌的坚固堡垒。'),
('CNV', '诗篇', 19, 61, 4, '我要永远住在你的帐棚里，投靠在你翅膀下的隐密处。（细拉）'),
('CNV', '诗篇', 19, 61, 5, '神啊！你听了我所许的愿；你把产业赐给敬畏你名的人。'),
('CNV', '诗篇', 19, 61, 6, '愿你增添王的寿数；愿他的年日世世无穷。'),
('CNV', '诗篇', 19, 61, 7, '愿他在神面前永远作王；愿你指派慈爱和诚实保护他。'),
('CNV', '诗篇', 19, 61, 8, '这样，我要永远歌颂你的名，并且天天还我向你所许的愿。'),
('CNV', '诗篇', 19, 62, 1, '唯独等候神，我的心才有安息；我的拯救从他而来。'),
('CNV', '诗篇', 19, 62, 2, '唯独他是我的磐石，我的拯救；他是我的保障，我必不至动摇。'),
('CNV', '诗篇', 19, 62, 3, '你们大家攻击一个人，要把他杀害，如同拆毁倾斜的墙，将倒的壁，要到几时呢？'),
('CNV', '诗篇', 19, 62, 4, '他们彼此商议，务要把他从尊位上拉下来；他们喜爱谎话；他们口虽祝福，心却咒诅。（细拉）'),
('CNV', '诗篇', 19, 62, 5, '唯独等候神，我的心才有安息；因为我的盼望是从他而来的。'),
('CNV', '诗篇', 19, 62, 6, '唯独他是我的磐石，我的拯救；他是我的保障，我必不至动摇。'),
('CNV', '诗篇', 19, 62, 7, '我的拯救，我的荣耀，都在于神；我坚固的磐石，我的避难所，都在于神。'),
('CNV', '诗篇', 19, 62, 8, '众民哪！你们要常常倚靠他，在他面前倾心吐意；因为神是我们的避难所。（细拉）'),
('CNV', '诗篇', 19, 62, 9, '卑贱的人真是虚空，高贵的人也是虚假，放在天平上就必升起；他们加在一起比空气还轻。'),
('CNV', '诗篇', 19, 62, 10, '不要倚靠藉强暴得来的财物，也不要妄想倚靠抢夺回来的钱财；如果财宝加增，你的心也不要倚靠它。'),
('CNV', '诗篇', 19, 62, 11, '神说了一次，我两次听过这事：能力都属于神。'),
('CNV', '诗篇', 19, 62, 12, '主啊！慈爱也属于你，你必照各人所作的报应各人。'),
('CNV', '诗篇', 19, 63, 1, '神啊！你是我的神，我要切切寻求你；在干旱、疲乏、无水之地，我的心，我的身，都渴想你，切慕你。'),
('CNV', '诗篇', 19, 63, 2, '因此，我在圣所中瞻仰你，为要见你的能力和荣耀。'),
('CNV', '诗篇', 19, 63, 3, '因你的慈爱比生命更好，我的嘴唇要颂赞你。'),
('CNV', '诗篇', 19, 63, 4, '我要一生称颂你，我要奉你的名举手祷告。'),
('CNV', '诗篇', 19, 63, 5, '我的心满足，就像饱享了骨髓肥油；我要用欢乐的嘴唇赞美你。'),
('CNV', '诗篇', 19, 63, 6, '我在床上记念你，我整夜默想你。'),
('CNV', '诗篇', 19, 63, 7, '因为你帮助了我，我要在你翅膀的荫下欢呼。'),
('CNV', '诗篇', 19, 63, 8, '我心紧紧追随你；你的右手扶持我。'),
('CNV', '诗篇', 19, 63, 9, '但那些寻索我、要杀我的人，必下到地的深处。'),
('CNV', '诗篇', 19, 63, 10, '他们必交在刀剑之下，成了野狗的食物。'),
('CNV', '诗篇', 19, 63, 11, '但王必因神欢喜；所有指着神起誓的，都必可以夸耀；说谎的人的口却必被塞住。'),
('CNV', '诗篇', 19, 64, 1, '神啊！我哀诉的时候，求你垂听我的声音；求你保护我的性命，脱离仇敌的恐吓。'),
('CNV', '诗篇', 19, 64, 2, '求你把我隐藏，使我脱离恶人的阴谋，脱离作孽的人的扰乱。'),
('CNV', '诗篇', 19, 64, 3, '他们磨快自己的舌头，如同刀剑；他们吐出恶毒的言语，好像利箭，'),
('CNV', '诗篇', 19, 64, 4, '要在暗地里射杀完全的人；他们忽然射杀他，毫不惧怕。'),
('CNV', '诗篇', 19, 64, 5, '他们彼此鼓励，设下恶计，商议暗设网罗，说：“谁能看见它们呢？”'),
('CNV', '诗篇', 19, 64, 6, '他们图谋奸恶，说：“我们设计了最精密的阴谋！”人的意念和心思实在深不可测。'),
('CNV', '诗篇', 19, 64, 7, '但神要用箭射他们，他们必忽然受伤。'),
('CNV', '诗篇', 19, 64, 8, '他们各人反被自己的舌头所害，必然跌倒；所有看见他们的，都必摇头。'),
('CNV', '诗篇', 19, 64, 9, '众人都要惧怕，要传扬神的作为，并且要思想他所作的事。'),
('CNV', '诗篇', 19, 64, 10, '愿义人因耶和华欢喜，并且投靠他；愿所有心里正直的人，都因他夸耀。'),
('CNV', '诗篇', 19, 65, 1, '神啊！在锡安城里，人们都在等候要颂赞你，他们也要向你偿还所许的愿。'),
('CNV', '诗篇', 19, 65, 2, '听祷告的主啊！所有的人都要到你面前来。'),
('CNV', '诗篇', 19, 65, 3, '罪孽胜过了我，但我们的过犯，你都必赦免。'),
('CNV', '诗篇', 19, 65, 4, '你所拣选，使他亲近你，可以住在你院子中的人，是有福的！愿我们因你的居所，就是你圣殿的美福心满意足。'),
('CNV', '诗篇', 19, 65, 5, '拯救我们的神啊！你必充满威严，按公义应允我们；你本是一切地极和海洋远处的人所倚靠的。'),
('CNV', '诗篇', 19, 65, 6, '你以大能束腰，用自己的力量坚立众山。'),
('CNV', '诗篇', 19, 65, 7, '你平息了海洋的洪涛和澎湃的巨浪，以及万民的喧哗。'),
('CNV', '诗篇', 19, 65, 8, '因此，住在地极的人都因你的神迹起了敬畏的心；你使日出和日落之地的人都欢呼歌唱。'),
('CNV', '诗篇', 19, 65, 9, '你眷顾大地，普降甘霖，使地甚为肥沃；神的河满了水，好为人预备五谷；你就这样预备了大地。'),
('CNV', '诗篇', 19, 65, 10, '你灌溉地的犁沟，润平犁脊，又降雨露使地松软，并且赐福给地上所生长的。'),
('CNV', '诗篇', 19, 65, 11, '你以恩典为年岁的冠冕，你的路径都滴下脂油，'),
('CNV', '诗篇', 19, 65, 12, '滴在旷野的草场上；群山以欢乐束腰，'),
('CNV', '诗篇', 19, 65, 13, '牧场以羊群为衣，山谷都盖满了五谷；这一切都欢呼歌唱。'),
('CNV', '诗篇', 19, 66, 1, '全地的居民哪！你们应当向神欢呼。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 66, 2, '你们要歌颂他名的荣耀，把荣耀和赞美都归给他。'),
('CNV', '诗篇', 19, 66, 3, '要对神说：“你的作为多么可畏！因你伟大的能力，你的仇敌必向你假意归顺。'),
('CNV', '诗篇', 19, 66, 4, '全地的居民都必敬拜你，向你歌颂，歌颂你的名。”（细拉）'),
('CNV', '诗篇', 19, 66, 5, '你们来看神的作为，他向世人所作的事是可畏惧的。'),
('CNV', '诗篇', 19, 66, 6, '他把海变为干地，众人就步行过河，我们要在那里因他欢喜。'),
('CNV', '诗篇', 19, 66, 7, '他以自己的权能永远统管万有，他的眼睛鉴察万国，悖逆的人不可自高。（细拉）'),
('CNV', '诗篇', 19, 66, 8, '万民哪！你们要称颂我们的神，宣扬赞美他的声音。'),
('CNV', '诗篇', 19, 66, 9, '他保全我们的性命，不使我们的脚动摇。'),
('CNV', '诗篇', 19, 66, 10, '神啊！你试炼了我们，熬炼了我们，如同熬炼银子一般。'),
('CNV', '诗篇', 19, 66, 11, '你使我们进入网罗，把重担放在我们的背上。'),
('CNV', '诗篇', 19, 66, 12, '你使人驾车轧我们的头，我们经过水火，你却把我们领到丰盛之地。'),
('CNV', '诗篇', 19, 66, 13, '我要带着燔祭进你的殿，我要向你还我的愿，'),
('CNV', '诗篇', 19, 66, 14, '就是在急难的时候，我嘴唇所许的，我口里所说的。'),
('CNV', '诗篇', 19, 66, 15, '我要把肥美的牲畜作燔祭，连同公绵羊的馨香祭献给你，我并且要把公牛和公山羊献上。（细拉）'),
('CNV', '诗篇', 19, 66, 16, '所有敬畏神的人哪！你们都要来听，我要述说他为我所行的事。'),
('CNV', '诗篇', 19, 66, 17, '我曾用口向他呼求，我曾用舌头颂赞他。'),
('CNV', '诗篇', 19, 66, 18, '如果我心里偏向罪孽，主必不听；'),
('CNV', '诗篇', 19, 66, 19, '神却垂听了，他留心听了我祷告的声音。'),
('CNV', '诗篇', 19, 66, 20, '神是应当称颂的，他没有拒绝我的祷告，也没有使他的慈爱离开我。'),
('CNV', '诗篇', 19, 67, 1, '愿神恩待我们，赐福给我们，愿他用脸光照我们，（细拉）'),
('CNV', '诗篇', 19, 67, 2, '好使全地得知你的道路，万国得知你的救恩。'),
('CNV', '诗篇', 19, 67, 3, '神啊！愿众民都称谢你，愿万民都称谢你。'),
('CNV', '诗篇', 19, 67, 4, '愿万族都快乐欢呼，因为你按正直统管众民，并引导地上的万族。（细拉）'),
('CNV', '诗篇', 19, 67, 5, '神啊！愿众民都称谢你，愿万民都称谢你。'),
('CNV', '诗篇', 19, 67, 6, '地生出土产；神，就是我们的神，要赐福给我们。'),
('CNV', '诗篇', 19, 67, 7, '神要赐福给我们，全地都要敬畏他。'),
('CNV', '诗篇', 19, 68, 1, '愿神兴起，愿他的仇敌四散；愿恨恶他的人从他面前逃跑。'),
('CNV', '诗篇', 19, 68, 2, '愿你把他们赶散，如同烟被风吹散一样；愿恶人在神面前灭亡，好像蜡在火前熔化。'),
('CNV', '诗篇', 19, 68, 3, '但愿义人在神面前欢喜快乐；愿他们高兴快乐。'),
('CNV', '诗篇', 19, 68, 4, '你们要向神歌唱，歌颂他的名；为那乘车经过旷野的预备道路（本句或译：“高举那乘驾云彩之上的”）；他的名是耶和华，你们要在他面前欢乐。'),
('CNV', '诗篇', 19, 68, 5, '神在他的圣居所，作孤儿的父亲，作寡妇的伸冤者。'),
('CNV', '诗篇', 19, 68, 6, '神使孤独的有家可居住；领被囚的出来，到丰盛之处；唯有悖逆的住在干旱之地。'),
('CNV', '诗篇', 19, 68, 7, '神啊！你领着你的子民出来，走过旷野的时候，（细拉）'),
('CNV', '诗篇', 19, 68, 8, '地就震动，在你面前天也落下雨来；这西奈山在神面前，就是在以色列的神面前，也要震动。'),
('CNV', '诗篇', 19, 68, 9, '神啊！你降下大雨，使你贫瘠的产业得到滋润。'),
('CNV', '诗篇', 19, 68, 10, '你的子民住在其中；神啊，你满有恩慈，为贫苦的人预备了一切。'),
('CNV', '诗篇', 19, 68, 11, '主发出命令，传扬好信息的妇女就成了一大群。'),
('CNV', '诗篇', 19, 68, 12, '“带领大军的君王都逃跑了，逃跑了；住在家中的妇女分得了战利品。'),
('CNV', '诗篇', 19, 68, 13, '你们躺卧在羊圈中，如同鸽子的翅膀镀上白银，羽毛镀上黄金。”'),
('CNV', '诗篇', 19, 68, 14, '全能者赶散境内列王的时候，就像撒们山上下大雪。'),
('CNV', '诗篇', 19, 68, 15, '巴珊山是神的山（“神的山”或译：“最宏伟的山”）；巴珊山是多峰多岭的山。'),
('CNV', '诗篇', 19, 68, 16, '多峰多岭的山哪！你们为什么敌视神所喜悦居住的山呢？耶和华必住在那里，直到永远。'),
('CNV', '诗篇', 19, 68, 17, '神的车马千千万万；主从西奈山来到他的圣所中（本句原文作“主在其中，西奈山在圣所中”）。'),
('CNV', '诗篇', 19, 68, 18, '你升到高天的时候，掳了许多俘虏；你在人间，就是在悖逆的人当中，接受了礼物，使耶和华神可以与他们同住。'),
('CNV', '诗篇', 19, 68, 19, '主，拯救我们的神，是应当称颂的，他天天背负我们的重担。（细拉）'),
('CNV', '诗篇', 19, 68, 20, '我们的神是施行拯救的神；人能逃脱死亡，是在于主耶和华。'),
('CNV', '诗篇', 19, 68, 21, '神必打碎仇敌的头颅，就是打碎那些常行在罪中的人的脑袋。'),
('CNV', '诗篇', 19, 68, 22, '主说：“我必使他们从巴珊回来，使他们从海的深处回来；'),
('CNV', '诗篇', 19, 68, 23, '好使你在他们的血中洗自己的脚（按照《马索拉文本》，本句应作“好使你在血中打碎自己的脚”；现参照《七十士译本》翻译），使你的狗的舌头也有分舔仇敌的血。”'),
('CNV', '诗篇', 19, 68, 24, '神啊！人人都看见你的巡行队伍，看见我的神、我的君王的巡行队伍，进入圣所。'),
('CNV', '诗篇', 19, 68, 25, '歌唱的在前头行，作乐的走在后面，中间还有击鼓的少女。'),
('CNV', '诗篇', 19, 68, 26, '你们要在大会中称颂神，以色列的子孙（“以色列的子孙”原文作“从以色列的源头来的”）啊！你们要称颂耶和华。'),
('CNV', '诗篇', 19, 68, 27, '在那里有微小的便雅悯领导他们；随后的，有犹大的领袖，成群结队，还有西布伦和拿弗他利的领袖。'),
('CNV', '诗篇', 19, 68, 28, '神（“神”有古抄本作“你的神”）啊！召唤你的能力吧。神啊！坚立你为我们作成的事吧。'),
('CNV', '诗篇', 19, 68, 29, '因为你在耶路撒冷的圣殿，众王都把礼物带来献给你。'),
('CNV', '诗篇', 19, 68, 30, '求你斥责芦苇中的野兽、成群的公牛和万民中的牛犊，并且把贪爱银块的人践踏在脚下；求你赶散那些喜爱战争的民族。'),
('CNV', '诗篇', 19, 68, 31, '有使节从埃及出来，古实人赶快向神呈献礼物。'),
('CNV', '诗篇', 19, 68, 32, '地上的万国啊！你们要歌颂神，你们要颂扬主。（细拉）'),
('CNV', '诗篇', 19, 68, 33, '歌颂那乘驾在自古就有的众天之上的主；看哪！他发出了强而有力的声音。'),
('CNV', '诗篇', 19, 68, 34, '你们要承认能力是从神而来的，他的威荣是在以色列之上，他的能力显于穹苍。'),
('CNV', '诗篇', 19, 68, 35, '神啊！你在你的圣所中显为可畏；以色列的神把能力和权能赐给他的子民。神是应当称颂的。'),
('CNV', '诗篇', 19, 69, 1, '神啊！求你拯救我，因为大水淹没了我。'),
('CNV', '诗篇', 19, 69, 2, '我深陷在淤泥中，没有立足之地；我到了水深之处，波涛漫过我身。'),
('CNV', '诗篇', 19, 69, 3, '我因不住呼求而疲倦，我的喉咙发干；我因等候我的神，眼睛昏花。'),
('CNV', '诗篇', 19, 69, 4, '那些无故恨我的，比我的头发还多；无理与我为敌，要把我灭绝的，人数众多。我没有抢夺过的，竟要我偿还。'),
('CNV', '诗篇', 19, 69, 5, '神啊！我的愚昧你是知道的，我的罪愆不能向你隐瞒。'),
('CNV', '诗篇', 19, 69, 6, '主万军之耶和华啊！愿那些等候你的，不要因我蒙羞；以色列的神啊！愿那些寻求你的，不要因我受辱。'),
('CNV', '诗篇', 19, 69, 7, '然而，为了你的缘故，我忍受辱骂，满面羞愧。'),
('CNV', '诗篇', 19, 69, 8, '我的兄弟都疏远我，我同母的兄弟把我当作外人。'),
('CNV', '诗篇', 19, 69, 9, '因我为你的殿，心中迫切如同火烧；辱骂你的人的辱骂，都落在我身上。'),
('CNV', '诗篇', 19, 69, 10, '我哭泣禁食，这竟成了我的羞辱。'),
('CNV', '诗篇', 19, 69, 11, '我披上麻衣，就成了他们取笑的对象。'),
('CNV', '诗篇', 19, 69, 12, '坐在城门口的人对我议论纷纷，我成了酒徒之歌。'),
('CNV', '诗篇', 19, 69, 13, '但是，耶和华啊！在悦纳的时候，我向你祷告；神啊！求你按着你丰盛的慈爱，凭着你信实的拯救应允我。'),
('CNV', '诗篇', 19, 69, 14, '求你救我脱离淤泥，不要容我沉下去；求你救我脱离那些恨我的人，救我脱离深水。'),
('CNV', '诗篇', 19, 69, 15, '求你不要让波涛淹没我，不要让深水吞灭我，也不要让深坑把我封闭。'),
('CNV', '诗篇', 19, 69, 16, '耶和华啊！求你应允我，因为你的慈爱美善；求你照着你丰盛的怜悯转脸垂顾我。'),
('CNV', '诗篇', 19, 69, 17, '求你不要向你的仆人掩面；求你快快应允我，因为我在困境之中。'),
('CNV', '诗篇', 19, 69, 18, '求你亲近我，拯救我，因我仇敌的缘故救赎我。'),
('CNV', '诗篇', 19, 69, 19, '我所受的辱骂、欺凌和侮辱，你都知道，我所有的敌人都在你面前。'),
('CNV', '诗篇', 19, 69, 20, '辱骂伤了我的心，我忧愁难过；我希望有人同情，却一个也没有；我希望有人安慰，还是找不到一个。'),
('CNV', '诗篇', 19, 69, 21, '他们在我的食物中加上苦胆，我渴了，他们把醋给我喝。'),
('CNV', '诗篇', 19, 69, 22, '愿他们的筵席在他们面前变为网罗、报应和陷阱（按照《马索拉文本》，“报应和陷阱”应作“在他们平安的时候，变为陷阱”；现参照《七十士译本》翻译。又按照《他耳根》或译：“愿他们的平安祭筵变为陷阱”）。'),
('CNV', '诗篇', 19, 69, 23, '愿他们的眼睛昏花，不能看见；愿他们的腰不停地战抖。'),
('CNV', '诗篇', 19, 69, 24, '求你把你的恼怒倾倒在他们身上，使你的烈怒追上他们。'),
('CNV', '诗篇', 19, 69, 25, '愿他们的住处变为荒场；愿他们的帐幕无人居住。'),
('CNV', '诗篇', 19, 69, 26, '因为他们迫害你所击打的人，嘲笑你所击伤的人的痛苦。'),
('CNV', '诗篇', 19, 69, 27, '愿你在他们的惩罚上加上惩罚，不容他们在你面前得称为义。'),
('CNV', '诗篇', 19, 69, 28, '愿他们的名字从生命册上被涂抹，不要让他们和义人一同被记录。'),
('CNV', '诗篇', 19, 69, 29, '至于我，我是忧伤痛苦的人；神啊！愿你的救恩保护我。'),
('CNV', '诗篇', 19, 69, 30, '我要用诗歌赞美神的名，以感谢尊他为大。'),
('CNV', '诗篇', 19, 69, 31, '这就使耶和华喜悦，胜过献牛，或是献有角有蹄的公牛。'),
('CNV', '诗篇', 19, 69, 32, '困苦的人看见了就喜乐；寻求神的人哪！愿你们的心苏醒。'),
('CNV', '诗篇', 19, 69, 33, '因为耶和华垂听了贫穷人的祷告，也不藐视属他自己、正被囚禁的人。'),
('CNV', '诗篇', 19, 69, 34, '愿天和地都赞美他，愿海洋和海中一切生物都赞美他。'),
('CNV', '诗篇', 19, 69, 35, '因为神要拯救锡安，要建造犹大的众城；他的子民必在那里居住，并且拥有那地为业。'),
('CNV', '诗篇', 19, 69, 36, '他众仆人的后裔都必承受那地为业，喜爱他名的人要住在其中。'),
('CNV', '诗篇', 19, 70, 1, '神啊！求你搭救我；耶和华啊！求你快来帮助我。'),
('CNV', '诗篇', 19, 70, 2, '愿那些寻索我性命的，抱愧蒙羞；愿那些喜悦我遭害的，退后受辱。'),
('CNV', '诗篇', 19, 70, 3, '愿那些对我说：“啊哈！啊哈！”的，都因羞愧退后。'),
('CNV', '诗篇', 19, 70, 4, '愿所有寻求你的，都因你欢喜快乐；愿那些喜爱你救恩的，常说：“要尊神为大。”'),
('CNV', '诗篇', 19, 70, 5, '至于我，我是困苦贫穷的；神啊！求你快快到我这里来；你是我的帮助，我的拯救；耶和华啊！求你不要耽延。'),
('CNV', '诗篇', 19, 71, 1, '耶和华啊！我投靠你，求你使我永不羞愧。'),
('CNV', '诗篇', 19, 71, 2, '求你按着你的公义搭救我，救赎我；求你留心听我，拯救我。'),
('CNV', '诗篇', 19, 71, 3, '求你作我避难的磐石，使我可以常来投靠；你已经下令救我，因为你是我的岩石、我的坚垒。'),
('CNV', '诗篇', 19, 71, 4, '我的神啊！求你救我脱离恶人的手，脱离邪恶和残暴的人的掌握，'),
('CNV', '诗篇', 19, 71, 5, '因为你是我的盼望；主耶和华啊！你是我自幼以来所倚靠的。'),
('CNV', '诗篇', 19, 71, 6, '我自出母胎就倚赖你，把我从母腹中领出来的就是你，我要常常赞美你。'),
('CNV', '诗篇', 19, 71, 7, '众人都以我为怪，但你是我坚固的避难所。'),
('CNV', '诗篇', 19, 71, 8, '我要满口赞美你，我终日颂扬你的荣美。'),
('CNV', '诗篇', 19, 71, 9, '我年老的时候，求你不要丢弃我；我气力衰弱的时候，求你不要离弃我。'),
('CNV', '诗篇', 19, 71, 10, '因为我的仇敌议论我；那些窥探着要害我性命的，一同商议，'),
('CNV', '诗篇', 19, 71, 11, '说：“神已经离弃了他，你们追赶他，拿住他吧！因为没有人搭救他。”'),
('CNV', '诗篇', 19, 71, 12, '神啊！求你不要远离我；我的神啊！求你快来帮助我。'),
('CNV', '诗篇', 19, 71, 13, '愿那些控告我的，都羞愧灭亡；愿那些谋求害我的，都蒙羞受辱。'),
('CNV', '诗篇', 19, 71, 14, '至于我，我要常常仰望你，要多多赞美你。'),
('CNV', '诗篇', 19, 71, 15, '我的口要述说你的公义，终日讲述你的救恩，尽管我不知道它们的数量。'),
('CNV', '诗篇', 19, 71, 16, '我要来述说主耶和华大能的事；我要提说你独有的公义。'),
('CNV', '诗篇', 19, 71, 17, '神啊！我自幼以来，你就教导我；直到现在，我还是宣扬你奇妙的作为。'),
('CNV', '诗篇', 19, 71, 18, '神啊！到我年老发白的时候，求你仍不要离弃我，等我把你的能力向下一代传扬，把你的大能向后世所有的人传扬。'),
('CNV', '诗篇', 19, 71, 19, '神啊！你的公义达到高天，你曾经行过大事，神啊！有谁像你呢？'),
('CNV', '诗篇', 19, 71, 20, '你使我们经历了很多苦难，你必使我们再活过来，你必把我们从地的深处救上来。'),
('CNV', '诗篇', 19, 71, 21, '你必增加我的尊荣，并转过来安慰我。'),
('CNV', '诗篇', 19, 71, 22, '我的神啊！我要弹琴称赞你，称赞你的信实；以色列的圣者啊！我要鼓瑟歌颂你。'),
('CNV', '诗篇', 19, 71, 23, '我歌颂你的时候，我的嘴唇要欢呼；我的灵魂，就是你所救赎的，也要欢呼。'),
('CNV', '诗篇', 19, 71, 24, '我的舌头也要终日讲述你的公义，因为那些谋求害我的人已经蒙羞受辱了。'),
('CNV', '诗篇', 19, 72, 1, '神啊！求你把你的公正赐给王，把你的公义赐给王子。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 72, 2, '他要按着公义审判你的子民，凭着公正审判你的困苦人。'),
('CNV', '诗篇', 19, 72, 3, '因着公义，愿大山和小山都给人民带来和平。'),
('CNV', '诗篇', 19, 72, 4, '他必为民间的困苦人伸冤，拯救贫穷人，粉碎那欺压人的。'),
('CNV', '诗篇', 19, 72, 5, '他必像日月一般长久，直到万代（按照《马索拉文本》，本节应作“日月还在的时候，愿人都敬畏你，直到万代”；现参照《七十士译本》翻译）。'),
('CNV', '诗篇', 19, 72, 6, '他必像雨降在已割的草地上，像甘霖滋润大地。'),
('CNV', '诗篇', 19, 72, 7, '他在世的日子，义人必兴旺，四境太平，直到月亮不再重现。'),
('CNV', '诗篇', 19, 72, 8, '他要执掌权柄，从这海到那海，从大河直到地极。'),
('CNV', '诗篇', 19, 72, 9, '住在旷野的人必向他屈身，他的仇敌必舔尘土。'),
('CNV', '诗篇', 19, 72, 10, '他施和海岛的列王都必带来礼物，示巴和西巴的列王都必献上贡物。'),
('CNV', '诗篇', 19, 72, 11, '众王都必向他俯伏，万国都必服事他。'),
('CNV', '诗篇', 19, 72, 12, '因为贫穷人呼求的时候，他就搭救；没有人帮助的困苦人，他也搭救。'),
('CNV', '诗篇', 19, 72, 13, '他必怜恤软弱和贫穷的人，拯救贫穷人的性命。'),
('CNV', '诗篇', 19, 72, 14, '他要救他们脱离欺凌和强暴，他们的血在他眼中看为宝贵。'),
('CNV', '诗篇', 19, 72, 15, '愿他长久活着，愿人把示巴的金子奉给他，愿人为他不住祷告，终日给他祝福。'),
('CNV', '诗篇', 19, 72, 16, '愿地上五谷丰登，山顶上也都丰收；愿地上的果实茂盛，像黎巴嫩山的树林，愿城里的人繁衍，好像地上的青草。'),
('CNV', '诗篇', 19, 72, 17, '愿他的名永远常存，愿他的名延续像太阳的恒久；愿万人都因他蒙福，愿万国都称他为有福的。'),
('CNV', '诗篇', 19, 72, 18, '独行奇事的以色列的神，就是耶和华神，是应当称颂的。'),
('CNV', '诗篇', 19, 72, 19, '他荣耀的名也是应当永远称颂的；愿他的荣耀充满全地。阿们，阿们。'),
('CNV', '诗篇', 19, 72, 20, '耶西的儿子大卫的祷告完毕。'),
('CNV', '诗篇', 19, 73, 1, '神实在善待以色列，善待那些内心清洁的人。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 73, 2, '至于我，我的脚几乎滑跌，我（“我”原文作“我的脚步”）险些跌倒。'),
('CNV', '诗篇', 19, 73, 3, '我看见恶人兴隆，我就嫉妒狂傲的人。'),
('CNV', '诗篇', 19, 73, 4, '他们没有痛苦，他们的身体又健康又肥壮（本节原文作“他们到死都没有痛苦，他们的身体肥壮”）。'),
('CNV', '诗篇', 19, 73, 5, '他们没有一般人所受的苦难，也不像普通人一样遭遇灾害。'),
('CNV', '诗篇', 19, 73, 6, '所以，骄傲像链子戴在他们的颈项上，强暴好像衣裳穿在他们的身上。'),
('CNV', '诗篇', 19, 73, 7, '他们的罪孽是出于麻木的心（按照《马索拉文本》，“他们的罪孽是出于麻木的心”应作“他们的眼睛因体胖而凸出”；现参照《七十士译本》翻译），他们心里的恶念泛滥。'),
('CNV', '诗篇', 19, 73, 8, '他们讥笑人，怀着恶意说欺压人的话，他们说话自高。'),
('CNV', '诗篇', 19, 73, 9, '他们用口亵渎上天，他们用舌头毁谤全地。'),
('CNV', '诗篇', 19, 73, 10, '因此他的人民归回那里去，并且喝光了大量的水。'),
('CNV', '诗篇', 19, 73, 11, '他们说：“神怎会晓得？至高者有知识吗？”'),
('CNV', '诗篇', 19, 73, 12, '看这些恶人，他们常享安逸，财富却增加。'),
('CNV', '诗篇', 19, 73, 13, '我谨守我心纯洁实在徒然；我洗手表明清白也是枉然。'),
('CNV', '诗篇', 19, 73, 14, '因为我终日受伤害，每天早晨受惩罚。'),
('CNV', '诗篇', 19, 73, 15, '如果我心里说：“我要说这样的话”，我就是对你这一代的众儿女不忠了。'),
('CNV', '诗篇', 19, 73, 16, '我思想要明白这事，我就看为烦恼；'),
('CNV', '诗篇', 19, 73, 17, '直到我进了神的圣所，才明白他们的结局。'),
('CNV', '诗篇', 19, 73, 18, '你实在把他们安放在滑地，使他们倒下、灭亡。'),
('CNV', '诗篇', 19, 73, 19, '他们忽然间成了多么荒凉，被突然的惊恐完全消灭。'),
('CNV', '诗篇', 19, 73, 20, '人睡醒了怎样看梦，主啊！你睡醒了，也要照样轻看他们（“他们”原文作“他们的影像”）。'),
('CNV', '诗篇', 19, 73, 21, '我心中酸苦，我肺腑刺痛的时候，'),
('CNV', '诗篇', 19, 73, 22, '我是愚昧无知的；我在你面前就像畜类一般。'),
('CNV', '诗篇', 19, 73, 23, '但是，我仍常与你同在；你紧握着我的右手。'),
('CNV', '诗篇', 19, 73, 24, '你要以你的训言引领我，以后还要接我到荣耀里去。'),
('CNV', '诗篇', 19, 73, 25, '除你以外，在天上，我还有谁呢？除你以外，在地上，我也无所爱慕。'),
('CNV', '诗篇', 19, 73, 26, '我的肉身和我的内心虽然渐渐衰弱，神却永远是我心里的磐石，是我的业分。'),
('CNV', '诗篇', 19, 73, 27, '看哪！远离你的，必定灭亡；凡是对你不贞的，你都要灭绝。'),
('CNV', '诗篇', 19, 73, 28, '对我来说，亲近神是美好的，我以主耶和华为我的避难所；我要述说你的一切作为。'),
('CNV', '诗篇', 19, 74, 1, '神啊！你为什么永远丢弃我们呢？为什么你的怒气向你草场上的羊群好像烟冒出呢？（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 74, 2, '求你记念你在古时买赎的会众，就是你赎回作你产业的民族；求你记念你所居住的锡安山。'),
('CNV', '诗篇', 19, 74, 3, '求你举步去看那些长久荒凉的地方，去看仇敌在圣所里所行的一切恶事。'),
('CNV', '诗篇', 19, 74, 4, '你的敌人在敬拜你的聚会中吼叫，他们竖起了自己的旗帜为记号。'),
('CNV', '诗篇', 19, 74, 5, '他们好像那些举起斧子，在树林中砍伐树木的人。'),
('CNV', '诗篇', 19, 74, 6, '圣殿中的一切雕刻，他们都用斧子和铳子打碎了。'),
('CNV', '诗篇', 19, 74, 7, '他们用火把你的圣所烧成焦土，他们亵渎你名的居所。'),
('CNV', '诗篇', 19, 74, 8, '他们心里说：“我们要把它们完全毁灭！”他们烧毁了地上一切敬拜神的聚会地方。'),
('CNV', '诗篇', 19, 74, 9, '我们看不见我们的记号，也不再有先知；我们中间也没有人知道这灾祸要到几时。'),
('CNV', '诗篇', 19, 74, 10, '神啊！敌人辱骂你要到几时呢？仇敌亵慢你的名要到永远吗？'),
('CNV', '诗篇', 19, 74, 11, '你为什么把你的手，就是你的右手收回呢？求你从怀中抽出来毁灭他们。'),
('CNV', '诗篇', 19, 74, 12, '神自古以来就是我的君王，在地上施行拯救。'),
('CNV', '诗篇', 19, 74, 13, '你曾用你的大能分开大海，把海中怪兽的头都打碎了。'),
('CNV', '诗篇', 19, 74, 14, '你砸碎了利未亚坦（“利未亚坦”为原文音译词，或译：“海怪”〔伯3:8〕或“鳄鱼”〔伯41:1〕）的头，把它给住在旷野的人作食物。'),
('CNV', '诗篇', 19, 74, 15, '你曾开辟泉源和溪流，又使长流不息的江河干涸。'),
('CNV', '诗篇', 19, 74, 16, '白昼是你的，黑夜也是你的，月亮和太阳，都是你设立的。'),
('CNV', '诗篇', 19, 74, 17, '地上的一切疆界都是你立定的，夏天和冬天都是你制定的。'),
('CNV', '诗篇', 19, 74, 18, '耶和华啊！仇敌辱骂你，愚顽人亵渎你的名，求你记念这事。'),
('CNV', '诗篇', 19, 74, 19, '求你不要把你斑鸠的性命交给野兽，不要永远忘记你困苦人的性命。'),
('CNV', '诗篇', 19, 74, 20, '求你顾念所立的约，因为地上黑暗的地方充满了强暴的居所。'),
('CNV', '诗篇', 19, 74, 21, '不要使受欺压的人蒙羞回去，要使困苦、贫穷的人赞美你的名。'),
('CNV', '诗篇', 19, 74, 22, '神啊！求你起来，为你的案件辩护，要记得愚顽人终日对你的辱骂。'),
('CNV', '诗篇', 19, 74, 23, '求你不要忘记你敌人的声音，不要忘记那些起来与你为敌的人不住加剧地喧闹。'),
('CNV', '诗篇', 19, 75, 1, '神啊！我们称谢你，我们称谢你，因为你（“你”原文作“你的名”）接近人，人都述说你奇妙的作为。'),
('CNV', '诗篇', 19, 75, 2, '你说：“我选定了日期，我要按公正施行审判。'),
('CNV', '诗篇', 19, 75, 3, '地和地上的居民都因惧怕而融化，我却使大地的柱子坚立。（细拉）'),
('CNV', '诗篇', 19, 75, 4, '我对狂傲的人说：‘不要行事狂傲’；对邪恶的人说：‘不要举角，'),
('CNV', '诗篇', 19, 75, 5, '不要高举你们的角，不要挺着傲慢的颈项说话。’”'),
('CNV', '诗篇', 19, 75, 6, '高升不是从东面来，不是从西面来，也不是旷野来，'),
('CNV', '诗篇', 19, 75, 7, '而是由神来决定；他使这人降卑，使那人升高。'),
('CNV', '诗篇', 19, 75, 8, '原来耶和华的手里有杯，装满了起沫和混杂各种香料的酒；他把酒从杯里倒出来，地上所有的恶人都必定要喝，甚至连酒的渣滓都要喝尽。'),
('CNV', '诗篇', 19, 75, 9, '至于我，我要永远传扬，我要向雅各的神歌唱。'),
('CNV', '诗篇', 19, 75, 10, '所有恶人的角，我都要砍断，只有义人的角必被高举。'),
('CNV', '诗篇', 19, 76, 1, '在犹大，神是人人所认识的，在以色列，他的名被尊为大。'),
('CNV', '诗篇', 19, 76, 2, '他的帐棚是在撒冷，他的居所是在锡安。'),
('CNV', '诗篇', 19, 76, 3, '在那里他折断了弓上的火箭，拆毁了盾牌、刀剑和争战的兵器。（细拉）'),
('CNV', '诗篇', 19, 76, 4, '你满有光华和荣美，胜过猎物丰富的群山。'),
('CNV', '诗篇', 19, 76, 5, '心里勇敢的人都被抢掠，他们长睡不起；所有大能的勇士都无力举手。'),
('CNV', '诗篇', 19, 76, 6, '雅各的神啊！因你的斥责，坐车的和骑马的都沉睡了。'),
('CNV', '诗篇', 19, 76, 7, '唯有你是可畏的，你的烈怒一发出，谁能在你面前站立得住呢？'),
('CNV', '诗篇', 19, 76, 8, '神啊！你起来施行审判，要拯救地上所有困苦的人。那时，你从天上宣告审判，地上的人就惧怕，并且静默无声。（细拉）'),
('CNV', '诗篇', 19, 76, 10, '人的忿怒必使你得称赞，人的余怒必成为你的装饰。'),
('CNV', '诗篇', 19, 76, 11, '你们许愿，总要向耶和华你们的神偿还；所有在他周围的人，都要把贡物带来献给那可敬畏的神。'),
('CNV', '诗篇', 19, 76, 12, '他必挫折众领袖的傲气，他必使地上的君王畏惧他。'),
('CNV', '诗篇', 19, 77, 1, '我要向神发声呼求，我向神发声，他必留心听我。'),
('CNV', '诗篇', 19, 77, 2, '我在患难的日子寻求主，我整夜举手祷告，总不倦怠，我的心不肯受安慰。'),
('CNV', '诗篇', 19, 77, 3, '我想到神，就哀怨唉哼；我沉思默想，心灵就烦乱。（细拉）'),
('CNV', '诗篇', 19, 77, 4, '你使我不能合眼，我烦躁不安，连话也说不出来。'),
('CNV', '诗篇', 19, 77, 5, '我回想过往的日子，上古的年代；'),
('CNV', '诗篇', 19, 77, 6, '我想起我夜间的诗歌。我的心沉思默想，我的灵仔细探究。'),
('CNV', '诗篇', 19, 77, 7, '主要永远丢弃我，不再施恩吗？'),
('CNV', '诗篇', 19, 77, 8, '他的慈爱永远消失，他的应许永久废去吗？'),
('CNV', '诗篇', 19, 77, 9, '神忘记施恩，因忿怒而止住他的怜悯吗？（细拉）'),
('CNV', '诗篇', 19, 77, 10, '因此我说：“这是我的忧伤：至高者的右手已经改变了（“至高者的右手已经改变了”或译：“但我要追念至高者显出右手的年代”）！”'),
('CNV', '诗篇', 19, 77, 11, '我要述说耶和华的作为，我要记念你古时所行的奇事。'),
('CNV', '诗篇', 19, 77, 12, '我要默想你一切所行的，思想你的作为。'),
('CNV', '诗篇', 19, 77, 13, '神啊！你的道路是圣洁的，有哪一位神好像我们的神这样伟大呢？'),
('CNV', '诗篇', 19, 77, 14, '你是行奇事的神，你在万民中显明你的能力。'),
('CNV', '诗篇', 19, 77, 15, '你曾用你的膀臂救赎你的子民，就是雅各和约瑟的子孙。（细拉）'),
('CNV', '诗篇', 19, 77, 16, '神啊！众水看见你，众水看见你就惧怕，深渊也都战抖。'),
('CNV', '诗篇', 19, 77, 17, '密云倾降雨水，天空发出响声，你的箭闪射四方。'),
('CNV', '诗篇', 19, 77, 18, '你的雷声在旋风中响起来，闪电照亮了世界，大地战抖震动。'),
('CNV', '诗篇', 19, 77, 19, '你的道路经过海洋，你的路径穿过大水，但你的脚踪无人知道。'),
('CNV', '诗篇', 19, 77, 20, '你曾藉着摩西和亚伦的手，带领你的子民如同带领羊群一样。'),
('CNV', '诗篇', 19, 78, 1, '我的民哪！你们要留心听我的教训，侧耳听我口中的言语。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 78, 2, '我要开口用比喻，把古时隐秘的事说出来，'),
('CNV', '诗篇', 19, 78, 3, '就是我们所听过所知道的，也是我们的列祖告诉我们的，'),
('CNV', '诗篇', 19, 78, 4, '我们不把这些事向他们的子孙隐瞒，却要把耶和华应得的赞美、他的能力，和他所行的奇事，都向后代的人述说。'),
('CNV', '诗篇', 19, 78, 5, '他在雅各设立法度，在以色列中制订律法，就是他吩咐我们的列祖，去教训他们的子孙的，'),
('CNV', '诗篇', 19, 78, 6, '好使后代的人，包括将要出生的儿女，都可以知道；他们也要起来，告诉他们的子孙，'),
('CNV', '诗篇', 19, 78, 7, '使他们信靠神，不忘记神的作为，谨守他的诫命；'),
('CNV', '诗篇', 19, 78, 8, '免得他们像他们的列祖，成了顽梗悖逆的一代，心不坚定的一代，他们的心对神不忠。'),
('CNV', '诗篇', 19, 78, 9, '以法莲的子孙，虽然备有弓箭，在争战的日子，却转身逃走。'),
('CNV', '诗篇', 19, 78, 10, '他们不谨守神的约，不肯遵行他的律法。'),
('CNV', '诗篇', 19, 78, 11, '他们忘记了神的作为，和他显给他们看的奇事。'),
('CNV', '诗篇', 19, 78, 12, '他在埃及地，在琐安的田野，在他们列祖的眼前，行了奇事。'),
('CNV', '诗篇', 19, 78, 13, '他把海分开，领他们走过去，又使海水直立像一道堤坝。'),
('CNV', '诗篇', 19, 78, 14, '白日他用云彩，夜间他用火光引导他们。'),
('CNV', '诗篇', 19, 78, 15, '他在旷野使磐石裂开，给他们水喝，多如深渊的水。'),
('CNV', '诗篇', 19, 78, 16, '他使水从磐石中涌出来，使水好像江河一般流下。'),
('CNV', '诗篇', 19, 78, 17, '但他们仍然犯罪顶撞他，在干旱之地仍然悖逆至高者。'),
('CNV', '诗篇', 19, 78, 18, '他们心里试探神，随着自己的欲望要求食物。'),
('CNV', '诗篇', 19, 78, 19, '他们妄论神，说：“神可以在旷野摆设筵席吗？'),
('CNV', '诗篇', 19, 78, 20, '他虽曾击打磐石，使水涌出来，好像江河泛滥，他还能赐粮食吗？他还能为自己的子民预备肉食吗？”'),
('CNV', '诗篇', 19, 78, 21, '因此耶和华听见了，就大怒；有烈火在雅各烧起，有怒气向以色列发作。'),
('CNV', '诗篇', 19, 78, 22, '因为他们不相信神，不倚靠他的拯救。'),
('CNV', '诗篇', 19, 78, 23, '然而，他吩咐天上的云彩，打开天上的门户。'),
('CNV', '诗篇', 19, 78, 24, '他降吗哪给他们吃，把天上的食物赐给他们。'),
('CNV', '诗篇', 19, 78, 25, '于是人吃了天使的食物，是神赐下的食粮，使他们饱足。'),
('CNV', '诗篇', 19, 78, 26, '他从天空刮起东风，施能力领出南风。'),
('CNV', '诗篇', 19, 78, 27, '他降肉食给他们，多如尘土；又降飞鸟给他们，多如海沙。'),
('CNV', '诗篇', 19, 78, 28, '他使飞鸟落在他们的营中，在他们住处的四围。'),
('CNV', '诗篇', 19, 78, 29, '他们吃了，而且吃得很饱，这样，神把他们所愿的都赐给他们了。'),
('CNV', '诗篇', 19, 78, 30, '他们还没有因所愿的满足，食物仍在他们口中的时候，'),
('CNV', '诗篇', 19, 78, 31, '神的怒气就向他们发作，杀了他们中间最肥壮的人，击倒了以色列的年轻人。'),
('CNV', '诗篇', 19, 78, 32, '虽然经历了这一切，他们仍然犯罪；尽管看见这些奇事，他们仍不相信。'),
('CNV', '诗篇', 19, 78, 33, '所以神使他们的日子在虚空中消逝，使他们的岁月在惊恐中完结。'),
('CNV', '诗篇', 19, 78, 34, '神击杀他们的时候，他们就寻求他；他们回转过来，切切求问神。'),
('CNV', '诗篇', 19, 78, 35, '他们也想起神是他们的磐石，至高的神是他们的救赎主。'),
('CNV', '诗篇', 19, 78, 36, '但他们仍然用口欺骗他，用舌头向他说谎。'),
('CNV', '诗篇', 19, 78, 37, '他们的心对他不坚定，也不忠于和他所立的约。'),
('CNV', '诗篇', 19, 78, 38, '他却有怜悯，赦免罪孽，没有把他们灭绝，并且多次抑制自己的怒气，没有完全宣泄他的烈怒。'),
('CNV', '诗篇', 19, 78, 39, '他顾念他们不过是人，是一阵吹去不再返回的风。'),
('CNV', '诗篇', 19, 78, 40, '他们多少次在旷野悖逆他，在沙漠使他担忧；'),
('CNV', '诗篇', 19, 78, 41, '他们再三试探神，使以色列的圣者忧伤。'),
('CNV', '诗篇', 19, 78, 42, '他们忘记了他的能力（“他的能力”直译是“他的手”），就是他救赎他们脱离敌人的日子，'),
('CNV', '诗篇', 19, 78, 43, '他怎样在埃及显神迹，在琐安的田野行奇事。'),
('CNV', '诗篇', 19, 78, 44, '他把他们的江河都变为血，使他们不能喝河流的水。'),
('CNV', '诗篇', 19, 78, 45, '他使成群的苍蝇到他们中间来，吞吃他们；又使青蛙来毁灭他们。'),
('CNV', '诗篇', 19, 78, 46, '他把他们的农产交给蚱蜢，把他们辛劳的收获交给蝗虫。'),
('CNV', '诗篇', 19, 78, 47, '他用冰雹摧毁他们的葡萄树，用严霜冻坏他们的桑树。'),
('CNV', '诗篇', 19, 78, 48, '又把他们的牲畜交给冰雹，把他们的群畜交给闪电。'),
('CNV', '诗篇', 19, 78, 49, '他使猛烈的怒气、忿怒、愤恨、患难，好像一群降灾的使者，临到他们中间。'),
('CNV', '诗篇', 19, 78, 50, '他为自己的怒气修平了路，不惜使他们死亡，把他们的性命交给瘟疫。'),
('CNV', '诗篇', 19, 78, 51, '他在埃及击杀了所有的长子，在含的帐棚中击杀了他们强壮时生的头胎子。'),
('CNV', '诗篇', 19, 78, 52, '他却把自己的子民领出来好像领羊群，在旷野引导他们像引导群畜一样。'),
('CNV', '诗篇', 19, 78, 53, '他带领他们平平安安地走过去，所以他们不惧怕；海却淹没了他们的仇敌。'),
('CNV', '诗篇', 19, 78, 54, '他领他们进入自己圣地的境界，到他右手所得的这山地。'),
('CNV', '诗篇', 19, 78, 55, '他在他们面前把外族人赶出去，用绳子量地，分给他们作为产业，又使以色列众支派的人居住在自己的帐棚里。'),
('CNV', '诗篇', 19, 78, 56, '但他们仍然试探和悖逆至高的神，不谨守他的法则。'),
('CNV', '诗篇', 19, 78, 57, '他们背信不忠，像他们的列祖一样；他们改变了，如同不可靠的弓。'),
('CNV', '诗篇', 19, 78, 58, '因他们的邱坛，惹起他的怒气，因他们雕刻的偶像，激起他的愤恨。'),
('CNV', '诗篇', 19, 78, 59, '神听见就大怒，完全弃绝了以色列。'),
('CNV', '诗篇', 19, 78, 60, '他丢弃了在示罗的居所，就是他在世人中间居住的帐棚。'),
('CNV', '诗篇', 19, 78, 61, '他又把象征他权能的约柜交给人掳去，把他的荣美交在敌人的手里，'),
('CNV', '诗篇', 19, 78, 62, '并且把自己的子民交给刀剑，向自己的产业大发烈怒。'),
('CNV', '诗篇', 19, 78, 63, '他们的青年被火吞灭，他们的少女也听不见结婚的喜歌。'),
('CNV', '诗篇', 19, 78, 64, '他们的祭司倒在刀下，他们的寡妇却不能哀哭。'),
('CNV', '诗篇', 19, 78, 65, '那时主好像从睡眠中醒过来，如同勇士酒后清醒一样。'),
('CNV', '诗篇', 19, 78, 66, '他击退了他的敌人，使他们永远蒙羞受辱。'),
('CNV', '诗篇', 19, 78, 67, '他弃绝约瑟的帐棚，不拣选以法莲支派，'),
('CNV', '诗篇', 19, 78, 68, '却拣选了犹大支派，他所爱的锡安山。'),
('CNV', '诗篇', 19, 78, 69, '他建造了自己的圣所好像在高天之上，又像他所建立永存的大地。'),
('CNV', '诗篇', 19, 78, 70, '他拣选了自己的仆人大卫，把他从羊圈中召出来；'),
('CNV', '诗篇', 19, 78, 71, '他领他出来，使他不再跟着那些母羊，却要牧养他的子民雅各，和他的产业以色列。'),
('CNV', '诗篇', 19, 78, 72, '于是大卫以正直的心牧养他们，灵巧地引导他们。'),
('CNV', '诗篇', 19, 79, 1, '神啊！外族人侵入你的产业，污秽了你的圣殿，使耶路撒冷成为废墟。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 79, 2, '他们把你仆人的尸首，给空中的飞鸟啄食；把你圣民的肉，给地上的野兽吞噬。'),
('CNV', '诗篇', 19, 79, 3, '他们在耶路撒冷的周围把圣民的血像水一般倒出，没有人埋葬他们。'),
('CNV', '诗篇', 19, 79, 4, '我们成为邻国羞辱的对象，成为四周的人嗤笑和讥刺的目标。'),
('CNV', '诗篇', 19, 79, 5, '耶和华啊！要到几时呢？你要永远怀怒吗？你的愤恨要像火焚烧吗？'),
('CNV', '诗篇', 19, 79, 6, '愿你把你的烈怒，倾倒在不认识你的外族人，和不求告你名的列国身上。'),
('CNV', '诗篇', 19, 79, 7, '因为他们吞吃了雅各，使他的住处荒凉。'),
('CNV', '诗篇', 19, 79, 8, '求你不要记住我们祖先的罪孽；愿你的怜悯快快临到我们，因为我们落到极卑微的地步。'),
('CNV', '诗篇', 19, 79, 9, '拯救我们的神啊！求你因你名的荣耀帮助我们；为你名的缘故，搭救我们，赦免我们的罪。'),
('CNV', '诗篇', 19, 79, 10, '为什么容外族人说：“他们的神在哪里呢？”愿我们亲眼看见你在列邦中，使人知道你要为你仆人所流的血伸冤。'),
('CNV', '诗篇', 19, 79, 11, '愿被囚的人的唉哼，达到你面前；愿你用你的大能，使那些已定死罪的人可以存留。'),
('CNV', '诗篇', 19, 79, 12, '主啊！愿你把我们邻国羞辱你的羞辱，七倍归还在他们身上。'),
('CNV', '诗篇', 19, 79, 13, '这样，我们作你的子民，作你牧场上的羊的，要永远称谢你；我们要世世代代述说你可称颂的事。'),
('CNV', '诗篇', 19, 80, 1, '以色列的牧者啊！带领约瑟好像带领羊群的啊！求你留心听；坐在基路伯上面的啊！求你显出荣光。'),
('CNV', '诗篇', 19, 80, 2, '在以法莲、便雅悯和玛拿西面前，求你施展你的大能，前来拯救我们。'),
('CNV', '诗篇', 19, 80, 3, '神啊，求你使我们复兴！愿你的脸光照我们，我们就可以得救。'),
('CNV', '诗篇', 19, 80, 4, '耶和华万军之神啊！你因你子民的祷告发怒，要到几时呢？'),
('CNV', '诗篇', 19, 80, 5, '你使他们以眼泪当饼吃，使他们喝满杯的泪水。'),
('CNV', '诗篇', 19, 80, 6, '你使我们的邻国因我们纷争，我们的仇敌也讥笑我们。'),
('CNV', '诗篇', 19, 80, 7, '万军的神啊！求你使我们复兴；愿你的脸光照我们，我们就可以得救。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '诗篇', 19, 80, 8, '你从埃及带走一棵葡萄树，你赶出外族人，把这树栽上。'),
('CNV', '诗篇', 19, 80, 9, '你为它预备了地土，它就深深扎根，充满全地。'),
('CNV', '诗篇', 19, 80, 10, '它的荫影遮盖了群山，它的枝条遮盖了高大的香柏树。'),
('CNV', '诗篇', 19, 80, 11, '它的枝条伸展，直到大海；它的幼苗，直到大河。'),
('CNV', '诗篇', 19, 80, 12, '你为什么拆毁它的篱笆，任由所有过路的人采摘呢？'),
('CNV', '诗篇', 19, 80, 13, '从树林中出来的野猪践踏它，田野的走兽把它吃了。'),
('CNV', '诗篇', 19, 80, 14, '万军的神啊！求你回心转意，从天上垂看鉴察，眷顾这葡萄树，'),
('CNV', '诗篇', 19, 80, 15, '眷顾你右手栽种的根，和你为自己培育的儿子。'),
('CNV', '诗篇', 19, 80, 16, '这树已被火烧，被砍下；他们因你脸上的怒容灭亡。'),
('CNV', '诗篇', 19, 80, 17, '愿你的手护庇你右边的人，就是你为自己培育的人。'),
('CNV', '诗篇', 19, 80, 18, '这样，我们就不退后离开你；求你救活我们，我们就要求告你的名。'),
('CNV', '诗篇', 19, 80, 19, '耶和华万军的神啊！求你使我们复兴；愿你的脸光照我们，我们就可以得救。'),
('CNV', '诗篇', 19, 81, 1, '要向神我们的力量欢呼，要向雅各的神大声呼叫。'),
('CNV', '诗篇', 19, 81, 2, '要唱诗歌，打手鼓，弹奏美好的琴瑟。'),
('CNV', '诗篇', 19, 81, 3, '要在月朔，在月望，在我们守节的日子吹角。'),
('CNV', '诗篇', 19, 81, 4, '因为这是给以色列的律例，是雅各的神的典章。'),
('CNV', '诗篇', 19, 81, 5, '约瑟从埃及地出来（“约瑟从埃及地出来”或译：“神出去攻击埃及地”）的时候，神为约瑟立了这法规。我听见了我不晓得的言语。'),
('CNV', '诗篇', 19, 81, 6, '神说：“我要除去你（“你”原文作“他”）肩头的重担，使你（“你”原文作“他”）的手放下筐子。'),
('CNV', '诗篇', 19, 81, 7, '你在患难中呼求，我就搭救你；我在打雷的密云中回答你，在米利巴的水边试验你。”（细拉）'),
('CNV', '诗篇', 19, 81, 8, '“我的子民哪！你要听，我要劝戒你；以色列啊！但愿你肯听从我。'),
('CNV', '诗篇', 19, 81, 9, '在你中间不可有别的神，外族人的神你也不可敬拜。'),
('CNV', '诗篇', 19, 81, 10, '我是耶和华你的神，曾把你从埃及地领出来。你要大大张口，我就要给它充满。'),
('CNV', '诗篇', 19, 81, 11, '我的子民却不听我的话，以色列不肯服从我。'),
('CNV', '诗篇', 19, 81, 12, '因此，我就任凭他们心里刚硬，随着自己的计谋行事。'),
('CNV', '诗篇', 19, 81, 13, '只要我的子民听从我，以色列肯遵行我的道，'),
('CNV', '诗篇', 19, 81, 14, '我就迅速制伏他们的仇敌，把手转回来攻击他们的敌人。'),
('CNV', '诗篇', 19, 81, 15, '憎恨耶和华的人必向他假意归顺，他们的刑期必永无止境。'),
('CNV', '诗篇', 19, 81, 16, '但我（“我”原文作“他”）必把上好的麦子给你们（“你们”原文作“他”）吃，又用磐石里的蜂蜜使你们饱足。”'),
('CNV', '诗篇', 19, 82, 1, '神站在大能者的会中，在众神之中施行审判，说：（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 82, 2, '“你们不按公义审判，偏袒恶人，要到几时呢？（细拉）'),
('CNV', '诗篇', 19, 82, 3, '你们要为贫寒的人和孤儿伸冤，为困苦和穷乏的人伸张正义。'),
('CNV', '诗篇', 19, 82, 4, '要搭救贫寒和穷困的人，救他们脱离恶人的手。”'),
('CNV', '诗篇', 19, 82, 5, '他们没有知识，也不明白，在黑暗中走来走去；大地的一切根基都摇动了。'),
('CNV', '诗篇', 19, 82, 6, '我曾说过：“你们都是神，是至高者的儿子。'),
('CNV', '诗篇', 19, 82, 7, '然而，你们要像世人一样死亡，像世上任何一位领袖一样倒毙。”'),
('CNV', '诗篇', 19, 82, 8, '神啊！求你起来，审判大地，因为万国都是你的产业。'),
('CNV', '诗篇', 19, 83, 1, '神啊！求你不要静默；神啊！求你不要闭口，也不要一言不发。'),
('CNV', '诗篇', 19, 83, 2, '看哪！你的仇敌喧哗，恨你的人都抬起头来。'),
('CNV', '诗篇', 19, 83, 3, '他们密谋奸诈，陷害你的子民；他们彼此商议，攻击你所宝贵的人。'),
('CNV', '诗篇', 19, 83, 4, '他们说：“来吧！我们来把他们除灭，使他们不再成国，使以色列的名不再被人记念。”'),
('CNV', '诗篇', 19, 83, 5, '他们同心商议，彼此结盟，要和你对抗。'),
('CNV', '诗篇', 19, 83, 6, '他们就是住帐棚的以东人和以实玛利人，摩押人和夏甲人，'),
('CNV', '诗篇', 19, 83, 7, '迦巴勒、亚扪、亚玛力、非利士和推罗的居民。'),
('CNV', '诗篇', 19, 83, 8, '亚述也和他们联合起来，作了罗得子孙的帮手。（细拉）'),
('CNV', '诗篇', 19, 83, 9, '求你待他们好像待米甸人，像在基顺河待西西拉和耶宾一样；'),
('CNV', '诗篇', 19, 83, 10, '他们都在隐．多珥被消灭，成了地上的粪土。'),
('CNV', '诗篇', 19, 83, 11, '求你使他们的贵族像俄立和西伊伯，使他们的王子像西巴和撒慕拿。'),
('CNV', '诗篇', 19, 83, 12, '他们曾说：“我们要得着神的牧场作自己的产业。”'),
('CNV', '诗篇', 19, 83, 13, '我的神啊！求你使他们像旋风卷起的草，像风前的碎秸。'),
('CNV', '诗篇', 19, 83, 14, '火怎样焚烧树林，火焰怎样燃烧群山，'),
('CNV', '诗篇', 19, 83, 15, '求你也照样用狂风追赶他们，藉暴风雨惊吓他们。'),
('CNV', '诗篇', 19, 83, 16, '耶和华啊！求你使他们满面羞愧，好使他们寻求你的名。'),
('CNV', '诗篇', 19, 83, 17, '愿他们永远受辱惊惶，愿他们抱愧灭亡。'),
('CNV', '诗篇', 19, 83, 18, '使他们知道只有你的名是耶和华，唯有你是掌管全地的至高者。'),
('CNV', '诗篇', 19, 84, 1, '万军之耶和华啊！你的居所多么可爱。'),
('CNV', '诗篇', 19, 84, 2, '我的灵渴想切慕耶和华的院子，我的心身向永活的神欢呼。'),
('CNV', '诗篇', 19, 84, 3, '万军之耶和华，我的王我的神啊！在你的祭坛那里，麻雀找到了住处，燕子也为自己找到了安置幼雏的巢。'),
('CNV', '诗篇', 19, 84, 4, '住在你殿中的，都是有福的，他们还要不断赞美你。（细拉）'),
('CNV', '诗篇', 19, 84, 5, '靠你有力量，心中向往通到圣殿大道的，这人是有福的。'),
('CNV', '诗篇', 19, 84, 6, '他们经过干旱的山谷，使这谷变为泉源之地，更有秋雨使这谷到处都是水池。'),
('CNV', '诗篇', 19, 84, 7, '他们行走，力上加力，直到各人在锡安朝见神。'),
('CNV', '诗篇', 19, 84, 8, '耶和华万军的神啊！求你听我的祷告；雅各的神啊！求你留心听。（细拉）'),
('CNV', '诗篇', 19, 84, 9, '神啊！求你垂顾我们的盾牌，求你看顾你的受膏者。'),
('CNV', '诗篇', 19, 84, 10, '在你院子里住一日，胜过在别处住千日；宁愿站在我神殿中的门槛上，也不愿住在恶人的帐棚里。'),
('CNV', '诗篇', 19, 84, 11, '因为耶和华神是太阳，是盾牌，耶和华赐下恩惠和光荣；他没有留下一样好处，不给那些行为正直的人。'),
('CNV', '诗篇', 19, 84, 12, '万军之耶和华啊！倚靠你的人是有福的。'),
('CNV', '诗篇', 19, 85, 1, '耶和华啊！你恩待了你的地，恢复了雅各的产业（“恢复了雅各的产业”或译：“领回了雅各被掳的”）。'),
('CNV', '诗篇', 19, 85, 2, '你赦免了你子民的罪孽，遮盖了他们的一切罪恶。（细拉）'),
('CNV', '诗篇', 19, 85, 3, '你收回了你的一切忿怒，使你猛烈的怒气转消。'),
('CNV', '诗篇', 19, 85, 4, '拯救我们的神啊！求你复兴我们，求你止住你向我们所发的忿怒。'),
('CNV', '诗篇', 19, 85, 5, '你要永远向我们发怒吗？你要延长你的怒气到万代吗？'),
('CNV', '诗篇', 19, 85, 6, '你不使我们再活过来，以致你的子民可以因你欢喜吗？'),
('CNV', '诗篇', 19, 85, 7, '耶和华啊！求你使我们得见你的慈爱，又把你的救恩赐给我们。'),
('CNV', '诗篇', 19, 85, 8, '我要听神耶和华所要说的话；因为他应许赐平安给他的子民，给他的圣民；但愿他们不要转向愚妄。'),
('CNV', '诗篇', 19, 85, 9, '他的救恩的确临近敬畏他的人，使他的荣耀住在我们的地上。'),
('CNV', '诗篇', 19, 85, 10, '慈爱和信实彼此相遇，公义和平安互相亲吻。'),
('CNV', '诗篇', 19, 85, 11, '信实从地上生出，公义从天上俯视。'),
('CNV', '诗篇', 19, 85, 12, '耶和华也必赐下好处，我们的地要多出土产。'),
('CNV', '诗篇', 19, 85, 13, '公义必行在他面前，为他的脚步预备道路。'),
('CNV', '诗篇', 19, 86, 1, '耶和华啊！求你留心听我、应允我，因为我是困苦贫穷的。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 86, 2, '求你保护我的性命，因为我是虔诚的人；我的神啊！求你拯救这倚靠你的仆人。'),
('CNV', '诗篇', 19, 86, 3, '主啊！求你恩待我，因为我终日向你呼求。'),
('CNV', '诗篇', 19, 86, 4, '主啊！求你使你的仆人心里欢喜，因为我的心仰望你。'),
('CNV', '诗篇', 19, 86, 5, '主啊！你是良善，又乐意饶恕人的，向你呼求的，你都以丰盛的慈爱待他们。'),
('CNV', '诗篇', 19, 86, 6, '耶和华啊！求你侧耳听我的祷告，留心听我的恳求。'),
('CNV', '诗篇', 19, 86, 7, '在我遭难的日子，我要求告你，因为你必应允我。'),
('CNV', '诗篇', 19, 86, 8, '主啊！在众神之中，没有能和你相比的，你的作为也是无可比拟的。'),
('CNV', '诗篇', 19, 86, 9, '主啊！你所造的万国都要来，在你面前下拜，他们必荣耀你的名。'),
('CNV', '诗篇', 19, 86, 10, '因为你是伟大的，并且行奇妙的事，只有你是神。'),
('CNV', '诗篇', 19, 86, 11, '耶和华啊！求你把你的道路指教我，使我行在你的真理中，专心敬畏你的名。'),
('CNV', '诗篇', 19, 86, 12, '主我的神啊！我要满心称赞你，我要永远荣耀你的名。'),
('CNV', '诗篇', 19, 86, 13, '因为你向我大施慈爱，你救了我的命，免入阴间的深处。'),
('CNV', '诗篇', 19, 86, 14, '神啊！骄傲的人起来攻击我，一群强暴的人寻索我的性命，他们不把你放在眼内。'),
('CNV', '诗篇', 19, 86, 15, '但是，主啊！你是有怜悯有恩典的神，你不轻易发怒，并且有极大的慈爱和信实。'),
('CNV', '诗篇', 19, 86, 16, '求你转向我，恩待我；把你的能力赐给你的仆人，拯救你婢女的儿子。'),
('CNV', '诗篇', 19, 86, 17, '求你向我显出恩待我的记号，好使恨我的人看见了，就觉得羞愧；因为你耶和华帮助了我，安慰了我。'),
('CNV', '诗篇', 19, 87, 1, '耶和华所立的根基在圣山上。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 87, 2, '耶和华爱锡安的城门，胜过雅各的一切居所。'),
('CNV', '诗篇', 19, 87, 3, '神的城啊！有很多荣耀的事，都是指着你说的。（细拉）'),
('CNV', '诗篇', 19, 87, 4, '“在认识我的人中，我提到拉哈伯和巴比伦，看哪！还有非利士、推罗和古实，我说：‘这一个是生在那里的。’”'),
('CNV', '诗篇', 19, 87, 5, '论到锡安，必有话说：“这一个、那一个都是生在锡安的。”至高者必亲自坚立这城。'),
('CNV', '诗篇', 19, 87, 6, '耶和华登记万民的时候，必记着：“这一个是生在那里的。”（细拉）'),
('CNV', '诗篇', 19, 87, 7, '他们跳舞歌唱的时候，要说：“我的泉源都在你里面。”'),
('CNV', '诗篇', 19, 88, 1, '耶和华、拯救我的神啊！我昼夜都在你面前哀求。'),
('CNV', '诗篇', 19, 88, 2, '愿我的祷告达到你面前，求你留心听我的呼求。'),
('CNV', '诗篇', 19, 88, 3, '因为我饱经忧患，我的性命临近阴间。'),
('CNV', '诗篇', 19, 88, 4, '我被列在下坑的人中，就像一个没有气力的人一样。'),
('CNV', '诗篇', 19, 88, 5, '我被弃在死人之中，好像被杀的人躺在坟墓里；你不再记念他们，他们也和你（“你”原文作“你的手”）隔绝了。'),
('CNV', '诗篇', 19, 88, 6, '你把我放在最深的坑里，把我放在黑暗的地方和深渊里。'),
('CNV', '诗篇', 19, 88, 7, '你的烈怒重重地压着我，你的波浪从四方八面把我淹盖。（细拉）'),
('CNV', '诗篇', 19, 88, 8, '你使我的知己都远离我，使我成为他们所厌恶的。我被囚禁，不能外出。'),
('CNV', '诗篇', 19, 88, 9, '我的眼睛因困苦而昏花；耶和华啊，我天天向你呼求，向你举手祷告。'),
('CNV', '诗篇', 19, 88, 10, '你要为死人行奇事吗？阴魂会起来称谢你吗？（细拉）'),
('CNV', '诗篇', 19, 88, 11, '在坟墓里有人述说你的慈爱吗？在灭亡之地（“灭亡之地”原文作“亚巴顿”）有人述说你的信实吗？'),
('CNV', '诗篇', 19, 88, 12, '你的奇事在黑暗里有人知道吗？你的公义在那遗忘之地有人知道吗？'),
('CNV', '诗篇', 19, 88, 13, '耶和华啊！我却向你呼求，我的祷告在早晨达到你面前。'),
('CNV', '诗篇', 19, 88, 14, '耶和华啊！你为什么丢弃我？为什么掩面不顾我？'),
('CNV', '诗篇', 19, 88, 15, '我自幼受苦，几乎死亡；我受了你的惊吓，以致困惑不安（“困惑不安”原文意义难确定）。'),
('CNV', '诗篇', 19, 88, 16, '你的烈怒把我淹没，你的惊吓把我除灭。'),
('CNV', '诗篇', 19, 88, 17, '这些终日像水一样环绕我，一起把我围困。'),
('CNV', '诗篇', 19, 88, 18, '你使我挚爱的和同伴都远离我，黑暗成了我的知己。'),
('CNV', '诗篇', 19, 89, 1, '我要永远歌唱耶和华的慈爱，世世代代用口传扬你的信实。'),
('CNV', '诗篇', 19, 89, 2, '我要说：“你的慈爱必永远建立；你的信实，你必坚立在天上。'),
('CNV', '诗篇', 19, 89, 3, '你曾说：‘我和我所拣选的人立了约，向我的仆人大卫起了誓，说：'),
('CNV', '诗篇', 19, 89, 4, '我必永远坚立你的后裔，也必世世代代建立你的王位。’”（细拉）'),
('CNV', '诗篇', 19, 89, 5, '耶和华啊！诸天要称颂你的奇事；在圣者的会中，你的信实也要被称颂。'),
('CNV', '诗篇', 19, 89, 6, '在天上，谁能和耶和华相比呢？在全能者的众子中，谁能像耶和华呢？'),
('CNV', '诗篇', 19, 89, 7, '在圣者的议会中，神是令人惊惧的，比一切在他周围的都更为可畏。'),
('CNV', '诗篇', 19, 89, 8, '耶和华万军之神啊！有谁像你？耶和华啊！你是大能的，你的信实在你的周围。'),
('CNV', '诗篇', 19, 89, 9, '你管辖海洋的狂涛，波浪翻腾的时候，你使它们平息。'),
('CNV', '诗篇', 19, 89, 10, '你打碎了拉哈伯，好像已遭刺杀的人；你用有力的膀臂，赶散了你的仇敌。'),
('CNV', '诗篇', 19, 89, 11, '天是你的，地也是你的；世界和世界充满的，都是你建立的。'),
('CNV', '诗篇', 19, 89, 12, '南北都是你创造的，他泊和黑门都因你的名欢呼。'),
('CNV', '诗篇', 19, 89, 13, '你有大能的膀臂，你的手强而有力，你的右手高举。'),
('CNV', '诗篇', 19, 89, 14, '公义和公正是你宝座的基础，慈爱和信实行在你前面。'),
('CNV', '诗篇', 19, 89, 15, '晓得向你欢呼的人民是有福的，耶和华啊！他们在你的脸光中行走。'),
('CNV', '诗篇', 19, 89, 16, '他们因你的名终日欢呼，因你的公义被高举。'),
('CNV', '诗篇', 19, 89, 17, '因为你是他们的荣耀和力量；因你的恩惠，我们的角得以高举。'),
('CNV', '诗篇', 19, 89, 18, '因为我们的盾牌是耶和华，我们的君王是以色列的圣者。'),
('CNV', '诗篇', 19, 89, 19, '那时，你在异象中告诉你的圣民说：“我帮助了一位勇士，我从民中兴起了一位青年（“我从民中兴起了一位青年”或译：“我兴起那从民中所拣选的”）。'),
('CNV', '诗篇', 19, 89, 20, '我找到我的仆人大卫，用我的圣膏油膏他。'),
('CNV', '诗篇', 19, 89, 21, '我的手必坚立他，我的膀臂必坚固他。'),
('CNV', '诗篇', 19, 89, 22, '仇敌必不能欺骗他，凶恶的人必不能压迫他。'),
('CNV', '诗篇', 19, 89, 23, '我要在他的面前击碎他的敌人，击杀那些恨他的人。'),
('CNV', '诗篇', 19, 89, 24, '我的信实和慈爱必与他同在，他的角必因我的名被高举。'),
('CNV', '诗篇', 19, 89, 25, '我必使他的左手伸到大海，使他的右手伸到大河。'),
('CNV', '诗篇', 19, 89, 26, '他必呼叫我，说：‘你是我的父、我的神、拯救我的磐石。’'),
('CNV', '诗篇', 19, 89, 27, '我也要立他为长子，为世上最高的君王。'),
('CNV', '诗篇', 19, 89, 28, '我要永远保持我对他的慈爱，我和他所立的约必坚立。'),
('CNV', '诗篇', 19, 89, 29, '我要使他的后裔存到永远，使他的王位好像天一样长久。'),
('CNV', '诗篇', 19, 89, 30, '如果他的子孙离弃我的律法，不照着我的典章而行；'),
('CNV', '诗篇', 19, 89, 31, '如果他们违背我的律例，不遵守我的诫命，'),
('CNV', '诗篇', 19, 89, 32, '我就用杖责罚他们的过犯，用鞭责罚他们的罪孽。'),
('CNV', '诗篇', 19, 89, 33, '但我必不把我的慈爱从他身上收回，也必不背弃我的信实。'),
('CNV', '诗篇', 19, 89, 34, '我必不违背我的约，也不改变我口中所出的话。'),
('CNV', '诗篇', 19, 89, 35, '我断然指着自己的圣洁起誓，说：‘我决不向大卫说谎。'),
('CNV', '诗篇', 19, 89, 36, '他的后裔必存到永远，他的王位在我面前必像太阳长存，'),
('CNV', '诗篇', 19, 89, 37, '又像月亮永远坚立，作天上确实的见证。’”（细拉）'),
('CNV', '诗篇', 19, 89, 38, '你却恼怒你的受膏者，丢掉弃绝他。'),
('CNV', '诗篇', 19, 89, 39, '你舍弃了和你仆人所立的约，把他的冠冕玷污在地。'),
('CNV', '诗篇', 19, 89, 40, '你拆毁了他的一切城墙，使他的堡垒成废堆。'),
('CNV', '诗篇', 19, 89, 41, '过路的都抢掠他，他成了邻国的人羞辱的对象。'),
('CNV', '诗篇', 19, 89, 42, '你高举了他敌人的右手，使他所有的仇敌欢喜。'),
('CNV', '诗篇', 19, 89, 43, '你使他的刀剑卷刃，使他在战场上站立不住。'),
('CNV', '诗篇', 19, 89, 44, '你使他的光辉消失，把他的王位推翻（“推翻”原文作“推倒在地”）。'),
('CNV', '诗篇', 19, 89, 45, '你减少了他青春的日子，使他披上耻辱。（细拉）'),
('CNV', '诗篇', 19, 89, 46, '耶和华啊！这要到几时呢？你要永远隐藏自己吗？你的烈怒像火一般焚烧，要到几时呢？'),
('CNV', '诗篇', 19, 89, 47, '求你记念我的一生多么短暂，你创造的世人是多么虚幻呢！'),
('CNV', '诗篇', 19, 89, 48, '有哪一个人能长活不死，能救自己的性命脱离阴间的权势呢？（细拉）'),
('CNV', '诗篇', 19, 89, 49, '主啊！你从前指着你的信实向大卫起誓要施的慈爱，现今在哪里呢？'),
('CNV', '诗篇', 19, 89, 50, '主啊！求你记念你仆人所受的羞辱，记念我心里（“我心里”原文作“我在我的怀里”）承担着万民的羞辱。'),
('CNV', '诗篇', 19, 89, 51, '耶和华啊！你的仇敌用这羞辱羞辱了你的仆人，羞辱了你受膏者的脚踪。'),
('CNV', '诗篇', 19, 89, 52, '耶和华是应当称颂的，直到永远！阿们，阿们！'),
('CNV', '诗篇', 19, 90, 1, '主啊！你世世代代作我们的居所。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 90, 2, '群山尚未生出，大地和世界你未曾造成，从永远到永远，你是神。'),
('CNV', '诗篇', 19, 90, 3, '你使人归回尘土，说：“世人哪！你们要归回尘土。”'),
('CNV', '诗篇', 19, 90, 4, '在你看来，千年好像刚过去了的昨天，又像夜里的一更。'),
('CNV', '诗篇', 19, 90, 5, '你使世人消逝，像被洪水冲去；他们好像睡了一觉；他们又像在早晨生长的草，'),
('CNV', '诗篇', 19, 90, 6, '早晨发芽生长，晚上就凋萎枯干。'),
('CNV', '诗篇', 19, 90, 7, '我们因你的怒气而消灭，因你的烈怒而惊恐。'),
('CNV', '诗篇', 19, 90, 8, '你把我们的罪孽摆在你面前，把我们的隐恶摆在你脸光之中。'),
('CNV', '诗篇', 19, 90, 9, '我们一生的日子都在你的震怒中消逝，我们度尽的年岁好像一声叹息。'),
('CNV', '诗篇', 19, 90, 10, '我们一生的年日是七十岁，如果强壮，可到八十岁，但其中可夸耀的，不过是劳苦愁烦；我们的年日转眼即逝，我们也如飞而去了。'),
('CNV', '诗篇', 19, 90, 11, '谁晓得你怒气的威力，谁按着你该受的敬畏晓得你的忿怒呢？'),
('CNV', '诗篇', 19, 90, 12, '求你教导我们怎样数算自己的日子，好使我们得着智慧的心。'),
('CNV', '诗篇', 19, 90, 13, '耶和华啊！要到几时呢？求你回心转意，求你怜恤你的仆人。'),
('CNV', '诗篇', 19, 90, 14, '求你使我们早晨饱尝你的慈爱，好使我们一生一世欢呼喜乐。'),
('CNV', '诗篇', 19, 90, 15, '你使我们受苦和遭难的年日有多久，求你使我们喜乐的日子也有多久。'),
('CNV', '诗篇', 19, 90, 16, '愿你的作为向你的仆人彰显，愿你的威严向他们的子孙显明。'),
('CNV', '诗篇', 19, 90, 17, '愿主我们的神的恩慈临到我们身上；愿你为我们的缘故，坚立我们手所作的工；我们手所作的工，愿你坚立。'),
('CNV', '诗篇', 19, 91, 1, '住在至高者的隐密处的，必在全能者的荫庇下安居。'),
('CNV', '诗篇', 19, 91, 2, '我要对耶和华说：“你是我的避难所，我的保障，你是我的神，我所倚靠的。”'),
('CNV', '诗篇', 19, 91, 3, '他必救你脱离捕鸟的人的网罗，脱离致命的瘟疫。'),
('CNV', '诗篇', 19, 91, 4, '他必用自己的羽毛遮盖你，你要投靠在他的翅膀底下；他的信实像盾牌，像坚垒。'),
('CNV', '诗篇', 19, 91, 5, '你不必害怕黑夜的惊恐，或是白日的飞箭；'),
('CNV', '诗篇', 19, 91, 6, '也不必害怕黑暗中流行的瘟疫，或是在正午把人毁灭的毒病。'),
('CNV', '诗篇', 19, 91, 7, '虽有千人仆倒在你的左边，万人仆倒在你的右边，但灾害必不临近你。'),
('CNV', '诗篇', 19, 91, 8, '不过你要亲眼观看，看见恶人遭报。'),
('CNV', '诗篇', 19, 91, 9, '你既然把耶和华当作自己的避难所，把至高者当作自己的居所，'),
('CNV', '诗篇', 19, 91, 10, '祸患必不临到你，灾害必不临近你的帐棚。'),
('CNV', '诗篇', 19, 91, 11, '因为他为了你，会吩咐自己的使者，在你所行的一切路上保护你。'),
('CNV', '诗篇', 19, 91, 12, '他们必用手托住你，免得你的脚碰到石头。'),
('CNV', '诗篇', 19, 91, 13, '你必践踏狮子和虺蛇。你必踏碎少壮狮子和大蛇。'),
('CNV', '诗篇', 19, 91, 14, '耶和华说：“因为他恋慕我，我必搭救他；因为他认识我的名，我必保护他。'),
('CNV', '诗篇', 19, 91, 15, '他求告我，我必应允他；他在患难中，我必与他同在；我必拯救他，使他得尊荣。'),
('CNV', '诗篇', 19, 91, 16, '我必使他得享长寿，又向他显明我的救恩。”'),
('CNV', '诗篇', 19, 92, 1, '称谢耶和华，歌颂你至高者的名；'),
('CNV', '诗篇', 19, 92, 2, '早晨传扬你的慈爱，夜间传讲你的信实；'),
('CNV', '诗篇', 19, 92, 3, '弹奏十弦的乐器和瑟，又用琴弹出美妙的声音，这是多么美的事（“这是多么美的事”原文是在第1节；第1至第3节是一个整体）。'),
('CNV', '诗篇', 19, 92, 4, '耶和华啊！你藉着你的作为使我欢喜，我要因你手的工作欢呼。'),
('CNV', '诗篇', 19, 92, 5, '耶和华啊！你的工作多么伟大，你的心思极为深奥。'),
('CNV', '诗篇', 19, 92, 6, '无理性的人不晓得，愚昧的人不明白这事：'),
('CNV', '诗篇', 19, 92, 7, '恶人虽好像草一样繁茂，所有作孽的人虽然兴旺，他们都要永远灭亡。'),
('CNV', '诗篇', 19, 92, 8, '但你耶和华永远是至高的。'),
('CNV', '诗篇', 19, 92, 9, '耶和华啊！你的仇敌必灭亡，你的仇敌必定灭亡；所有作孽的都必被分散。'),
('CNV', '诗篇', 19, 92, 10, '你却高举了我的角，像野牛的角；你用新油膏抹我。'),
('CNV', '诗篇', 19, 92, 11, '我亲眼看见那些窥伺我的人遭报，我亲耳听见那些起来攻击我的恶人受罚。'),
('CNV', '诗篇', 19, 92, 12, '义人必像棕树一样繁茂，像黎巴嫩的香柏树一样高耸。'),
('CNV', '诗篇', 19, 92, 13, '他们栽在耶和华的殿中，在我们神的院子里繁茂生长。'),
('CNV', '诗篇', 19, 92, 14, '他们年老的时候仍要结果子，经常保持茂盛青翠，'),
('CNV', '诗篇', 19, 92, 15, '好显明耶和华是正直的；他是我的磐石，在他里面没有不义。'),
('CNV', '诗篇', 19, 93, 1, '耶和华作王，他以威严为衣；耶和华以威严为衣，以能力束腰，世界就得以坚立，永不动摇。'),
('CNV', '诗篇', 19, 93, 2, '你的宝座自古就立定，你从亘古就存在。'),
('CNV', '诗篇', 19, 93, 3, '耶和华啊！大水扬起了，大水扬起了声音，大水扬起了澎湃的波浪。'),
('CNV', '诗篇', 19, 93, 4, '耶和华在高处大有能力，胜过大水的响声，胜过海中的巨浪。'),
('CNV', '诗篇', 19, 93, 5, '耶和华啊！你的法度极为确定；你的殿永远被称为圣是合宜的。'),
('CNV', '诗篇', 19, 94, 1, '耶和华啊！你是伸冤的神；伸冤的神啊！求你显出荣光。'),
('CNV', '诗篇', 19, 94, 2, '审判大地的主啊！求你起来，使骄傲的人得到应得的报应。'),
('CNV', '诗篇', 19, 94, 3, '耶和华啊！恶人得意要到几时呢？恶人欢乐要到几时呢？'),
('CNV', '诗篇', 19, 94, 4, '他们不住地说骄傲的话，所有作孽的人都夸耀自己。'),
('CNV', '诗篇', 19, 94, 5, '耶和华啊！他们欺压你的子民，苦害你的产业。'),
('CNV', '诗篇', 19, 94, 6, '他们杀死寡妇和寄居的，又杀害孤儿。'),
('CNV', '诗篇', 19, 94, 7, '他们还说：“耶和华必看不见，雅各的神并不留意。”'),
('CNV', '诗篇', 19, 94, 8, '民间的愚昧人哪！你们要留心；愚顽人哪！你们要到几时才能明白呢？'),
('CNV', '诗篇', 19, 94, 9, '那造耳朵的，自己不能听见吗？那造眼睛的，自己不能看见吗？'),
('CNV', '诗篇', 19, 94, 10, '那管教万国的，不施行审判吗？那教导人的，自己没有知识吗？'),
('CNV', '诗篇', 19, 94, 11, '耶和华知道人的意念是虚妄的。'),
('CNV', '诗篇', 19, 94, 12, '耶和华啊！你所管教，用律法教导的人，是有福的。'),
('CNV', '诗篇', 19, 94, 13, '在患难的日子，你使他得享平安，直到为恶人所预备的坑挖好了。'),
('CNV', '诗篇', 19, 94, 14, '因为耶和华必不丢弃他的子民，必不离弃他的产业。'),
('CNV', '诗篇', 19, 94, 15, '因为审判必再转向公义，所有心里正直的都必顺从。'),
('CNV', '诗篇', 19, 94, 16, '谁肯为我起来攻击作恶的人呢？谁肯为我挺身而起对抗作孽的人呢？'),
('CNV', '诗篇', 19, 94, 17, '如果不是耶和华帮助我，我早就不在人世了（“我早就不在人世了”原文作“我早就住在寂静中”）。'),
('CNV', '诗篇', 19, 94, 18, '我说：“我失了脚”，耶和华啊！那时你的慈爱就扶持我。'),
('CNV', '诗篇', 19, 94, 19, '我心里充满忧虑的时候，你就安慰我，使我的心欢乐。'),
('CNV', '诗篇', 19, 94, 20, '凭着律例制造奸恶，藉着权位行毁灭的，怎能和你相交呢？'),
('CNV', '诗篇', 19, 94, 21, '他们集结起来攻击义人，把无辜的人定了死罪。'),
('CNV', '诗篇', 19, 94, 22, '但耶和华作了我的高台，我的神作了我避难的磐石。'),
('CNV', '诗篇', 19, 94, 23, '他必使他们的罪孽归到他们身上，他必因他们的罪恶灭绝他们；耶和华我们的神必把他们灭绝。'),
('CNV', '诗篇', 19, 95, 1, '来吧，我们来向耶和华歌唱，向拯救我们的磐石欢呼。'),
('CNV', '诗篇', 19, 95, 2, '我们要来到他面前称谢他，用诗歌向他欢呼。'),
('CNV', '诗篇', 19, 95, 3, '因为耶和华是伟大的神，是超越众神的大君王。'),
('CNV', '诗篇', 19, 95, 4, '地的深处在他手中，山的高峰也都属他。'),
('CNV', '诗篇', 19, 95, 5, '海洋属他，因为是他创造的，陆地也是他的手造成的。'),
('CNV', '诗篇', 19, 95, 6, '来吧，我们来俯伏敬拜，在造我们的耶和华面前跪下。'),
('CNV', '诗篇', 19, 95, 7, '因为他是我们的神，我们是他草场上的子民，是他手下的羊群。如果你们今天听从他的声音，'),
('CNV', '诗篇', 19, 95, 8, '就不要硬着心，好像在米利巴，就是在旷野的玛撒的日子一样。'),
('CNV', '诗篇', 19, 95, 9, '在那里你们的祖先虽曾见过我的作为，还是试探我，考验我。'),
('CNV', '诗篇', 19, 95, 10, '四十年之久，我厌恶那个世代的人；我曾说：“他们是心里迷误的人民，不认识我的道路。”'),
('CNV', '诗篇', 19, 95, 11, '所以我在忿怒中起誓，说：“他们绝不可进入我的安息。”'),
('CNV', '诗篇', 19, 96, 1, '你们要向耶和华唱新歌，全地都要向耶和华歌唱。'),
('CNV', '诗篇', 19, 96, 2, '要向耶和华歌唱，称颂他的名，天天传扬他的救恩。'),
('CNV', '诗篇', 19, 96, 3, '要在列国中述说他的荣耀。在万民中述说他奇妙的作为。'),
('CNV', '诗篇', 19, 96, 4, '因为耶和华是伟大的，该受极大的赞美，他当受敬畏，过于众神之上。'),
('CNV', '诗篇', 19, 96, 5, '因为万民的神都是虚空的偶像，但耶和华创造了诸天。'),
('CNV', '诗篇', 19, 96, 6, '尊荣和威严在他面前，能力和华美在他圣所之中。'),
('CNV', '诗篇', 19, 96, 7, '列国的万族啊！你们要归给耶和华，要把荣耀和能力归给耶和华。'),
('CNV', '诗篇', 19, 96, 8, '要把耶和华的名当得的荣耀归给他，带着礼物进入他的院子。'),
('CNV', '诗篇', 19, 96, 9, '要以圣洁的装束敬拜耶和华（“要以圣洁的装束敬拜耶和华”或译：“在耶和华显现的时候，要敬拜他”，或“要在耶和华圣洁的光辉中敬拜他”），全地都要在他面前战栗。'),
('CNV', '诗篇', 19, 96, 10, '你们要在万国中宣告：“耶和华作王！”世界就坚定，必不动摇；他必按着公正审判万民。'),
('CNV', '诗篇', 19, 96, 11, '愿天欢喜，愿地快乐；愿海和海中充满的，都翻腾响闹；'),
('CNV', '诗篇', 19, 96, 12, '愿田野和其中的一切都欢乐，那时林中的一切树木都必欢呼。'),
('CNV', '诗篇', 19, 96, 13, '它们都要在耶和华面前欢呼，因为他来了；他来要审判全地。他要按着公义审判世界，凭着他的信实审判万民。'),
('CNV', '诗篇', 19, 97, 1, '耶和华作王，愿地快乐，愿众海岛都欢喜。'),
('CNV', '诗篇', 19, 97, 2, '密云和幽暗在他的四围，公义和公正是他宝座的根基。'),
('CNV', '诗篇', 19, 97, 3, '有火走在他的前面，烧尽他四围的敌人。'),
('CNV', '诗篇', 19, 97, 4, '他的闪电照亮世界，大地看见了就战栗。'),
('CNV', '诗篇', 19, 97, 5, '在耶和华面前，就是在全地的主面前，群山都像蜡一般融化。'),
('CNV', '诗篇', 19, 97, 6, '诸天传扬他的公义，万民得见他的荣耀。'),
('CNV', '诗篇', 19, 97, 7, '愿所有事奉雕刻的偶像的，以虚无的偶像为夸口的，都蒙羞；众神哪！你们都要拜他。'),
('CNV', '诗篇', 19, 97, 8, '耶和华啊！锡安听见你的判断就欢喜，犹大的各城（“各城”原文作“女子”）也都快乐。'),
('CNV', '诗篇', 19, 97, 9, '耶和华啊！因为你是全地的至高者；你被尊崇，远超过众神之上。'),
('CNV', '诗篇', 19, 97, 10, '你们爱耶和华的，都要恨恶罪恶；耶和华保护圣民的性命，救他们脱离恶人的手。'),
('CNV', '诗篇', 19, 97, 11, '有亮光照耀（“照耀”有古抄本作“散播”）义人，心里正直的人得享喜乐。'),
('CNV', '诗篇', 19, 97, 12, '义人哪！你们要靠耶和华欢喜，要称赞他的圣名。'),
('CNV', '诗篇', 19, 98, 1, '你们要向耶和华唱新歌，因为他行了奇妙的事；他的右手和他的圣臂，为他施行拯救。'),
('CNV', '诗篇', 19, 98, 2, '耶和华显明了他的救恩，在列国眼前显示了他的公义。'),
('CNV', '诗篇', 19, 98, 3, '他记念他向以色列家所应许的慈爱和信实，地的四极都看见我们神的救恩。'),
('CNV', '诗篇', 19, 98, 4, '全地都要向耶和华欢呼，要发声欢唱，要歌颂。'),
('CNV', '诗篇', 19, 98, 5, '要弹琴歌颂耶和华，要用琴和歌声歌颂他；'),
('CNV', '诗篇', 19, 98, 6, '要用号筒和号角的声音，在大君王耶和华面前欢呼。'),
('CNV', '诗篇', 19, 98, 7, '愿海和海中充满的，都翻腾响闹，愿世界和住在世上的也都发声；'),
('CNV', '诗篇', 19, 98, 8, '愿江河拍手，愿群山一起欢呼；'),
('CNV', '诗篇', 19, 98, 9, '它们都要在耶和华面前欢呼，因为他来是要审判全地，他要按着公义审判世界，凭着公正审判万民。'),
('CNV', '诗篇', 19, 99, 1, '耶和华作王，万民都要战栗；他坐在两个基路伯之上，大地也要震动。'),
('CNV', '诗篇', 19, 99, 2, '耶和华在锡安是至大的，他崇高，超过万民。'),
('CNV', '诗篇', 19, 99, 3, '愿他们称赞你伟大可畏的名。他是圣洁的。'),
('CNV', '诗篇', 19, 99, 4, '王有能力（“王有能力”原文作“王的能力”），喜爱公正；你坚立正义；你在雅各家施行公正和公义。'),
('CNV', '诗篇', 19, 99, 5, '你们要尊崇耶和华我们的神，在他的脚凳前敬拜；他是圣洁的。'),
('CNV', '诗篇', 19, 99, 6, '在他的祭司中有摩西和亚伦，在求告他名的人中有撒母耳；他们求告耶和华，他就应允他们。'),
('CNV', '诗篇', 19, 99, 7, '他从云柱中对他们说话；他们谨守耶和华赐给他们的法度和律例。'),
('CNV', '诗篇', 19, 99, 8, '耶和华我们的神啊！你应允了他们；你虽然按照他们所行的报应他们，但对他们来说，你是一位赦免人的神。'),
('CNV', '诗篇', 19, 99, 9, '你们要尊崇耶和华我们的神，在他的圣山上敬拜，因为耶和华我们的神是圣洁的。'),
('CNV', '诗篇', 19, 100, 1, '全地应当向耶和华欢呼。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 100, 2, '应当欢欢喜喜事奉耶和华，欢唱着到他的面前。'),
('CNV', '诗篇', 19, 100, 3, '要知道耶和华是神；他创造了我们，我们是属他的（“我们是属他的”有古抄本作“不是我们自己”）；我们是他的子民，也是他草场上的羊。'),
('CNV', '诗篇', 19, 100, 4, '应当充满感恩进入他的殿门，满口赞美进入他的院子；要感谢他，称颂他的名。'),
('CNV', '诗篇', 19, 100, 5, '因为耶和华本是美善的，他的慈爱存到永远，他的信实直到万代。'),
('CNV', '诗篇', 19, 101, 1, '我要歌唱慈爱和公正；耶和华啊！我要向你歌颂。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 101, 2, '我要小心谨慎行正直的路；你什么时候才到我这里来呢？我要在我的家中，以正直的心行事。'),
('CNV', '诗篇', 19, 101, 3, '邪恶的事，我都不摆在眼前；离开正路的人所作的事，我都恨恶，决不容这些沾染我。'),
('CNV', '诗篇', 19, 101, 4, '狡诈的心思，我要远离；邪恶的事，我不参与。'),
('CNV', '诗篇', 19, 101, 5, '暗中诽谤邻舍的，我必把他灭绝；眼目高傲，心里骄横的，我必不容忍他。'),
('CNV', '诗篇', 19, 101, 6, '我的眼目必看顾国中的诚实人，使他们与我同住；行为正直的，必要侍候我。'),
('CNV', '诗篇', 19, 101, 7, '行诡诈的，必不得住在我的家里；说谎话的，必不能在我眼前坚立。'),
('CNV', '诗篇', 19, 101, 8, '我每日早晨必灭绝国中所有的恶人，好把所有作孽的人都从耶和华的城里剪除。'),
('CNV', '诗篇', 19, 102, 1, '耶和华啊！求你听我的祷告；愿我的呼求达到你那里。'),
('CNV', '诗篇', 19, 102, 2, '我在患难的日子，求你不要向我掩面；我呼求的时候，求你留心听我，并且迅速应允我。'),
('CNV', '诗篇', 19, 102, 3, '因为我的年日好像烟一般消散；我的骨头烧焦像炉中的炭。'),
('CNV', '诗篇', 19, 102, 4, '我的心受创伤，好像草一般枯干，以致我连饭也忘了吃。'),
('CNV', '诗篇', 19, 102, 5, '因我唉哼的声音，我就渐渐消瘦（“我就渐渐消瘦”原文作“我的骨头紧贴着肉”）。'),
('CNV', '诗篇', 19, 102, 6, '我像旷野的鹈鹕，又像废墟里的猫头鹰。'),
('CNV', '诗篇', 19, 102, 7, '我躺在床上警醒着，就像屋顶上孤单的麻雀。'),
('CNV', '诗篇', 19, 102, 8, '我的仇敌终日辱骂我；嘲弄我的指着我赌咒。'),
('CNV', '诗篇', 19, 102, 9, '我吃炉灰像吃饭一样；我所喝的与眼泪混和。'),
('CNV', '诗篇', 19, 102, 10, '这都是因为你的愤恨和烈怒；你把我举起来，又把我摔下去。'),
('CNV', '诗篇', 19, 102, 11, '我的年日好像日影偏斜，我也好像草一般枯干。'),
('CNV', '诗篇', 19, 102, 12, '耶和华啊！你却永远坐着为王，你可记念的名也必存到万代。'),
('CNV', '诗篇', 19, 102, 13, '你要起来，怜悯锡安，因为现在是恩待锡安的时候；所定的日期已经到了。'),
('CNV', '诗篇', 19, 102, 14, '因为你的众仆人喜爱它的石头，爱惜它的尘土。'),
('CNV', '诗篇', 19, 102, 15, '万国都必敬畏耶和华的名；世上列王都敬畏你的荣耀。'),
('CNV', '诗篇', 19, 102, 16, '因为耶和华必建造锡安，在他自己的荣耀里显现。'),
('CNV', '诗篇', 19, 102, 17, '他要垂顾困苦人的祷告，必不藐视他们的祈求。'),
('CNV', '诗篇', 19, 102, 18, '这些事要记下来，传给后代，好使将来出生的人民可以赞美耶和华。'),
('CNV', '诗篇', 19, 102, 19, '因为耶和华从他至高的圣所里垂看，从天上观看大地，'),
('CNV', '诗篇', 19, 102, 20, '为要垂听被囚的人的叹息，解救定了死罪的人；'),
('CNV', '诗篇', 19, 102, 21, '使人在锡安传扬耶和华的名，在耶路撒冷传扬赞美他的话。'),
('CNV', '诗篇', 19, 102, 22, '那时，万民和万国必一同聚集，要事奉耶和华。'),
('CNV', '诗篇', 19, 102, 23, '耶和华在我壮年的时候，使我的力量衰弱，缩短我的年日。'),
('CNV', '诗篇', 19, 102, 24, '所以我说：“我的神啊！求你不要使我中年去世，你的年数万代无疆。'),
('CNV', '诗篇', 19, 102, 25, '你起初立了地的根基；天也是你手的工作。'),
('CNV', '诗篇', 19, 102, 26, '天地都要毁灭，你却长存；天地都要像衣服一样渐渐残旧；你要更换天地如同更换衣物一样，天地就被更换。'),
('CNV', '诗篇', 19, 102, 27, '只有你永不改变，你的年数也没有穷尽。'),
('CNV', '诗篇', 19, 102, 28, '你仆人的子孙必安然居住；他们的后裔必在你面前坚立。”'),
('CNV', '诗篇', 19, 103, 1, '我的心哪！你要称颂耶和华；在我里面的一切，都要称颂他的圣名。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 103, 2, '我的心哪！你要称颂耶和华；不可忘记他的一切恩惠。'),
('CNV', '诗篇', 19, 103, 3, '他赦免你的一切罪孽，医治你的一切疾病；'),
('CNV', '诗篇', 19, 103, 4, '他救赎你的性命脱离死亡，以慈爱和怜悯作你的冠冕；'),
('CNV', '诗篇', 19, 103, 5, '他以福乐使你的心愿满足，以致你好像鹰一般恢复青春的活力。'),
('CNV', '诗篇', 19, 103, 6, '耶和华施行公义，为所有受欺压的人主持公道。'),
('CNV', '诗篇', 19, 103, 7, '他向摩西指示自己的道路，向以色列人显明自己的作为。'),
('CNV', '诗篇', 19, 103, 8, '耶和华有怜悯，有恩典，不轻易发怒，并且有丰盛的慈爱。'),
('CNV', '诗篇', 19, 103, 9, '他不长久责备，也不永远怀怒。'),
('CNV', '诗篇', 19, 103, 10, '他没有按着我们的罪过待我们，也没有照着我们的罪孽报应我们。'),
('CNV', '诗篇', 19, 103, 11, '天离地有多高，他的慈爱向敬畏他的人也有多大。'),
('CNV', '诗篇', 19, 103, 12, '东离西有多远，他使我们的过犯离我们也有多远。'),
('CNV', '诗篇', 19, 103, 13, '父亲怎样怜恤儿子，耶和华也照样怜恤敬畏他的人；'),
('CNV', '诗篇', 19, 103, 14, '因为他知道我们的本体，记得我们不过是尘土。'),
('CNV', '诗篇', 19, 103, 15, '至于世人，他的年日好像草一般；他又像野地繁茂的花。'),
('CNV', '诗篇', 19, 103, 16, '经风一吹，就归无有；他原来的地方再不认识他。'),
('CNV', '诗篇', 19, 103, 17, '但从亘古到永远，耶和华的慈爱临到敬畏他的人；他的公义也归于他们的子子孙孙，'),
('CNV', '诗篇', 19, 103, 18, '就是那些谨守他的约，记住他的训词，并且遵行的人。'),
('CNV', '诗篇', 19, 103, 19, '耶和华在天上立定宝座，他的王权统管万有。'),
('CNV', '诗篇', 19, 103, 20, '你们作他天使的，就是那些大有能力，行他所吩咐，以及听从他命令的，都要称颂耶和华。'),
('CNV', '诗篇', 19, 103, 21, '你们作他的众军，作他的仆役，遵行他旨意的，都要称颂耶和华。'),
('CNV', '诗篇', 19, 103, 22, '你们一切被他所造的，在他统治的各处，都要称颂耶和华。我的心哪，你要称颂耶和华。'),
('CNV', '诗篇', 19, 104, 1, '我的心哪！你要称颂耶和华；耶和华我的神啊！你真伟大；你以尊荣和威严为衣服。'),
('CNV', '诗篇', 19, 104, 2, '你披上亮光好像披上外袍；展开诸天好像铺张帐幔。'),
('CNV', '诗篇', 19, 104, 3, '你在水上立起你楼阁的栋梁；你以云彩为战车；乘驾风的翅膀而行。'),
('CNV', '诗篇', 19, 104, 4, '你用风作你的使者，用火焰作你的仆役。'),
('CNV', '诗篇', 19, 104, 5, '你把大地坚立在根基上，使地永永远远不动摇。'),
('CNV', '诗篇', 19, 104, 6, '你用深水像衣服一般覆盖大地，使众水高过群山。'),
('CNV', '诗篇', 19, 104, 7, '因你的斥责，水就退去；因你的雷声，水就奔逃。'),
('CNV', '诗篇', 19, 104, 8, '众水流经群山，向下流往众谷，流到你为它们指定的地方。'),
('CNV', '诗篇', 19, 104, 9, '你定了界限，使众水不能越过；它们不再转回掩盖大地。'),
('CNV', '诗篇', 19, 104, 10, '你使泉源在山谷中涌流，流经群山中间。'),
('CNV', '诗篇', 19, 104, 11, '使野地所有的走兽有水喝，野驴得以解渴。'),
('CNV', '诗篇', 19, 104, 12, '天上的飞鸟在水边住宿，在树枝上鸣叫。'),
('CNV', '诗篇', 19, 104, 13, '你从自己的楼阁中浇灌群山，因你所作的事的果效，大地就丰足。'),
('CNV', '诗篇', 19, 104, 14, '你为了牲畜使青草滋生，为了人的需用使蔬菜生长，使粮食从地里生出；'),
('CNV', '诗篇', 19, 104, 15, '又有酒使人心欢喜，有油使人容光焕发，有粮加添人的心力。'),
('CNV', '诗篇', 19, 104, 16, '耶和华的树，就是他所栽种的黎巴嫩香柏树，都得到了充分的灌溉。'),
('CNV', '诗篇', 19, 104, 17, '雀鸟在上面筑巢；至于鹤，松树是它的家。'),
('CNV', '诗篇', 19, 104, 18, '高山是野山羊的住所；岩石是石貛藏身的地方。'),
('CNV', '诗篇', 19, 104, 19, '你造月亮为定节令；太阳知道何时沉落。'),
('CNV', '诗篇', 19, 104, 20, '你安设黑暗，有了晚上，林中的百兽就都爬出来。'),
('CNV', '诗篇', 19, 104, 21, '少壮狮子吼叫觅食，要寻求从神而来的食物。'),
('CNV', '诗篇', 19, 104, 22, '太阳升起的时候，它们就躲避，回到自己的洞穴躺卧。'),
('CNV', '诗篇', 19, 104, 23, '人出去作工，劳碌直到晚上。'),
('CNV', '诗篇', 19, 104, 24, '耶和华啊！你所造的真是众多。它们都是你用智慧造成的；全地充满你所造的东西。'),
('CNV', '诗篇', 19, 104, 25, '那里有海，又大又广；海里有无数的活物，大小活物都有。'),
('CNV', '诗篇', 19, 104, 26, '那里有船只往来航行，有你所造的大鱼，在海里嬉戏。'),
('CNV', '诗篇', 19, 104, 27, '这些活物都仰望你，仰望你按时赐给它们食物。'),
('CNV', '诗篇', 19, 104, 28, '你赐给它们，它们就拾取；你张开你的手，它们就饱享美物。'),
('CNV', '诗篇', 19, 104, 29, '你向它们掩面，它们就惊慌；你收回它们的气息，它们就死亡，归回尘土。'),
('CNV', '诗篇', 19, 104, 30, '你发出你的灵，万物就被造成；你也使地面更换一新。'),
('CNV', '诗篇', 19, 104, 31, '愿耶和华的荣耀存到永远；愿耶和华喜悦他自己所作的。'),
('CNV', '诗篇', 19, 104, 32, '他注视大地，地就震动；他触摸群山，山就冒烟。'),
('CNV', '诗篇', 19, 104, 33, '我一生要向耶和华歌唱；我还在世的时候，我要向我的神歌颂。'),
('CNV', '诗篇', 19, 104, 34, '愿我的默想蒙他喜悦；我要因耶和华欢喜。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
